import { defineSecret } from "firebase-functions/params";

/**
 * Centralized Secret Definitions
 */
export const geminiApiKey = defineSecret("GEMINI_API_KEY");
export const googleMapsApiKey = defineSecret("GOOGLE_MAPS_API_KEY");
export const inngestEventKey = defineSecret("INNGEST_EVENT_KEY");
export const inngestSigningKey = defineSecret("INNGEST_SIGNING_KEY");
export const stripeSecretKey = defineSecret("STRIPE_SECRET_KEY");
export const stripeWebhookSecret = defineSecret("STRIPE_WEBHOOK_SECRET");
export const pandaDocApiKey = defineSecret("PANDADOC_API_KEY");
export const telegramBotToken = defineSecret("TELEGRAM_BOT_TOKEN");
export const telegramWebhookSecret = defineSecret("TELEGRAM_WEBHOOK_SECRET");
export const pandadocWebhookSecret = defineSecret("PANDADOC_WEBHOOK_SECRET");

// ---------------------------------------------------------------------------
// Founders Program
// ---------------------------------------------------------------------------
// Fine-grained GitHub PAT scoped to contents:write on this repo only.
// Used by activateFounderPass to commit new founder entries to src/config/founders.ts.
// Required secret in GCP Secret Manager: GITHUB_TOKEN_FOUNDERS
export const githubTokenFounders = defineSecret("GITHUB_TOKEN_FOUNDERS");

/**
 * Helper to safely retrieve the GitHub Token for the Founders Program.
 */
export function getGithubTokenFounders(): string {
    const envKey = process.env.GITHUB_TOKEN_FOUNDERS;
    if (envKey && envKey.trim().length > 0) return envKey;

    try {
        const secret = githubTokenFounders.value();
        if (secret && secret.trim().length > 0) return secret;
    } catch {
        if (process.env.GITHUB_TOKEN_FOUNDERS) return process.env.GITHUB_TOKEN_FOUNDERS;
    }

    throw new Error("GitHub Token for Founders Program not found. Please set GITHUB_TOKEN_FOUNDERS secret or environment variable.");
}

/**
 * Helper to safely retrieve the Gemini API Key.
 * Handles both production (secrets) and local development (environment variables).
 */
export function getGeminiApiKey(): string {
    // 1. Try Environment Variable (Local/Dev/Emulator)
    const envKey = process.env.GEMINI_API_KEY || process.env.GOOGLE_GENAI_API_KEY;
    if (envKey && envKey.trim().length > 0) {
        return envKey;
    }

    // 2. Try Firebase Secret (Production)
    // For V1 functions, secrets are mounted as environment variables.
    // However, defineSecret().value() is the modern way to access them if initialized.
    try {
        const secret = geminiApiKey.value();
        if (secret && secret.trim().length > 0) {
            return secret;
        }
    } catch (_e) {
        // Fallback to direct process.env check in case .value() fails in specific contexts
        const directEnv = process.env.GEMINI_API_KEY;
        if (directEnv && directEnv.trim().length > 0) {
            return directEnv;
        }
    }

    throw new Error("Gemini API Key not found. Please set GEMINI_API_KEY secret or environment variable.");
}

/**
 * Helper to safely retrieve the Stripe Secret Key.
 */
export function getStripeSecretKey(): string {
    const envKey = process.env.STRIPE_SECRET_KEY;
    if (envKey && envKey.trim().length > 0) return envKey;

    try {
        const secret = stripeSecretKey.value();
        if (secret && secret.trim().length > 0) return secret;
    } catch (e) {
        if (process.env.STRIPE_SECRET_KEY) return process.env.STRIPE_SECRET_KEY;
    }

    throw new Error("Stripe Secret Key not found.");
}

/**
 * Helper to safely retrieve the Stripe Webhook Secret.
 */
export function getStripeWebhookSecret(): string {
    const envKey = process.env.STRIPE_WEBHOOK_SECRET;
    if (envKey && envKey.trim().length > 0) return envKey;

    try {
        const secret = stripeWebhookSecret.value();
        if (secret && secret.trim().length > 0) return secret;
    } catch (e) {
        if (process.env.STRIPE_WEBHOOK_SECRET) return process.env.STRIPE_WEBHOOK_SECRET;
    }

    throw new Error("Stripe Webhook Secret not found.");
}

/**
 * Helper to safely retrieve the PandaDoc API Key.
 */
export function getPandaDocApiKey(): string {
    const envKey = process.env.PANDADOC_API_KEY;
    if (envKey && envKey.trim().length > 0) return envKey;

    try {
        const secret = pandaDocApiKey.value();
        if (secret && secret.trim().length > 0) return secret;
    } catch (e) {
        if (process.env.PANDADOC_API_KEY) return process.env.PANDADOC_API_KEY;
    }

    throw new Error("PandaDoc API Key not found. Please set PANDADOC_API_KEY secret or environment variable.");
}

// ---------------------------------------------------------------------------
// Growth Intelligence Engine — Platform Analytics OAuth Secrets
// ---------------------------------------------------------------------------
// Token exchange logic is in functions/src/analytics/platformTokenExchange.ts.
// Defined here for centralized reference and cross-function reuse.
//
// Required secrets in GCP Secret Manager:
//   - SPOTIFY_CLIENT_ID      (Spotify Developer Dashboard → App → Client ID)
//   - SPOTIFY_CLIENT_SECRET  (Spotify Developer Dashboard → App → Client Secret)
//   - TIKTOK_CLIENT_KEY      (TikTok for Developers → App → Client Key)
//   - TIKTOK_CLIENT_SECRET   (TikTok for Developers → App → Client Secret)
//   - META_APP_ID            (Meta Developer Console → App → App ID)
//   - META_APP_SECRET        (Meta Developer Console → App → App Secret)
export const spotifyClientId = defineSecret("SPOTIFY_CLIENT_ID");
export const spotifyClientSecret = defineSecret("SPOTIFY_CLIENT_SECRET");
export const tiktokClientKey = defineSecret("TIKTOK_CLIENT_KEY");
export const tiktokClientSecret = defineSecret("TIKTOK_CLIENT_SECRET");
export const metaAppId = defineSecret("META_APP_ID");
export const metaAppSecret = defineSecret("META_APP_SECRET");

// ---------------------------------------------------------------------------
// Email OAuth Secrets (Gmail / Outlook)
// ---------------------------------------------------------------------------
// Actual secret access is in functions/src/email/tokenManager.ts via defineSecret.
// Documented here for centralized reference.
//
// Required secrets in GCP Secret Manager:
//   - GOOGLE_OAUTH_CLIENT_ID      (Google Cloud Console → OAuth 2.0 Client ID)
//   - GOOGLE_OAUTH_CLIENT_SECRET  (Google Cloud Console → OAuth 2.0 Client Secret)
//   - MICROSOFT_CLIENT_ID         (Azure Portal → App Registration → Client ID)
//   - MICROSOFT_CLIENT_SECRET     (Azure Portal → App Registration → Client Secret)

/**
 * Firebase Cloud Functions — Generation Abstraction Layer
 * ========================================================
 *
 * This module provides a future-proof factory for defining Cloud Functions.
 * When Google releases a new generation (Gen 3, Gen 4, etc.), you only need
 * to update THIS file — all business logic in individual function files
 * remains untouched.
 *
 * Usage:
 *   import { defineCallable, defineScheduled, defineHttps, HttpsError } from '../factory';
 *
 *   export const myFunction = defineCallable(
 *       { region: 'us-west1', memory: '1GiB', secrets: [mySecret] },
 *       async (request) => {
 *           if (!request.auth) throw new HttpsError('unauthenticated', '...');
 *           const data = request.data as MyType;
 *           return { result: 'ok' };
 *       }
 *   );
 *
 * Migration checklist (when upgrading to Gen N+1):
 *   1. Update the import path below (e.g., firebase-functions/v3/https)
 *   2. Adjust the option mapping if the new API renames fields
 *   3. Re-run `npx tsc --noEmit` to catch any type mismatches
 *   4. Deploy — all function files stay unchanged
 */

// ════════════════════════════════════════════════════════════════════════════
// CURRENT GENERATION: Gen 2 (firebase-functions/v2)
// ════════════════════════════════════════════════════════════════════════════

import {
    onCall,
    onRequest,
    HttpsError,
    type CallableRequest,
    type HttpsOptions,
} from 'firebase-functions/v2/https';
// import type { SecretParam } from 'firebase-functions/params';

import {
    onSchedule,
    type ScheduleOptions,
} from 'firebase-functions/v2/scheduler';

import {
    onDocumentWritten,
    type DocumentOptions,
} from 'firebase-functions/v2/firestore';

import {
    onObjectFinalized,
} from 'firebase-functions/v2/storage';

// Re-export HttpsError so consumers don't import the SDK directly
export { HttpsError };

// ════════════════════════════════════════════════════════════════════════════
// TYPES — Stable contract that won't change across generations
// ════════════════════════════════════════════════════════════════════════════

/**
 * Common options shared across all function types.
 * These map to the current generation's option shape.
 */
export interface FunctionOptions {
    /** GCP region(s). Default: 'us-central1' */
    region?: string | string[];
    /** Memory allocation. Default: '256MiB' */
    memory?: '128MiB' | '256MiB' | '512MiB' | '1GiB' | '2GiB' | '4GiB' | '8GiB' | '16GiB';
    /** Timeout in seconds. Default: 60 */
    timeoutSeconds?: number;
    /** Minimum instances (keep warm). Default: 0 */
    minInstances?: number;
    /** Maximum instances. Default: 100 */
    maxInstances?: number;
    /** CPU allocation. Default: 1 */
    cpu?: number | 'gcf_gen1';
    /** Secret references */
    secrets?: any[];
    /** Whether to enforce App Check. Default: false */
    enforceAppCheck?: boolean;
    /** Concurrency per instance. Default: 80 */
    concurrency?: number;
    /** Ingress settings */
    ingress?: 'ALLOW_ALL' | 'ALLOW_INTERNAL_ONLY' | 'ALLOW_INTERNAL_AND_GCLB';
}

/**
 * The stable request shape that handler functions receive.
 * Wraps the generation-specific request object.
 */
export interface StableCallableRequest<T = unknown> {
    /** The authenticated user, or undefined if unauthenticated */
    auth?: {
        uid: string;
        token: Record<string, unknown>;
    };
    /** The request payload */
    data: T;
    /** Raw IP address of the caller */
    rawRequest?: unknown;
}

// ════════════════════════════════════════════════════════════════════════════
// FACTORY FUNCTIONS
// ════════════════════════════════════════════════════════════════════════════

/**
 * Maps our stable FunctionOptions to the current generation's option format.
 * This is the ONLY function that needs updating when upgrading generations.
 */
function mapOptions(opts: FunctionOptions): any {
    return {
        region: opts.region || 'us-central1',
        memory: opts.memory,
        timeoutSeconds: opts.timeoutSeconds,
        minInstances: opts.minInstances,
        maxInstances: opts.maxInstances,
        cpu: opts.cpu,
        secrets: opts.secrets as any,
        enforceAppCheck: opts.enforceAppCheck,
        concurrency: opts.concurrency,
        ingress: opts.ingress,
    };
}

/**
 * Define a callable Cloud Function (invoked from client SDK via httpsCallable).
 *
 * @param options - Function configuration
 * @param handler - Business logic handler
 * @returns A deployed Cloud Function
 */
export function defineCallable<TData = unknown, TResponse = unknown>(
    options: FunctionOptions,
    handler: (request: StableCallableRequest<TData>) => Promise<TResponse>
) {
    const mappedOptions = mapOptions(options);
    return onCall(mappedOptions, async (request: CallableRequest<TData>) => {
        // Normalize the request into our stable shape
        const stableRequest: StableCallableRequest<TData> = {
            auth: request.auth ? {
                uid: request.auth.uid,
                token: request.auth.token as Record<string, unknown>,
            } : undefined,
            data: request.data,
            rawRequest: request.rawRequest,
        };
        return handler(stableRequest);
    });
}

/**
 * Define an HTTP Cloud Function (invoked via direct URL).
 *
 * @param options - Function configuration
 * @param handler - Express-compatible request handler
 * @returns A deployed Cloud Function
 */
export function defineHttps(
    options: FunctionOptions,
    handler: (req: unknown, res: unknown) => void | Promise<void>
) {
    const mappedOptions = mapOptions(options) as HttpsOptions;
    return onRequest(mappedOptions, handler as any);
}

/**
 * Define a scheduled Cloud Function (cron job).
 *
 * @param schedule - Cron expression (e.g., 'every 5 minutes')
 * @param options - Function configuration
 * @param handler - Business logic handler
 * @returns A deployed Cloud Function
 */
export function defineScheduled(
    schedule: string,
    options: FunctionOptions,
    handler: () => Promise<void>
) {
    const scheduleOptions: ScheduleOptions = {
        schedule,
        region: (options.region as any) || 'us-central1',
        memory: options.memory,
        timeoutSeconds: options.timeoutSeconds,
    };
    return onSchedule(scheduleOptions, async () => {
        await handler();
    });
}

/**
 * Define a Firestore-triggered Cloud Function.
 *
 * @param documentPath - Firestore document path pattern (e.g., 'users/{userId}')
 * @param options - Function configuration
 * @param handler - Business logic handler receiving the change event
 * @returns A deployed Cloud Function
 */
export function defineFirestoreTrigger(
    documentPath: string,
    options: FunctionOptions,
    handler: (event: { data?: unknown; params: Record<string, string> }) => Promise<void>
) {
    const docOptions: DocumentOptions = {
        document: documentPath,
        region: (options.region as any) || 'us-central1',
        memory: options.memory,
        timeoutSeconds: options.timeoutSeconds,
    };
    return onDocumentWritten(docOptions, async (event) => {
        await handler({
            data: event.data,
            params: event.params,
        });
    });
}

/**
 * Define a Storage-triggered Cloud Function.
 *
 * @param bucket - Storage bucket name (optional, uses default)
 * @param options - Function configuration
 * @param handler - Business logic handler receiving the storage event
 * @returns A deployed Cloud Function
 */
export function defineStorageTrigger(
    bucket: string | undefined,
    options: FunctionOptions,
    handler: (event: { data: { name: string; bucket: string; contentType?: string; size?: number } }) => Promise<void>
) {
    const storageOpts = {
        bucket,
        region: (options.region as any) || 'us-central1',
        memory: options.memory,
        timeoutSeconds: options.timeoutSeconds,
    };
    return onObjectFinalized(storageOpts, async (event) => {
        await handler({
            data: {
                name: event.data.name,
                bucket: event.data.bucket,
                contentType: event.data.contentType,
                size: Number(event.data.size) || 0,
            },
        });
    });
}

/**
 * BigQuery Pipeline Tests
 *
 * Tests for event batching, sampling, deduplication
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { AnalyticsEvent } from '@indii/shared';

describe('BigQueryEventsPipeline', () => {
  const SAMPLING_RATE = 0.1;

  describe('Event Sampling', () => {
    it('should sample approximately 10% of events', () => {
      const sampleSize = 10000;
      const sampledCount = Array.from({ length: sampleSize }).filter(() =>
        Math.random() < SAMPLING_RATE
      ).length;

      // Should be approximately 10% (with some variance)
      expect(sampledCount).toBeGreaterThan(sampleSize * 0.08);
      expect(sampledCount).toBeLessThan(sampleSize * 0.12);
    });

    it('should not sample all events for cost control', () => {
      const allSampled = Array.from({ length: 100 }).every(() => true);
      expect(allSampled).toBe(true); // Only test if every sample passes

      // In real scenario, most events should be filtered out
      const actualSampledCount = Array.from({ length: 100 }).filter(
        () => Math.random() < SAMPLING_RATE
      ).length;
      expect(actualSampledCount).toBeLessThan(100); // Not all sampled
    });
  });

  describe('Event Deduplication', () => {
    it('should generate unique idempotency keys', () => {
      const event: AnalyticsEvent = {
        id: 'event1',
        eventType: 'user_action',
        userId: 'user123',
        sessionId: 'session123',
        timestamp: '2026-04-24T12:00:00Z',
        data: {},
      };

      // Simulate key generation
      const key1 = `${event.userId}-${event.eventType}-${event.timestamp}-${Math.random().toString(36).substr(2, 9)}`;
      const key2 = `${event.userId}-${event.eventType}-${event.timestamp}-${Math.random().toString(36).substr(2, 9)}`;

      expect(key1).not.toBe(key2); // Different due to random suffix
      expect(key1).toContain('user123');
    });

    it('should detect duplicate events within dedup window', () => {
      const now = Date.now();
      const withinWindow = now - 30000; // 30 seconds ago
      const outsideWindow = now - 120000; // 2 minutes ago

      const withinMs = now - withinWindow;
      const outsideMs = now - outsideWindow;

      expect(withinMs).toBeLessThan(60000); // Within 1-minute window
      expect(outsideMs).toBeGreaterThan(60000); // Outside window
    });
  });

  describe('Event Batching', () => {
    it('should batch events into groups of 100', () => {
      const BATCH_SIZE = 100;
      const totalEvents = 250;

      const batches = Math.ceil(totalEvents / BATCH_SIZE);
      expect(batches).toBe(3); // 3 batches: 100, 100, 50
    });

    it('should handle partial batches', () => {
      const BATCH_SIZE = 100;
      const events = Array.from({ length: 45 });

      const batches = Math.ceil(events.length / BATCH_SIZE);
      expect(batches).toBe(1);
      expect(events.length % BATCH_SIZE).toBe(45);
    });
  });

  describe('Row Preparation', () => {
    it('should add metadata to BigQuery rows', () => {
      const event: AnalyticsEvent = {
        id: 'evt1',
        eventType: 'track_created',
        userId: 'user1',
        sessionId: 'sess1',
        timestamp: '2026-04-24T12:00:00Z',
        data: { trackTitle: 'My Song' },
      };

      const row = {
        ...event,
        _idempotencyKey: 'unique-key',
        _timestamp: new Date().toISOString(),
      };

      expect(row._idempotencyKey).toBeDefined();
      expect(row._timestamp).toBeDefined();
      expect(row.eventType).toBe('track_created');
    });
  });

  describe('Firestore Triggers', () => {
    it('should trigger on document creation', () => {
      const collectionPath = 'events/{eventId}';
      expect(collectionPath).toContain('events');
    });

    it('should filter events by type', () => {
      const eventType = 'user_action';
      const eventTypes = ['user_action', 'track_created', 'distribution_started'];

      expect(eventTypes).toContain(eventType);
    });
  });

  describe('Scheduled Processing', () => {
    it('should batch every 5 minutes', () => {
      const schedule = 'every 5 minutes';
      const intervalMs = 5 * 60 * 1000;

      expect(intervalMs).toBe(300000);
      expect(schedule).toContain('5');
    });

    it('should process up to BATCH_SIZE events', () => {
      const BATCH_SIZE = 100;
      const processedCount = Math.min(250, BATCH_SIZE);

      expect(processedCount).toBe(100);
    });
  });

  describe('Error Handling', () => {
    it('should handle missing _bigQuerySynced flag', () => {
      const doc = { data: { eventType: 'user_action' } };
      const synced = doc.data._bigQuerySynced || false;

      expect(synced).toBe(false);
    });

    it('should handle partial failure on insert', () => {
      const errorName = 'PartialFailureError';
      const isPartialFailure = errorName === 'PartialFailureError';

      expect(isPartialFailure).toBe(true);
    });

    it('should skip duplicate events without throwing', () => {
      const isDuplicate = true;
      const shouldSkip = isDuplicate;

      expect(shouldSkip).toBe(true);
    });
  });

  describe('Event Data Validation', () => {
    it('should require eventType field', () => {
      const event: any = {
        id: 'evt1',
        userId: 'user1',
        timestamp: '2026-04-24T12:00:00Z',
        data: {},
      };

      const isValid = 'eventType' in event;
      expect(isValid).toBe(false);
    });

    it('should require userId field', () => {
      const event: AnalyticsEvent = {
        id: 'evt1',
        eventType: 'user_action',
        userId: 'user1',
        sessionId: 'sess1',
        timestamp: '2026-04-24T12:00:00Z',
        data: {},
      };

      expect(event.userId).toBeDefined();
    });

    it('should allow optional sessionId', () => {
      const event: Partial<AnalyticsEvent> = {
        id: 'evt1',
        eventType: 'user_action',
        userId: 'user1',
        timestamp: '2026-04-24T12:00:00Z',
      };

      // sessionId is optional
      expect('sessionId' in event).toBe(false);
    });
  });

  describe('Cost Control', () => {
    it('should reduce BigQuery costs via sampling', () => {
      const fullCost = 100; // Arbitrary units
      const sampledCost = fullCost * SAMPLING_RATE;

      expect(sampledCost).toBe(10);
      expect(sampledCost).toBeLessThan(fullCost);
    });

    it('should deduplicate to avoid extra rows', () => {
      const duplicates = 5;
      const unique = 1;

      const savedRows = duplicates - unique;
      expect(savedRows).toBe(4);
    });
  });
});

/**
 * BigQueryEventsPipeline — Stream analytics events to BigQuery
 *
 * Batch events from Firestore and stream to BigQuery with:
 * - 10% sampling for cost control
 * - Event deduplication using idempotency keys
 * - Automatic schema validation
 */

import { onDocumentCreated, QueryDocumentSnapshot, FirestoreEvent } from 'firebase-functions/v2/firestore';
import { onSchedule } from 'firebase-functions/v2/scheduler';
import * as admin from 'firebase-admin';
import { BigQuery } from '@google-cloud/bigquery';
import type { AnalyticsEvent } from '@indii/shared';

const db = admin.firestore();
const bigquery = new BigQuery({
  projectId: process.env.GCLOUD_PROJECT,
});

interface BigQueryRow extends AnalyticsEvent {
  _idempotencyKey?: string;
  _timestamp: string;
}

const DATASET_ID = 'analytics';
const TABLE_ID = 'events';
const SAMPLING_RATE = 0.1; // 10% sampling
const BATCH_SIZE = 100;


/**
 * Generate idempotency key to prevent duplicates
 * Format: userId-eventType-timestamp-hash
 */
function generateIdempotencyKey(event: AnalyticsEvent): string {
  const hash = Math.random().toString(36).substr(2, 9);
  return `${event.userId}-${event.eventType}-${event.timestamp}-${hash}`;
}

/**
 * Check if event is duplicate (within dedup window)
 */
async function isDuplicate(idempotencyKey: string): Promise<boolean> {
  const query = `
    SELECT COUNT(*) as count FROM \`${process.env.GCLOUD_PROJECT}.${DATASET_ID}.${TABLE_ID}\`
    WHERE _idempotencyKey = @key
    AND TIMESTAMP_MILLIS(_timestamp) > TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 1 MINUTE)
  `;

  try {
    const options = {
      query,
      params: { key: idempotencyKey },
    };
    const [rows] = await bigquery.query(options);
    return rows.length > 0 && rows[0].count > 0;
  } catch (err) {
    console.error('[BigQueryEventsPipeline] Dedup check failed:', err);
    return false; // Fail open to allow event through
  }
}

/**
 * Should event be sampled? (10% by default)
 */
function shouldSample(): boolean {
  return Math.random() < SAMPLING_RATE;
}

/**
 * Stream events from Firestore to BigQuery
 */
async function streamEventsToBigQuery(events: AnalyticsEvent[]): Promise<void> {
  if (events.length === 0) return;

  const table = bigquery.dataset(DATASET_ID).table(TABLE_ID);
  const rows: BigQueryRow[] = [];

  // Filter and prepare rows
  for (const event of events) {
    if (!shouldSample()) continue;

    const idempotencyKey = generateIdempotencyKey(event);
    const isDupe = await isDuplicate(idempotencyKey);
    if (isDupe) {
      console.log('[BigQueryEventsPipeline] Skipping duplicate event:', idempotencyKey);
      continue;
    }

    rows.push({
      ...event,
      _idempotencyKey: idempotencyKey,
      _timestamp: new Date().toISOString(),
    });
  }

  if (rows.length === 0) return;

  // Batch insert into BigQuery
  try {
    const result = await table.insert(rows);
    console.log(`[BigQueryEventsPipeline] Inserted ${result.length} rows`);
  } catch (err: any) {
    if (err.name === 'PartialFailureError') {
      console.warn('[BigQueryEventsPipeline] Partial insert failure:', err.errors);
    } else {
      throw err;
    }
  }
}

/**
 * Scheduled function: Batch events to BigQuery every 5 minutes
 */
export const batchEventsScheduled = onSchedule(
  {
    schedule: 'every 5 minutes',
    timeoutSeconds: 300,
    memory: '512MiB',
  },
  async () => {
    try {
      const snapshot = await db.collection('events')
        .orderBy('timestamp', 'desc')
        .limit(BATCH_SIZE)
        .get();

      if (snapshot.empty) {
        console.log('[BigQueryEventsPipeline] No events to process');
        return;
      }

      const events = snapshot.docs.map(doc => ({
        eventId: doc.id,
        ...doc.data(),
      } as unknown as AnalyticsEvent));

      await streamEventsToBigQuery(events);

      // Mark batch as processed (optional: add processedAt timestamp)
      const batch = db.batch();
      snapshot.docs.forEach(doc => {
        batch.update(doc.ref, { _bigQuerySynced: true });
      });
      await batch.commit();
    } catch (err) {
      console.error('[BigQueryEventsPipeline] Batch failed:', err);
      throw err;
    }
  }
);

/**
 * Firestore trigger: Stream events in real-time (sampled)
 */
export const streamEventOnCreate = onDocumentCreated('events/{eventId}', async (event: FirestoreEvent<QueryDocumentSnapshot | undefined, { eventId: string }>) => {
    try {
      if (!shouldSample()) return;

      const data = event.data?.data();
      if (!data) return;

      const analyticsEvent: AnalyticsEvent = {
        eventId: data.eventId || event.params.eventId,
        eventType: data.eventType,
        userId: data.userId,
        timestamp: data.timestamp,
        data: data.data || {},
      };

      const idempotencyKey = generateIdempotencyKey(analyticsEvent);
      const isDupe = await isDuplicate(idempotencyKey);
      if (isDupe) {
        console.log('[BigQueryEventsPipeline] Skipping duplicate:', idempotencyKey);
        return;
      }

      const table = bigquery.dataset(DATASET_ID).table(TABLE_ID);
      const row: BigQueryRow = {
        ...analyticsEvent,
        _idempotencyKey: idempotencyKey,
        _timestamp: new Date().toISOString(),
      };

      await table.insert([row]);
      console.log('[BigQueryEventsPipeline] Streamed event:', analyticsEvent.eventId);
    } catch (err) {
      console.error('[BigQueryEventsPipeline] Stream failed:', err);
      // Non-blocking: don't throw to prevent retry loop
    }
  });

