/**
 * WebhookDispatcher — Deliver webhook events with retry logic
 *
 * Features:
 * - HMAC-SHA256 signature verification
 * - Exponential backoff retry (3 attempts)
 * - Dead letter queue for failed webhooks
 * - Event deduplication with idempotency keys
 */

import { onDocumentCreated } from 'firebase-functions/v2/firestore';
import { onSchedule } from 'firebase-functions/v2/scheduler';
import { onRequest } from 'firebase-functions/v2/https';
import * as express from 'express';
import * as admin from 'firebase-admin';
import * as crypto from 'crypto';

const db = admin.firestore();

interface Webhook {
  id: string;
  userId: string;
  url: string;
  secret: string;
  events: string[];
  active: boolean;
  createdAt: string;
}

interface WebhookEvent {
  eventId: string;
  webhookId: string;
  eventType: string;
  payload: Record<string, unknown>;
  timestamp: string;
  attempt: number;
  maxAttempts: number;
  nextRetry?: string;
  error?: string;
}

/**
 * Generate HMAC-SHA256 signature for webhook
 */
function generateSignature(secret: string, payload: string): string {
  return crypto
    .createHmac('sha256', secret)
    .update(payload)
    .digest('hex');
}

/**
 * Verify webhook signature
 */
export function verifySignature(secret: string, signature: string, payload: string): boolean {
  const expected = generateSignature(secret, payload);
  return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
}

/**
 * Calculate exponential backoff delay (in milliseconds)
 * Attempt 0: 1s, Attempt 1: 2s, Attempt 2: 4s
 */
function getBackoffDelay(attempt: number): number {
  return Math.pow(2, attempt) * 1000;
}

/**
 * Deliver webhook to endpoint with timeout
 */
async function deliverWebhook(
  webhook: Webhook,
  event: WebhookEvent,
  payload: string
): Promise<{ success: boolean; status?: number; error?: string }> {
  const signature = generateSignature(webhook.secret, payload);
  const timeout = 10000; // 10 seconds

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    const response = await fetch(webhook.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-indii-Signature': signature,
        'X-indii-Event-ID': event.eventId,
        'X-indii-Event-Type': event.eventType,
        'X-indii-Timestamp': event.timestamp,
      },
      body: payload,
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    // 2xx and 3xx are success
    if (response.status >= 200 && response.status < 400) {
      return { success: true, status: response.status };
    }

    // 4xx errors are not retryable
    if (response.status >= 400 && response.status < 500) {
      return {
        success: false,
        status: response.status,
        error: `HTTP ${response.status}`,
      };
    }

    // 5xx errors are retryable
    return {
      success: false,
      status: response.status,
      error: `HTTP ${response.status}`,
    };
  } catch (err: any) {
    const errorMsg = err?.message || 'Unknown error';
    return { success: false, error: errorMsg };
  }
}

/**
 * Schedule webhook retry
 */
async function scheduleRetry(
  event: WebhookEvent,
  backoffMs: number
): Promise<void> {
  const nextRetry = new Date(Date.now() + backoffMs).toISOString();
  await db.collection('webhook_queue').doc(event.eventId).update({
    attempt: event.attempt + 1,
    nextRetry,
    error: null,
  });
  console.log(`[WebhookDispatcher] Scheduled retry for ${event.eventId} in ${backoffMs}ms`);
}

/**
 * Mark webhook as failed (dead letter)
 */
async function markFailed(
  event: WebhookEvent,
  reason: string
): Promise<void> {
  await db.collection('webhook_deadletter').doc(event.eventId).set({
    ...event,
    failedAt: new Date().toISOString(),
    reason,
  });
  await db.collection('webhook_queue').doc(event.eventId).delete();
  console.error(`[WebhookDispatcher] Webhook ${event.eventId} moved to dead letter: ${reason}`);
}

/**
 * Process webhook delivery
 */
async function processWebhookDelivery(
  event: WebhookEvent,
  webhook: Webhook
): Promise<void> {
  const payload = JSON.stringify({
    id: event.eventId,
    type: event.eventType,
    data: event.payload,
    timestamp: event.timestamp,
  });

  const result = await deliverWebhook(webhook, event, payload);

  if (result.success) {
    await db.collection('webhook_queue').doc(event.eventId).delete();
    console.log(`[WebhookDispatcher] Webhook ${event.eventId} delivered successfully`);
    return;
  }

  // Non-retryable 4xx errors
  if (result.status && result.status >= 400 && result.status < 500) {
    await markFailed(event, `${result.error} (non-retryable)`);
    return;
  }

  // Retryable errors
  if (event.attempt < event.maxAttempts - 1) {
    const backoffMs = getBackoffDelay(event.attempt);
    await scheduleRetry(event, backoffMs);
  } else {
    await markFailed(event, `Max retries exceeded: ${result.error}`);
  }
}

/**
 * Firestore trigger: Send webhook when event created
 */
export const sendWebhookOnEvent = onDocumentCreated('events/{eventId}', async (change) => {
    try {
      const eventData = change.data?.data();
      if (!eventData) return;

      const userId = eventData.userId;
      const eventType = eventData.eventType;

      // Find webhooks subscribed to this event type
      const webhookSnapshot = await db
        .collection('users').doc(userId).collection('webhooks')
        .where('active', '==', true)
        .where('events', 'array-contains', eventType)
        .get();

      if (webhookSnapshot.empty) {
        console.log(`[WebhookDispatcher] No webhooks for event type: ${eventType}`);
        return;
      }

      // Queue webhook deliveries
      const webhookEvents: WebhookEvent[] = [];
      webhookSnapshot.docs.forEach(doc => {
        const webhook = doc.data() as Webhook;
        const eventId = `${change.data?.id}-${webhook.id}`;

        webhookEvents.push({
          eventId,
          webhookId: webhook.id,
          eventType,
          payload: eventData.data || {},
          timestamp: new Date().toISOString(),
          attempt: 0,
          maxAttempts: 3,
        });
      });

      // Batch insert webhook events to queue
      const batch = db.batch();
      webhookEvents.forEach(we => {
        batch.set(db.collection('webhook_queue').doc(we.eventId), we);
      });
      await batch.commit();

      console.log(`[WebhookDispatcher] Queued ${webhookEvents.length} webhooks`);
    } catch (err) {
      console.error('[WebhookDispatcher] Event trigger failed:', err);
    }
  });

/**
 * Scheduled function: Process webhook queue every 30 seconds
 */
export const processWebhookQueue = onSchedule(
  {
    schedule: 'every 30 seconds',
    timeoutSeconds: 300,
    memory: '256MiB',
  },
  async () => {
    try {
      const now = new Date().toISOString();

      // Get pending webhooks (no nextRetry or nextRetry in past)
      const snapshot = await db
        .collection('webhook_queue')
        .where('nextRetry', '<=', now)
        .limit(50)
        .get();

      if (snapshot.empty) {
        console.log('[WebhookDispatcher] No webhooks to process');
        return;
      }

      for (const doc of snapshot.docs) {
        const event = doc.data() as WebhookEvent;

        const webhook = await db
          .collection('users').doc(event.webhookId.split('-')[0])
          .collection('webhooks').doc(event.webhookId)
          .get();

        if (!webhook.exists) {
          await db.collection('webhook_queue').doc(doc.id).delete();
          console.warn(`[WebhookDispatcher] Webhook not found: ${event.webhookId}`);
          continue;
        }

        const webhookData = webhook.data() as Webhook;
        if (!webhookData.active) {
          await db.collection('webhook_queue').doc(doc.id).delete();
          continue;
        }

        await processWebhookDelivery(event, webhookData);
      }
    } catch (err) {
      console.error('[WebhookDispatcher] Queue processing failed:', err);
    }
  }
);

/**
 * HTTP endpoint: Create webhook subscription
 */
export const createWebhook = onRequest(async (req: express.Request, res: express.Response) => {
  try {
    const { userId, url, secret, events } = req.body;

    if (!userId || !url || !secret || !Array.isArray(events)) {
      res.status(400).json({ error: 'Missing required fields' });
      return;
    }

    const webhookId = db.collection('_').doc().id;
    const webhook: Webhook = {
      id: webhookId,
      userId,
      url,
      secret,
      events,
      active: true,
      createdAt: new Date().toISOString(),
    };

    await db.collection('users').doc(userId).collection('webhooks').doc(webhookId).set(webhook);
    res.status(201).json({ ...webhook, id: webhookId });
  } catch (err) {
    console.error('[WebhookDispatcher] Create webhook failed:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

import * as functions from "firebase-functions/v1";
import { GoogleGenAI } from "@google/genai";
import { FUNCTION_AI_MODELS, NANO_BANANA_CAPABILITIES, type NanoBananaTier } from "../config/models";
import {
    GenerateImageRequestSchema,
    EditImageRequestSchema,
    type EditImageRequest,
    type GenerateImageRequest,
} from "./image";

import { geminiApiKey, getGeminiApiKey } from "../config/secrets";
import { enforceRateLimit, RATE_LIMITS } from "./rateLimit";

// ============================================================================
// TYPES
// ============================================================================

interface ImageResult {
    bytesBase64Encoded: string;
    mimeType: string;
}

interface GenerateResponse {
    images: ImageResult[];
    textNarration?: string;
    thoughtSignature?: string;
    groundingMetadata?: Record<string, unknown>;
    aiMetadata: Record<string, unknown>;
    aiGenerationInfo: Record<string, unknown>;
}

interface EditResponse {
    base64: string;
    mimeType: string;
    textNarration?: string;
    thoughtSignature?: string;
    groundingMetadata?: Record<string, unknown>;
    aiMetadata: Record<string, unknown>;
    aiGenerationInfo: Record<string, unknown>;
}

/**
 * Interface representing a part of the content in a Gemini API request or response.
 */
interface GeminiContentPart {
    text?: string;
    inlineData?: {
        mimeType: string;
        data: string;
    };
    thought?: boolean;
    thought_signature?: string;
    thoughtSignature?: string;
}

/**
 * Interface representing a candidate in the Gemini API response.
 */
interface GeminiCandidate {
    content?: {
        parts?: GeminiContentPart[];
    };
    finishReason?: string;
    safetyRatings?: any[];
    groundingMetadata?: Record<string, unknown>;
}

/**
 * Interface representing the structure of a Gemini generateContent response.
 */
interface GeminiGenerateContentResponse {
    candidates?: GeminiCandidate[];
}

// ============================================================================
// SERVICE
// ============================================================================

/**
 * GeminiImageService
 *
 * Centralized service for Nano Banana image generation and editing.
 * Supports all 3 tiers: Legacy (OG), Fast (Nano Banana 2), Pro (Nano Banana Pro).
 *
 * Full feature support:
 * - Text-to-image with configurable aspect ratio + resolution
 * - Multi-reference images (up to 14)
 * - Google Search + Image Search grounding
 * - Thinking level control + thought signature circulation
 * - Multi-turn conversation history for iterative editing
 * - Interleaved text + image output
 */
export class GeminiImageService {
    private client: GoogleGenAI | null = null;

    /**
     * Lazily initializes and returns the Google Gen AI client.
     * @returns The initialized GoogleGenAI instance.
     * @throws {functions.https.HttpsError} If the API key is missing or invalid.
     */
    private getClient(): GoogleGenAI {
        if (!this.client) {
            const apiKey = getGeminiApiKey();
            if (!apiKey || apiKey.includes("PLACEHOLDER")) {
                console.error("[GeminiImageService] Invalid or missing GEMINI_API_KEY. Operations will fail.");
                throw new functions.https.HttpsError("permission-denied", "Gemini API Key is missing or invalid.");
            }

            console.log(`[GeminiImageService] Initializing Google Gen AI Client (API_KEY: ${apiKey.substring(0, 4)}...)`);
            this.client = new GoogleGenAI({ apiKey });
        }
        return this.client;
    }

    /**
     * Resolves a NanoBananaTier to its corresponding model ID string.
     * @param tier - The tier to resolve.
     * @returns The model ID string (e.g., 'gemini-3.1-flash-image-preview').
     */
    private resolveModelId(tier: NanoBananaTier | undefined | null): string {
        switch (tier) {
            case "pro":
                return FUNCTION_AI_MODELS.IMAGE.GENERATION;
            case "legacy":
                return FUNCTION_AI_MODELS.IMAGE.LEGACY;
            case "fast":
            default:
                return FUNCTION_AI_MODELS.IMAGE.FAST;
        }
    }

    /**
     * Build the SDK config object from request parameters.
     * Maps our schema fields to the exact Gemini SDK config shape.
     * 
     * @param data - The raw request data from the client.
     * @param modelId - The resolved model ID string.
     * @returns A configuration object compatible with the Google Gen AI SDK.
     */
    private buildConfig(data: {
        aspectRatio?: string | null;
        imageSize?: string | null;
        thinkingLevel?: string | null;
        includeThoughts?: boolean | null;
        useGoogleSearch?: boolean | null;
        useImageSearch?: boolean | null;
        responseFormat?: string | null;
        count?: number | null;
        style?: string | null;
        quality?: string | null;
        seed?: number | null;
        personGeneration?: string | null;
        // Legacy compat
        thinking?: boolean | null;
        useGrounding?: boolean | null;
    }, modelId: string): Record<string, unknown> {
        const capabilities = NANO_BANANA_CAPABILITIES[modelId as keyof typeof NANO_BANANA_CAPABILITIES];
        const isPro = capabilities?.tier === "pro";

        // Response modalities
        const wantsText = data.responseFormat === "image_and_text";
        const responseModalities = wantsText ? ["TEXT", "IMAGE"] : ["IMAGE"];

        // Image config — always pass when we have values
        const imageConfig: Record<string, unknown> = {};
        if (data.aspectRatio) {
            imageConfig.aspectRatio = data.aspectRatio;
        }
        if (data.imageSize) {
            // Ensure lowercase k (API requires lowercase)
            imageConfig.imageSize = data.imageSize.toLowerCase();
        }
        if (data.style) {
            imageConfig.style = data.style;
        }
        if (data.quality) {
            imageConfig.quality = data.quality;
        }
        if (data.seed !== undefined && data.seed !== null) {
            imageConfig.seed = data.seed;
        }

        // Thinking config — Flash supports level control; Pro always thinks
        const thinkingConfig: Record<string, unknown> = {};
        const effectiveThinkingLevel = data.thinkingLevel || (data.thinking ? "high" : null);
        if (effectiveThinkingLevel && capabilities?.supportsThinkingControl) {
            // Flash: capitalize first letter for API ("minimal" → "Minimal", "high" → "High")
            thinkingConfig.thinkingLevel = effectiveThinkingLevel.charAt(0).toUpperCase() + effectiveThinkingLevel.slice(1);
        }
        if (data.includeThoughts) {
            thinkingConfig.includeThoughts = true;
        }

        // Grounding tools — use `tools` array (NOT deprecated `groundingConfig`)
        const effectiveUseSearch = data.useGoogleSearch || data.useGrounding;
        let tools: Record<string, unknown>[] | undefined;
        if (effectiveUseSearch) {
            if (data.useImageSearch && !isPro) {
                // Image Search: Flash only. Build searchTypes with both web + image.
                tools = [{
                    googleSearch: {
                        searchTypes: {
                            webSearch: {},
                            imageSearch: {},
                        },
                    },
                }];
            } else {
                // Standard Google Search grounding
                tools = [{ googleSearch: {} }];
            }
        }

        // Assemble config
        const config: Record<string, unknown> = {
            responseModalities,
        };

        if (data.personGeneration) {
            config.personGeneration = data.personGeneration;
        }

        // Pro only supports 1 candidate
        if (!isPro && data.count && data.count > 1) {
            config.candidateCount = data.count;
        }

        if (Object.keys(imageConfig).length > 0) {
            config.imageConfig = imageConfig;
        }

        if (Object.keys(thinkingConfig).length > 0) {
            config.thinkingConfig = thinkingConfig;
        }

        if (tools) {
            config.tools = tools;
        }

        return config;
    }

    /**
     * Build the contents array for the API call.
     * Handles: plain text, reference images, conversation history, and thought signatures.
     * 
     * @param data - The input data for building contents.
     * @param modelId - The Gemini model ID being used.
     * @returns An array of content objects for the Gemini model.
     */
    private buildContents(
        data: {
            prompt: string;
            images?: { mimeType: string; data: string }[] | null;
            conversationHistory?: { role: string; parts: Record<string, unknown>[] }[] | null;
            thoughtSignature?: string | null;
        },
        modelId: string
    ): Record<string, unknown>[] {
        const caps = NANO_BANANA_CAPABILITIES[modelId as keyof typeof NANO_BANANA_CAPABILITIES];
        const maxRefImages = caps?.maxReferenceImages ?? 0;

        // Multi-turn: if conversation history is provided, use it as the base
        // and append the new user message at the end
        if (data.conversationHistory && data.conversationHistory.length > 0) {
            const contents = [...data.conversationHistory];

            // Build the new user turn
            const userParts: Record<string, unknown>[] = [];

            // Add reference images first (if supported)
            if (maxRefImages > 0 && data.images && data.images.length > 0) {
                const imagesToAdd = data.images.slice(0, maxRefImages);
                for (const img of imagesToAdd) {
                    userParts.push({
                        inlineData: {
                            mimeType: img.mimeType,
                            data: img.data,
                        },
                    });
                }
            }

            // Text prompt
            userParts.push({ text: data.prompt });

            // Thought signature for reasoning continuity (Pro models)
            if (data.thoughtSignature) {
                userParts.push({ thought_signature: data.thoughtSignature });
            }

            contents.push({ role: "user", parts: userParts });
            return contents;
        }

        // Single-turn: build a flat contents array
        const parts: Record<string, unknown>[] = [];

        // Text prompt first
        parts.push({ text: data.prompt });

        // Reference images (if supported)
        if (maxRefImages > 0 && data.images && data.images.length > 0) {
            const imagesToAdd = data.images.slice(0, maxRefImages);
            for (const img of imagesToAdd) {
                parts.push({
                    inlineData: {
                        mimeType: img.mimeType,
                        data: img.data,
                    },
                });
            }
        }

        // Thought signature for reasoning continuity (Pro models)
        if (data.thoughtSignature) {
            parts.push({ thought_signature: data.thoughtSignature });
        }

        return [{ role: "user", parts }];
    }

    /**
     * Extracts results (images, text, thoughts) from the generic model response object.
     * 
     * @param response - The raw JSON result from the Gemini API.
     * @returns Extracted data including images, narrative text, and grounding metadata.
     * @throws {Error} If no candidates or content parts are found in the response.
     */
    private extractResults(response: unknown): {
        images: ImageResult[];
        textParts: string[];
        thoughtSignature?: string;
        groundingMetadata?: Record<string, unknown>;
    } {
        const result = response as GeminiGenerateContentResponse;
        const candidates = result.candidates;
        if (!candidates || candidates.length === 0) {
            throw new Error(`No candidates returned from Gemini API. Response keys: ${Object.keys(result).join(', ')}`);
        }

        const candidate = candidates[0];
        const parts = candidate?.content?.parts;
        if (!parts || parts.length === 0) {
            throw new Error(`No content parts in response. Finish reason: ${candidate?.finishReason || 'Unknown'}. Safety Ratings: ${JSON.stringify(candidate?.safetyRatings || [])}`);
        }

        const images: ImageResult[] = [];
        const textParts: string[] = [];
        let thoughtSignature: string | undefined;

        for (const part of parts) {
            // Skip thinking parts (thought: true) — they don't contain final output
            if (part.thought === true) {
                continue;
            }

            // Extract thought signature from non-thought parts
            if (part.thought_signature || part.thoughtSignature) {
                thoughtSignature = part.thought_signature || part.thoughtSignature;
            }

            // Image data
            if (part.inlineData) {
                images.push({
                    bytesBase64Encoded: part.inlineData.data,
                    mimeType: part.inlineData.mimeType || "image/png",
                });
            }

            // Text narration
            if (part.text && !part.thought) {
                textParts.push(part.text);
            }
        }

        // Extract grounding metadata (search results, source URLs)
        const groundingMetadata = candidate.groundingMetadata || undefined;

        return { images, textParts, thoughtSignature, groundingMetadata };
    }

    /**
     * Maps low-level Gemini API errors to structured Firebase Cloud Function errors.
     * 
     * @param error - The raw error object caught from the SDK.
     * @param context - Descriptive context (e.g., 'generate' or 'edit') for logging.
     * @returns This method never returns normally; it always throws.
     * @throws {functions.https.HttpsError} Structured error for the client.
     */
    private handleApiError(error: unknown, context: string): never {
        const err = error as Error & { status?: number };
        console.error(`[GeminiImageService:${context}] Error:`, err);

        const message = err.message || "Unknown Gemini API error";
        let status = err.status;

        // Handle fetch errors where we manually added status to the error message
        if (!status && message.includes("Vertex AI Image Edit API Error:")) {
            const match = message.match(/Error: (\d+)/);
            if (match) status = parseInt(match[1]);
        }

        console.error(`[GeminiImageService:${context}] Extracted Status: ${status} | Message: ${message}`);

        if (status === 400 || message.includes("400")) {
            throw new functions.https.HttpsError("invalid-argument", `Gemini API Request Error: ${message}`);
        }
        if (status === 401 || status === 403 || message.includes("401") || message.includes("403")) {
            throw new functions.https.HttpsError("permission-denied", `Gemini API Authentication Error: ${message}`);
        }
        if (status === 404 || message.includes("404")) {
            throw new functions.https.HttpsError("not-found", `Gemini API Resource Not Found: ${message}`);
        }
        if (status === 429 || message.includes("429")) {
            throw new functions.https.HttpsError("resource-exhausted", "Gemini API rate limit exceeded. Please try again later.");
        }
        if (status === 504 || status === 503 || message.includes("deadline") || err.name === 'AbortError') {
            throw new functions.https.HttpsError("deadline-exceeded", "Gemini API timed out during generation. The model may be overloaded.");
        }

        throw new functions.https.HttpsError("internal", `Gemini Image Generation Failed (${context}): ${message}`);
    }

    // ========================================================================
    // PUBLIC API
    // ========================================================================

    /**
     * Core Text-to-Image Generation
     *
     * Supports all 3 Nano Banana tiers with full feature passthrough:
     * - imageConfig (aspectRatio, imageSize)
     * - thinkingConfig (thinkingLevel, includeThoughts)
     * - tools (googleSearch, imageSearch)
     * - reference images (up to 14)
     * - multi-turn conversation history
     * - interleaved text + image output
     */
    async generate(data: GenerateImageRequest): Promise<GenerateResponse> {
        const tier = (data.model || "fast") as NanoBananaTier;
        const modelId = this.resolveModelId(tier);

        console.log(`[GeminiImageService:generate] Tier: ${tier} | Model: ${modelId} | Prompt: "${data.prompt.substring(0, 50)}..."`);

        try {
            const client = this.getClient();
            const config = this.buildConfig(data, modelId);
            const contents = this.buildContents(data, modelId);

            console.log(`[GeminiImageService:generate] Config:`, JSON.stringify({
                model: modelId,
                responseModalities: config.responseModalities,
                hasImageConfig: !!config.imageConfig,
                hasThinkingConfig: !!config.thinkingConfig,
                hasTools: !!config.tools,
                contentsTurns: contents.length,
                refImageCount: data.images?.length || 0,
            }));

            // Use a local interface to bypass SDK type mismatches for preview models 
            // without using 'any', satisfying strict CI linting requirements.
            const result = await (client.models as { 
                generateContent: (req: { model: string; contents: unknown; config: unknown }) => Promise<unknown> 
            }).generateContent({
                model: modelId,
                contents,
                config,
            });

            const extracted = this.extractResults(result);

            if (extracted.images.length === 0) {
                throw new Error("No image data found in response");
            }

            return {
                images: extracted.images,
                textNarration: extracted.textParts.length > 0
                    ? extracted.textParts.join("\n\n")
                    : undefined,
                thoughtSignature: extracted.thoughtSignature,
                groundingMetadata: extracted.groundingMetadata,
                aiMetadata: {
                    toolName: modelId,
                    tier,
                    generationType: "text-to-image",
                    isAIGenerated: true,
                    timestamp: new Date().toISOString(),
                    promptSnippet: data.prompt.substring(0, 100),
                    aspectRatio: data.aspectRatio || "1:1",
                    imageSize: data.imageSize || "1K",
                    referenceImageCount: data.images?.length || 0,
                    hasGrounding: !!(data.useGoogleSearch || data.useGrounding),
                    hasThinking: !!(data.thinkingLevel || data.thinking),
                    isMultiTurn: !!(data.conversationHistory && data.conversationHistory.length > 0),
                },
                aiGenerationInfo: {
                    isFullyAIGenerated: true,
                    isPartiallyAIGenerated: false,
                    aiToolsUsed: [modelId],
                    humanContributionDescription: `Generated via indii ${tier} using prompt: "${data.prompt.substring(0, 100)}..."`,
                },
            };
        } catch (error) {
            this.handleApiError(error, "generate");
        }
    }

    /**
     * Image Editing via Gemini generateContent
     *
     * Supports:
     * - Source image + text instruction
     * - Binary mask for inpainting
     * - Multiple reference images for composition
     * - Multi-turn conversation history for iterative editing
     * - Full config passthrough (imageConfig, thinkingConfig, tools)
     * - Thought signature circulation
     * 
     * @param data - The edit request containing source image, mask, and instructions.
     * @returns A promise resolving to the edited image and narration.
     */
    async edit(data: EditImageRequest): Promise<EditResponse> {
        // Resolve model — accept tier string or full model ID
        let modelId: string;
        if (data.model === "pro" || data.model === "fast" || data.model === "legacy") {
            modelId = this.resolveModelId(data.model as NanoBananaTier);
        } else if (data.model) {
            modelId = data.model;
        } else {
            modelId = FUNCTION_AI_MODELS.IMAGE.GENERATION; // Default to Pro for editing
        }

        console.log(`[GeminiImageService:edit] Model: ${modelId} | Prompt: "${data.prompt.substring(0, 50)}..."`);

        try {
            const client = this.getClient();

            // Build config with edit-specific fields
            const config = this.buildConfig({
                aspectRatio: data.aspectRatio,
                imageSize: data.imageSize,
                thinkingLevel: data.thinkingLevel,
                includeThoughts: data.includeThoughts,
                useGoogleSearch: data.useGoogleSearch,
                responseFormat: data.responseFormat,
                style: data.style,
                quality: data.quality,
                seed: data.seed,
                personGeneration: data.personGeneration,
            }, modelId);

            // Build contents for edit: text + source image + mask + reference images
            let contents: Record<string, unknown>[];
            const caps = NANO_BANANA_CAPABILITIES[modelId as keyof typeof NANO_BANANA_CAPABILITIES];
            const maxRefs = caps?.maxReferenceImages ?? 0;

            if (data.conversationHistory && data.conversationHistory.length > 0) {
                // Multi-turn edit: history + new turn
                contents = [...data.conversationHistory];

                const newParts: Record<string, unknown>[] = [];

                // Source image
                if (data.image) {
                    newParts.push({
                        inlineData: {
                            mimeType: data.imageMimeType || "image/png",
                            data: data.image,
                        },
                    });
                }

                // Mask
                if (data.mask) {
                    newParts.push({
                        inlineData: {
                            mimeType: data.maskMimeType || "image/png",
                            data: data.mask,
                        },
                    });
                }

                // Reference images (new array field)
                if (maxRefs > 0 && data.referenceImages && data.referenceImages.length > 0) {
                    const imagesToAdd = data.referenceImages.slice(0, maxRefs);
                    for (const ref of imagesToAdd) {
                        newParts.push({
                            inlineData: {
                                mimeType: ref.mimeType,
                                data: ref.data,
                            },
                        });
                    }
                }

                // Legacy single reference image (gate on maxRefs > 0 for consistency with single-turn)
                if (maxRefs > 0 && data.referenceImage && !data.referenceImages?.length) {
                    newParts.push({
                        inlineData: {
                            mimeType: data.refMimeType || "image/png",
                            data: data.referenceImage,
                        },
                    });
                }

                // Prompt text
                const promptText = data.mask
                    ? `Edit the masked region of this image according to this instruction: ${data.prompt}`
                    : data.prompt;
                newParts.push({ text: promptText });

                // Thought signature (circulate back exactly for continuity)
                if (data.thoughtSignature) {
                    newParts.push({ thought_signature: data.thoughtSignature });
                }

                contents.push({ role: "user", parts: newParts });
            } else {
                // Single-turn edit — images before text to match multi-turn ordering
                const parts: Record<string, unknown>[] = [];

                // Source image first (consistent with multi-turn ordering)
                if (data.image) {
                    parts.push({
                        inlineData: {
                            mimeType: data.imageMimeType || "image/png",
                            data: data.image,
                        },
                    });
                }

                // Mask
                if (data.mask) {
                    parts.push({
                        inlineData: {
                            mimeType: data.maskMimeType || "image/png",
                            data: data.mask,
                        },
                    });
                }

                const caps = NANO_BANANA_CAPABILITIES[modelId as keyof typeof NANO_BANANA_CAPABILITIES];
                const maxRefs = caps?.maxReferenceImages ?? 0;

                // Reference images (new array field)
                if (maxRefs > 0 && data.referenceImages && data.referenceImages.length > 0) {
                    const imagesToAdd = data.referenceImages.slice(0, maxRefs);
                    for (const ref of imagesToAdd) {
                        parts.push({
                            inlineData: {
                                mimeType: ref.mimeType,
                                data: ref.data,
                            },
                        });
                    }
                }

                // Legacy single reference image
                if (maxRefs > 1 && data.referenceImage && !data.referenceImages?.length) {
                    parts.push({
                        inlineData: {
                            mimeType: data.refMimeType || "image/png",
                            data: data.referenceImage,
                        },
                    });
                }

                // Prompt text last (after images — consistent with multi-turn ordering)
                const promptText = data.mask
                    ? `Edit the masked region of this image according to this instruction: ${data.prompt}`
                    : data.prompt;
                parts.push({ text: promptText });

                // Thought signature
                if (data.thoughtSignature) {
                    parts.push({ thought_signature: data.thoughtSignature });
                }

                contents = [{ role: "user", parts }];
            }

            // Use a local interface to bypass SDK type mismatches for preview models
            // without using 'any', satisfying strict CI linting requirements.
            const result = await (client.models as {
                generateContent: (req: { model: string; contents: unknown; config: unknown }) => Promise<unknown>
            }).generateContent({
                model: modelId,
                contents,
                config,
            });

            const extracted = this.extractResults(result);

            if (extracted.images.length === 0) {
                throw new Error("No image data found in edit response");
            }

            const primary = extracted.images[0]!;

            return {
                base64: primary.bytesBase64Encoded,
                mimeType: primary.mimeType,
                textNarration: extracted.textParts.length > 0
                    ? extracted.textParts.join("\n\n")
                    : undefined,
                thoughtSignature: extracted.thoughtSignature,
                groundingMetadata: extracted.groundingMetadata,
                aiMetadata: {
                    toolName: modelId,
                    generationType: "image-to-image",
                    isAIGenerated: true,
                    timestamp: new Date().toISOString(),
                    promptSnippet: data.prompt.substring(0, 100),
                    hasMultipleReferences: !!(data.referenceImages && data.referenceImages.length > 0),
                    hasMask: !!data.mask,
                    isMultiTurn: !!(data.conversationHistory && data.conversationHistory.length > 0),
                },
                aiGenerationInfo: {
                    isFullyAIGenerated: false,
                    baseModel: modelId,
                    generatorType: "cloud_function",
                },
            };
        } catch (error) {
            return this.handleApiError(error, "edit");
        }
    }
}

/** Singleton instance of GeminiImageService used by Cloud Functions */
const service = new GeminiImageService();

/**
 * Cloud Function: Text-to-Image Generation (V3)
 * 
 * Scalable entry point for generating images with Gemini 3.1+.
 * Enforces authentication, rate limits, and schema validation.
 */
export const generateImageV3Fn = () => functions
    .region("us-west1")
    .runWith({
        enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true',
        secrets: [geminiApiKey],
        timeoutSeconds: 120,
        // Bumped to 1GB: Pro 4K generation + long-context history needs parity with editImageFn
        memory: "1GB"
    })
    .https.onCall(async (data: unknown, context) => {
        // 1. Authenticate
        if (!context.auth) {
            throw new functions.https.HttpsError("unauthenticated", "User must be authenticated.");
        }

        // 1b. Rate limit — image generation is the highest-cost endpoint
        await enforceRateLimit(context.auth.uid, "generateImageV3", RATE_LIMITS.generation);

        // 2. Validate Input
        const validation = GenerateImageRequestSchema.safeParse(data);
        if (!validation.success) {
            throw new functions.https.HttpsError(
                "invalid-argument",
                `Validation failed: ${validation.error.issues.map(i => i.message).join(", ")}`
            );
        }

        // 3. Delegate to Service
        return await service.generate(validation.data);
    });

/**
 * Cloud Function: Image Editing (Inpainting/Outpainting)
 * 
 * Scalable entry point for editing images using Gemini.
 * Supports reference images, masks, and iterative turns.
 */
export const editImageFn = () => functions
    .region("us-west1")
    .runWith({
        enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true',
        secrets: [geminiApiKey],
        timeoutSeconds: 120,
        memory: "1GB" // Bumped from 512MB — editing with references + 4K can exceed 512MB
    })
    .https.onCall(async (data: unknown, context) => {
        // 1. Authenticate
        if (!context.auth) {
            throw new functions.https.HttpsError("unauthenticated", "User must be authenticated.");
        }

        // 1b. Rate limit — image editing is a high-cost operation
        await enforceRateLimit(context.auth.uid, "editImage", RATE_LIMITS.generation);

        // 2. Validate Input
        const validation = EditImageRequestSchema.safeParse(data);
        if (!validation.success) {
            throw new functions.https.HttpsError(
                "invalid-argument",
                `Validation failed: ${validation.error.issues.map(i => i.message).join(", ")}`
            );
        }

        // 3. Delegate to Service
        const result = await service.edit(validation.data);

        // Map to candidates format for frontend compatibility
        const candidates = [
            {
                content: {
                    parts: [
                        {
                            inlineData: {
                                mimeType: result.mimeType,
                                data: result.base64
                            }
                        }
                    ]
                }
            }
        ];

        return {
            candidates,
            textNarration: result.textNarration,
            thoughtSignature: result.thoughtSignature,
            groundingMetadata: result.groundingMetadata,
            aiMetadata: result.aiMetadata,
            aiGenerationInfo: result.aiGenerationInfo
        };
    });

/**
 * video_generation_direct.ts
 *
 * Video generation using the @google/genai SDK with Vertex AI backend.
 * Uses the same SDK methods as the Gemini API docs, but with vertexai:true
 * for production Cloud Functions (ADC auth, no API key needed).
 *
 * Previous approach used raw REST to Vertex AI predictLongRunning which returned 404.
 * The SDK handles endpoint routing automatically.
 */

import * as admin from "firebase-admin";
import { GoogleGenAI } from "@google/genai";
import { FUNCTION_AI_MODELS } from "../config/models";

/**
 * Sleep helper.
 */
const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/**
 * Fetch an image input (URL, data URI, or raw base64) and return pure base64 bytes.
 */
const fetchImageAsBase64 = async (input: string | undefined): Promise<string | undefined> => {
    if (!input) return undefined;
    if (input.startsWith('data:image')) {
        return input.replace(/^data:image\/\w+;base64,/, '');
    }
    if (input.startsWith('http')) {
        try {
            const res = await fetch(input);
            if (!res.ok) throw new Error(`Failed to fetch image: ${res.statusText}`);
            const buffer = await res.arrayBuffer();
            return Buffer.from(buffer).toString('base64');
        } catch (err) {
            console.error(`[VideoGenDirect] Failed to fetch frame from URL: ${input}`, err);
            return undefined;
        }
    }
    return input; // Assume raw base64
};

export interface DirectVideoGenerationParams {
    jobId: string;
    userId: string;
    orgId: string;
    prompt: string;
    options: Record<string, unknown>;
}

/**
 * Run video generation using the @google/genai SDK with Vertex AI backend.
 *
 * Pattern from official docs (https://ai.google.dev/gemini-api/docs/video):
 *   1. ai.models.generateVideos({ model, prompt, config }) → operation
 *   2. Poll with ai.operations.getVideosOperation({ operation })
 *   3. Result in operation.response.generatedVideos[0].video
 *   4. Extract video URI and update Firestore
 */
export async function generateVideoDirect(params: DirectVideoGenerationParams): Promise<void> {
    const { jobId, userId, prompt, options: rawOptions } = params;
    const options = rawOptions as Record<string, unknown>;
    const isThinking = options?.thinking === true;
    let finalPrompt = isThinking
        ? `[Think CINEMATIC PHYSICS & CONTINUITY]: ${prompt}`
        : prompt;

    if (finalPrompt.length > 500) {
        finalPrompt = finalPrompt.substring(0, 500);
    }

    console.log(`[VideoGenDirect] Starting for Job: ${jobId} (Thinking: ${isThinking})`);

    try {
        // ── Step 1: Update status to "processing" ──────────────────────────
        await admin.firestore().collection("videoJobs").doc(jobId).set({
            status: "processing",
            updatedAt: admin.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
        console.log(`[VideoGenDirect] Status → processing for ${jobId}`);

        // ── Step 2: Initialize SDK ─────────────────────────────────────────
        const { model: requestedModel } = options || {};
        const modelId = requestedModel === 'fast'
            ? FUNCTION_AI_MODELS.VIDEO.FAST
            : FUNCTION_AI_MODELS.VIDEO.PRO;

        // Vertex AI for production — ADC handles auth automatically in Cloud Functions
        const projectId = process.env.GCLOUD_PROJECT || process.env.GCP_PROJECT || 'indii-v-1-1';
        const ai = new GoogleGenAI({
            vertexai: true,
            project: projectId,
            location: 'us-central1',
        });

        console.log(`[VideoGenDirect] Using Vertex AI SDK with model: ${modelId}, project: ${projectId}`);

        // ── Step 3: Build config ───────────────────────────────────────────
        // Only include parameters confirmed by official docs:
        // aspectRatio, durationSeconds, personGeneration, resolution, numberOfVideos
        const config: Record<string, unknown> = {
            numberOfVideos: 1,
        };

        // Aspect ratio
        const aspectRatio = options?.aspectRatio;
        if (aspectRatio === "9:16" || aspectRatio === "16:9") {
            config.aspectRatio = aspectRatio;
        } else {
            config.aspectRatio = "16:9"; // Default
        }

        // Duration — must be 4, 5, 6, or 8
        const rawDuration = options.durationSeconds || options.duration;
        if (rawDuration) {
            let dur = typeof rawDuration === 'string' ? parseInt(rawDuration) : (rawDuration as number);
            if (dur <= 4) dur = 4;
            else if (dur <= 6) dur = 6; // strictly 4, 6, or 8 for Veo 3.1
            else dur = 8;
            config.durationSeconds = dur;
        }

        // Person generation — Veo 3.1 supports allow_adult, allow_all
        if (options.personGeneration) {
            config.personGeneration = options.personGeneration;
        }

        // Resolution — 720p, 1080p, 4k
        if (options.resolution && ['720p', '1080p', '4k'].includes(options.resolution as string)) {
            config.resolution = options.resolution;
        }

        // ── Step 4: Build image input if provided ──────────────────────────
        let imageInput: { imageBytes: string; mimeType: string } | undefined;

        let startImageBytes: string | undefined;
        const optImage = (options.image as Record<string, unknown>) || {};
        if (optImage.imageBytes) {
            startImageBytes = optImage.imageBytes as string;
        } else {
            startImageBytes = await fetchImageAsBase64(options.firstFrame as string);
        }
        if (startImageBytes) {
            imageInput = {
                imageBytes: startImageBytes,
                mimeType: "image/png",
            };
        }

        // ── Step 5: Call SDK — exact pattern from official docs ─────────────
        console.log(`[VideoGenDirect] Calling ai.models.generateVideos() with model: ${modelId}`);

        let operation;
        if (imageInput) {
            // Image-to-video
            operation = await ai.models.generateVideos({
                model: modelId,
                prompt: finalPrompt,
                image: imageInput,
                config: config,
            });
        } else {
            // Text-to-video
            operation = await ai.models.generateVideos({
                model: modelId,
                prompt: finalPrompt,
                config: config,
            });
        }

        console.log(`[VideoGenDirect] Operation created. Polling for completion...`);

        // ── Step 6: Poll for completion ────────────────────────────────────
        // Official pattern: ai.operations.getVideosOperation({ operation })
        let attempts = 0;
        const maxAttempts = 36; // 6 minutes at 10s intervals (video gen takes 11s-6min per docs)

        while (!operation.done && attempts < maxAttempts) {
            attempts++;
            await sleep(10000); // 10 second intervals per official docs

            // Update progress in Firestore every 3 polls
            if (attempts % 3 === 0) {
                const progress = Math.min(90, Math.round((attempts / maxAttempts) * 100));
                await admin.firestore().collection("videoJobs").doc(jobId).set({
                    progress: progress,
                    updatedAt: admin.firestore.FieldValue.serverTimestamp()
                }, { merge: true });
                console.log(`[VideoGenDirect] Poll ${attempts}/${maxAttempts} (${progress}%) for ${jobId}`);
            }

            try {
                operation = await ai.operations.getVideosOperation({ operation });
            } catch (pollErr: unknown) {
                const err = pollErr as Error;
                console.warn(`[VideoGenDirect] Poll attempt ${attempts} failed: ${err.message}`);
                if (attempts >= maxAttempts) {
                    throw new Error(`Polling failed after ${attempts} attempts: ${err.message}`);
                }
            }
        }

        if (!operation.done) {
            throw new Error(`Video generation timed out after ${attempts * 10}s.`);
        }

        console.log(`[VideoGenDirect] Operation complete for ${jobId}`);

        // ── Step 7: Extract video from response ────────────────────────────
        const response = operation.response as unknown as { generatedVideos?: Array<Record<string, unknown>> };
        if (!response) {
            const opAny = operation as unknown as { error?: { message?: string } };
            if (opAny.error) {
                console.error(`[VideoGenDirect] Vertex AI Operation Error details:`, JSON.stringify(opAny.error, null, 2));
                throw new Error(`Vertex AI API Error: ${opAny.error.message || JSON.stringify(opAny.error)}`);
            }
            throw new Error("No response in completed operation");
        }

        const generatedVideos = response.generatedVideos;
        if (!generatedVideos || generatedVideos.length === 0) {
            throw new Error("No generated videos in response: " + JSON.stringify(response));
        }

        const videoResult = generatedVideos[0];
        const video = videoResult.video;

        console.log(`[VideoGenDirect] Video result keys:`, Object.keys(videoResult));
        if (video) {
            console.log(`[VideoGenDirect] Video object keys:`, Object.keys(video));
        }

        let videoUrl: string = "";
        const durationSec = config.durationSeconds || 5;
        const resolutionStr = config.resolution || "720p";

        // ALWAYS download the video and upload to Firebase Storage, 
        // as raw Google API URIs require authentication to play in the browser.

        const targetBucketName = (process.env.VITE_FIREBASE_STORAGE_BUCKET || 'indii-alpha-electron.appspot.com').replace('.appspot.com', '');

        // Check for bytesBase64Encoded or videoBytes inline first
        const videoObj = video as Record<string, unknown>;
        const base64Data = videoObj.bytesBase64Encoded || videoObj.videoBytes;
        if (base64Data) {
            console.log(`[VideoGenDirect] Got inline base64 video, uploading to Storage ${targetBucketName}...`);
            const bucket = admin.storage().bucket(targetBucketName);
            const filePath = `videos/${userId}/${jobId}.mp4`;
            const file = bucket.file(filePath);

            // Depending on SDK version, videoBytes might be a string (base64) or Uint8Array. 
            // Buffer.from works well with string ('base64' encoding) or raw byte arrays.
            let buffer: Buffer;
            if (typeof base64Data === 'string') {
                buffer = Buffer.from(base64Data, 'base64');
            } else {
                buffer = Buffer.from(base64Data as Uint8Array);
            }

            await file.save(buffer, {
                metadata: { contentType: 'video/mp4' },
                public: true
            });
            videoUrl = file.publicUrl();
            console.log(`[VideoGenDirect] Uploaded to Firebase Storage from inline bytes: ${videoUrl}`);
        }

        // Otherwise, download via SDK file API
        if (!videoUrl && videoObj.name) {
            console.log(`[VideoGenDirect] Attempting SDK file download for: ${videoObj.name}`);
            try {
                const tmpPath = `/tmp/${jobId}.mp4`;
                // Cast to any for the external API call where the SDK type is complex
                await ai.files.download({ file: videoObj as any, downloadPath: tmpPath });

                // Read from tmp and upload to Storage
                const fs = await import("fs");
                const videoBuffer = fs.readFileSync(tmpPath);
                const bucket = admin.storage().bucket(targetBucketName);
                const filePath = `videos/${userId}/${jobId}.mp4`;
                const storageFile = bucket.file(filePath);
                await storageFile.save(videoBuffer, {
                    metadata: { contentType: 'video/mp4' },
                    public: true
                });
                videoUrl = storageFile.publicUrl();
                console.log(`[VideoGenDirect] Downloaded via SDK and uploaded: ${videoUrl}`);

                // Clean up tmp
                if (fs.existsSync(tmpPath)) {
                    fs.unlinkSync(tmpPath);
                }
            } catch (downloadErr: unknown) {
                console.error(`[VideoGenDirect] SDK file download failed:`, downloadErr);
            }
        }

        // Fallback: If it gave us a URI, try fetching it directly with the API key or ADC
        if (!videoUrl && videoObj.uri) {
            const vUri = videoObj.uri as string;
            console.log(`[VideoGenDirect] Attempting fetch fallback from URI: ${vUri}`);
            try {
                const apiKey = process.env.GEMINI_API_KEY || process.env.GOOGLE_GENAI_API_KEY;
                const fetchUrl = apiKey && !vUri.includes('key=') ? `${vUri}&key=${apiKey}` : vUri;
                const res = await fetch(fetchUrl);
                if (!res.ok) throw new Error(`HTTP ${res.status} - ${res.statusText}`);
                const arrayBuf = await res.arrayBuffer();
                const buffer = Buffer.from(arrayBuf);

                const bucket = admin.storage().bucket();
                const filePath = `videos/${userId}/${jobId}.mp4`;
                const file = bucket.file(filePath);
                await file.save(buffer, {
                    metadata: { contentType: 'video/mp4' },
                    public: true
                });
                videoUrl = file.publicUrl();
                console.log(`[VideoGenDirect] Fetched directly from URI and uploaded: ${videoUrl}`);
            } catch (err: unknown) {
                console.error(`[VideoGenDirect] URI fetch fallback failed:`, err);
            }
        }

        if (!videoUrl) {
            // Strip out massive buffers to prevent Firestore 1MB document limit crashes
            const safeOutputKeys = generatedVideos.map((v: Record<string, unknown>) => Object.keys((v?.video as Record<string, unknown>) || {}));
            throw new Error(`No video URL or downloadable video in response. Available keys: ${JSON.stringify(safeOutputKeys)}`);
        }

        // ── Step 8: Update Firestore → "completed" ────────────────────────
        await admin.firestore().collection("videoJobs").doc(jobId).set({
            status: "completed",
            videoUrl: videoUrl,
            progress: 100,
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
            output: {
                url: videoUrl,
                metadata: {
                    duration_seconds: durationSec,
                    fps: options?.fps || 24,
                    mime_type: "video/mp4",
                    resolution: resolutionStr,
                }
            }
        }, { merge: true });

        console.log(`[VideoGenDirect] ✅ Job ${jobId} completed. Video: ${videoUrl}`);

    } catch (error: unknown) {
        const err = error as Error;
        console.error(`[VideoGenDirect] ❌ Error in Video Generation (${jobId}):`, err);
        await admin.firestore().collection("videoJobs").doc(jobId).set({
            status: "failed",
            error: err.message || "Unknown error during video generation",
            updatedAt: admin.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
    }
}

import * as admin from 'firebase-admin';
import * as functions from 'firebase-functions/v1';

export async function checkRateLimit(
    userId: string,
    endpoint: string,
    maxRequests: number = 60,
    windowMs: number = 60000
): Promise<{ allowed: boolean; remaining: number }> {
    const now = Date.now();
    const windowStart = Math.floor(now / windowMs) * windowMs;
    const key = `rate_limit:${endpoint}:${userId}:${windowStart}`;
    const ref = admin.firestore().collection('_rate_limits').doc(key);

    return admin.firestore().runTransaction(async (tx) => {
        const doc = await tx.get(ref);
        const count = doc.exists ? (doc.data()?.count || 0) : 0;
        if (count >= maxRequests) {
            return { allowed: false, remaining: 0 };
        }
        tx.set(ref, { count: count + 1, expiresAt: windowStart + windowMs });
        return { allowed: true, remaining: maxRequests - count - 1 };
    });
}

export function withRateLimit<T>(
    handler: (data: T, ctx: functions.https.CallableContext) => Promise<any>,
    config: { endpoint: string; maxRequests?: number }
) {
    return async (data: T, ctx: functions.https.CallableContext) => {
        if (!ctx.auth) throw new functions.https.HttpsError('unauthenticated', 'Auth required');
        const result = await checkRateLimit(ctx.auth.uid, config.endpoint, config.maxRequests);
        if (!result.allowed) {
            throw new functions.https.HttpsError('resource-exhausted', 'Rate limit exceeded');
        }
        return handler(data, ctx);
    };
}

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import fetch from 'node-fetch';

const PRINTFUL_API_KEY = process.env.PRINTFUL_API_KEY;
const BASE_URL = 'https://api.printful.com';

async function request<T>(endpoint: string, options: any = {}): Promise<T> {
    if (!PRINTFUL_API_KEY) {
        throw new HttpsError('internal', 'Printful API key not configured.');
    }

    const response = await fetch(`${BASE_URL}${endpoint}`, {
        ...options,
        headers: {
            'Authorization': `Bearer ${PRINTFUL_API_KEY}`,
            'Content-Type': 'application/json',
            ...options.headers
        }
    });

    if (!response.ok) {
        const errorBody = await response.json().catch(() => ({ message: response.statusText }));
        throw new HttpsError('internal', `Printful API error: ${errorBody.error?.message || errorBody.message || response.statusText}`);
    }

    const data = await response.json();
    return data.result as T;
}

