/**
 * Firebase Cloud Function: Cancel Subscription
 *
 * Cancels subscription at the end of current billing period.
 */

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import { getFirestore } from 'firebase-admin/firestore';
import { stripe, mapStripeStatus } from '../stripe/config';
import { stripeSecretKey } from '../config/secrets';

export const cancelSubscription = onCall({
  secrets: [stripeSecretKey],
  timeoutSeconds: 30,
  memory: '128MiB',
  enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true',
}, async (request) => {
  const { userId } = request.data;

  if (!userId || userId !== request.auth?.uid) {
    throw new HttpsError('unauthenticated', 'Unauthorized');
  }

  try {
    const db = getFirestore();
    const subscriptionDoc = await db.collection('subscriptions').doc(userId).get();

    if (!subscriptionDoc.exists) {
      throw new HttpsError('not-found', 'Subscription not found');
    }

    const subscription = subscriptionDoc.data();

    if (!subscription) {
      throw new HttpsError('not-found', 'Subscription data not found');
    }

    const stripeCustomerId = subscription.stripeCustomerId;
    const stripeSubscriptionId = subscription.stripeSubscriptionId;

    if (!stripeCustomerId || !stripeSubscriptionId) {
      throw new HttpsError('failed-precondition', 'No active subscription found');
    }

    if (subscription.cancelAtPeriodEnd) {
      console.log(`[cancelSubscription] Subscription for ${userId} already set to cancel.`);
      return { success: true };
    }

    // Cancel at period end in Stripe
    const stripeSubscription = await stripe.subscriptions.update(stripeSubscriptionId, {
      cancel_at_period_end: true
    });

    // Update in Firestore
    await subscriptionDoc.ref.update({
      cancelAtPeriodEnd: true,
      status: mapStripeStatus(stripeSubscription.status),
      updatedAt: Date.now()
    });

    return { success: true };
  } catch (error: any) {
    console.error('[cancelSubscription] Error:', error);
    throw new HttpsError('internal', error.message || 'Failed to cancel subscription');
  }
});

/**
 * Firebase Cloud Function: Create Stripe Checkout Session
 *
 * Creates a Stripe checkout session for subscription purchase or upgrade.
 */

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import { getFirestore } from 'firebase-admin/firestore';
import { stripe, getPriceId } from '../stripe/config';
import Stripe from 'stripe';
import { CheckoutSessionParams, CheckoutSessionResponse } from '../shared/subscription/types';
import { Subscription, SubscriptionTier } from '../shared/subscription/types';
import { stripeSecretKey } from '../config/secrets';

export const createCheckoutSession = onCall({
  secrets: [stripeSecretKey],
  timeoutSeconds: 60,
  memory: '256MiB',
  enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true',
}, async (request) => {
  const { userId, tier, successUrl, cancelUrl, customerEmail, trialDays } = request.data as CheckoutSessionParams;

  if (!userId || userId !== request.auth?.uid) {
    throw new HttpsError('unauthenticated', 'Unauthorized');
  }

  if (tier === SubscriptionTier.FREE) {
    throw new HttpsError('invalid-argument', 'Cannot create checkout session for free tier');
  }

  try {
    const db = getFirestore();

    // Get or create Stripe customer
    const subscriptionDoc = await db.collection('subscriptions').doc(userId).get();
    let stripeCustomerId: string;

    if (subscriptionDoc.exists) {
      const subscription = subscriptionDoc.data() as Subscription;
      if (subscription.stripeCustomerId) {
        stripeCustomerId = subscription.stripeCustomerId;
      } else {
        // Create new Stripe customer
        const customer = await stripe.customers.create({
          email: customerEmail || request.auth?.token?.email,
          metadata: { userId }
        }, { idempotencyKey: `create_customer_${userId}` });
        stripeCustomerId = customer.id;

        // Update subscription with Stripe customer ID
        await subscriptionDoc.ref.update({ stripeCustomerId });
      }
    } else {
      // Create new Stripe customer for new user
      const customer = await stripe.customers.create({
        email: customerEmail || request.auth?.token?.email,
        metadata: { userId }
      }, { idempotencyKey: `create_customer_${userId}` });
      stripeCustomerId = customer.id;
    }

    // Determine price ID
    const isYearly = tier === SubscriptionTier.PRO_YEARLY;
    const priceId = getPriceId(tier, isYearly);

    if (!priceId) {
      throw new HttpsError('failed-precondition', `No Stripe price configured for tier: ${tier}`);
    }

    // Build checkout session parameters
    const sessionParams: Stripe.Checkout.SessionCreateParams = {
      mode: 'subscription',
      payment_method_types: ['card'],
      customer: stripeCustomerId,
      line_items: [
        {
          price: priceId,
          quantity: 1
        }
      ],
      success_url: successUrl,
      cancel_url: cancelUrl,
      metadata: { userId, tier },
      allow_promotion_codes: true,
      automatic_tax: { enabled: true },
      client_reference_id: userId
    };

    // Add trial period if specified
    if (trialDays && trialDays > 0) {
      sessionParams.subscription_data = {
        trial_period_days: trialDays,
        metadata: { userId, tier }
      };
    }

    // Create checkout session
    const session = await stripe.checkout.sessions.create(sessionParams);

    const response: CheckoutSessionResponse = {
      checkoutUrl: session.url || '',
      sessionId: session.id
    };

    return response;
  } catch (error: any) {
    console.error('[createCheckoutSession] Error:', error);
    throw new HttpsError('internal', error.message || 'Failed to create checkout session');
  }
});

/**
 * Firebase Cloud Function: Create One-Time Stripe Checkout Session
 *
 * Used for one-off purchases (merchandise, beat licenses, sync fees)
 * that are NOT recurring subscriptions.
 *
 * Item 201: Enables PaymentService for real billing beyond subscriptions.
 */

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import { stripe } from '../stripe/config';
import { stripeSecretKey } from '../config/secrets';

export interface OneTimeCheckoutParams {
    userId: string;
    items: Array<{
        name: string;
        description?: string;
        amount: number; // in cents
        quantity: number;
        metadata?: Record<string, string>;
    }>;
    successUrl: string;
    cancelUrl: string;
    customerEmail?: string;
    metadata?: Record<string, string>;
}

export const createOneTimeCheckout = onCall({
    secrets: [stripeSecretKey],
    timeoutSeconds: 60,
    memory: '256MiB',
    enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true',
}, async (request) => {
    const { userId, items, successUrl, cancelUrl, customerEmail, metadata } =
        request.data as OneTimeCheckoutParams;

    if (!request.auth?.uid || request.auth.uid !== userId) {
        throw new HttpsError('unauthenticated', 'User must be signed in.');
    }

    if (!items || items.length === 0) {
        throw new HttpsError('invalid-argument', 'At least one item is required.');
    }

    try {
        const session = await stripe.checkout.sessions.create({
            mode: 'payment',
            payment_method_types: ['card'],
            customer_email: customerEmail || request.auth.token?.email || undefined,
            line_items: items.map((item) => ({
                price_data: {
                    currency: 'usd',
                    unit_amount: item.amount,
                    product_data: {
                        name: item.name,
                        description: item.description,
                        metadata: item.metadata,
                    },
                },
                quantity: item.quantity,
            })),
            success_url: successUrl,
            cancel_url: cancelUrl,
            allow_promotion_codes: true,
            automatic_tax: { enabled: true },
            payment_intent_data: {
                metadata: {
                    userId,
                    type: 'one_time',
                    ...metadata,
                },
            },
            metadata: {
                userId,
                type: 'one_time',
                ...metadata,
            },
            client_reference_id: userId,
        });

        return {
            checkoutUrl: session.url || '',
            sessionId: session.id,
        };
    } catch (error: any) {
        console.error('[createOneTimeCheckout] Error:', error);
        throw new HttpsError('internal', error.message || 'Failed to create checkout session');
    }
});

/**
 * Firebase Cloud Function: Generate Invoice
 *
 * Assembles structured invoice data from Stripe + Firestore for a given
 * subscription period. Returns JSON; the client renders it with the browser
 * print API or jsPDF.
 *
 * Item 205: PDF Invoice Generation for enterprise/label plan subscribers.
 */

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import { getFirestore } from 'firebase-admin/firestore';
import { stripe } from '../stripe/config';
import { stripeSecretKey } from '../config/secrets';

export interface InvoiceData {
    invoiceId: string;
    invoiceNumber: string;
    status: string;
    created: number;
    dueDate: number | null;
    periodStart: number;
    periodEnd: number;
    customerName: string;
    customerEmail: string;
    lines: Array<{
        description: string;
        quantity: number;
        unitAmount: number;
        amount: number;
    }>;
    subtotal: number;
    tax: number;
    total: number;
    currency: string;
    pdfUrl: string | null;
}

export const generateInvoice = onCall({
    secrets: [stripeSecretKey],
    timeoutSeconds: 30,
    memory: '256MiB',
    enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true',
}, async (request) => {
    const { invoiceId } = request.data as { invoiceId?: string };

    if (!request.auth?.uid) {
        throw new HttpsError('unauthenticated', 'User must be signed in.');
    }

    const db = getFirestore();
    const userId = request.auth.uid;

    // Get the subscription to verify ownership and get stripeCustomerId
    const subscriptionDoc = await db.collection('subscriptions').doc(userId).get();
    if (!subscriptionDoc.exists) {
        throw new HttpsError('not-found', 'No subscription found.');
    }

    const { stripeCustomerId } = subscriptionDoc.data() as { stripeCustomerId?: string };
    if (!stripeCustomerId) {
        throw new HttpsError('failed-precondition', 'No Stripe customer associated with this account.');
    }

    try {
        let invoice;

        if (invoiceId) {
            // Fetch specific invoice and verify it belongs to this customer
            invoice = await stripe.invoices.retrieve(invoiceId);
            if (invoice.customer !== stripeCustomerId) {
                throw new HttpsError('permission-denied', 'Invoice does not belong to this account.');
            }
        } else {
            // Fetch the most recent paid invoice for this customer
            const invoices = await stripe.invoices.list({
                customer: stripeCustomerId,
                status: 'paid',
                limit: 1,
            });
            if (invoices.data.length === 0) {
                throw new HttpsError('not-found', 'No paid invoices found.');
            }
            invoice = invoices.data[0];
        }

        // Retrieve customer details
        const customer = await stripe.customers.retrieve(stripeCustomerId);
        const customerName = 'deleted' in customer ? 'Unknown' : (customer.name || '');
        const customerEmail = 'deleted' in customer ? '' : (customer.email || '');

        const invoiceData: InvoiceData = {
            invoiceId: invoice.id,
            invoiceNumber: invoice.number || invoice.id,
            status: invoice.status || 'unknown',
            created: invoice.created * 1000,
            dueDate: invoice.due_date ? invoice.due_date * 1000 : null,
            periodStart: (invoice as unknown as { period_start?: number }).period_start ? (invoice as unknown as { period_start: number }).period_start * 1000 : 0,
            periodEnd: (invoice as unknown as { period_end?: number }).period_end ? (invoice as unknown as { period_end: number }).period_end * 1000 : 0,
            customerName,
            customerEmail,
            lines: invoice.lines.data.map((line) => ({
                description: line.description || '',
                quantity: line.quantity || 1,
                unitAmount: (line as unknown as { unit_amount_excluding_tax?: string }).unit_amount_excluding_tax
                    ? parseInt((line as unknown as { unit_amount_excluding_tax: string }).unit_amount_excluding_tax)
                    : (line.amount || 0),
                amount: line.amount || 0,
            })),
            subtotal: invoice.subtotal || 0,
            tax: (invoice as unknown as { tax?: number }).tax || 0,
            total: invoice.total || 0,
            currency: invoice.currency || 'usd',
            pdfUrl: invoice.invoice_pdf || null,
        };

        return invoiceData;
    } catch (error: any) {
        if (error instanceof HttpsError) throw error;
        console.error('[generateInvoice] Error:', error);
        throw new HttpsError('internal', error.message || 'Failed to generate invoice');
    }
});

/**
 * Firebase Cloud Function: Get Customer Portal URL
 *
 * Creates a Stripe customer portal session for managing subscription.
 */

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import { getFirestore } from 'firebase-admin/firestore';
import { stripe } from '../stripe/config';
import { stripeSecretKey } from '../config/secrets';

export const getCustomerPortal = onCall({
  secrets: [stripeSecretKey],
  timeoutSeconds: 30,
  memory: '128MiB',
  enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true',
}, async (request) => {
  const { userId, returnUrl } = request.data;

  if (!userId || userId !== request.auth?.uid) {
    throw new HttpsError('unauthenticated', 'Unauthorized');
  }

  try {
    const db = getFirestore();
    const subscriptionDoc = await db.collection('subscriptions').doc(userId).get();

    if (!subscriptionDoc.exists) {
      throw new HttpsError('not-found', 'Subscription not found');
    }

    const subscription = subscriptionDoc.data();

    if (!subscription) {
      throw new HttpsError('not-found', 'Subscription data not found');
    }

    const stripeCustomerId = subscription.stripeCustomerId;

    if (!stripeCustomerId) {
      throw new HttpsError('failed-precondition', 'No Stripe customer found');
    }

    // Create customer portal session
    const session = await stripe.billingPortal.sessions.create({
      customer: stripeCustomerId,
      return_url: returnUrl
    });

    return { url: session.url };
  } catch (error: any) {
    console.error('[getCustomerPortal] Error:', error);
    throw new HttpsError('internal', error.message || 'Failed to create customer portal session');
  }
});

/**
 * Firebase Cloud Function: Get User Usage Statistics
 *
 * Retrieves usage statistics for the current billing period.
 */

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import { getFirestore, FieldPath } from 'firebase-admin/firestore';
import { UsageStats, SubscriptionTier } from '../shared/subscription/types';
import { TIER_CONFIGS } from '../shared/subscription/SubscriptionTier';

export const getUsageStats = onCall({ enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true' }, async (request) => {
  const { userId } = request.data;

  if (!userId || userId !== request.auth?.uid) {
    throw new HttpsError('unauthenticated', 'Unauthorized');
  }

  try {
    const db = getFirestore();

    // Get subscription
    const subscriptionDoc = await db.collection('subscriptions').doc(userId).get();
    if (!subscriptionDoc.exists) {
      throw new HttpsError('not-found', 'Subscription not found');
    }

    const subscription = subscriptionDoc.data();

    if (!subscription) {
      throw new HttpsError('not-found', 'Subscription data not found');
    }

    const tier = subscription.tier as SubscriptionTier;
    const tierConfig = TIER_CONFIGS[tier];

    // Get usage records for current billing period
    const now = Date.now();
    const periodStart = subscription.currentPeriodStart || (now - 30 * 24 * 60 * 60 * 1000);
    const periodEnd = subscription.currentPeriodEnd || (now + 30 * 24 * 60 * 60 * 1000);

    const usageSnapshot = await db
      .collection('usage')
      .where('userId', '==', userId)
      .where('timestamp', '>=', periodStart)
      .where('timestamp', '<', periodEnd)
      .get();

    // Calculate usage
    let imagesGenerated = 0;
    let videoDurationSeconds = 0;
    let aiChatTokensUsed = 0;
    let storageUsedBytes = 0;

    usageSnapshot.forEach(doc => {
      const record = doc.data();
      switch (record.type) {
        case 'image':
          imagesGenerated += record.amount;
          break;
        case 'video':
          videoDurationSeconds += record.amount;
          break;
        case 'chat_tokens':
          aiChatTokensUsed += record.amount;
          break;
        case 'storage':
          storageUsedBytes += record.amount;
          break;
      }
    });

    // Convert to appropriate units
    const videoDurationMinutes = videoDurationSeconds / 60;
    const storageUsedGB = storageUsedBytes / (1024 * 1024 * 1024);

    // Calculate remaining
    const imagesRemaining = Math.max(0, tierConfig.imageGenerations.monthly - imagesGenerated);
    const videoRemainingMinutes = Math.max(0, tierConfig.videoGenerations.totalDurationMinutes - videoDurationMinutes);
    const tokensRemaining = Math.max(0, tierConfig.aiChat.tokensPerMonth - aiChatTokensUsed);
    const storageRemainingGB = Math.max(0, tierConfig.storage.totalGB - storageUsedGB);

    // Get project count
    const projectsSnapshot = await db
      .collection('projects')
      .where('userId', '==', userId)
      .where('archived', '==', false)
      .get();
    const projectsCreated = projectsSnapshot.size;

    // Get team members count
    const teamMembersField = new FieldPath('members', userId);
    const teamSnapshot = await db
      .collection('organizations')
      .where(teamMembersField, '!=', null)
      .get();
    const teamMembersUsed = teamSnapshot.size;

    // Build response
    const stats: UsageStats = {
      tier,
      resetDate: periodEnd,
      imagesGenerated,
      imagesRemaining,
      imagesPerMonth: tierConfig.imageGenerations.monthly,
      videoDurationSeconds,
      videoDurationMinutes,
      videoRemainingMinutes,
      videoTotalMinutes: tierConfig.videoGenerations.totalDurationMinutes,
      aiChatTokensUsed,
      aiChatTokensRemaining: tokensRemaining,
      aiChatTokensPerMonth: tierConfig.aiChat.tokensPerMonth,
      storageUsedGB,
      storageRemainingGB,
      storageTotalGB: tierConfig.storage.totalGB,
      projectsCreated,
      projectsRemaining: Math.max(0, tierConfig.maxProjects - projectsCreated),
      maxProjects: tierConfig.maxProjects,
      teamMembersUsed,
      teamMembersRemaining: Math.max(0, tierConfig.maxTeamMembers - teamMembersUsed),
      maxTeamMembers: tierConfig.maxTeamMembers
    };

    return stats;
  } catch (error: any) {
    console.error('[getUsageStats] Error:', error);
    throw new HttpsError('internal', error.message || 'Failed to retrieve usage statistics');
  }
});

/**
 * Firebase Cloud Function: Resume Subscription
 *
 * Resumes a cancelled subscription (if it hasn't been cancelled yet).
 */

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import { getFirestore } from 'firebase-admin/firestore';
import { stripe, mapStripeStatus } from '../stripe/config';
import { stripeSecretKey } from '../config/secrets';

export const resumeSubscription = onCall({
  secrets: [stripeSecretKey],
  timeoutSeconds: 30,
  memory: '128MiB',
  enforceAppCheck: process.env.SKIP_APP_CHECK !== 'true',
}, async (request) => {
  const { userId } = request.data;

  if (!userId || userId !== request.auth?.uid) {
    throw new HttpsError('unauthenticated', 'Unauthorized');
  }

  try {
    const db = getFirestore();
    const subscriptionDoc = await db.collection('subscriptions').doc(userId).get();

    if (!subscriptionDoc.exists) {
      throw new HttpsError('not-found', 'Subscription not found');
    }

    const subscription = subscriptionDoc.data();

    if (!subscription) {
      throw new HttpsError('not-found', 'Subscription data not found');
    }

    const stripeCustomerId = subscription.stripeCustomerId;
    const stripeSubscriptionId = subscription.stripeSubscriptionId;

    if (!stripeCustomerId || !stripeSubscriptionId) {
      throw new HttpsError('failed-precondition', 'No active subscription found');
    }

    // Check if subscription is set to cancel at period end
    const stripeSubscription = await stripe.subscriptions.retrieve(stripeSubscriptionId);

    if (!stripeSubscription.cancel_at_period_end) {
      throw new HttpsError('failed-precondition', 'Subscription is not scheduled for cancellation');
    }

    // Resume by removing cancel_at_period_end
    const updatedSubscription = await stripe.subscriptions.update(stripeSubscriptionId, {
      cancel_at_period_end: false
    });

    // Update in Firestore
    await subscriptionDoc.ref.update({
      cancelAtPeriodEnd: false,
      status: mapStripeStatus(updatedSubscription.status),
      updatedAt: Date.now()
    });

    return { success: true };
  } catch (error: any) {
    console.error('[resumeSubscription] Error:', error);
    throw new HttpsError('internal', error.message || 'Failed to resume subscription');
  }
});

/**
 * pollTimelineMilestones.ts
 *
 * Firebase Cloud Scheduler function that runs every 15 minutes to check
 * for due timeline milestones and dispatch their execution via Inngest.
 *
 * Flow:
 * 1. Query all users' `timelines` collections for `status === 'active'`
 * 2. Find milestones with `status === 'pending'` and `scheduledAt <= now`
 * 3. For each due milestone, dispatch a `timeline/milestone.due` event to Inngest
 * 4. Inngest's `executeMilestoneFn` picks it up and runs the agent server-side
 *
 * This is the autonomy bridge — milestones execute even when the user is offline.
 */

import { onSchedule } from 'firebase-functions/v2/scheduler';
import * as admin from 'firebase-admin';
import { Inngest } from 'inngest';

const db = admin.firestore();

// ============================================================================
// Types (duplicated from client to avoid cross-project imports)
// ============================================================================

interface TimelineMilestone {
    id: string;
    phaseId: string;
    phaseName: string;
    scheduledAt: number;
    type: string;
    instruction: string;
    assetStrategy: string;
    status: string;
    agentId: string;
    platform?: string;
    result?: string;
    error?: string;
    executedAt?: number;
    retryCount?: number;
}

interface Timeline {
    id: string;
    userId: string;
    title: string;
    goal: string;
    domain: string;
    status: string;
    phases: Array<{ id: string; name: string; order: number }>;
    milestones: TimelineMilestone[];
    currentPhaseOrder: number;
    completedCount: number;
    totalCount: number;
    updatedAt: number;
}

// ============================================================================
// Inngest Client (lazy init — secrets only available at runtime)
// ============================================================================

let inngestClient: Inngest | null = null;

function getInngest(): Inngest {
    if (!inngestClient) {
        const eventKey = process.env.INNGEST_EVENT_KEY || '';
        inngestClient = new Inngest({
            id: 'indii-os-timeline-poller',
            eventKey,
        });
    }
    return inngestClient;
}

// ============================================================================
// Cloud Function
// ============================================================================

/**
 * pollTimelineMilestones
 *
 * Runs every 15 minutes. Finds due milestones and dispatches them
 * to Inngest for fully autonomous server-side execution.
 */
export const pollTimelineMilestones = onSchedule(
    {
        schedule: 'every 15 minutes',
        region: 'us-central1',
        timeoutSeconds: 120,
        memory: '256MiB',
        secrets: ['INNGEST_EVENT_KEY'],
    },
    async () => {
        const now = Date.now();
        console.log(`[pollTimelineMilestones] Checking for due milestones at ${new Date(now).toISOString()}`);

        let totalProcessed = 0;
        let totalDue = 0;
        const inngest = getInngest();

        try {
            // OPTIMIZATION: Use collectionGroup to find ALL active timelines across ALL users in one query
            // Requires a Firestore index: collectionGroup('items') with status == 'active'
            const activeTimelinesSnap = await db.collectionGroup('items')
                .where('status', '==', 'active')
                .get();

            console.log(`[pollTimelineMilestones] Found ${activeTimelinesSnap.size} active timelines across the platform.`);

            for (const timelineDoc of activeTimelinesSnap.docs) {
                // The parent doc id is the userId in our structure: timelines/{userId}/items/{timelineId}
                const userId = timelineDoc.ref.parent.parent?.id;
                if (!userId) {
                    console.warn(`[pollTimelineMilestones] Could not determine userId for timeline ${timelineDoc.id}`);
                    continue;
                }

                const timeline = timelineDoc.data() as Timeline;

                    let updated = false;

                    // Find due milestones
                    for (let i = 0; i < timeline.milestones.length; i++) {
                        const milestone = timeline.milestones[i];

                        if (milestone.status === 'pending' && milestone.scheduledAt <= now) {
                            totalDue++;

                            // Mark milestone as dispatched (prevents double-fire on next poll)
                            timeline.milestones[i] = {
                                ...milestone,
                                status: 'executing',
                            };
                            updated = true;

                            console.log(
                                `[pollTimelineMilestones] Dispatching milestone: "${milestone.instruction.slice(0, 80)}..." ` +
                                `(timeline: ${timeline.title}, phase: ${milestone.phaseName}, agent: ${milestone.agentId})`
                            );

                            // Dispatch to Inngest for autonomous server-side execution
                            try {
                                await inngest.send({
                                    name: 'timeline/milestone.due',
                                    data: {
                                        userId,
                                        timelineId: timeline.id,
                                        milestoneId: milestone.id,
                                        agentId: milestone.agentId,
                                        instruction: milestone.instruction,
                                        assetStrategy: milestone.assetStrategy,
                                        phaseName: milestone.phaseName,
                                        type: milestone.type,
                                        platform: milestone.platform ?? null,
                                        goal: timeline.goal,
                                        title: timeline.title,
                                        domain: timeline.domain,
                                    },
                                });
                                totalProcessed++;
                                console.log(
                                    `[pollTimelineMilestones] Inngest event sent for milestone ${milestone.id}`
                                );
                            } catch (sendError) {
                                console.error(
                                    `[pollTimelineMilestones] Failed to send Inngest event for milestone ${milestone.id}:`,
                                    sendError
                                );
                                // Revert to pending so it can retry next polling cycle
                                timeline.milestones[i].status = 'pending';
                            }
                        }
                    }

                    // Update the timeline document if any milestones were triggered
                    // Use a transaction to prevent race with executeMilestoneFn
                    if (updated) {
                        const dueMilestoneIds = new Set(
                            timeline.milestones
                                .filter((m: TimelineMilestone) => m.status === 'executing')
                                .map((m: TimelineMilestone) => m.id)
                        );

                        await db.runTransaction(async (transaction) => {
                            const freshSnap = await transaction.get(timelineDoc.ref);
                            if (!freshSnap.exists) return;

                            const freshTimeline = freshSnap.data() as Timeline;
                            const freshMilestones = freshTimeline.milestones;

                            // Only update milestones that WE dispatched (don't overwrite executor changes)
                            for (let j = 0; j < freshMilestones.length; j++) {
                                if (dueMilestoneIds.has(freshMilestones[j].id) && freshMilestones[j].status === 'pending') {
                                    freshMilestones[j].status = 'executing';
                                }
                            }

                            const completedCount = freshMilestones.filter(
                                (m: TimelineMilestone) => m.status === 'completed'
                            ).length;

                            const allDone = freshMilestones.every(
                                (m: TimelineMilestone) => m.status === 'completed' || m.status === 'skipped' || m.status === 'failed'
                            );

                            const updates: Record<string, any> = {
                                milestones: freshMilestones,
                                updatedAt: now,
                                completedCount,
                            };

                            if (allDone) {
                                updates.status = 'completed';
                                console.log(`[pollTimelineMilestones] Timeline "${timeline.title}" is now completed!`);
                            }

                            transaction.update(timelineDoc.ref, updates);
                        });
                    }
            }
            console.log(
                `[pollTimelineMilestones] Done. Found ${totalDue} due milestones, dispatched ${totalProcessed} to Inngest.`
            );
        } catch (error) {
            console.error('[pollTimelineMilestones] Fatal error:', error);
        }
    }
);


'use client';

import { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { shaderMaterial } from '@react-three/drei';
import { extend } from '@react-three/fiber';
import { createNoise3D } from 'simplex-noise';
import { audioStore } from '../../store/audioStore';

// Custom Shader Material
// Uniforms object cast as `any` to avoid TS2322 when duplicate @types/three
// copies exist in CI hoisting (drei's UniformValue narrows from a different copy
// than THREE.Color/Vector instances, defeating per-value `as any` casts).
const WaveShaderMaterial = shaderMaterial(
    {
        uTime: 0,
        uColorStart: new THREE.Color('#050a05'),
        uColorEnd: new THREE.Color('#0a1a0a'),
        uMouse: new THREE.Vector2(0, 0),
        uHover: 0,
        uAudioEQ: new THREE.Vector4(0, 0, 0, 0),
        uColorBass: new THREE.Color('#00ff66'),
        uColorLowMid: new THREE.Color('#bfff00'),
        uColorHighMid: new THREE.Color('#10b981'),
        uColorTreble: new THREE.Color('#ffffff'),
    } as any,
    // Vertex Shader
    `
    varying vec2 vUv;
    varying float vElevation;
    varying vec4 vAudio;
    varying float vDisplacement;

    uniform float uTime;
    uniform vec4 uAudioEQ;

    // Simplex noise function (simplified)
    vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

    float snoise(vec2 v) {
        const vec4 C = vec4(0.211324865405187,  // (3.0-sqrt(3.0))/6.0
                            0.366025403784439,  // 0.5*(sqrt(3.0)-1.0)
                            -0.577350269189626, // -1.0 + 2.0 * C.x
                            0.024390243902439); // 1.0 / 41.0
        vec2 i  = floor(v + dot(v, C.yy) );
        vec2 x0 = v - i + dot(i, C.xx);
        vec2 i1;
        i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
        vec4 x12 = x0.xyxy + C.xxzz;
        x12.xy -= i1;
        i = mod289(i); // Avoid truncation effects in permutation
        vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
            + i.x + vec3(0.0, i1.x, 1.0 ));
        vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
        m = m*m ;
        m = m*m ;
        vec3 x = 2.0 * fract(p * C.www) - 1.0;
        vec3 h = abs(x) - 0.5;
        vec3 ox = floor(x + 0.5);
        vec3 a0 = x - ox;
        m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
        vec3 g;
        g.x  = a0.x  * x0.x  + h.x  * x0.y;
        g.yz = a0.yz * x12.xz + h.yz * x12.yw;
        return 130.0 * dot(m, g);
    }

    void main() {
      vUv = uv;
      vAudio = uAudioEQ;
      vec4 modelPosition = modelMatrix * vec4(position, 1.0);

      // Distance from center
      float dist = length(modelPosition.xz);
      float angle = atan(modelPosition.z, modelPosition.x);

      // --- Band 1: BASS (Deep, slow, central pulse) ---
      // Acts like a heartbeat or subwoofer cone
      float bassDisplacement = sin(dist * 0.5 - uTime * 1.0) * uAudioEQ.x * 2.0;
      float bassKick = smoothstep(10.0, 0.0, dist) * uAudioEQ.x * 2.0;

      // --- Band 2: LOW MID (Rolling waves) ---
      // Moves from front to back - SLOW
      float lowMidDisplacement = sin(modelPosition.x * 0.5 + uTime * 0.5) * uAudioEQ.y * 1.5;

      // --- Band 3: HIGH MID (Interference patterns) ---
      // Creates cross-hatching or more complex ripples
      float highMidDisplacement = snoise(modelPosition.xz * 0.2 + uTime * 0.5) * uAudioEQ.z * 1.5;

      // --- Band 4: TREBLE (Sharp, jagged noise) ---
      float trebleDisplacement = snoise(modelPosition.xz * 1.0 - uTime) * uAudioEQ.w * 0.8;

      // Combine displacements
      // Ideally, the bass is the strongest "shape", others add texture
      float totalDisplacement = bassDisplacement + bassKick + lowMidDisplacement + highMidDisplacement + trebleDisplacement;

      // Add subtle base breathing - SLOW OCEAN SWELL
      totalDisplacement += sin(modelPosition.x * 1.0 + uTime * 0.2) * 0.2;

      modelPosition.y += totalDisplacement;
      vElevation = totalDisplacement;
      vDisplacement = totalDisplacement;

      gl_Position = projectionMatrix * viewMatrix * modelPosition;
    }
  `,
    // Fragment Shader
    `
    varying vec2 vUv;
    varying float vElevation;
    varying vec4 vAudio;
    varying float vDisplacement;

    uniform vec3 uColorStart;
    uniform vec3 uColorEnd;
    uniform vec3 uColorBass;
    uniform vec3 uColorLowMid;
    uniform vec3 uColorHighMid;
    uniform vec3 uColorTreble;

    void main() {
      // Base Gradient with deeper void - sharper mix based on elevation
      float mixStrength = (vElevation + 1.0) * 0.25; 
      vec3 color = mix(uColorStart, uColorEnd, mixStrength);

      // --- AUDIO COLOR MIXING ---
      // Additive mixing for neon glow feel

      // Bass: Indigo - Boosted INTENSITY
      color += uColorBass * vAudio.x * 0.8;

      // LowMid: Cyan
      float wavePattern = sin(vUv.x * 10.0 + vAudio.y);
      color += uColorLowMid * vAudio.y * 0.6 * smoothstep(0.3, 0.7, wavePattern);

      // HighMid: Magenta
      float ripplePattern = sin(length(vUv - 0.5) * 20.0);
      color += uColorHighMid * vAudio.z * 0.6 * smoothstep(0.3, 0.7, ripplePattern);

      // Treble: White sparks
      float peak = smoothstep(1.0, 3.5, vElevation);
      color += uColorTreble * vAudio.w * peak * 3.5;

      // Vignette
      float vignette = 1.0 - length(vUv - 0.5);
      color *= smoothstep(0.0, 1.5, vignette);

      gl_FragColor = vec4(color, 1.0); 
    }
  `
);

extend({ WaveShaderMaterial });

// Add type definition for the shader material
declare module '@react-three/fiber' {
    interface ThreeElements {
        waveShaderMaterial: {
            ref?: React.Ref<any>;
            uColorStart?: any;
            uColorEnd?: any;
            uTime?: number;
            uMouse?: THREE.Vector2;
            uHover?: number;
            uAudioEQ?: THREE.Vector4;
            uColorBass?: any;
            uColorLowMid?: any;
            uColorHighMid?: any;
            uColorTreble?: any;
            wireframe?: boolean;
            transparent?: boolean;
