        mesh.current.rotation.x = rotation[0] + t * speed;
        mesh.current.rotation.y = rotation[1] + t * speed * 0.5;
        mesh.current.position.y = position[1] + Math.sin(t * 2 + position[0]) * 0.2; // Float
