/* eslint-disable react-hooks/purity */
'use client';

import { useFrame } from '@react-three/fiber';
import { useRef, useMemo } from 'react';
import * as THREE from 'three';
import { Instances, Instance } from '@react-three/drei';

import { useAudioStore } from '../store/audioStore';

function LaserGrid() {
    const meshRef = useRef<any>(null!);
    const count = 40;


    const beams = useMemo(() => {
        return new Array(count).fill(0).map((_, i) => ({
            y: (i - count / 2) * 0.5,
            speed: Math.random() * 0.5 + 0.2,
            offset: Math.random() * Math.PI * 2
        }));
    }, []);

    useFrame((state) => {
        const t = state.clock.getElapsedTime();
        const dummy = new THREE.Object3D();

        beams.forEach((beam, i) => {
            // Vertical flow
            const y = beam.y + Math.sin(t * beam.speed + beam.offset) * 0.2;

            // Forward/Backward Wave
            const z = Math.sin(t * 1.5 + beam.y * 2) * 3;

            dummy.position.set(0, y, z);
            dummy.rotation.x = Math.cos(t * 1.5 + beam.y * 2) * 0.1;
            dummy.scale.set(1, 1, 1);
            dummy.updateMatrix();
            meshRef.current.setMatrixAt(i, dummy.matrix);
        });
        meshRef.current.instanceMatrix.needsUpdate = true;
    });

    return (
        <Instances range={count} ref={meshRef}>
            <boxGeometry args={[30, 0.05, 0.05]} />
            <meshBasicMaterial color="#ff0000" transparent opacity={0.8} toneMapped={false} />
            {beams.map((_, i) => (
                <Instance key={i} />
            ))}
        </Instances>
    );
}

function Scanner() {
    const mesh = useRef<any>(null!);

    useFrame((state) => {
        const t = state.clock.getElapsedTime();
        mesh.current.position.y = Math.sin(t) * 8;
        mesh.current.scale.x = 30;
        mesh.current.scale.z = 1 + Math.sin(t * 10) * 0.1;
    });

    return (
        <mesh ref={mesh} rotation={[Math.PI / 2, 0, 0]}>
            <planeGeometry args={[1, 1]} />
            <meshBasicMaterial color="#ff0000" transparent opacity={0.1} side={THREE.DoubleSide} />
        </mesh>
    );
}

function HexShields() {
    const meshRef = useRef<any>(null!);
    const count = 20;


    const hexes = useMemo(() => {
        return new Array(count).fill(0).map(() => ({
            position: [
                (Math.random() - 0.5) * 20,
                (Math.random() - 0.5) * 10,
                (Math.random() - 0.5) * 5
            ] as [number, number, number],
            rotation: [
                Math.random() * Math.PI,
                Math.random() * Math.PI,
                0
            ] as [number, number, number],
            scale: Math.random() * 0.5 + 0.5
        }));
    }, []);

    useFrame((state) => {
        const t = state.clock.getElapsedTime();
        const dummy = new THREE.Object3D();

        hexes.forEach((hex, i) => {
            dummy.position.set(...hex.position);
            dummy.rotation.set(
                hex.rotation[0] + t * 0.2,
                hex.rotation[1] + t * 0.3,
                hex.rotation[2]
            );
            dummy.scale.setScalar(hex.scale * (1 + Math.sin(t * 2 + i) * 0.2));
            dummy.updateMatrix();
            meshRef.current.setMatrixAt(i, dummy.matrix);
        });
        meshRef.current.instanceMatrix.needsUpdate = true;
    });

    return (
        <Instances range={count} ref={meshRef}>
            <circleGeometry args={[1, 6]} />
            <meshBasicMaterial color="#ff0000" wireframe transparent opacity={0.2} />
            {hexes.map((_, i) => (
                <Instance key={i} />
            ))}
        </Instances>
    );
}

function DataVault() {
    const group = useRef<any>(null!);
    const coreMat = useRef<any>(null!);
    const ring1 = useRef<any>(null!);
    const ring2 = useRef<any>(null!);

    // Audio Reactivity
    const bass = useAudioStore((state) => state.frequencyData.bass);
    const high = useAudioStore((state) => state.frequencyData.high);

    useFrame((state) => {
        const t = state.clock.getElapsedTime();

        // Core Pulsate (Bass)
        const pulse = 1 + bass * 0.5;
        if (coreMat.current) {
            coreMat.current.emissiveIntensity = 0.5 + bass * 2;
            coreMat.current.color.setHSL(0, 1, 0.2 + bass * 0.3); // Red pulse
        }

        // Rings "Racing" Effect (Highs)
        // We simulate "racing" by spinning faster with highs
        const raceSpeed = 0.2 + high * 2;

        if (ring1.current) {
            ring1.current.rotation.z += raceSpeed * 0.05;
            ring1.current.rotation.x = Math.PI / 2 + Math.sin(t) * 0.2;
        }
        if (ring2.current) {
            ring2.current.rotation.z -= raceSpeed * 0.05;
            ring2.current.rotation.z += 0.01;
        }

        group.current.position.y = Math.sin(t * 0.5) * 0.5;
    });

    return (
        <group ref={group}>
            {/* Core - Solid Pulsating Base */}
            <mesh scale={2}>
                <icosahedronGeometry args={[1, 4]} /> {/* Higher detail for solid look */}
                <meshStandardMaterial
                    ref={coreMat}
                    color="#330000"
                    emissive="#ff0000"
                    emissiveIntensity={0.5}
                    roughness={0.4}
                    metalness={0.8}
                />
            </mesh>

            {/* Outer Casing - Dark Purple/Black with Neon Purple */}
            {/* Ring 1 */}
            <mesh ref={ring1} rotation={[Math.PI / 2, 0, 0]}>
                <torusGeometry args={[3, 0.1, 16, 100]} />
                <meshStandardMaterial
                    color="#0a0010" // Almost black
                    emissive="#b026ff" // Neon Purple
                    emissiveIntensity={2}
                    roughness={0.1}
                    metalness={1}
                />
            </mesh>

            {/* Ring 2 */}
            <mesh ref={ring2} rotation={[0, 0, Math.PI / 4]}>
                <torusGeometry args={[3.5, 0.05, 16, 100]} />
                <meshStandardMaterial
                    color="#000000"
                    emissive="#8a2be2"
                    emissiveIntensity={1}
                    roughness={0.1}
                    metalness={1}
                />
            </mesh>

            {/* Energy Field */}
            <mesh scale={2.5}>
                <sphereGeometry args={[1, 32, 32]} />
                <meshBasicMaterial color="#ff0000" transparent opacity={0.05} side={THREE.BackSide} />
            </mesh>
        </group>
    );
}

export default function SecurityGrid() {
    return (
        <group position={[0, -48, 0]}>
            <LaserGrid />
            <Scanner />
            <HexShields />
            <DataVault />
            <pointLight position={[0, 0, 5]} color="#ff0000" intensity={5} distance={20} />
        </group>
    );
}

'use client';

import { useFrame, useThree } from '@react-three/fiber';
import { useRef, useState } from 'react';
import * as THREE from 'three';
import { useScroll, Text, Float } from '@react-three/drei';

export default function TheTitan() {
    const meshRef = useRef<any>(null!);
    const textRef = useRef<any>(null!);
    const scroll = useScroll();
    const { camera } = useThree();
    const [triggered, setTriggered] = useState(false);

    useFrame((state) => {
        if (!meshRef.current) return;

        const t = state.clock.getElapsedTime();
        const offset = scroll.offset; // 0 to 1

        // Trigger logic: Very end of scroll
        if (offset > 0.98 && !triggered) {
            setTriggered(true);
        } else if (offset < 0.95 && triggered) {
            setTriggered(false);
        }

        if (triggered) {
            // "The Manifestation"
            // Scale up instantly 
            meshRef.current.scale.lerp(new THREE.Vector3(1, 1, 1), 0.1);

            // Slow rotation
            meshRef.current.rotation.y = t * 0.2;

            // Camera Shake
            // eslint-disable-next-line react-hooks/immutability
            camera.position.x += (Math.random() - 0.5) * 0.05;
            camera.position.y += (Math.random() - 0.5) * 0.05;

            // Text Reveal
            if (textRef.current) {
                textRef.current.visible = true;
                textRef.current.scale.lerp(new THREE.Vector3(1, 1, 1), 0.1);
            }

        } else {
            // Dormant state
            meshRef.current.scale.lerp(new THREE.Vector3(0, 0, 0), 0.1);
            if (textRef.current) {
                textRef.current.visible = false;
                textRef.current.scale.set(0, 0, 0);
            }
        }
    });

    return (
        <group position={[0, -84, 0]}> {/* Positioned way below everything else */}

            {/* The Monolith - Massive Obsidian Diamond */}
            <Float speed={2} rotationIntensity={0.5} floatIntensity={0.5}>
                <mesh ref={meshRef} scale={[0, 0, 0]}>
                    <octahedronGeometry args={[8, 0]} />
                    <meshPhysicalMaterial
                        color="#000000"
                        roughness={0}
                        metalness={1}
                        clearcoat={1}
                        clearcoatRoughness={0}
                        reflectivity={1}
                        emissive="#ffffff"
                        emissiveIntensity={0.1}
                    />
                </mesh>
            </Float>

            <group ref={textRef} position={[0, 0, 2]} visible={false} scale={[0, 0, 0]}>
                <Text
                    position={[0, 0, 0]}
                    fontSize={2}
                    color="white"
                    anchorX="center"
                    anchorY="middle"
                    letterSpacing={0.2}
                >
                    OWN YOUR FUTURE
                </Text>

            </group>

            {/* Dramatic Lighting */}
            {triggered && (
                <>
                    <pointLight position={[0, 0, 10]} intensity={5} color="white" distance={20} />
                    <pointLight position={[-10, 10, 5]} intensity={5} color="#b026ff" distance={30} />
                    <pointLight position={[10, -10, 5]} intensity={5} color="#00f3ff" distance={30} />
                </>
            )}
        </group>
    );
}

