        await PythonBridge.runScript('distribution', 'sftp_uploader.py', [
            '--host', 'localhost',
            '--user', 'testuser',
            '--local', 'test.xml'
        ], undefined, { SFTP_PASSWORD: password });

        // Check if the password was logged
