describe('Shield 🛡️: Audio Path Validation Security', () => {

    afterEach(() => {
        vi.clearAllMocks();
    });

    it('should allow valid, safe audio files', () => {
        const safePath = '/Users/indii/Music/song.mp3';
        vi.mocked(fs.realpathSync).mockReturnValue(safePath);

        expect(validateSafeAudioPath(safePath)).toBe(safePath);
    });

    it('should BLOCK Path Traversal attempts resolving to system files', () => {
        // Attack: "../../../etc/passwd" -> resolves to "/etc/passwd"
        // Note: The function checks Extension BEFORE System Directory.
        // So "/etc/passwd" (no ext) fails on extension check.
        // To test System Directory check, we simulate a file with valid extension in system dir.

        const attackPath = '/Users/indii/Music/../../../etc/passwd.mp3';
        const resolvedPath = '/etc/passwd.mp3';

        vi.mocked(fs.realpathSync).mockReturnValue(resolvedPath);

        expect(() => validateSafeAudioPath(attackPath))
            .toThrow(/Security Violation: Access to system directory/);
    });

    it('should BLOCK Symlink Attacks pointing to sensitive files', () => {
        // Attack: "innocent_song.wav" -> symlink to "/etc/shadow"
        // Again, if /etc/shadow has no extension, it fails extension check first.
        // We test that it fails SECURELY.

        const innocentPath = '/Users/indii/Music/innocent_song.wav';
        const targetPath = '/etc/shadow';

        vi.mocked(fs.realpathSync).mockReturnValue(targetPath);

        expect(() => validateSafeAudioPath(innocentPath))
            .toThrow(/Security Violation: File type '' is not allowed/);

        // ALSO test a symlink to a file that HAS a valid extension but is in a system dir
        // e.g. /etc/config.mp3
        const targetSystemPath = '/etc/config.mp3';
        vi.mocked(fs.realpathSync).mockReturnValue(targetSystemPath);
        expect(() => validateSafeAudioPath(innocentPath))
             .toThrow(/Security Violation: Access to system directory/);
    });

    it('should BLOCK hidden files (dotfiles)', () => {
        // Attack: accessing SSH keys masquerading as audio or just hidden
        const hiddenPath = '/Users/indii/.ssh/id_rsa';

        vi.mocked(fs.realpathSync).mockReturnValue(hiddenPath);

        // Fails extension check first
        expect(() => validateSafeAudioPath(hiddenPath))
            .toThrow(/Security Violation: File type '' is not allowed/);

        // Test hidden file with valid extension
        const hiddenAudio = '/Users/indii/.hidden.mp3';
        vi.mocked(fs.realpathSync).mockReturnValue(hiddenAudio);
        expect(() => validateSafeAudioPath(hiddenAudio))
            .toThrow(/Security Violation: Access to hidden files/);
    });

    it('should BLOCK hidden directories', () => {
        const hiddenDirPath = '/Users/indii/.secret/song.mp3';
        vi.mocked(fs.realpathSync).mockReturnValue(hiddenDirPath);

        expect(() => validateSafeAudioPath(hiddenDirPath))
            .toThrow(/Security Violation: Access to hidden files/);
    });

    it('should BLOCK forbidden extensions (Spoofing)', () => {
        // Attack: "song.mp3.exe"
        const exePath = '/Users/indii/Music/song.mp3.exe';
        vi.mocked(fs.realpathSync).mockReturnValue(exePath);

        expect(() => validateSafeAudioPath(exePath))
            .toThrow(/Security Violation: File type '.exe' is not allowed/);
    });

    it('should BLOCK shell scripts', () => {
        const scriptPath = '/Users/indii/Music/malware.sh';
        vi.mocked(fs.realpathSync).mockReturnValue(scriptPath);

        expect(() => validateSafeAudioPath(scriptPath))
            .toThrow(/Security Violation: File type '.sh' is not allowed/);
    });

    it('should BLOCK non-existent files (Information Disclosure prevention)', () => {
        vi.mocked(fs.realpathSync).mockImplementation(() => {
            throw new Error('ENOENT');
        });

        expect(() => validateSafeAudioPath('/does/not/exist.mp3'))
            .toThrow(/Security Violation: Invalid file path/);
    });

    it('should BLOCK System Roots', () => {
        // We use .mp3 extension to ensure we bypass extension check and hit system root check
        const roots = ['/bin/bash.mp3', '/usr/bin/python.mp3', '/var/log/syslog.mp3'];

        roots.forEach(root => {
            vi.mocked(fs.realpathSync).mockReturnValue(root);
            expect(() => validateSafeAudioPath(root))
                .toThrow(/Security Violation: Access to system directory/);
        });
    });

});

import dns from 'node:dns';
import net from 'node:net';

/**
 * Expands an IPv6 address to its full 32-digit hexadecimal representation.
 * Handles :: expansion and IPv4-mapped addresses.
 */
export function expandIPv6(ip: string): string {
    // 1. Handle embedded IPv4 (e.g. ::ffff:192.168.1.1)
    if (ip.includes('.')) {
        const lastColon = ip.lastIndexOf(':');
        const ipv4 = ip.substring(lastColon + 1);
        if (net.isIP(ipv4) === 4) {
            const parts = ipv4.split('.').map(Number);
            const hex = parts.map(p => p.toString(16).padStart(2, '0')).join('');
            const p1 = hex.substring(0, 4);
            const p2 = hex.substring(4, 8);
            const prefix = ip.substring(0, lastColon);
            return expandIPv6(`${prefix}:${p1}:${p2}`);
        }
    }

    // 2. Expand "::"
    const parts = ip.split('::');
    if (parts.length > 2) return ip; // Invalid

    const head = parts[0] ? parts[0].split(':') : [];
    const tail = parts.length > 1 ? (parts[1] ? parts[1].split(':') : []) : [];

    // Total groups should be 8
    const zerosToFill = 8 - (head.length + tail.length);
    const zeros = new Array(zerosToFill).fill('0000');

    const groups = [...head, ...zeros, ...tail];

    return groups.map(g => g.padStart(4, '0')).join(':').toLowerCase();
}

/**
 * Checks if an IP address is private or reserved.
 */
export function isPrivateIP(ip: string): boolean {
    const family = net.isIP(ip);
    if (family === 4) {
        const parts = ip.split('.').map(Number);
        if (parts.length !== 4) return false;

        // 0.0.0.0/8 (Current network)
        if (parts[0] === 0) return true;
        // 127.0.0.0/8 (Loopback)
        if (parts[0] === 127) return true;
        // 10.0.0.0/8 (Private)
        if (parts[0] === 10) return true;
        // 172.16.0.0/12 (Private)
        if (parts[0] === 172 && parts[1]! >= 16 && parts[1]! <= 31) return true;
        // 192.168.0.0/16 (Private)
        if (parts[0] === 192 && parts[1] === 168) return true;
        // 169.254.0.0/16 (Link-Local)
        if (parts[0] === 169 && parts[1] === 254) return true;
        // 100.64.0.0/10 (Carrier Grade NAT)
        if (parts[0] === 100 && parts[1]! >= 64 && parts[1]! <= 127) return true;
        // 192.0.0.0/24 (IETF Protocol Assignments)
        if (parts[0] === 192 && parts[1] === 0 && parts[2] === 0) return true;
        // 192.0.2.0/24 (TEST-NET-1)
        if (parts[0] === 192 && parts[1] === 0 && parts[2] === 2) return true;
        // 198.18.0.0/15 (Benchmarking)
        if (parts[0] === 198 && parts[1]! >= 18 && parts[1]! <= 19) return true;
        // 198.51.100.0/24 (TEST-NET-2)
        if (parts[0] === 198 && parts[1] === 51 && parts[2] === 100) return true;
        // 203.0.113.0/24 (TEST-NET-3)
        if (parts[0] === 203 && parts[1] === 0 && parts[2] === 113) return true;
        // 224.0.0.0/4 (Multicast)
        if (parts[0]! >= 224) return true;

        return false;
    } else if (family === 6) {
        // Expand IPv6 to full 32-digit hex form
        const expanded = expandIPv6(ip);

        // Loopback (::1) -> 0000:0000:0000:0000:0000:0000:0000:0001
        if (expanded === '0000:0000:0000:0000:0000:0000:0000:0001') return true;

        // Unspecified (::) -> 0000:0000:0000:0000:0000:0000:0000:0000
        if (expanded === '0000:0000:0000:0000:0000:0000:0000:0000') return true;

        // Unique Local (fc00::/7) -> fc.. or fd..
        if (expanded.startsWith('fc') || expanded.startsWith('fd')) return true;

        // Link-Local (fe80::/10) -> fe8., fe9., fea., feb.
        const firstGroup = expanded.substring(0, 4);
        if (['fe8', 'fe9', 'fea', 'feb'].some(prefix => firstGroup.startsWith(prefix))) return true;

        // Multicast (ff00::/8) -> ff..
        if (expanded.startsWith('ff')) return true;

        // IPv4 Mapped (::ffff:0:0/96)
        // 0000:0000:0000:0000:0000:ffff:xxxx:xxxx
        if (expanded.startsWith('0000:0000:0000:0000:0000:ffff:')) {
            const lastPart = expanded.substring(30);
            const parts = lastPart.split(':');
            const p1 = parseInt(parts[0]!, 16);
            const p2 = parseInt(parts[1]!, 16);
            const ip4 = `${(p1 >> 8) & 255}.${p1 & 255}.${(p2 >> 8) & 255}.${p2 & 255}`;
            return isPrivateIP(ip4);
        }

        // IPv4 Compatible (deprecated but exists) ::0.0.0.0 (::/96)
        // 0000:0000:0000:0000:0000:0000:xxxx:xxxx
        if (expanded.startsWith('0000:0000:0000:0000:0000:0000:')) {
            const lastPart = expanded.substring(30);
            if (lastPart !== '0000:0001' && lastPart !== '0000:0000') {
                const parts = lastPart.split(':');
                const p1 = parseInt(parts[0]!, 16);
                const p2 = parseInt(parts[1]!, 16);
                const ip4 = `${(p1 >> 8) & 255}.${p1 & 255}.${(p2 >> 8) & 255}.${p2 & 255}`;
                return isPrivateIP(ip4);
            }
        }
    }
    return false;
}

/**
 * Validates that a Host (hostname or IP) is safe to access (SSRF Protection).
 * Resolves DNS and blocks Private/Local IPs.
 */
export async function validateSafeHostAsync(hostInput: string): Promise<void> {
    if (!hostInput) throw new Error('Invalid host');

    let hostname = hostInput;

    // Normalize using URL parser if possible, to handle IPv6 brackets [::1] correctly and ports
    try {
        const u = new URL('https://' + hostInput);
        hostname = u.hostname;
    } catch (_e) {
        // Fallback to raw input if URL parsing fails
    }

    // 1. Initial Blocklist (Defense in Depth)
    if (hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]' || hostname === '0.0.0.0' || hostname === '::1') {
        throw new Error(`Security Violation: Access to localhost is denied.`);
    }
    if (hostname === '169.254.169.254') {
        throw new Error(`Security Violation: Access to Cloud Metadata services is denied.`);
    }

    // 2. Resolve DNS
    try {
        const addresses = await dns.promises.lookup(hostname, { all: true });

        // 3. Validate ALL Resolved IPs
        for (const { address } of addresses) {
            if (isPrivateIP(address)) {
                throw new Error(`Security Violation: Domain '${hostInput}' resolves to private IP ${address}.`);
            }
        }
    } catch (error: unknown) {
        const errMsg = error instanceof Error ? error.message : String(error);
        if (errMsg.startsWith('Security Violation')) throw error;
        // Fail closed if DNS resolution fails
        throw new Error(`Security Violation: Could not verify DNS for '${hostname}': ${errMsg}`);
    }
}

/**
 * Validates that a URL is safe to fetch by resolving DNS.
 */
export async function validateSafeUrlAsync(urlString: string): Promise<void> {
    let url: URL;
    try {
        url = new URL(urlString);
    } catch (_e) {
        throw new Error('Invalid URL format');
    }

    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
        throw new Error(`Security Violation: Protocol '${url.protocol}' is not allowed. Only HTTP/HTTPS are permitted.`);
    }

    const hostname = url.hostname;
    if (!hostname) throw new Error('Invalid URL: Missing hostname');

    await validateSafeHostAsync(hostname);
}

/**
 * @deprecated Use validateSafeUrlAsync instead. Kept for backward compatibility.
 */
export function validateSafeUrl(urlString: string): void {
    let url: URL;
    try {
        url = new URL(urlString);
    } catch (e) { throw new Error('Invalid URL'); }

    const hostname = url.hostname;
    if (hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '0.0.0.0' || hostname === '[::1]') {
        throw new Error('Security Violation: Access to localhost is denied.');
    }
    if (hostname === '169.254.169.254') {
        throw new Error('Security Violation: Access to Cloud Metadata services is denied.');
    }
}

/**
 * StreamingAgentCard Component
 *
 * Displays agent responses with token-by-token streaming animation.
 * Supports interruption, copy, and export functionality.
 */

import React, { useState } from 'react';
import { useAgentStream } from '@/hooks/useAgentStream';
import { Loader, Copy, Download, X } from 'lucide-react';
import { useStore } from '@/core/store';
import { useShallow } from 'zustand/react/shallow';
import clsx from 'clsx';

interface StreamingAgentCardProps {
  agentId: string;
  input?: string;
  context?: Record<string, unknown>;
  onComplete?: (text: string) => void;
  onError?: (error: Error) => void;
  autoStart?: boolean;
  title?: string;
  className?: string;
}

export const StreamingAgentCard: React.FC<StreamingAgentCardProps> = ({
  agentId,
  input = '',
  context,
  onComplete,
  onError,
  autoStart = false,
  title = 'Agent Response',
  className = ''
}) => {
  const { user } = useStore(useShallow(state => ({
    user: state.user
  })));
  const [copied, setCopied] = useState(false);
  const [expandedMetadata, setExpandedMetadata] = useState(false);

  const {
    isStreaming,
    fullText,
    tokens,
    error,
    stream,
    stop,
    reset,
    tokenCount
  } = useAgentStream(user?.uid || '', {
    onComplete: (metadata) => {
      onComplete?.(fullText);
    },
    onError: (err) => {
      onError?.(err);
    }
  });

  React.useEffect(() => {
    if (autoStart && input && !isStreaming) {
      stream(input, agentId, context);
    }
  }, [autoStart, input, agentId]);

  const handleCopy = () => {
    navigator.clipboard.writeText(fullText);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleExport = () => {
    const element = document.createElement('a');
    element.setAttribute('href', `data:text/plain;charset=utf-8,${encodeURIComponent(fullText)}`);
    element.setAttribute('download', `agent-response-${Date.now()}.txt`);
    element.style.display = 'none';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  return (
    <div className={clsx(
      'rounded-lg border border-gray-200 bg-white shadow-sm overflow-hidden',
      className
    )}>
      {/* Header */}
      <div className="flex items-center justify-between border-b border-gray-200 px-4 py-3">
        <div className="flex items-center gap-2">
          <h3 className="font-semibold text-gray-900">{title}</h3>
          {isStreaming && (
            <Loader className="h-4 w-4 animate-spin text-blue-500" />
          )}
        </div>
        <div className="flex items-center gap-2">
          {fullText && (
            <>
              <button
                onClick={handleCopy}
                className="p-1.5 hover:bg-gray-100 rounded transition-colors"
                title="Copy to clipboard"
              >
                <Copy className={clsx('h-4 w-4', copied ? 'text-green-600' : 'text-gray-600')} />
              </button>
              <button
                onClick={handleExport}
                className="p-1.5 hover:bg-gray-100 rounded transition-colors"
                title="Export as text file"
              >
                <Download className="h-4 w-4 text-gray-600" />
              </button>
            </>
          )}
          {isStreaming && (
            <button
              onClick={stop}
              className="p-1.5 hover:bg-red-50 rounded transition-colors"
              title="Stop streaming"
            >
              <X className="h-4 w-4 text-red-600" />
            </button>
          )}
        </div>
      </div>

      {/* Content */}
      <div className="px-4 py-3">
        {error ? (
          <div className="rounded bg-red-50 p-3 text-red-700 text-sm">
            <p className="font-semibold">Error</p>
            <p>{error.message}</p>
            <button
              onClick={reset}
              className="mt-2 text-red-600 hover:text-red-800 underline text-sm"
            >
              Try again
            </button>
          </div>
        ) : fullText ? (
          <div className="prose prose-sm max-w-none text-gray-900 whitespace-pre-wrap break-words">
            {fullText}
            {isStreaming && (
              <span className="inline-block w-2 h-4 bg-blue-500 ml-1 animate-pulse" />
            )}
          </div>
        ) : isStreaming ? (
          <div className="flex items-center justify-center py-8">
            <div className="text-center">
              <Loader className="h-8 w-8 animate-spin text-blue-500 mx-auto mb-2" />
              <p className="text-sm text-gray-600">Streaming response...</p>
            </div>
          </div>
        ) : (
          <div className="text-center py-8 text-gray-500">
            <p className="text-sm">No response yet</p>
            {input ? (
              <button
                onClick={() => stream(input, agentId, context)}
                className="mt-3 px-3 py-1.5 bg-blue-600 text-white rounded text-sm hover:bg-blue-700 transition-colors"
              >
                Start Streaming
              </button>
            ) : null}
          </div>
        )}
      </div>

      {/* Footer with Metadata */}
      {(tokenCount > 0 || isStreaming) && (
        <div className="border-t border-gray-200 bg-gray-50 px-4 py-2">
          <button
            onClick={() => setExpandedMetadata(!expandedMetadata)}
            className="flex items-center gap-2 text-xs text-gray-600 hover:text-gray-900 w-full"
          >
            <span>Tokens: {tokenCount}</span>
            <span>•</span>
            <span>Status: {isStreaming ? 'Streaming' : 'Complete'}</span>
          </button>
          {expandedMetadata && (
            <div className="mt-2 text-xs text-gray-600 space-y-1">
              <div>Agent: {agentId}</div>
              <div>Tokens generated: {tokenCount}</div>
              {input && <div>Input length: {input.length} chars</div>}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect } from 'vitest';
import AI_Input_Search from './ai-input-search';

// Mock Lucide icons
vi.mock('lucide-react', async (importOriginal) => ({
  ...(await importOriginal<typeof import('lucide-react')>()),
  Globe: () => <div data-testid="icon-globe">Globe</div>,
  Paperclip: ({ className }: { className?: string }) => (
    <div data-testid="icon-paperclip" className={className}>
      Paperclip
    </div>
  ),
  Send: () => <div data-testid="icon-send">Send</div>,
  Loader2: () => <div data-testid="icon-loader">Loader2</div>,
}));

// Mock motion/motion
vi.mock('motion/react', () => ({
  motion: {
    // Correctly filtering out motion props to avoid React warnings
    div: ({ children, whileHover, animate, initial, exit, transition, ...props }: any) => <div {...props}>{children}</div>,
    span: ({ children, whileHover, animate, initial, exit, transition, ...props }: any) => <span {...props}>{children}</span>,
  },
  AnimatePresence: ({ children }: any) => <>{children}</>,
}));

// Mock hook
vi.mock('@/hooks/use-auto-resize-textarea', () => ({
  useAutoResizeTextarea: () => ({
    textareaRef: { current: null },
    adjustHeight: vi.fn(),
  }),
}));

describe('AI_Input_Search Interaction', () => {
  it('handles the full Send lifecycle: Type -> Enable -> Click -> Submit -> Reset', async () => {
    const handleSubmit = vi.fn();
    const user = userEvent.setup();

    render(<AI_Input_Search onSubmit={handleSubmit} placeholder="Ask me anything..." />);

    // 1. Initial State: Button should be disabled
    const sendButton = screen.getByRole('button', { name: /send prompt/i });
    expect(sendButton).toBeDisabled();
    expect(sendButton).toHaveClass('cursor-not-allowed');

    // 2. Interaction: Type text
    const input = screen.getByPlaceholderText('Ask me anything...');
    await user.type(input, 'Hello Click Agent');

    // 3. Feedback: Button becomes enabled
    expect(sendButton).not.toBeDisabled();
    expect(sendButton).toHaveClass('cursor-pointer');
    expect(input).toHaveValue('Hello Click Agent');

    // 4. Action: Click Send
    await user.click(sendButton);

    // 5. Success Event: onSubmit called with trimmed value
    expect(handleSubmit).toHaveBeenCalledTimes(1);
    expect(handleSubmit).toHaveBeenCalledWith('Hello Click Agent');

    // Note: Since onSubmit is provided, internal value is NOT cleared.
    expect(input).toHaveValue('Hello Click Agent');
  });

  it('handles Loading state correctly', () => {
    render(<AI_Input_Search isLoading={true} />);

    const sendButton = screen.getByRole('button', { name: /sending prompt/i });
    expect(sendButton).toBeDisabled();
    expect(screen.getByTestId('icon-loader')).toBeInTheDocument();
    expect(screen.queryByTestId('icon-send')).not.toBeInTheDocument();
  });

  it('prevents sending empty or whitespace-only strings', async () => {
    const handleSubmit = vi.fn();
    const user = userEvent.setup();
    render(<AI_Input_Search onSubmit={handleSubmit} placeholder="Type here..." />);

    const input = screen.getByPlaceholderText('Type here...');
    const sendButton = screen.getByRole('button', { name: /send prompt/i });

    // Type spaces
    await user.type(input, '   ');
    expect(sendButton).toBeDisabled();

    // Try to force click (though disabled)
    await user.click(sendButton);
    expect(handleSubmit).not.toHaveBeenCalled();
  });

  it('submits on Enter key (without Shift)', async () => {
    const handleSubmit = vi.fn();
    const user = userEvent.setup();
    render(<AI_Input_Search onSubmit={handleSubmit} placeholder="Type here..." />);

    const input = screen.getByPlaceholderText('Type here...');
    await user.type(input, 'Quick message');

    // Press Enter
    await user.keyboard('{Enter}');

    expect(handleSubmit).toHaveBeenCalledWith('Quick message');
  });

  it('clears input automatically when no onSubmit prop is provided (default behavior)', async () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {});
    const user = userEvent.setup();

    render(<AI_Input_Search placeholder="Type here..." />); // No onSubmit provided

    const input = screen.getByPlaceholderText('Type here...');
    const sendButton = screen.getByRole('button', { name: /send prompt/i });

    await user.type(input, 'Self clearing message');
    await user.click(sendButton);

    // Should clear the input
    expect(input).toHaveValue('');

    consoleSpy.mockRestore();
  });

  it('toggles Search mode visibility on click', async () => {
    const user = userEvent.setup();
    render(<AI_Input_Search />);

    // Initial state: Search is visible (showSearch default is true)
    const toggleButton = screen.getByRole('button', { name: /hide search options/i });
    expect(toggleButton).toBeInTheDocument();

    // Check if "Search" text is visible
    expect(screen.getByText('Search')).toBeInTheDocument();

    // Click to toggle off
    await user.click(toggleButton);

    // Feedback: Aria label changes
    expect(toggleButton).toHaveAttribute('aria-label', 'Show search options');

    // Feedback: "Search" text disappears (mocked AnimatePresence removes it)
    await waitFor(() => {
      expect(screen.queryByText('Search')).not.toBeInTheDocument();
    });

    // Click to toggle on
    await user.click(toggleButton);

    // Feedback: Aria label changes back
    expect(toggleButton).toHaveAttribute('aria-label', 'Hide search options');
    expect(screen.getByText('Search')).toBeInTheDocument();
  });

  it('triggers file selection when Paperclip is clicked', async () => {
    const onFileSelect = vi.fn();
    const user = userEvent.setup();
    render(<AI_Input_Search onFileSelect={onFileSelect} />);

    const file = new File(['hello'], 'hello.png', { type: 'image/png' });
    const paperclipButton = screen.getByRole('button', { name: /attach file/i });
    const fileInput = screen.getByLabelText(/upload file/i); // Using aria-label on hidden input

    // Verify input is hidden
    expect(fileInput).toHaveClass('hidden');

    // Simulate file selection via user event on the input directly
    // (In a real browser, clicking the button triggers the input click, but in JSDOM we can simulate the upload directly)
    await user.upload(fileInput, file);

    expect(onFileSelect).toHaveBeenCalledTimes(1);
    expect(onFileSelect).toHaveBeenCalledWith(file);
    // Note: The component does NOT reset the file input value after selection,
    // so it will retain "C:\fakepath\hello.png" in JSDOM. We skip asserting empty value.
  });

  it('triggers file input click when Paperclip button is clicked', async () => {
    // This tests the wiring between the visible button and the hidden input
    const user = userEvent.setup();
    render(<AI_Input_Search />);

    const paperclipButton = screen.getByRole('button', { name: /attach file/i });
    const fileInput = screen.getByLabelText(/upload file/i);

    // Spy on the click method of the input
    const clickSpy = vi.spyOn(fileInput, 'click');

    await user.click(paperclipButton);

    expect(clickSpy).toHaveBeenCalled();
  });
});

import React from 'react';
import { useMobile } from '@/hooks/useMobile';
import { useResponsiveLayout } from '@/providers/ResponsiveLayoutProvider';
import { cn } from '@/lib/utils';

interface MobileAdaptiveLayoutProps {
  children: React.ReactNode;
  className?: string;
  hideOnPhone?: boolean;
  hideOnTablet?: boolean;
  hideOnDesktop?: boolean;
  showOnlyOn?: 'phone' | 'tablet' | 'desktop';
}

/**
 * MobileAdaptiveLayout
 *
 * Wraps content with responsive constraints and visibility rules.
 * Automatically hides/shows content based on breakpoint.
 */
export const MobileAdaptiveLayout: React.FC<MobileAdaptiveLayoutProps> = ({
  children,
  className,
  hideOnPhone,
  hideOnTablet,
  hideOnDesktop,
  showOnlyOn,
}) => {
  const mobile = useMobile();
  const layout = useResponsiveLayout();

  // Determine visibility
  const isHidden =
    hideOnPhone ||
    hideOnTablet ||
    hideOnDesktop ||
    (showOnlyOn === 'phone' && !mobile.isAnyPhone) ||
    (showOnlyOn === 'tablet' && mobile.deviceType !== 'tablet') ||
    (showOnlyOn === 'desktop' && !mobile.isDesktop);

  if (isHidden) {
    return null;
  }

  // Mobile-specific padding/spacing
  const mobilePadding = mobile.isAnyPhone ? 'px-4 py-3' : 'px-6 py-4';

  return (
    <div
      className={cn(
        'w-full transition-all duration-200',
        mobilePadding,
        // Responsive max-width
        mobile.isPhone && 'max-w-full',
        mobile.isPhoneLg && 'max-w-xl',
        mobile.isTablet && 'max-w-2xl',
        mobile.isDesktop && 'max-w-4xl',
        mobile.isDesktopXl && 'max-w-6xl',
        className
      )}
    >
      {children}
    </div>
  );
};

interface ResponsiveContainerProps {
  children: React.ReactNode;
  className?: string;
}

/**
 * ResponsiveContainer
 *
 * Applies adaptive layout with proper spacing for all breakpoints.
 */
export const ResponsiveContainer: React.FC<ResponsiveContainerProps> = ({
  children,
  className,
}) => {
  const mobile = useMobile();

  return (
    <div
      className={cn(
        'w-full h-full',
        // Grid spacing based on breakpoint
        mobile.isPhone && 'gap-2',
        mobile.isPhoneLg && 'gap-3',
        mobile.isTablet && 'gap-4',
        mobile.isDesktop && 'gap-6',
        className
      )}
    >
      {children}
    </div>
  );
};

interface ResponsiveGridProps {
  children: React.ReactNode;
  className?: string;
  cols?: {
    phone?: number;
    tablet?: number;
    desktop?: number;
  };
}

/**
 * ResponsiveGrid
 *
 * Grid layout that adapts column count by breakpoint.
 */
export const ResponsiveGrid: React.FC<ResponsiveGridProps> = ({
  children,
  className,
  cols = {
    phone: 1,
    tablet: 2,
    desktop: 3,
  },
}) => {
  const mobile = useMobile();

  let colClass = 'grid-cols-1';
  if (mobile.isPhone) {
    colClass = `grid-cols-${cols.phone}`;
  } else if (mobile.isTablet) {
    colClass = `grid-cols-${cols.tablet}`;
  } else {
    colClass = `grid-cols-${cols.desktop}`;
  }

  return (
    <div className={cn('grid gap-4', colClass, className)}>{children}</div>
  );
};

import { useState, useCallback } from 'react';
import * as DialogPrimitive from '@radix-ui/react-dialog';
import { AlertTriangle, Trash2 } from 'lucide-react';
import { cn } from '@/lib/utils';

/**
 * Item 291: Reusable Destructive Action Confirmation Dialog
 *
 * Wraps Radix Dialog to provide a consistent confirm/cancel UI
 * for irreversible actions (delete release, remove collaborator, cancel subscription, etc.).
 */

export interface ConfirmDialogProps {
    /** Whether the dialog is open */
    open: boolean;
    /** Called when the dialog should close (cancel or backdrop click) */
    onOpenChange: (open: boolean) => void;
    /** Called when the user confirms the destructive action */
    onConfirm: () => void | Promise<void>;
    /** Dialog title */
    title: string;
    /** Description/body text explaining the consequences */
    description: string;
    /** Text for the confirm button (default: "Delete") */
    confirmLabel?: string;
    /** Text for the cancel button (default: "Cancel") */
    cancelLabel?: string;
    /** Visual variant — determines icon and button color */
    variant?: 'danger' | 'warning';
    /** Whether the confirm action is currently loading */
    loading?: boolean;
}

const variantConfig = {
    danger: {
        icon: Trash2,
        iconBg: 'bg-red-500/10',
        iconColor: 'text-red-400',
        confirmBg: 'bg-red-600 hover:bg-red-700 focus:ring-red-500',
    },
    warning: {
        icon: AlertTriangle,
        iconBg: 'bg-amber-500/10',
        iconColor: 'text-amber-400',
        confirmBg: 'bg-amber-600 hover:bg-amber-700 focus:ring-amber-500',
    },
};

export function ConfirmDialog({
    open,
    onOpenChange,
    onConfirm,
    title,
    description,
    confirmLabel = 'Delete',
    cancelLabel = 'Cancel',
    variant = 'danger',
    loading = false,
}: ConfirmDialogProps) {
    const config = variantConfig[variant];
    const Icon = config.icon;

    const handleConfirm = useCallback(async () => {
        await onConfirm();
        onOpenChange(false);
    }, [onConfirm, onOpenChange]);

    return (
        <DialogPrimitive.Root open={open} onOpenChange={onOpenChange}>
