/**
 * Hook to globally toggle the shortcuts modal with the "?" key.
 * Install once in the app shell (e.g., App.tsx or Sidebar).
 */
export function useGlobalShortcutsModal() {
    const [isOpen, setIsOpen] = useState(false);

    const handleKeyDown = useCallback((e: KeyboardEvent) => {
        const target = e.target as HTMLElement;
        const isInput = target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable;

        if (e.key === '?' && !e.ctrlKey && !e.metaKey && !isInput) {
            e.preventDefault();
            setIsOpen(prev => !prev);
            return;
        }

        if (e.code === 'Space' && !e.ctrlKey && !e.metaKey && !isInput) {
            const state = useStore.getState();
            if (state.currentTrack) {
                e.preventDefault();
                if (state.isPlaying) {
                    state.pauseTrack();
                } else {
                    state.resumeTrack();
                }
            }
            return;
        }

        if (e.key === 'Escape' && isOpen) {
            setIsOpen(false);
        }
    }, [isOpen]);

    useEffect(() => {
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [handleKeyDown]);

    return { isOpen, close: () => setIsOpen(false) };
}

import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { shaderMaterial } from '@react-three/drei';
import { extend } from '@react-three/fiber';
import { useStore } from '@/core/store';

// Custom Shader Material
const WaveShaderMaterial = shaderMaterial(
    // Uniforms
    {
        uTime: 0,
        uColorStart: new THREE.Color('#050a05') as any, // Dark Green Base
        uColorEnd: new THREE.Color('#0a1a0a') as any,   // Forest Green
        uMouse: new THREE.Vector2(0, 0) as any,
        uHover: 0,
        uAudioEQ: new THREE.Vector4(0, 0, 0, 0) as any,
        // Brand Colors / Frequency Colors
        uColorBass: new THREE.Color('#00ff66') as any,    // Spring Green
        uColorLowMid: new THREE.Color('#bfff00') as any,  // Lime
        uColorHighMid: new THREE.Color('#10b981') as any, // Emerald
        uColorTreble: new THREE.Color('#ffffff') as any,  // White Sparkle
    },
    // Vertex Shader
    `
    varying vec2 vUv;
    varying float vElevation;
    varying vec4 vAudio;
    varying float vDisplacement;

    uniform float uTime;
    uniform vec4 uAudioEQ;

    // Simplex noise function (simplified)
    vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

    float snoise(vec2 v) {
        const vec4 C = vec4(0.211324865405187,  // (3.0-sqrt(3.0))/6.0
                            0.366025403784439,  // 0.5*(sqrt(3.0)-1.0)
                            -0.577350269189626, // -1.0 + 2.0 * C.x
                            0.024390243902439); // 1.0 / 41.0
        vec2 i  = floor(v + dot(v, C.yy) );
        vec2 x0 = v - i + dot(i, C.xx);
        vec2 i1;
        i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
        vec4 x12 = x0.xyxy + C.xxzz;
        x12.xy -= i1;
        i = mod289(i); // Avoid truncation effects in permutation
        vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
            + i.x + vec3(0.0, i1.x, 1.0 ));
        vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
        m = m*m ;
        m = m*m ;
        vec3 x = 2.0 * fract(p * C.www) - 1.0;
        vec3 h = abs(x) - 0.5;
        vec3 ox = floor(x + 0.5);
        vec3 a0 = x - ox;
        m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
        vec3 g;
        g.x  = a0.x  * x0.x  + h.x  * x0.y;
        g.yz = a0.yz * x12.xz + h.yz * x12.yw;
        return 130.0 * dot(m, g);
    }

    void main() {
      vUv = uv;
      vAudio = uAudioEQ;
      vec4 modelPosition = modelMatrix * vec4(position, 1.0);

      // Distance from center
      float dist = length(modelPosition.xz);
      float angle = atan(modelPosition.z, modelPosition.x);

      // --- Band 1: BASS (Deep, slow, central pulse) ---
      float bassDisplacement = sin(dist * 0.5 - uTime * 1.0) * uAudioEQ.x * 2.0;
      float bassKick = smoothstep(10.0, 0.0, dist) * uAudioEQ.x * 2.0;

      // --- Band 2: LOW MID (Rolling waves) ---
      float lowMidDisplacement = sin(modelPosition.x * 0.5 + uTime * 0.5) * uAudioEQ.y * 1.5;

      // --- Band 3: HIGH MID (Interference patterns) ---
      float highMidDisplacement = snoise(modelPosition.xz * 0.2 + uTime * 0.5) * uAudioEQ.z * 1.5;

      // --- Band 4: TREBLE (Sharp, jagged noise) ---
      float trebleDisplacement = snoise(modelPosition.xz * 1.0 - uTime) * uAudioEQ.w * 0.8;

      // Combine displacements
      float totalDisplacement = bassDisplacement + bassKick + lowMidDisplacement + highMidDisplacement + trebleDisplacement;

      // Add subtle base breathing
      totalDisplacement += sin(modelPosition.x * 1.0 + uTime * 0.2) * 0.2;

      modelPosition.y += totalDisplacement;
      vElevation = totalDisplacement;
      vDisplacement = totalDisplacement;

      gl_Position = projectionMatrix * viewMatrix * modelPosition;
    }
  `,
    // Fragment Shader
    `
    varying vec2 vUv;
    varying float vElevation;
    varying vec4 vAudio;
    varying float vDisplacement;

    uniform vec3 uColorStart;
    uniform vec3 uColorEnd;
    uniform vec3 uColorBass;
    uniform vec3 uColorLowMid;
    uniform vec3 uColorHighMid;
    uniform vec3 uColorTreble;

    void main() {
      float mixStrength = (vElevation + 1.0) * 0.25; 
      vec3 color = mix(uColorStart, uColorEnd, mixStrength);

      // --- AUDIO COLOR MIXING ---
      color += uColorBass * vAudio.x * 0.8;

      float wavePattern = sin(vUv.x * 10.0 + vAudio.y);
      color += uColorLowMid * vAudio.y * 0.6 * smoothstep(0.3, 0.7, wavePattern);

      float ripplePattern = sin(length(vUv - 0.5) * 20.0);
      color += uColorHighMid * vAudio.z * 0.6 * smoothstep(0.3, 0.7, ripplePattern);

      float peak = smoothstep(1.0, 3.5, vElevation);
      color += uColorTreble * vAudio.w * peak * 3.5;

      float vignette = 1.0 - length(vUv - 0.5);
      color *= smoothstep(0.0, 1.5, vignette);

      gl_FragColor = vec4(color, 1.0); 
    }
  `
);

extend({ WaveShaderMaterial });

// Add type definition for the shader material
/* eslint-disable @typescript-eslint/no-namespace */
declare global {
    namespace JSX {
        interface IntrinsicElements {
            waveShaderMaterial: any;
        }
    }
}

export default function WaveMesh() {
    const materialRef = useRef<any>(null);

    // Helper to calculate average of a sub-array
    const avg = (arr: number[]) => arr.reduce((a, b) => a + b, 0) / (arr.length || 1);

    useFrame((state) => {
        if (materialRef.current) {
            materialRef.current.uTime = state.clock.elapsedTime * 0.4;

            // Get Audio Data from the global store
            const { frequencyData } = useStore.getState();
            const { bands } = frequencyData;

            // Create 4-Band EQ (Bands 0-30)
            const bass = Math.pow(avg(bands.slice(0, 4)), 1.5) * 1.2;
            const lowMid = Math.pow(avg(bands.slice(4, 11)), 1.5) * 1.0;
            const highMid = Math.pow(avg(bands.slice(11, 21)), 1.5) * 1.0;
            const treble = Math.pow(avg(bands.slice(21, 31)), 1.5) * 1.5;

            materialRef.current.uAudioEQ.set(bass, lowMid, highMid, treble);
        }
    });

    return (
        <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -2, 0]} frustumCulled={false}>
            <planeGeometry args={[25, 25, 64, 64]} />
            <waveShaderMaterial
                ref={materialRef}
                uColorStart={new THREE.Color('#050a05') as any}
                uColorEnd={new THREE.Color('#0a1a0a') as any}
                uColorBass={new THREE.Color('#00ff66') as any}   // Spring Green
                uColorLowMid={new THREE.Color('#bfff00') as any} // Lime
                uColorHighMid={new THREE.Color('#10b981') as any} // Emerald
                uColorTreble={new THREE.Color('#ffffff') as any}
                wireframe={true}
                transparent={true}
                opacity={1.0}
            />
        </mesh>
    );
}

import React, { useRef, useState, useCallback } from 'react';
import { Camera, RefreshCw, Check, Loader2, X } from 'lucide-react';
import { logger } from '@/utils/logger';

interface WebcamCaptureProps {
    onCapture: (blob: Blob) => void;
    onClose: () => void;
}

export default function WebcamCapture({ onCapture, onClose }: WebcamCaptureProps) {
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [stream, setStream] = useState<MediaStream | null>(null);
    const [capturedImage, setCapturedImage] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [isInitializing, setIsInitializing] = useState(true);

    const startCamera = useCallback(async () => {
        setIsInitializing(true);
        setError(null);
        try {
            const mediaStream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: 'user' },
                audio: false
            });
            setStream(mediaStream);
            if (videoRef.current) {
                videoRef.current.srcObject = mediaStream;
            }
        } catch (err: unknown) {
            logger.error("Error accessing camera:", err);
            setError("Could not access camera. Please check permissions.");
        } finally {
            setIsInitializing(false);
        }
    }, []);

    const streamRef = useRef<MediaStream | null>(null);

    React.useEffect(() => {
        startCamera();
        const currentStreamRef = streamRef;
        return () => {
            currentStreamRef.current?.getTracks().forEach(track => track.stop());
        };
    }, [startCamera]);

    const handleCapture = () => {
        if (videoRef.current && canvasRef.current) {
            const video = videoRef.current;
            const canvas = canvasRef.current;
            const context = canvas.getContext('2d');

            if (context) {
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                context.drawImage(video, 0, 0, canvas.width, canvas.height);

                const dataUrl = canvas.toDataURL('image/png');
                setCapturedImage(dataUrl);
            }
        }
    };

    const handleRetake = () => {
        setCapturedImage(null);
    };

    const handleConfirm = () => {
        if (canvasRef.current) {
            canvasRef.current.toBlob((blob) => {
                if (blob) {
                    onCapture(blob);
                }
            }, 'image/png');
        }
    };

    return (
        <div
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4"
            role="dialog"
            aria-modal="true"
            aria-labelledby="webcam-capture-title"
        >
            <div className="bg-[#161b22] border border-gray-800 rounded-xl p-6 w-full max-w-lg flex flex-col gap-4">
                <div className="flex justify-between items-center">
                    <h3 id="webcam-capture-title" className="text-lg font-bold text-white">Capture Reference</h3>
                    <button
                        onClick={onClose}
                        className="text-gray-400 hover:text-white"
                        aria-label="Close camera"
                    >
                        <X size={24} />
                    </button>
                </div>

                <div className="relative aspect-video bg-black rounded-lg overflow-hidden flex items-center justify-center">
                    {isInitializing && <Loader2 className="animate-spin text-purple-400" size={32} />}

                    {error && (
                        <div className="text-red-400 text-center px-4">
                            <p>{error}</p>
                            <button
                                onClick={startCamera}
                                className="mt-2 text-sm underline hover:text-red-300"
                            >
                                Retry
                            </button>
                        </div>
                    )}

                    {!capturedImage && !error && (
                        <video
                            ref={videoRef}
                            autoPlay
                            playsInline
                            className={`w-full h-full object-cover transform scale-x-[-1] ${isInitializing ? 'hidden' : ''}`}
                        />
                    )}

                    {capturedImage && (
                        <img
                            src={capturedImage}
                            alt="Captured"
                            className="w-full h-full object-cover"
                        />
                    )}

                    <canvas ref={canvasRef} className="hidden" />
                </div>

                <div className="flex justify-center gap-4">
                    {!capturedImage ? (
                        <button
                            onClick={handleCapture}
                            disabled={!!error || isInitializing}
                            className="flex items-center gap-2 bg-purple-600 hover:bg-purple-700 text-white px-6 py-3 rounded-full font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            <Camera size={20} />
                            Capture
                        </button>
                    ) : (
                        <>
                            <button
                                onClick={handleRetake}
                                className="flex items-center gap-2 bg-gray-700 hover:bg-gray-600 text-white px-6 py-3 rounded-full font-medium transition-colors"
                            >
                                <RefreshCw size={20} />
                                Retake
                            </button>
                            <button
                                onClick={handleConfirm}
                                className="flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-full font-bold transition-colors"
                            >
                                <Check size={20} />
                                Use Photo
                            </button>
                        </>
                    )}
                </div>
            </div>
        </div>
    );
}

import React, { useState, useCallback } from 'react';
import { useOfflineSync } from '@/hooks/useOfflineSync';
import { useMobile } from '@/hooks/useMobile';
import {
  AlertCircle,
  WifiOff,
  RefreshCw,
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface SyncQueueIndicatorProps {
  className?: string;
}

/**
 * SyncQueueIndicator
 *
 * Shows pending offline operations status.
 * Displays as a badge when there are pending items or device is offline.
 */
export const SyncQueueIndicator: React.FC<SyncQueueIndicatorProps> = ({
  className,
}) => {
  const { isOnline, pendingOperations, sync } = useOfflineSync();
  const [isRetrying, setIsRetrying] = useState(false);

  const handleRetry = useCallback(async () => {
    setIsRetrying(true);
    try {
      await sync();
    } finally {
      setIsRetrying(false);
    }
  }, [sync]);

  // Don't show if online and no pending operations
  if (isOnline && pendingOperations === 0) {
    return null;
  }

  const badgeColor = isOnline ? 'bg-amber-100 text-amber-800' : 'bg-red-100 text-red-800';
  const statusText = isOnline
    ? `${pendingOperations} pending`
    : 'Offline';

  return (
    <div className={cn('flex items-center', className)}>
      <button
        onClick={handleRetry}
        disabled={isRetrying || !isOnline}
        className={cn(
          'relative flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors',
          'disabled:opacity-50 disabled:cursor-not-allowed',
          badgeColor,
          isRetrying && 'opacity-75'
        )}
        title={isOnline ? 'Click to sync pending changes' : 'You are offline'}
      >
        {isOnline ? (
          <AlertCircle className="h-4 w-4" />
        ) : (
          <WifiOff className="h-4 w-4" />
        )}

        <span>{statusText}</span>

        {pendingOperations > 0 && isRetrying && (
          <RefreshCw className="h-3 w-3 animate-spin" />
        )}
      </button>
    </div>
  );
};

import { useState, useEffect, useCallback } from 'react';

/**
 * Item 290: Contextual First-Run Tooltips
 *
 * Lightweight first-run tooltip system using localStorage.
 * Shows contextual hints to new users, each dismissed permanently.
 *
 * Usage:
 *   const { shouldShow, dismiss } = useFirstRunTip('command-bar');
 *
 *   return (
 *     <>
 *       <CommandBar />
 *       {shouldShow && (
 *         <FirstRunTooltip
 *           message="Press ⌘K to open the Command Bar"
 *           onDismiss={dismiss}
 *         />
 *       )}
 *     </>
 *   );
 */

const STORAGE_KEY = 'indii_first_run_tips';

interface TipState {
    [tipId: string]: boolean; // true = dismissed
}

function loadTipState(): TipState {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? JSON.parse(raw) : {};
    } catch {
        return {};
    }
}

function saveTipState(state: TipState): void {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch {
        // Ignore storage errors
    }
}

/**
 * Hook to manage a single first-run tooltip
 */
export function useFirstRunTip(tipId: string) {
    const [shouldShow, setShouldShow] = useState(false);

    useEffect(() => {
        const state = loadTipState();
        if (!state[tipId]) {
            // Small delay so it doesn't flash on mount
            const timer = setTimeout(() => setShouldShow(true), 1000);
            return () => clearTimeout(timer);
        }
    }, [tipId]);

    const dismiss = useCallback(() => {
        setShouldShow(false);
        const state = loadTipState();
        state[tipId] = true;
        saveTipState(state);
    }, [tipId]);

    return { shouldShow, dismiss };
}

/**
 * Reset all tips (useful for testing or "replay tour" feature)
 */
export function resetAllTips(): void {
    localStorage.removeItem(STORAGE_KEY);
}

/** Predefined tips for key features */
export const TIPS = {
    COMMAND_BAR: 'command-bar',
    MODULE_SWITCHER: 'module-switcher',
    AI_CHAT: 'ai-chat',
    CREATIVE_STUDIO: 'creative-studio',
    DISTRIBUTION: 'distribution',
    VIDEO_STUDIO: 'video-studio',
} as const;

/**
 * Lightweight tooltip component for first-run hints
 */
interface FirstRunTooltipProps {
    message: string;
    onDismiss: () => void;
    position?: 'top' | 'bottom' | 'left' | 'right';
    className?: string;
}

export function FirstRunTooltip({
    message,
    onDismiss,
    position = 'bottom',
    className = '',
}: FirstRunTooltipProps) {
    const positionClasses: Record<string, string> = {
        top: 'bottom-full mb-2',
        bottom: 'top-full mt-2',
        left: 'right-full mr-2',
        right: 'left-full ml-2',
    };

    return (
        <div
            className={`absolute z-50 ${positionClasses[position]} ${className}`}
            role="tooltip"
        >
            <div className="bg-linear-to-r from-purple-600 to-blue-600 text-white text-xs px-4 py-2.5 rounded-xl shadow-lg shadow-purple-900/30 max-w-xs animate-in fade-in slide-in-from-bottom-2 duration-300">
                <p className="leading-relaxed">{message}</p>
                <button
                    onClick={onDismiss}
                    className="mt-1.5 text-[10px] font-bold text-white/70 hover:text-white uppercase tracking-wider transition-colors"
                    aria-label="Dismiss tip"
                >
                    Got it
                </button>
            </div>
        </div>
    );
}

