// Context to share hover state
const MouseEnterContext = React.createContext<[boolean, React.Dispatch<React.SetStateAction<boolean>>] | undefined>(undefined);

export const ThreeDCardContainer = ({
    children,
    className,
    containerClassName,
    onClick
}: {
    children: React.ReactNode;
    className?: string;
    containerClassName?: string;
    onClick?: () => void;
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const frameRef = useRef<number>(0);
    const rectRef = useRef<DOMRect | null>(null);
    const [isMouseEntered, setIsMouseEntered] = useState(false);

    const updateRect = useCallback(() => {
        if (containerRef.current) {
            rectRef.current = containerRef.current.getBoundingClientRect();
        }
    }, []);

    // Cleanup listeners on unmount
    useEffect(() => {
        return () => {
            window.removeEventListener('scroll', updateRect, { capture: true });
            if (frameRef.current) {
                cancelAnimationFrame(frameRef.current);
            }
        };
    }, [updateRect]);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
        if (!containerRef.current) return;

        const clientX = e.clientX;
        const clientY = e.clientY;

        if (frameRef.current) {
            cancelAnimationFrame(frameRef.current);
        }

        frameRef.current = requestAnimationFrame(() => {
            if (!containerRef.current) return;
            // Bolt Optimization: Use cached rect to avoid reflow on every frame
            const rect = rectRef.current || containerRef.current.getBoundingClientRect();

            const { left, top, width, height } = rect;
            const x = (clientX - left - width / 2) / 25;
            const y = (clientY - top - height / 2) / 25;
            containerRef.current.style.transform = `rotateY(${x}deg) rotateX(${-y}deg)`;
        });
    };

    const handleMouseEnter = (e: React.MouseEvent<HTMLDivElement>) => {
        setIsMouseEntered(true);
        if (!containerRef.current) return;
        updateRect();
        // Bolt Optimization: Update rect on scroll to handle scrolling while hovering
        window.addEventListener('scroll', updateRect, { capture: true, passive: true });
    };

    const handleMouseLeave = (e: React.MouseEvent<HTMLDivElement>) => {
        if (!containerRef.current) return;
        setIsMouseEntered(false);
        window.removeEventListener('scroll', updateRect, { capture: true });
        if (frameRef.current) {
            cancelAnimationFrame(frameRef.current);
        }
        containerRef.current.style.transform = `rotateY(0deg) rotateX(0deg)`;
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
        if (onClick && (e.key === 'Enter' || e.key === ' ')) {
            e.preventDefault();
            onClick();
        }
    };

    return (
        <MouseEnterContext.Provider value={[isMouseEntered, setIsMouseEntered]}>
            <div
                className={cn(
                    "flex items-center justify-center",
                    containerClassName
                )}
                style={{
                    perspective: "1000px",
                }}
            >
                <div
                    ref={containerRef}
                    onMouseEnter={handleMouseEnter}
                    onMouseMove={handleMouseMove}
                    onMouseLeave={handleMouseLeave}
                    onClick={onClick}
                    role={onClick ? "button" : undefined}
                    tabIndex={onClick ? 0 : undefined}
                    onKeyDown={handleKeyDown}
                    className={cn(
                        "flex items-center justify-center relative transition-all duration-200 ease-linear",
                        onClick && "cursor-pointer focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 rounded-xl",
                        className
                    )}
                    style={{
                        transformStyle: "preserve-3d",
                    }}
                >
                    {children}
                </div>
            </div>
        </MouseEnterContext.Provider>
    );
};

export const useMouseEnter = () => {
    const context = React.useContext(MouseEnterContext);
    if (context === undefined) {
        throw new Error("useMouseEnter must be used within a MouseEnterProvider");
    }
    return context;
};

import { render, screen, fireEvent } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { PromptInput, PromptInputTextarea } from './prompt-input'
import { describe, it, expect, vi } from 'vitest'
import React from 'react'

describe('PromptInput', () => {
  it('renders with focus-within classes', () => {
    render(
      <PromptInput>
        <PromptInputTextarea />
      </PromptInput>
    )

    const container = screen.getByTestId('prompt-wrapper')
    expect(container).toHaveClass('focus-within:ring-2')
    expect(container).toHaveClass('focus-within:ring-ring')
    expect(container).toHaveClass('focus-within:ring-offset-2')
  })

  it('updates value when typing', async () => {
    const user = userEvent.setup()
    const onValueChange = vi.fn()

    render(
      <PromptInput onValueChange={onValueChange}>
        <PromptInputTextarea />
      </PromptInput>
    )

    const textarea = screen.getByRole('textbox')
    await user.type(textarea, 'Hello World')

    expect(textarea).toHaveValue('Hello World')
    expect(onValueChange).toHaveBeenLastCalledWith('Hello World')
  })

  it('submits on Enter (without Shift)', async () => {
    const user = userEvent.setup()
    const onSubmit = vi.fn()

    render(
      <PromptInput onSubmit={onSubmit}>
        <PromptInputTextarea />
      </PromptInput>
    )

    const textarea = screen.getByRole('textbox')
    await user.type(textarea, 'Hello{Enter}')

    expect(onSubmit).toHaveBeenCalledTimes(1)
  })

  it('does not submit on Shift+Enter', async () => {
    const user = userEvent.setup()
    const onSubmit = vi.fn()

    render(
      <PromptInput onSubmit={onSubmit}>
        <PromptInputTextarea />
      </PromptInput>
    )

    const textarea = screen.getByRole('textbox')
    await user.type(textarea, 'Hello{Shift>}{Enter}{/Shift}World')

    expect(onSubmit).not.toHaveBeenCalled()
    expect(textarea).toHaveValue('Hello\nWorld')
  })

  it('disables input when isLoading is true', () => {
    render(
      <PromptInput isLoading={true}>
        <PromptInputTextarea />
      </PromptInput>
    )

    const container = screen.getByTestId('prompt-wrapper')
    const textarea = screen.getByRole('textbox')

    expect(container).toHaveClass('opacity-60')
    expect(container).toHaveClass('cursor-not-allowed')
    expect(textarea).toBeDisabled()
  })

  it('does not submit when disabled', async () => {
    const user = userEvent.setup()
    const onSubmit = vi.fn()

    render(
      <PromptInput disabled={true} onSubmit={onSubmit}>
        <PromptInputTextarea />
      </PromptInput>
    )

    const textarea = screen.getByRole('textbox')
    // We can't type into a disabled input with userEvent, so we check it's disabled
    // and try to force a keydown event using fireEvent to ensure the handler blocks it or simply rely on the disabled attribute

    expect(textarea).toBeDisabled()

    // Attempt to manually fire the event, though browsers would block this on disabled inputs.
    // The handler logic usually sits on the element.
    fireEvent.keyDown(textarea, { key: 'Enter', code: 'Enter' })

    expect(onSubmit).not.toHaveBeenCalled()
  })

  it('does not submit when isLoading is true', async () => {
    const onSubmit = vi.fn()

    render(
      <PromptInput isLoading={true} onSubmit={onSubmit}>
        <PromptInputTextarea />
      </PromptInput>
    )

    const textarea = screen.getByRole('textbox')
    expect(textarea).toBeDisabled()

    fireEvent.keyDown(textarea, { key: 'Enter', code: 'Enter' })

    expect(onSubmit).not.toHaveBeenCalled()
  })
})

