import React, { useEffect } from 'react';
import { useStore } from '@/core/store';
import { useProjectSlice } from '@/core/store/slices/projectSlice';
import { ProjectService } from '@/services/project/ProjectService';
import { FolderGit2, Plus, ChevronDown, Pencil, Trash2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';
import { useShallow } from 'zustand/react/shallow';
import { getAuth } from 'firebase/auth';
import { useProjectSync } from '@/hooks/useProjectSync';

interface ProjectListProps {
  isSidebarOpen: boolean;
}

export function ProjectList({ isSidebarOpen }: ProjectListProps) {
  const {
    projects,
    selectedProjectId,
    setSelectedProject,
    setProjects,
    isLoading,
    setLoading,
    setError
  } = useProjectSlice(
    useShallow((state) => ({
      projects: state.projects,
      selectedProjectId: state.selectedProjectId,
      setSelectedProject: state.setSelectedProject,
      setProjects: state.setProjects,
      isLoading: state.isLoading,
      setLoading: state.setLoading,
      setError: state.setError
    }))
  );

  const { syncProject } = useProjectSync();

  const [isOpen, setIsOpen] = React.useState(true);

  useEffect(() => {
    async function loadProjects() {
      const auth = getAuth();
      const user = auth.currentUser;
      if (!user) return;

      try {
        setLoading(true);
        // Ensure inbox project exists and list all active projects
        await ProjectService.ensureInbox(user.uid);
        const userProjects = await ProjectService.listByUser(user.uid);
        setProjects(userProjects);
      } catch (err) {
        console.error('Failed to load projects:', err);
        setError(err instanceof Error ? err.message : 'Unknown error');
      } finally {
        setLoading(false);
      }
    }

    loadProjects();
  }, [setProjects, setLoading, setError]);

  const handleCreateProject = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const auth = getAuth();
    const user = auth.currentUser;
    if (!user) return;

    // In a real implementation this would probably open a modal
    const name = prompt('Project Name:');
    if (!name) return;

    try {
      const newProject = await ProjectService.create(user.uid, name);
      // Reload projects
      const updatedProjects = await ProjectService.listByUser(user.uid);
      setProjects(updatedProjects);
      setSelectedProject(newProject);
      syncProject(newProject.id);
    } catch (err) {
      console.error('Failed to create project:', err);
    }
  };

  const handleRenameProject = async (e: React.MouseEvent, project: any) => {
    e.stopPropagation();
    const newName = prompt('Rename project:', project.name);
    if (!newName || newName === project.name) return;

    try {
      await ProjectService.update(project.id, { name: newName });
      const auth = getAuth();
      if (auth.currentUser) {
        const updatedProjects = await ProjectService.listByUser(auth.currentUser.uid);
        setProjects(updatedProjects);
      }
    } catch (err) {
      console.error('Failed to rename project:', err);
    }
  };

  const handleDeleteProject = async (e: React.MouseEvent, project: any) => {
    e.stopPropagation();
    if (project.name === 'Inbox') {
      alert('The Inbox project cannot be deleted.');
      return;
    }

    if (!confirm(`Are you sure you want to delete "${project.name}"?`)) return;

    try {
      await ProjectService.setStatus(project.id, 'archived');
      const auth = getAuth();
      if (auth.currentUser) {
        const updatedProjects = await ProjectService.listByUser(auth.currentUser.uid);
        setProjects(updatedProjects);
        // Reset selected project if we deleted the current one
        if (selectedProjectId === project.id) {
            const defaultProj = updatedProjects.find(p => p.name === 'Inbox') || updatedProjects[0];
            if (defaultProj) {
                setSelectedProject(defaultProj);
                syncProject(defaultProj.id);
            }
        }
      }
    } catch (err) {
      console.error('Failed to delete project:', err);
    }
  };

  const projectArray = Array.from(projects.values());

  return (
    <div className="mb-2">
      {isSidebarOpen && (
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="w-full flex items-center justify-between px-4 py-1 text-xs font-semibold text-gray-400 hover:text-gray-200 uppercase tracking-wider mb-1 transition-colors group"
        >
          <span className="whitespace-nowrap flex items-center gap-2">
            Projects
          </span>
          <div className="flex items-center gap-1">
            <Plus
              size={14}
              className="opacity-0 group-hover:opacity-100 transition-opacity hover:text-white"
              onClick={handleCreateProject}
            />
            <ChevronDown
              size={14}
              className={cn("transition-transform duration-200", isOpen ? "rotate-180" : "")}
            />
          </div>
        </button>
      )}

      <AnimatePresence initial={false}>
        {(!isSidebarOpen || isOpen) && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="space-y-0.5 overflow-hidden"
          >
            {isLoading && projectArray.length === 0 ? (
              <div className="px-4 py-2 text-xs text-gray-500">Loading...</div>
            ) : projectArray.length === 0 ? (
              <div className="px-4 py-2 text-xs text-gray-500">No projects</div>
            ) : (
              projectArray.map((project) => {
                const isActive = selectedProjectId === project.id;
                return (
                  <div
                    key={project.id}
                    onClick={() => {
                      setSelectedProject(project);
                      syncProject(project.id);
                    }}
                    className={cn(
                      "w-[calc(100%-8px)] mx-1 flex items-center justify-between px-3 py-2 text-sm rounded-lg transition-all duration-200 relative group overflow-hidden mb-0.5 cursor-pointer",
                      isActive
                        ? "text-white font-bold bg-white/[0.12] shadow-[inset_0_0_0_1px_rgba(255,255,255,0.15)] ring-1 ring-white/10"
                        : "text-gray-400 font-medium hover:text-white hover:bg-white/[0.05]"
                    )}
                  >
                    <div className="flex items-center gap-3 overflow-hidden flex-1">
                      {isActive && (
                        <motion.div
                          layoutId="active-project-pill"
                          className="absolute left-0 top-0 w-1 h-full bg-blue-500 rounded-r-md"
                          transition={{ type: "spring", stiffness: 300, damping: 30 }}
                        />
                      )}

                      <FolderGit2
                        size={16}
                        className={cn(
                          "relative z-10 transition-transform duration-200 flex-shrink-0 group-hover:scale-110",
                          isActive ? "text-blue-400" : "opacity-70 group-hover:opacity-100"
                        )}
                      />

                      {isSidebarOpen && (
                        <span className={cn(
                          "truncate relative z-10 transition-all duration-200",
                          isActive ? "translate-x-1" : "group-hover:translate-x-0.5"
                        )}>
                          {project.name}
                        </span>
                      )}
                    </div>

                    {isSidebarOpen && (
                      <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity relative z-10">
                        <Pencil
                          size={14}
                          className="text-gray-400 hover:text-white transition-colors"
                          onClick={(e) => handleRenameProject(e, project)}
                        />
                        <Trash2
                          size={14}
                          className="text-gray-400 hover:text-red-400 transition-colors"
                          onClick={(e) => handleDeleteProject(e, project)}
                        />
                      </div>
                    )}
                  </div>
                );
              })
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { createContext, useContext, useEffect, useState } from "react";
import { useStore } from "@/core/store";
import { useShallow } from "zustand/react/shallow";

type Theme = "dark" | "light" | "system";

interface ThemeProviderProps {
    children: React.ReactNode;
    defaultTheme?: Theme;
    storageKey?: string;
}

interface ThemeProviderState {
    theme: Theme;
    setTheme: (theme: Theme) => void;
    resolvedTheme: "dark" | "light"; // Actual applied theme
}

const initialState: ThemeProviderState = {
    theme: "system",
    setTheme: () => null,
    resolvedTheme: "dark",
};

const ThemeContext = createContext<ThemeProviderState>(initialState);

export function ThemeProvider({
    children,
    defaultTheme = "system",
    ...props
}: ThemeProviderProps) {
    // Connect to global store for persistence
    const { userProfile, updateTheme } = useStore(useShallow(state => ({
        userProfile: state.userProfile,
        updateTheme: state.setTheme // Alias for clarity
    })));

    // Track system theme preference via media query
    const [systemTheme, setSystemTheme] = useState<"dark" | "light">(() =>
        typeof window !== 'undefined' && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"
    );

    // Get current preference from profile or default
    const theme = (userProfile?.preferences?.theme as Theme) || defaultTheme;

    // Derive resolved theme without setState in effects
    const resolvedTheme: "dark" | "light" = theme === "system" ? systemTheme : theme;

    // Apply resolved theme to DOM
    useEffect(() => {
        const root = window.document.documentElement;
        root.classList.remove("light", "dark");
        root.classList.add(resolvedTheme);
    }, [resolvedTheme]);

    // Listener for system changes when in 'system' mode
    useEffect(() => {
        if (theme !== 'system') return;

        const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
        const handleChange = () => setSystemTheme(mediaQuery.matches ? "dark" : "light");

        mediaQuery.addEventListener("change", handleChange);
        return () => mediaQuery.removeEventListener("change", handleChange);
    }, [theme]);

    const value = {
        theme,
        setTheme: (newTheme: Theme) => {
            updateTheme(newTheme);
        },
        resolvedTheme
    };

    return (
        <ThemeContext.Provider {...props} value={value}>
            {children}
        </ThemeContext.Provider>
    );
}

export const useTheme = () => {
    const context = useContext(ThemeContext);

    if (context === undefined) {
        throw new Error("useTheme must be used within a ThemeProvider");
    }

    return context;
};

import React, { createContext, useContext, useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { AnimatePresence } from 'motion/react';
import { Toast, ToastMessage, ToastType } from '../components/Toast';
import { v4 as uuidv4 } from 'uuid';
import { events } from '../events';

/** Alert data from system events */
interface AlertData {
    level: 'error' | 'warning' | 'success' | 'info';
    message: string;
}

/** Toast context API available via useToast hook */
export interface ToastContextType {
    showToast: (message: string, type: ToastType, duration?: number) => void;
    success: (message: string, duration?: number) => void;
    error: (message: string, duration?: number) => void;
    info: (message: string, duration?: number) => void;
    warning: (message: string, duration?: number) => void;
    loading: (message: string) => string; // Returns toast ID for updating/dismissing
    updateProgress: (id: string, progress: number, message?: string) => void;
    dismiss: (id: string) => void;
    promise: <T>(
        promise: Promise<T>,
        messages: { loading: string; success: string; error: string }
    ) => Promise<T>;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const useToast = () => {
    const context = useContext(ToastContext);
    if (!context) {
        throw new Error('useToast must be used within a ToastProvider');
    }
    return context;
};

export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    // ToastProvider Rendering
    const [toasts, setToasts] = useState<ToastMessage[]>([]);
    const MAX_TOASTS = 3; // Item 289: Reduced from 5 to 3 for cleaner UX

    // Item 289: Deduplication — track recent messages to prevent duplicates within 2s window
    const recentMessages = useRef<Map<string, number>>(new Map());
    const DEDUP_WINDOW_MS = 2000;

    const isDuplicate = useCallback((message: string, type: ToastType): boolean => {
        const key = `${type}:${message}`;
        const lastShown = recentMessages.current.get(key);
        if (lastShown && Date.now() - lastShown < DEDUP_WINDOW_MS) {
            return true;
        }
        recentMessages.current.set(key, Date.now());
        // Clean old entries periodically
        if (recentMessages.current.size > 50) {
            const cutoff = Date.now() - DEDUP_WINDOW_MS;
            for (const [k, v] of recentMessages.current) {
                if (v < cutoff) recentMessages.current.delete(k);
            }
        }
        return false;
    }, []);

    const addToast = useCallback((message: string, type: ToastType, duration?: number, progress?: number) => {
        // Item 289: Skip duplicate messages within the dedup window
        if (isDuplicate(message, type)) return '';

        const id = uuidv4();
        setToasts(prev => {
            const next = [...prev, { id, message, type, duration, progress }];
            return next.length > MAX_TOASTS ? next.slice(next.length - MAX_TOASTS) : next;
        });
        return id;
    }, [isDuplicate]);

    const removeToast = useCallback((id: string) => {
        setToasts(prev => prev.filter(t => t.id !== id));
    }, []);

    const updateToast = useCallback((id: string, updates: Partial<ToastMessage>) => {
        setToasts(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));
    }, []);

    useEffect(() => {
        const handleAlert = (data: AlertData) => {
            const type = data.level === 'error' ? 'error' :
                data.level === 'warning' ? 'warning' :
                    data.level === 'success' ? 'success' : 'info';
            addToast(data.message, type);
        };

        events.on('SYSTEM_ALERT', handleAlert);
        return () => events.off('SYSTEM_ALERT', handleAlert);
    }, [addToast]);

    const loadingToast = useCallback((message: string) => {
        return addToast(message, 'loading', undefined, 0);
    }, [addToast]);

    const updateProgress = useCallback((id: string, progress: number, message?: string) => {
        updateToast(id, { progress, ...(message ? { message } : {}) });
    }, [updateToast]);

    const promiseToast = useCallback(async <T,>(
        promise: Promise<T>,
        messages: { loading: string; success: string; error: string }
    ): Promise<T> => {
        const id = addToast(messages.loading, 'loading');
        try {
            const result = await promise;
            removeToast(id);
            addToast(messages.success, 'success');
            return result;
        } catch (error: unknown) {
            removeToast(id);
            addToast(messages.error, 'error');
            throw error;
        }
    }, [addToast, removeToast]);

    // Helpers need to be stable too, though they are usually just wrappers around addToast
    const success = useCallback((msg: string, dur?: number) => { addToast(msg, 'success', dur); }, [addToast]);
    const error = useCallback((msg: string, dur?: number) => { addToast(msg, 'error', dur); }, [addToast]);
    const info = useCallback((msg: string, dur?: number) => { addToast(msg, 'info', dur); }, [addToast]);
    const warning = useCallback((msg: string, dur?: number) => { addToast(msg, 'warning', dur); }, [addToast]);

    const contextValue: ToastContextType = useMemo(() => ({
        showToast: addToast,
        success,
        error,
        info,
        warning,
        loading: loadingToast,
        updateProgress,
        dismiss: removeToast,
        promise: promiseToast,
    }), [addToast, success, error, info, warning, loadingToast, updateProgress, removeToast, promiseToast]);

    return (
        <ToastContext.Provider value={contextValue}>
            {children}
            {/* Item 342: aria-live="assertive" for error toasts, "polite" for informational */}
            <div className="fixed bottom-4 right-4 z-[100] flex flex-col gap-2 pointer-events-none">
                <div role="status" aria-live="assertive" aria-label="Error notifications" className="flex flex-col gap-2 items-end pointer-events-auto">
                    <AnimatePresence>
                        {toasts.filter(t => t.type === 'error').map(toast => (
                            <Toast key={toast.id} toast={toast} onDismiss={removeToast} />
                        ))}
                    </AnimatePresence>
                </div>
                <div role="status" aria-live="polite" aria-label="Notifications" className="flex flex-col gap-2 items-end pointer-events-auto">
                    <AnimatePresence>
                        {toasts.filter(t => t.type !== 'error').map(toast => (
                            <Toast key={toast.id} toast={toast} onDismiss={removeToast} />
                        ))}
                    </AnimatePresence>
                </div>
            </div>
        </ToastContext.Provider>
    );
};

// Singleton helper for non-React context usage (services, etc)
export const toast = {
    success: (message: string, _duration?: number) => events.emit('SYSTEM_ALERT', { level: 'success', message }),
    error: (message: string, _duration?: number) => events.emit('SYSTEM_ALERT', { level: 'error', message }),
    info: (message: string, _duration?: number) => events.emit('SYSTEM_ALERT', { level: 'info', message }),
    warning: (message: string, _duration?: number) => events.emit('SYSTEM_ALERT', { level: 'warning', message }),
};

import React, { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import { audioService } from '@/services/audio/AudioService';
import { logger } from '@/utils/logger';

interface VoiceContextType {
    isVoiceEnabled: boolean;
    setVoiceEnabled: (enabled: boolean) => void;
    isListening: boolean;
    toggleListening: () => void;
    transcript: string;
}

interface VoiceSpeechRecognitionResult {
    isFinal: boolean;
    readonly length: number;
    [index: number]: {
        transcript: string;
        confidence: number;
    };
}

interface VoiceSpeechRecognitionEvent {
    resultIndex: number;
    results: {
        length: number;
        [index: number]: VoiceSpeechRecognitionResult;
    };
}

interface VoiceSpeechRecognitionInstance {
    continuous: boolean;
    interimResults: boolean;
    lang: string;
    onstart: () => void;
    onend: () => void;
    onresult: (event: VoiceSpeechRecognitionEvent) => void;
    onerror: (event: { error: string }) => void;
    start: () => void;
    stop: () => void;
}

const VoiceContext = createContext<VoiceContextType | undefined>(undefined);

export const VoiceProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [isVoiceEnabled, setVoiceEnabledState] = useState(() => {
        // Voice is disabled by default for fresh sessions unless explicitly enabled
        if (typeof window === 'undefined') return false;
        return localStorage.getItem('voice_enabled') === 'true';
    });

    const [isListening, setIsListening] = useState(false);
    const [transcript, setTranscript] = useState('');
    const recognitionRef = useRef<VoiceSpeechRecognitionInstance | null>(null);

    const setVoiceEnabled = (enabled: boolean) => {
        setVoiceEnabledState(enabled);
        localStorage.setItem('voice_enabled', enabled ? 'true' : 'false');
        audioService.setEnabled(enabled);
    };

    useEffect(() => {
        audioService.setEnabled(isVoiceEnabled);
    }, [isVoiceEnabled]);

    // Initialize Speech Recognition
    useEffect(() => {
        if (typeof window !== 'undefined') {
            const SpeechRecognitionCtor = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
            if (SpeechRecognitionCtor) {
                const recognitionInstance = new SpeechRecognitionCtor() as unknown as VoiceSpeechRecognitionInstance;
                recognitionInstance.continuous = true;
                recognitionInstance.interimResults = true;
                recognitionInstance.lang = 'en-US';

                recognitionInstance.onstart = () => setIsListening(true);
                recognitionInstance.onend = () => setIsListening(false);
                recognitionInstance.onresult = (event) => {
                    let interimTranscript = '';
                    let finalTranscript = '';

                    for (let i = event.resultIndex; i < event.results.length; ++i) {
                        if (event.results[i]!.isFinal) {
                            finalTranscript += event.results[i]![0]!.transcript;
                        } else {
                            interimTranscript += event.results[i]![0]!.transcript;
                        }
                    }
                    setTranscript(finalTranscript || interimTranscript);
                };

                recognitionInstance.onerror = (event) => {
                    logger.error('Speech recognition error', event.error);
                    setIsListening(false);
                };

                recognitionRef.current = recognitionInstance;
            }
        }
    }, []);

    const toggleListening = useCallback(() => {
        if (!recognitionRef.current) {
            logger.warn('Speech recognition not supported in this browser.');
            return;
        }

        if (isListening) {
            recognitionRef.current.stop();
        } else {
            setTranscript('');
            recognitionRef.current.start();
        }
    }, [isListening]);

    return (
        <VoiceContext.Provider value={{
            isVoiceEnabled,
            setVoiceEnabled,
            isListening,
            toggleListening,
            transcript
        }}>
            {children}
        </VoiceContext.Provider>
    );
};

export const useVoice = () => {
    const context = useContext(VoiceContext);
    if (!context) throw new Error('useVoice must be used within VoiceProvider');
    return context;
};

