import { StateCreator } from 'zustand';
import { doc, onSnapshot, Unsubscribe } from 'firebase/firestore';
import { db, auth } from '@/services/firebase';
import type { GraphExecutionState, AgentGraph } from '@/services/agent/types';

// Re-using the types defined in the shared firebase package
export enum AgentTaskStateEnum {
    PENDING = 'PENDING',
    RUNNING = 'RUNNING',
    COMPLETED = 'COMPLETED',
    FAILED = 'FAILED'
}

export interface AgentTaskNode {
    id: string;
    toolName: string;
    arguments: Record<string, unknown>;
    state: AgentTaskStateEnum;
    result?: unknown;
    error?: string;
    dependencies: string[];
}

export interface AgentTaskGraph {
    taskId: string;
    status: AgentTaskStateEnum;
    nodes: Record<string, AgentTaskNode>;
    createdAt: number;
    updatedAt: number;
}

export interface AgentOrchestrationSlice {
    // Legacy/Other
    activeGraphs: Record<string, AgentTaskGraph>;

    // Phase 4: Dynamic Graph Orchestration
    activeGraphExecution: GraphExecutionState | null;
    activeGraphDefinition: AgentGraph | null;

    startListeningToGraph: (taskId: string) => Promise<void>;
    stopListeningToGraph: (taskId: string) => void;

    // Phase 4 Listeners
    startListeningToGraphExecution: (executionId: string) => Promise<void>;
    stopListeningToGraphExecution: () => void;
    setActiveGraphDefinition: (graph: AgentGraph | null) => void;
    setActiveGraphExecution: (execution: GraphExecutionState | null) => void;
}

const graphListeners: Record<string, Unsubscribe> = {};
let activeExecutionListener: Unsubscribe | null = null;

export const buildAgentOrchestrationState: (
    set: Parameters<StateCreator<AgentOrchestrationSlice>>[0],
    get: Parameters<StateCreator<AgentOrchestrationSlice>>[1]
) => AgentOrchestrationSlice = (set, get) => ({
    activeGraphs: {},
    activeGraphExecution: null,
    activeGraphDefinition: null,

    startListeningToGraph: async (taskId: string) => {
        if (graphListeners[taskId]) {
            console.warn(`[AgentOrchestrationSlice] Already listening to graph: ${taskId}`);
            return;
        }

        const uid = auth.currentUser?.uid;
        if (!uid) {
            console.warn('[AgentOrchestrationSlice] Cannot listen to graph without authenticated user.');
            return;
        }

        console.info(`[AgentOrchestrationSlice] Starting listener for legacy graph: ${taskId}`);
        const graphRef = doc(db, 'agent_tasks', taskId);

        const unsubscribe = onSnapshot(
            graphRef,
            (snapshot) => {
                if (snapshot.exists()) {
                    const data = snapshot.data() as AgentTaskGraph;
                    set((state) => ({
                        activeGraphs: {
                            ...state.activeGraphs,
                            [taskId]: data
                        }
                    }));
                } else {
                    console.warn(`[AgentOrchestrationSlice] Graph document missing or deleted: ${taskId}`);
                    set((state) => {
                        const nextGraphs = { ...state.activeGraphs };
                        delete nextGraphs[taskId];
                        return { activeGraphs: nextGraphs };
                    });
                }
            },
            (error) => {
                console.error(`[AgentOrchestrationSlice] Firestore listener error for ${taskId}:`, error);
            }
        );

        graphListeners[taskId] = unsubscribe;
    },

    stopListeningToGraph: (taskId: string) => {
        if (graphListeners[taskId]) {
            console.info(`[AgentOrchestrationSlice] Stopping listener for graph: ${taskId}`);
            graphListeners[taskId]();
            delete graphListeners[taskId];

            set((state) => {
                const nextGraphs = { ...state.activeGraphs };
                delete nextGraphs[taskId];
                return { activeGraphs: nextGraphs };
            });
        }
    },

    // Phase 4: Graph-Based Orchestration Methods

    setActiveGraphDefinition: (graph) => set({ activeGraphDefinition: graph }),

    setActiveGraphExecution: (execution) => set({ activeGraphExecution: execution }),

    startListeningToGraphExecution: async (executionId: string) => {
        if (activeExecutionListener) {
            console.info('[AgentOrchestrationSlice] Stopping existing active graph execution listener.');
            activeExecutionListener();
            activeExecutionListener = null;
        }

        const uid = auth.currentUser?.uid;
        if (!uid) {
            console.warn('[AgentOrchestrationSlice] Cannot listen to graph execution without authenticated user.');
            return;
        }

        console.info(`[AgentOrchestrationSlice] Starting listener for graph execution: ${executionId}`);
        // Path: users/{userId}/graphExecutions/{id}
        const executionRef = doc(db, 'users', uid, 'graphExecutions', executionId);

        activeExecutionListener = onSnapshot(
            executionRef,
            (snapshot) => {
                if (snapshot.exists()) {
                    const data = snapshot.data() as GraphExecutionState;
                    set({ activeGraphExecution: data });
                } else {
                    console.warn(`[AgentOrchestrationSlice] Graph execution missing or deleted: ${executionId}`);
                    set({ activeGraphExecution: null });
                }
            },
            (error) => {
                console.error(`[AgentOrchestrationSlice] Firestore listener error for execution ${executionId}:`, error);
            }
        );
    },

    stopListeningToGraphExecution: () => {
        if (activeExecutionListener) {
            console.info('[AgentOrchestrationSlice] Stopping active graph execution listener.');
            activeExecutionListener();
            activeExecutionListener = null;
            set({ activeGraphExecution: null });
        }
    }
});

import { StateCreator } from 'zustand';
import { type ModuleId, isValidModule } from '@/core/constants';
import type { ProjectMetadata } from '@/services/dashboard/DashboardService';
import { logger } from '@/utils/logger';

// Helper to get initial module from URL
const getInitialModule = (): ModuleId => {
    if (typeof window === 'undefined') return 'dashboard';
    const pathSegments = window.location.pathname.split('/').filter(Boolean);
    const firstSegment = pathSegments[0];
    if (firstSegment && isValidModule(firstSegment)) {
        return firstSegment;
    }
    return 'dashboard';
};

export interface Project {
    id: string;
    name: string;
    type: AppSlice['currentModule'];
    date?: number;
    lastModified?: number;
    orgId: string;
    thumbnail?: string;
    assetCount?: number;
    metadata?: Record<string, any>;
}

export interface AppSlice {
    currentModule: ModuleId;
    currentProjectId: string;
    projects: ProjectMetadata[]; // Changed from Project[] to enforce UI type
    setModule: (module: AppSlice['currentModule']) => void;
    setProject: (id: string) => void;
    addProject: (project: ProjectMetadata) => void; // Changed parameter type
    loadProjects: () => Promise<void>;
    createNewProject: (name: string, type: Project['type'], orgId: string) => Promise<string>;
    updateProjectMetadata: (projectId: string, metadata: Record<string, any>) => Promise<void>;
    pendingPrompt: string | null;
    setPendingPrompt: (prompt: string | null) => void;
    apiKeyError: boolean;
    setApiKeyError: (error: boolean) => void;
    isSidebarOpen: boolean;
    isRightPanelOpen: boolean;
    rightPanelTab: 'context' | 'assets' | 'agent';
    toggleSidebar: () => void;
    toggleRightPanel: () => void;
    setRightPanelTab: (tab: 'context' | 'assets' | 'agent') => void;
    isCommandMenuOpen: boolean;
    setCommandMenuOpen: (open: boolean) => void;
    hasUnsavedChanges: boolean;
    setHasUnsavedChanges: (hasUnsaved: boolean) => void;
    isEntryAssistantDismissed: boolean;
    setEntryAssistantDismissed: (dismissed: boolean) => void;
    /** @internal Debounce tracker for toggleSidebar */
    _lastSidebarToggle?: number;
    /** @internal Debounce tracker for toggleRightPanel */
    _lastRightPanelToggle?: number;
}

export const createAppSlice: StateCreator<AppSlice> = (set, get) => ({
    currentModule: getInitialModule(),
    currentProjectId: 'default',
    projects: [],
    hasUnsavedChanges: false,
    setHasUnsavedChanges: (hasUnsaved) => set({ hasUnsavedChanges: hasUnsaved }),
    isEntryAssistantDismissed: typeof window !== 'undefined' ? localStorage.getItem('indii_entryAssistantDismissed') === 'true' : false,
    setEntryAssistantDismissed: (dismissed) => {
        if (typeof window !== 'undefined') {
            if (dismissed) {
                localStorage.setItem('indii_entryAssistantDismissed', 'true');
            } else {
                localStorage.removeItem('indii_entryAssistantDismissed');
            }
        }
        set({ isEntryAssistantDismissed: dismissed });
    },
    setModule: (module) => {
        const state = get();
        if (state.hasUnsavedChanges && state.currentModule !== module) {
            const confirmLeave = window.confirm("You have unsaved changes that will be lost. Are you sure you want to leave?");
            if (!confirmLeave) {
                return;
            }
            set({ hasUnsavedChanges: false });
        }

        // Aggressively tear down listeners from previous modules
        // This requires dynamic import of store to avoid circular dependency
        import('@/core/store').then(({ useStore }) => {
            const currentModule = get().currentModule;
            // Only clear if actually switching modules
            if (currentModule !== module) {
                const store = useStore.getState();
                // Clean up Firestore subscriptions for the module we're leaving
                // to prevent INTERNAL ASSERTION FAILED errors during rapid navigation
                const prefixes: Partial<Record<string, string>> = {
                    creative: 'creative_',
                    publishing: 'publishing_',
                    finance: 'finance_',
                    memory: 'memory_',
                    publicist: 'publicist_',
                    distribution: 'distribution_',
                    merch: 'merch_',
                };
                const prefix = prefixes[currentModule];
                if (prefix) {
                    store.clearSubscriptionsByPrefix(prefix);
                }
            }
        }).catch(err => logger.error('[AppSlice] Failed to cleanup subscriptions:', err));

        set({
            currentModule: module,
        });
    },
    setProject: (id) => set({ currentProjectId: id }),
    addProject: (project) => set((state) => ({ projects: [project, ...state.projects] })),
    loadProjects: async () => {
        const { ProjectService } = await import('@/services/ProjectService');
        const { OrganizationService } = await import('@/services/OrganizationService');
        const { projectsToMetadata } = await import('@/services/dashboard/projectTypeUtils');
        const orgId = OrganizationService.getCurrentOrgId();
        if (orgId) {
            const firestoreProjects = await ProjectService.getProjectsForOrg(orgId);
            // Convert Project[] to ProjectMetadata[] at the boundary
            const projects = projectsToMetadata(firestoreProjects);
            set({ projects });
        }
    },
    createNewProject: async (name, type, orgId) => {
        const { ProjectService } = await import('@/services/ProjectService');
        const { projectToMetadata } = await import('@/services/dashboard/projectTypeUtils');
        const newProject = await ProjectService.createProject(name, type, orgId);
        // Convert Project to ProjectMetadata at the boundary
        const metadata = projectToMetadata(newProject);
        set((state) => ({
            projects: [metadata, ...state.projects],
            currentProjectId: newProject.id,
            currentModule: type,
        }));
        return newProject.id;
    },
    updateProjectMetadata: async (projectId, metadata) => {
        const { ProjectService } = await import('@/services/ProjectService');
        const { projectToMetadata } = await import('@/services/dashboard/projectTypeUtils');

        // 1. Update in Firestore via ProjectService
        // We need to assume ProjectService has an update method or use patch
        // Let's check ProjectService after this.
        await ProjectService.update(projectId, { metadata });

        // 2. Update local state
        set((state) => ({
            projects: state.projects.map((p) => 
                p.id === projectId 
                    ? { ...p, metadata: { ...(p.metadata || {}), ...metadata } }
                    : p
            )
        }));

        logger.info(`[AppSlice] Updated metadata for project ${projectId}`);
    },
    pendingPrompt: null,
    setPendingPrompt: (prompt) => set({ pendingPrompt: prompt }),
    apiKeyError: false,
    setApiKeyError: (error) => set({ apiKeyError: error }),
    isSidebarOpen: typeof window !== 'undefined' ? localStorage.getItem('indii_sidebarOpen') !== 'false' : true,
    isRightPanelOpen: false,
    rightPanelTab: 'context',
    toggleSidebar: () => {
        const now = Date.now();
        const state = get();
        if (state._lastSidebarToggle && now - state._lastSidebarToggle < 200) {
            return; // Ignore rapid-fire toggles
        }
        const newState = !state.isSidebarOpen;
        if (typeof window !== 'undefined') {
            localStorage.setItem('indii_sidebarOpen', String(newState));
        }
        set({ isSidebarOpen: newState, _lastSidebarToggle: now });
    },
    toggleRightPanel: () => {
        // BUG-006 FIX: Debounce rapid toggle clicks.
        // The AnimatePresence mode="wait" in RightPanel can get stuck
        // if toggled faster than the spring animation duration (~100ms).
        const now = Date.now();
        const state = get();
        if (state._lastRightPanelToggle && now - state._lastRightPanelToggle < 100) {
            return; // Ignore rapid-fire toggles
        }
        set({ isRightPanelOpen: !state.isRightPanelOpen, _lastRightPanelToggle: now });
    },
    setRightPanelTab: (tab) => set({ rightPanelTab: tab, isRightPanelOpen: true }),
    isCommandMenuOpen: false,
    setCommandMenuOpen: (open) => set({ isCommandMenuOpen: open }),
});

import { logger } from '@/utils/logger';

import { StateCreator } from 'zustand';
import {
    Auth,
    User,
    onAuthStateChanged as firebaseOnAuthStateChanged,
    signInWithPopup,
    GoogleAuthProvider,
    signOut,
    signInWithEmailAndPassword,
    createUserWithEmailAndPassword,
    signInAnonymously,
    sendPasswordResetEmail,
    signInWithCredential
} from 'firebase/auth';

/** Minimal interface for E2E mock auth objects that provide their own listener */
interface E2EMockAuth {
    onAuthStateChanged: (callback: (user: User | null) => void) => () => void;
    signInAnonymously: () => Promise<any>;
    signInWithEmailAndPassword: (email: string, pass: string) => Promise<any>;
    createUserWithEmailAndPassword: (email: string, pass: string) => Promise<any>;
    sendPasswordResetEmail: (email: string) => Promise<any>;
    signInWithPopup: (provider: any) => Promise<any>;
    signOut: () => Promise<void>;
}

/**
 * Enhanced auth listener with E2E mock support.
 * Ensures that if a mock auth object provides its own listener, we use it.
 */
const onAuthStateChanged = (authObj: Auth | E2EMockAuth, callback: (user: User | null) => void) => {
    if (typeof (authObj as E2EMockAuth).onAuthStateChanged === 'function') {
        return (authObj as E2EMockAuth).onAuthStateChanged(callback);
    }
    return firebaseOnAuthStateChanged(authObj as Auth, callback);
};

const wrappedSignInAnonymously = (authObj: Auth | E2EMockAuth) => {
    if (typeof (authObj as E2EMockAuth).signInAnonymously === 'function') {
        return (authObj as E2EMockAuth).signInAnonymously();
    }
    return signInAnonymously(authObj as Auth);
};

const wrappedSignInWithEmailAndPassword = (authObj: Auth | E2EMockAuth, email: string, pass: string) => {
    if (typeof (authObj as E2EMockAuth).signInWithEmailAndPassword === 'function') {
        return (authObj as E2EMockAuth).signInWithEmailAndPassword(email, pass);
    }
    return signInWithEmailAndPassword(authObj as Auth, email, pass);
};

const wrappedCreateUserWithEmailAndPassword = (authObj: Auth | E2EMockAuth, email: string, pass: string) => {
    if (typeof (authObj as E2EMockAuth).createUserWithEmailAndPassword === 'function') {
        return (authObj as E2EMockAuth).createUserWithEmailAndPassword(email, pass);
    }
    return createUserWithEmailAndPassword(authObj as Auth, email, pass);
};

const wrappedSendPasswordResetEmail = (authObj: Auth | E2EMockAuth, email: string) => {
    if (typeof (authObj as E2EMockAuth).sendPasswordResetEmail === 'function') {
        return (authObj as E2EMockAuth).sendPasswordResetEmail(email);
    }
    return sendPasswordResetEmail(authObj as Auth, email);
};

const wrappedSignInWithPopup = (authObj: Auth | E2EMockAuth, provider: any) => {
    if (typeof (authObj as E2EMockAuth).signInWithPopup === 'function') {
        return (authObj as E2EMockAuth).signInWithPopup(provider);
    }
    return signInWithPopup(authObj as Auth, provider);
};

const wrappedSignOut = (authObj: Auth | E2EMockAuth) => {
    if (typeof (authObj as E2EMockAuth).signOut === 'function') {
        return (authObj as E2EMockAuth).signOut();
    }
    return signOut(authObj as Auth);
};
import { auth, db } from '@/services/firebase';
import { doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore';

/** Type guard for Firebase Auth errors */
interface FirebaseAuthError {
    code: string;
    message: string;
}

/**
 * Maps a Firebase Auth error code to a user-friendly message.
 * Centralised to avoid duplicating error strings across every auth method.
 */
function getAuthErrorMessage(error: FirebaseAuthError): string | null {
    switch (error.code) {
        // ── Config / service issues ────────────────────────────────────────
        case 'auth/argument-error':
        case 'auth/invalid-api-key':
            return 'Authentication service unavailable. Please try again later.';

        // ── Popup dismissed (not a real error — user cancelled) ────────────
        case 'auth/popup-closed-by-user':
        case 'auth/cancelled-popup-request':
            return null; // Suppress — the user intentionally dismissed the dialog

        // ── Credential errors ──────────────────────────────────────────────
        case 'auth/user-not-found':
        case 'auth/wrong-password':
        case 'auth/invalid-credential':
            return 'Incorrect email or password. Please try again.';

        // ── Sign-up specific ───────────────────────────────────────────────
        case 'auth/email-already-in-use':
            return 'An account with this email already exists. Try signing in instead.';
        case 'auth/weak-password':
            return 'Password must be at least 6 characters.';
        case 'auth/invalid-email':
            return 'Please enter a valid email address.';

        // ── Rate limiting ──────────────────────────────────────────────────
        case 'auth/too-many-requests':
            return 'Too many sign-in attempts. Please wait a few minutes and try again.';

        // ── Network ────────────────────────────────────────────────────────
        case 'auth/network-request-failed':
            return 'Network error. Check your internet connection and try again.';

        // ── Account disabled ───────────────────────────────────────────────
        case 'auth/user-disabled':
            return 'This account has been disabled. Contact support for help.';

        // ── Admin-restricted (sign-in provider not enabled) ────────────────
        case 'auth/admin-restricted-operation':
        case 'auth/operation-not-allowed':
            return 'This sign-in method is not enabled. Contact administrator.';

        // ── Re-authentication required (stale session for destructive ops) ─
        case 'auth/requires-recent-login':
            return 'Your session has expired. Please sign in again before making this change.';

        // ── Fallback ───────────────────────────────────────────────────────
        default:
            return error.message ?? 'Authentication failed';
    }
}

// Define the shape of our Auth state
export interface AuthSlice {
    user: User | null;
    authLoading: boolean;
    authError: string | null;
    isSignUpMode: boolean;
    passwordResetSent: boolean;

    // Actions
    loginWithGoogle: () => Promise<void>;
    loginWithEmail: (email: string, pass: string) => Promise<void>;
    signUpWithEmail: (email: string, pass: string) => Promise<void>;
    loginAsGuest: () => Promise<void>;
    logout: () => Promise<void>;
    resetPassword: (email: string) => Promise<void>;
    setSignUpMode: (isSignUp: boolean) => void;
    clearAuthError: () => void;
    initializeAuthListener: () => () => void;
}

// Create the slice
export const createAuthSlice: StateCreator<AuthSlice> = (set, _get) => ({
    user: null,
    authLoading: true,
    authError: null,
    isSignUpMode: false,
    passwordResetSent: false,

    loginWithGoogle: async () => {
        try {
            set({ authLoading: true, authError: null });
            const provider = new GoogleAuthProvider();
            await wrappedSignInWithPopup(auth, provider);
            // State update handled by listener
        } catch (error: unknown) {
            const firebaseError = error as FirebaseAuthError;
            const errorMessage = getAuthErrorMessage(firebaseError);
            // If errorMessage is null (popup dismissed), reset loading but don't show an error
            if (errorMessage === null) {
                set({ authLoading: false });
            } else {
                set({ authError: errorMessage, authLoading: false });
            }
        }
    },

    loginWithEmail: async (email: string, pass: string) => {
        try {
            set({ authLoading: true, authError: null });
            await wrappedSignInWithEmailAndPassword(auth, email, pass);
            // State update handled by listener
        } catch (error: unknown) {
            const firebaseError = error as FirebaseAuthError;
            const errorMessage = getAuthErrorMessage(firebaseError);
            set({ authError: errorMessage ?? 'Sign-in failed', authLoading: false });
            throw error;
        }
    },

    signUpWithEmail: async (email: string, pass: string) => {
        try {
            set({ authLoading: true, authError: null });
            await wrappedCreateUserWithEmailAndPassword(auth, email, pass);
            // State update handled by listener — initializeAuthListener will create the user doc
        } catch (error: unknown) {
            const firebaseError = error as FirebaseAuthError;
            const errorMessage = getAuthErrorMessage(firebaseError);
            set({ authError: errorMessage ?? 'Account creation failed', authLoading: false });
            throw error;
        }
    },

    loginAsGuest: async () => {
        try {
            set({ authLoading: true, authError: null });

            // 1. Bypass Onboarding and Tours for the Founders Pitch Demo
            if (typeof window !== 'undefined') {
                window.localStorage.setItem('TOUR_COMPLETED_dashboard', 'true');
                window.localStorage.setItem('INDIIOS_ONBOARDING_COMPLETE', 'true');
                window.localStorage.setItem('cookie-consent', '{"analytics":false,"marketing":false}');
            }

            // 2. Attempt Anonymous Auth. If Identity Toolkit signups are blocked (which
            // throws the identitytoolkit error), fallback to an injected Mock User.
            try {
                await wrappedSignInAnonymously(auth);
            } catch (err: unknown) {
                const firebaseError = err as FirebaseAuthError;
                if (firebaseError.code === 'auth/admin-restricted-operation' || firebaseError.code?.includes('identitytoolkit')) {
                    logger.warn('[Auth] Anonymous Auth blocked by Firebase. Injecting local mock user for Founders Demo.');
                    if (typeof window !== 'undefined') {
                        (window as unknown as Record<string, boolean>).FIREBASE_E2E_MOCK = true; // Tell listener to ignore nulls
                    }
                    set({
                        user: {
                            uid: 'founder-demo-uid',
                            email: 'founder@indii.local',
                            displayName: 'Founder Demo',
                            isAnonymous: true,
                            getIdToken: async () => 'mock-token'
                        } as unknown as User,
                        authLoading: false,
                        authError: null
                    });
                    return; // Successfully bypassed
                }
                throw err;
            }
            // State update handled by listener normally
        } catch (error: unknown) {
            const firebaseError = error as FirebaseAuthError;
            const errorMessage = getAuthErrorMessage(firebaseError) ?? 'Founders Demo login failed';
            set({ authError: errorMessage, authLoading: false });
        }
    },

    resetPassword: async (email: string) => {
        try {
            set({ authLoading: true, authError: null, passwordResetSent: false });
            await wrappedSendPasswordResetEmail(auth, email);
            set({ authLoading: false, passwordResetSent: true });
        } catch (error: unknown) {
            const firebaseError = error as FirebaseAuthError;
            let errorMessage: string;

            switch (firebaseError.code) {
                case 'auth/user-not-found':
                    // Security: Don't reveal whether the email exists.
                    // Still show "success" to prevent enumeration attacks.
                    set({ authLoading: false, passwordResetSent: true });
                    return;
                case 'auth/invalid-email':
                    errorMessage = 'Please enter a valid email address.';
                    break;
                case 'auth/too-many-requests':
                    errorMessage = 'Too many requests. Please wait a few minutes before trying again.';
                    break;
                default:
                    errorMessage = getAuthErrorMessage(firebaseError) ?? 'Failed to send reset email. Please try again.';
            }
            set({ authError: errorMessage, authLoading: false });
        }
    },

    setSignUpMode: (isSignUp: boolean) => {
        set({ isSignUpMode: isSignUp, authError: null, passwordResetSent: false });
    },

    clearAuthError: () => {
        set({ authError: null });
    },

    logout: async () => {
        try {
            await wrappedSignOut(auth);

            // ST9: Clear cache on logout to prevent stale data cross-contamination
            const { cacheService } = await import('@/services/cache/CacheService');
            cacheService.clear();

            // Clear all active Firestore subscriptions to prevent permission errors
            import('@/core/store').then(({ useStore }) => {
                const state = useStore.getState() as unknown as Record<string, unknown>;
                if (typeof state.clearAllSubscriptions === 'function') {
                    (state.clearAllSubscriptions as () => void)();
                }
            }).catch(err => logger.error('[Auth] Failed to clear subscriptions during logout:', err));

            set({ user: null, authError: null, isSignUpMode: false, passwordResetSent: false });
        } catch (error: unknown) {
            const message = error instanceof Error ? error.message : 'Logout failed';
            set({ authError: message });
        }
    },

    initializeAuthListener: () => {
        logger.debug('[Auth] Initializing Auth Listener...');
        logger.debug('[Auth] Initializing Auth Listener...');

        // 6. Electron Auth Handoff Listener (Item 518)
        let electronUnsub: (() => void) | null = null;
        if (typeof window !== 'undefined' && window.electronAPI?.auth?.onUserUpdate) {
            electronUnsub = window.electronAPI.auth.onUserUpdate(async (tokens) => {
                if (tokens) {
                    logger.info('[Auth] Received handoff tokens from Main Process. Signing in...');
                    try {
                        set({ authLoading: true, authError: null });
                        const credential = GoogleAuthProvider.credential(tokens.idToken, tokens.accessToken || undefined);
                        await signInWithCredential(auth, credential);
                        // onAuthStateChanged will handle the rest
                    } catch (err) {
                        logger.error('[Auth] Failed to sign in with handoff tokens:', err);
                        set({ authError: 'Authentication handoff failed. Please try again.', authLoading: false });
                    }
                } else {
                    logger.info('[Auth] Received logout signal from Main Process.');
                    // User already signed out in main, just clear local state if listener doesn't fire
                    set({ user: null, authLoading: false });
                }
            });
        }

        // 7. Electron Auth Error Listener
        let errorUnsub: (() => void) | null = null;
        const electronAuth = typeof window !== 'undefined' ? (window.electronAPI?.auth as any) : null;
        if (typeof window !== 'undefined' && window.electronAPI?.auth?.onError) {
            errorUnsub = window.electronAPI.auth.onError((data: { message: string }) => {
                logger.error('[Auth] Received auth error from Main Process:', data.message);
                set({ authError: data.message, authLoading: false });
            });
        }

        // FAST FAIL: If no API key, don't wait for Firebase (it might hang or crash)
        // EXCLUSION: If we are using the E2E mock, allow any API key string.
        const apiKey = auth.app?.options?.apiKey;
        const apiKeyLower = apiKey?.toLowerCase() ?? '';
        const isE2EMock = typeof window !== 'undefined' && (window as unknown as Record<string, boolean>).FIREBASE_E2E_MOCK;

        if (!isE2EMock && (!apiKey || apiKeyLower.includes('fake') || apiKeyLower.includes('bypass') || apiKeyLower.includes('mock') || apiKeyLower.includes('your_'))) {
            logger.warn('[Auth] No valid API Key found and not in E2E mode.');
            set({ authLoading: false });
            return () => { };
        }

        // TIMEOUT FAILSAFE: If onAuthStateChanged never fires (API key blocked,
        // network down, SDK error), fall through to login after 10s instead of
        // spinning forever. See: API_KEY_SERVICE_BLOCKED incident 2026-03-11.
        let hasResolved = false;
        const timeoutId = setTimeout(() => {
            if (!hasResolved) {
                logger.error('[Auth] Auth listener timed out after 10s — falling through to login.');
                set({
                    authLoading: false,
                    authError: 'Authentication timed out. The service may be temporarily unavailable. Please try again.',
                });
            }
        }, 10_000);

        // BUG-002 FIX: Debounce rapid null→user transitions during token refresh.
        // Firebase may briefly emit null between token refresh cycles,
        // causing spurious logouts under rapid load (100+ clicks/sec).
        let debounceTimer: ReturnType<typeof setTimeout> | null = null;
        let lastKnownUser: typeof auth.currentUser = null;

        // Return unsubscribe function
        const unsubscribe = onAuthStateChanged(auth, async (user) => {
            logger.info(`[Auth] onAuthStateChanged fired. User: ${user ? user.uid : 'null'}, lastKnownUser: ${lastKnownUser ? lastKnownUser.uid : 'null'}`);
            if (isE2EMock) {
                logger.debug('[Auth] Mock Auth Listener Fired', { userUid: user?.uid });
            }
            hasResolved = true;
            clearTimeout(timeoutId);

            // If transitioning FROM a valid user TO null, debounce it.
            // This prevents the brief null flash during Firebase Auth token refresh.
            if (!user && lastKnownUser) {
                logger.info('[Auth] User went null — debouncing for 500ms to guard against token refresh race...');
                if (debounceTimer) clearTimeout(debounceTimer);
                debounceTimer = setTimeout(() => {
                    // Re-check: if auth.currentUser is STILL null after 500ms,
                    // it's a genuine logout — not a token refresh blip.
                    if (!auth.currentUser) {
                        logger.info('[Auth] Confirmed logout after debounce.');
                        lastKnownUser = null;
                        set({ user: null, authLoading: false });
                    } else {
                        logger.info('[Auth] Token refresh resolved — user is still authenticated.');
                        lastKnownUser = auth.currentUser;
                        set({ user: auth.currentUser, authLoading: false });
                    }
                }, 500);
                return;
            }

            // BUG-002 FIX: Debounce rapid null→user transitions during token refresh.
            // Firebase may briefly emit null between token refresh cycles,
            // causing spurious logouts under rapid load (100+ clicks/sec).
            if (user && !lastKnownUser) {
                logger.info('[Auth] User went from null to valid — debouncing for 500ms to guard against rapid transitions...');
                if (debounceTimer) clearTimeout(debounceTimer);
                debounceTimer = setTimeout(async () => {
                    const currentUser = auth.currentUser || user;
                    if (currentUser) {
                        logger.info('[Auth] Confirmed login after debounce. Setting authLoading to false.');
                        lastKnownUser = currentUser;
                        set({ user: currentUser, authLoading: false });

                        // Optional: Ensure user document exists in Firestore
                        try {
                            const userRef = doc(db, 'users', currentUser.uid);
                            const userSnap = await getDoc(userRef);

                            if (!userSnap.exists()) {
                                await setDoc(userRef, {
                                    email: currentUser.email,
                                    displayName: currentUser.displayName,
                                    photoURL: currentUser.photoURL,
                                    createdAt: serverTimestamp(),
                                    lastLogin: serverTimestamp()
                                }, { merge: true });
                            } else {
                                // Update last login
                                await setDoc(userRef, {
                                    lastLogin: serverTimestamp()
                                }, { merge: true });
                            }
                        } catch (e: unknown) {
                            logger.error("[Auth] Failed to sync user to Firestore", e);
                        }
                    } else {
                        logger.info('[Auth] Debounce finished but currentUser is null. Setting authLoading to false.');
                        set({ authLoading: false });
                    }
                }, 500);
                return;
            }

            // Clear any pending debounce if we received a steady state
            if (debounceTimer) {
                clearTimeout(debounceTimer);
                debounceTimer = null;
            }

            logger.info(`[Auth] Steady state reached. Setting authLoading to false. User: ${user ? user.uid : 'null'}`);
            lastKnownUser = user;
            set({ user, authLoading: false });

            if (user) {
                // Optional: Ensure user document exists in Firestore
                try {
                    const userRef = doc(db, 'users', user.uid);
                    const userSnap = await getDoc(userRef);

                    if (!userSnap.exists()) {
                        await setDoc(userRef, {
                            email: user.email,
                            displayName: user.displayName,
                            photoURL: user.photoURL,
                            createdAt: serverTimestamp(),
                            lastLogin: serverTimestamp()
                        }, { merge: true });
                    } else {
                        // Update last login
                        await setDoc(userRef, {
                            lastLogin: serverTimestamp()
                        }, { merge: true });
                    }
                } catch (e: unknown) {
                    logger.error("[Auth] Failed to sync user to Firestore", e);
                }
            }
        });

        return () => {
            clearTimeout(timeoutId);
            if (debounceTimer) clearTimeout(debounceTimer);
            if (electronUnsub) electronUnsub();
            if (errorUnsub) errorUnsub();
            unsubscribe();
        };
    }
});

import { StateCreator } from 'zustand';

export interface ReferencedAsset {
    id: string;
    name: string;
    type: 'url' | 'file' | 'database';
    value: string;
}

export interface BoardroomSlice {
    isBoardroomMode: boolean;
    activeAgents: string[];
    referencedAssets: ReferencedAsset[];

    // Actions
    toggleBoardroomMode: () => void;
    setBoardroomMode: (isActive: boolean) => void;

    toggleAgent: (agentId: string) => void;
    addActiveAgent: (agentId: string) => void;
    removeActiveAgent: (agentId: string) => void;

    addReferencedAsset: (asset: ReferencedAsset) => void;
    removeReferencedAsset: (assetId: string) => void;
    clearReferencedAssets: () => void;
}

export const createBoardroomSlice: StateCreator<BoardroomSlice> = (set, get) => ({
    isBoardroomMode: false,
    activeAgents: ['generalist'], // indii Conductor (hub agent) always present initially
    referencedAssets: [],

    toggleBoardroomMode: () => set((state) => ({ isBoardroomMode: !state.isBoardroomMode })),
    setBoardroomMode: (isActive) => set({ isBoardroomMode: isActive }),

    toggleAgent: (agentId) => set((state) => {
        const isActive = state.activeAgents.includes(agentId);
        if (isActive) {
            return { activeAgents: state.activeAgents.filter(id => id !== agentId) };
        } else {
            return { activeAgents: [...state.activeAgents, agentId] };
        }
    }),

    addActiveAgent: (agentId) => set((state) => {
        if (!state.activeAgents.includes(agentId)) {
            return { activeAgents: [...state.activeAgents, agentId] };
        }
        return state;
    }),

    removeActiveAgent: (agentId) => set((state) => ({
        activeAgents: state.activeAgents.filter(id => id !== agentId)
    })),

    addReferencedAsset: (asset) => set((state) => ({
        referencedAssets: [...state.referencedAssets, asset]
    })),

    removeReferencedAsset: (assetId) => set((state) => ({
        referencedAssets: state.referencedAssets.filter(a => a.id !== assetId)
    })),

    clearReferencedAssets: () => set({ referencedAssets: [] }),
});

