import { StateCreator } from 'zustand';
import { type EarningsSummary } from '@/services/revenue/schema';
import { ProfileSlice } from './profileSlice';
import { SubscriptionSlice } from './subscriptionSlice';
import { logger } from '@/utils/logger';

export interface FinanceSlice {
    finance: {
        earningsSummary: EarningsSummary | null;
        loading: boolean;
        error: string | null;
    };
    fetchEarnings: (period: { startDate: string; endDate: string }) => Promise<void>;
}

export const createFinanceSlice: StateCreator<FinanceSlice & ProfileSlice & SubscriptionSlice, [], [], FinanceSlice> = (set, get) => ({
    finance: {
        earningsSummary: null,
        loading: false,
        error: null,
    },
    fetchEarnings: async (period) => {
        const state = get();
        const userId = state.userProfile?.id;

        if (!userId) {
            logger.warn('[FinanceSlice] No user ID found for fetching earnings.');
            return;
        }

        set((state) => ({ finance: { ...state.finance, loading: true } }));

        try {
            const { financeService } = await import('@/services/finance/FinanceService');

            // Clear previous subscription before creating a new one
            state.clearSubscription?.('finance-earnings');

            const unsubscribe = financeService.subscribeToEarnings(userId, (data: EarningsSummary | null) => {
                set((state) => ({
                    finance: {
                        ...state.finance,
                        loading: false,
                        earningsSummary: data,
                        error: null
                    }
                }));
            });

            // Register the unsubscribe so it's cleaned up when no longer needed
            state.registerSubscription?.('finance-earnings', unsubscribe);
        } catch (error: unknown) {
            const message = error instanceof Error ? error.message : 'Failed to fetch earnings';
            set((state) => ({
                finance: {
                    ...state.finance,
                    loading: false,
                    error: message
                }
            }));
        }
    }

});

import { StateCreator } from 'zustand';
import { UserProfile, BrandKit, UserPreferences } from '@/types/User';
import { saveProfileToStorage, getProfileFromStorage } from '@/services/storage/repository';
import { Timestamp } from 'firebase/firestore';
import { logger } from '@/utils/logger';

export interface Organization {
    id: string;
    name: string;
    plan: 'free' | 'pro' | 'enterprise';
    members: string[];
    ownerId?: string;
    memberRoles?: Record<string, 'owner' | 'manager' | 'producer' | 'member'>;
}

export interface ProfileSlice {
    currentOrganizationId: string;
    organizations: Organization[];
    userProfile: UserProfile;
    setOrganization: (id: string) => void;
    addOrganization: (org: Organization) => void;
    setUserProfile: (profile: UserProfile) => void;
    updateBrandKit: (updates: Partial<BrandKit>) => void;
    loadUserProfile: (uid: string) => Promise<void>;
    logout: () => Promise<void>;
    setTheme: (theme: 'dark' | 'light' | 'system') => void;
    updatePreferences: (updates: Partial<UserPreferences>) => void;
}

// Default Brand Kit — Intentionally empty so new users trigger onboarding
const DEFAULT_BRAND_KIT: BrandKit = {
    colors: [],
    fonts: '',
    brandDescription: '',
    negativePrompt: '',
    socials: {},
    brandAssets: [],
    referenceImages: [],
    releaseDetails: {
        title: '',
        type: '',
        artists: '',
        genre: '',
        mood: '',
        themes: '',
        lyrics: ''
    }
};

const DEFAULT_USER_PROFILE: UserProfile = {
    id: 'pending',
    uid: '',
    email: '',
    displayName: 'New Artist',
    photoURL: null,
    createdAt: Timestamp.now(),
    updatedAt: Timestamp.now(),
    lastLoginAt: Timestamp.now(),
    emailVerified: false,
    membership: { tier: 'free', expiresAt: null },
    accountType: 'artist',

    bio: '',
    preferences: {
        theme: 'system',
        notifications: true,
        observabilityEnabled: false
    },
    brandKit: DEFAULT_BRAND_KIT,
    analyzedTrackIds: [],
    knowledgeBase: [],
    savedWorkflows: [],
    careerStage: '',
    goals: []
};

export const createProfileSlice: StateCreator<ProfileSlice> = (set, get) => ({
    currentOrganizationId: 'org-default',
    organizations: [],
    userProfile: DEFAULT_USER_PROFILE,
    // Auth state delegated to AuthSlice
    setOrganization: (id) => {
        set((state) => {
            const newProfile = { ...state.userProfile, currentOrganizationId: id };
            saveProfileToStorage(newProfile).catch(err => logger.error("[ProfileSlice] Failed to save org change:", err));
            return { currentOrganizationId: id, userProfile: newProfile };
        });
    },
    addOrganization: (org) => set((state) => ({ organizations: [...state.organizations, org] })),
    setUserProfile: (profile) => {
        const newProfile = { ...profile, updatedAt: Timestamp.now() };
        set({ userProfile: newProfile });
        // Persistence Strategy: Hybrid (IndexedDB for speed + Firestore for cloud backup)
        saveProfileToStorage(newProfile).catch(err => logger.error("[ProfileSlice] Failed to save profile:", err));
    },
    updateBrandKit: (updates) => set((state) => {
        const currentBrandKit = state.userProfile.brandKit || DEFAULT_BRAND_KIT;
        const newProfile = {
            ...state.userProfile,
            brandKit: { ...currentBrandKit, ...updates },
            updatedAt: Timestamp.now()
        };
        saveProfileToStorage(newProfile).catch(err => logger.error("[ProfileSlice] Failed to save profile update:", err));
        return { userProfile: newProfile };
    }),
    loadUserProfile: async (uid: string) => {
        logger.info('[Profile] Loading user profile for:', uid);

        // Guard: If uid is the default 'pending' placeholder, skip Firestore calls
        if (!uid || uid === 'pending') {
            logger.debug('[Profile] Skipping load — no real UID yet.');
            return;
        }

        try {
            // Try to get from Firestore first (via Service/Repo) 
            const profile = await getProfileFromStorage(uid);

            // --- Fetch Organizations (Fix for Permission Errors) ---
            try {
                const { db } = await import('@/services/firebase');
                const { collection, query, where, getDocs } = await import('firebase/firestore');

                const orgsRef = collection(db, 'organizations');
                const q = query(orgsRef, where('members', 'array-contains', uid));
                const orgSnap = await getDocs(q);

                const userOrgs: Organization[] = [];
                orgSnap.forEach((doc) => {
                    const data = doc.data();
                    userOrgs.push({
                        id: doc.id,
                        name: data.name || 'Untitled Org',
                        plan: data.plan || 'free',
                        members: data.members || [],
                        ownerId: data.ownerId,
                        memberRoles: data.memberRoles
                    });
                });

                if (userOrgs.length > 0) {
                    logger.info('[Profile] Loaded organizations:', userOrgs.map(o => o.id));
                    set({ organizations: userOrgs });

                    // Resolve Current Org ID
                    // Resolve Current Org ID from Cloud Profile Preference
                    const preferredOrgId = profile?.currentOrganizationId;
                    const isValidPreferred = userOrgs.find(o => o.id === preferredOrgId);

                    if (isValidPreferred) {
                        set({ currentOrganizationId: isValidPreferred.id });
                    } else {
                        // Default to the first found org and sync back to cloud if possible
                        logger.info('[Profile] Defaulting to first org:', userOrgs[0]!.id);
                        set({ currentOrganizationId: userOrgs[0]!.id });
                        if (profile && !profile.currentOrganizationId) {
                            const updatedProfile = { ...profile, currentOrganizationId: userOrgs[0]!.id };
                            saveProfileToStorage(updatedProfile).catch(err => logger.error("[ProfileSlice] Failed to sync default org:", err));
                        }
                    }
                }
            } catch (orgErr: unknown) {
                // Suppress permission-denied — expected when Firestore rules restrict org access
                const code = (orgErr as { code?: string })?.code;
                if (code === 'permission-denied') {
                    logger.debug('[Profile] Organizations unavailable — insufficient permissions (expected in dev).');
                } else {
                    logger.error('[Profile] Failed to load organizations:', orgErr);
                }
            }
            // -----------------------------------------------------

            if (profile) {
                logger.info('[Profile] Loaded profile for:', uid);
                // Ensure legacy profiles align with new schema if needed (runtime migration could go here)
                set({ userProfile: profile });
            } else {
                logger.info('[Profile] No profile found, creating default for:', uid);
                // Create a new profile for this user
                const newProfile = { ...DEFAULT_USER_PROFILE, id: uid, uid: uid };
                set({ userProfile: newProfile });
                await saveProfileToStorage(newProfile);
            }

            // Set up real-time listener for the user profile using SubscriptionManager
            try {
                const { db } = await import('@/services/firebase');
                const { doc, onSnapshot } = await import('firebase/firestore');
                const { useStore } = await import('@/core/store');

                const userRef = doc(db, 'users', uid);
                const unsubscribe = onSnapshot(userRef, (docSnap) => {
                    if (docSnap.exists()) {
                        const cloudProfile = docSnap.data() as UserProfile;

                        const currentProfile = get().userProfile;
                        const getMs = (t: any) => {
                            if (!t) return 0;
                            if (typeof t.toMillis === 'function') return t.toMillis();
                            if (t.seconds) return t.seconds * 1000 + (t.nanoseconds || 0) / 1000000;
                            // Also handle ISO strings if somehow it was converted
                            if (typeof t === 'string') return new Date(t).getTime();
                            return 0;
                        };

                        const currentMs = getMs(currentProfile?.updatedAt);
                        const cloudMs = getMs(cloudProfile?.updatedAt);

                        if (currentMs > cloudMs) {
                            logger.info('[Profile] Ignoring stale cloud update (local is newer)');
                            return;
                        }

                        set({ userProfile: cloudProfile });
                    }
                }, (error) => {
                    logger.error('[Profile] Real-time listener error:', error);
                });

                useStore.getState().registerSubscription('global_profile', unsubscribe);
            } catch (err: unknown) {
                logger.error('[Profile] Failed to initialize real-time listener:', err);
            }
        } catch (err: unknown) {
            logger.error('[Profile] Failed to load profile:', err);
        }
    },
    logout: async () => {
        try {
            const { useStore } = await import('@/core/store');
            useStore.getState().clearAllSubscriptions();
        } catch (err: unknown) {
            logger.error('[Profile] Failed to clear subscriptions on logout', err);
        }
        logger.info('[System] Logout requested - resetting session state...');
        // In a no-auth world, "logout" might just reset preferences or switch to a guest profile.
        // For now, we just reload the page to clear transient state
        window.location.reload();
    },
    setTheme: (theme) => set((state) => {
        // Assume preferences is object now
        const preferences = state.userProfile.preferences || { notifications: true, theme: 'system' };

        const newProfile = {
            ...state.userProfile,
            preferences: { ...preferences, theme },
            updatedAt: Timestamp.now()
        };
        saveProfileToStorage(newProfile).catch(err => logger.error("[ProfileSlice] Failed to save theme update:", err));
        return { userProfile: newProfile };
    }),
    updatePreferences: (updates: Partial<UserPreferences>) => set((state) => {
        const currentPrefs = state.userProfile.preferences || { theme: 'system', notifications: true };
        const newProfile = {
            ...state.userProfile,
            preferences: { ...currentPrefs, ...updates },
            updatedAt: Timestamp.now()
        };
        saveProfileToStorage(newProfile).catch(err => logger.error("[ProfileSlice] Failed to save preferences:", err));
        return { userProfile: newProfile };
    })
});

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import type { Project, ProjectStatus } from '@/services/project/ProjectService';

interface ProjectSlice {
  selectedProjectId: string | null;
  selectedProject: Project | null;
  projects: Map<string, Project>;
  isLoading: boolean;
  error: string | null;

  setSelectedProject: (project: Project | null) => void;
  setProject: (project: Project) => void;
  setProjects: (projects: Project[]) => void;
  setProjectStatus: (projectId: string, status: ProjectStatus) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  clearSelected: () => void;
}

export const useProjectSlice = create<ProjectSlice>()(
  persist(
    (set) => ({
      selectedProjectId: null,
      selectedProject: null,
      projects: new Map(),
      isLoading: false,
      error: null,

      setSelectedProject: (project) =>
        set({
          selectedProjectId: project?.id ?? null,
          selectedProject: project,
          error: null,
        }),

      setProject: (project) =>
        set((state) => {
          const newProjects = new Map(state.projects);
          newProjects.set(project.id, project);
          return {
            projects: newProjects,
            selectedProject:
              state.selectedProjectId === project.id
                ? project
                : state.selectedProject,
          };
        }),

      setProjects: (projects) =>
        set((state) => {
          const newProjects = new Map();
          projects.forEach((p) => newProjects.set(p.id, p));

          const currentSelectedId = state.selectedProjectId;
          const currentSelected = currentSelectedId ? newProjects.get(currentSelectedId) ?? null : null;

          return {
            projects: newProjects,
            selectedProject: currentSelected,
            selectedProjectId: currentSelected ? currentSelected.id : null,
          };
        }),

      setProjectStatus: (projectId, status) =>
        set((state) => {
          const project = state.projects.get(projectId);
          if (!project) return state;

          const updated = { ...project, status, updatedAt: new Date() as any };
          const newProjects = new Map(state.projects);
          newProjects.set(projectId, updated);

          return {
            projects: newProjects,
            selectedProject:
              state.selectedProjectId === projectId
                ? updated
                : state.selectedProject,
          };
        }),

      setLoading: (loading) => set({ isLoading: loading }),
      setError: (error) => set({ error }),
      clearSelected: () =>
        set({
          selectedProjectId: null,
          selectedProject: null,
        }),
    }),
    {
      name: 'indii-project-storage',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({ selectedProjectId: state.selectedProjectId }),
    }
  )
);

/* eslint-disable @typescript-eslint/no-explicit-any */
import { z } from 'zod';

// Schema for input validation
export const AudioFidelitySchema = z.object({
  filePath: z.string().min(1, "File path is required"),
  targetStandard: z.enum(["CD", "Hi-Res", "Atmos"]).optional().default("Hi-Res"),
  // Optional: pythonPath for environment configuration
  pythonPath: z.string().optional().default('python3'),
});

export type AudioFidelityInput = z.input<typeof AudioFidelitySchema>;
export type AudioFidelityOptions = z.output<typeof AudioFidelitySchema>; // The internal full options

export interface AudioFidelityResult {
  success: boolean;
  data?: {
    file: string;
    format: string;
    sample_rate: string;
    bit_depth: string;
    channels: number;
    compliance: {
      CD_Quality: boolean;
      Hi_Res: boolean;
      Atmos_Ready: boolean;
    };
    summary_status: string;
    error?: string;
  };
  error?: string;
}

/**
 * Feature: Audio Fidelity Audit
 * Wraps the execution/audio/audio_fidelity_audit.py script.
 * Ensures strict input validation and standardized output.
 */
export class AudioFidelityFeature {

  /**
   * Executes the Audio Fidelity Audit process.
   * @param options The audit options (filePath, targetStandard)
   * @returns Standardized result object
   */
  async execute(options: AudioFidelityInput): Promise<AudioFidelityResult> {
    // 1. Validation
    const validation = AudioFidelitySchema.safeParse(options);
    if (!validation.success) {
      return {
        success: false,
        error: `Validation Error: ${validation.error.issues.map(i => i.message).join(', ')}`
      };
    }

    const { filePath, targetStandard, pythonPath } = validation.data;

    // 2. Path resolution
    const path = await import('path');
    // NOTE: In a hybrid app, we import from the electron utils if in Node context
    // This assumes the feature is executing in the main process as per its design note.
    const { AgentSupervisor } = await import('../../../../main/src/utils/AgentSupervisor');

    const scriptName = 'audio_fidelity_audit.py';

    // 3. Execution via AgentSupervisor
    try {
      const result: any = await AgentSupervisor.runScript(
        'audio',
        scriptName,
        [filePath, targetStandard],
        undefined, // onProgress
        { PYTHON_PATH: pythonPath } as Record<string, string> // env
      );

      if (result.error) {
        return {
          success: false,
          error: result.error
        };
      }

      return {
        success: true,
        data: result
      };
    } catch (e: unknown) {
      const err = e as Error;
      return {
        success: false,
        error: `Audio Fidelity Audit failed: ${err.message}`
      };
    }
  }
}

