import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import BrowserAgentTester from './BrowserAgentTester';
import { browserAgentDriver } from '../../../services/agent/BrowserAgentDriver';
import { useAgentStore } from '../store/AgentStore';
import { AgentActionType } from '../types';

// Mock dependencies
vi.mock('../../../services/agent/BrowserAgentDriver', () => ({
    browserAgentDriver: {
        drive: vi.fn(),
    }
}));

const mockLogAction = vi.fn();
vi.mock('../store/AgentStore', () => ({
    useAgentStore: vi.fn(() => ({
        logAction: mockLogAction,
    }))
}));

describe('BrowserAgentTester', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        // Mock scrollIntoView as it's not supported in JSDOM
        window.HTMLElement.prototype.scrollIntoView = vi.fn();
    });

    it('renders initial state correctly', () => {
        render(<BrowserAgentTester />);

        // Check for inputs
        expect(screen.getByLabelText(/Target URL/i)).toHaveValue('https://www.google.com');
        expect(screen.getByLabelText(/Instruction \/ Goal/i)).toHaveValue('Find the capacity of "Saint Andrew\'s Hall" in Detroit');

        // Check button
        expect(screen.getByRole('button', { name: /Launch Agent/i })).toBeInTheDocument();

        // Check Logs area
        expect(screen.getByText('Execution Logs')).toBeInTheDocument();
    });

    it('handles successful agent execution', async () => {
        // Mock success response
        (browserAgentDriver.drive as import("vitest").Mock).mockResolvedValueOnce({
            success: true,
            logs: ['[Driver] Starting', '[Driver] Goal Achieved!']
        });

        render(<BrowserAgentTester />);

        const launchButton = screen.getByRole('button', { name: /Launch Agent/i });
        fireEvent.click(launchButton);

        // Verify Loading State
        expect(screen.getByText(/Agent Driving.../i)).toBeInTheDocument();
        expect(launchButton).toBeDisabled();

        // Wait for completion
        await waitFor(() => {
            expect(screen.getByText(/Launch Agent/i)).toBeEnabled();
        });

        // Verify Logs
        expect(screen.getByText('[Driver] Starting')).toBeInTheDocument();
        expect(screen.getByText('[Driver] Goal Achieved!')).toBeInTheDocument();

        // Verify Store Update
        expect(mockLogAction).toHaveBeenCalledWith(expect.objectContaining({
            type: AgentActionType.BROWSER_DRIVE,
            status: 'completed'
        }));
    });

    it('handles failed agent execution', async () => {
        // Mock failure response
        (browserAgentDriver.drive as import("vitest").Mock).mockResolvedValueOnce({
            success: false,
            logs: ['[Driver] Starting', '[Driver] Error: Something went wrong']
        });

        render(<BrowserAgentTester />);

        fireEvent.click(screen.getByRole('button', { name: /Launch Agent/i }));

        await waitFor(() => {
            expect(screen.getByText(/Launch Agent/i)).toBeEnabled();
        });

        // Verify Error Log
        expect(screen.getByText('[Driver] Error: Something went wrong')).toBeInTheDocument();

        // Verify Error Banner (The component sets 'error' state which renders an alert)
        // The component logic: if (!result.success) setError('Agent failed to complete the goal.');
        expect(screen.getByText('Agent failed to complete the goal.')).toBeInTheDocument();

        // Verify Store Update
        expect(mockLogAction).toHaveBeenCalledWith(expect.objectContaining({
            status: 'failed'
        }));
    });

    it('handles unexpected exceptions', async () => {
        // Mock exception
        (browserAgentDriver.drive as import("vitest").Mock).mockRejectedValueOnce(new Error('Network Error'));

        render(<BrowserAgentTester />);

        fireEvent.click(screen.getByRole('button', { name: /Launch Agent/i }));

        await waitFor(() => {
            expect(screen.getByText(/Launch Agent/i)).toBeEnabled();
        });

        // Verify Error Banner
        expect(screen.getByText('Network Error')).toBeInTheDocument();

        // Verify Log
        expect(screen.getByText('[ERROR] Network Error')).toBeInTheDocument();
    });

    it('updates input fields correctly', () => {
        render(<BrowserAgentTester />);

        const urlInput = screen.getByLabelText(/Target URL/i);
        fireEvent.change(urlInput, { target: { value: 'https://example.com' } });
        expect(urlInput).toHaveValue('https://example.com');

        const goalInput = screen.getByLabelText(/Instruction \/ Goal/i);
        fireEvent.change(goalInput, { target: { value: 'New Goal' } });
        expect(goalInput).toHaveValue('New Goal');
    });
});

import React, { useState, useEffect, useRef } from 'react';
import { Play, Terminal, ExternalLink, AlertCircle, CheckCircle2, Loader2, Image as ImageIcon } from 'lucide-react';
import { browserAgentDriver } from '../../../services/agent/BrowserAgentDriver';
import { useAgentStore } from '../store/AgentStore';
import { AgentActionType } from '../types';

const BrowserAgentTester: React.FC = () => {
    const [url, setUrl] = useState('https://www.google.com');
    const [goal, setGoal] = useState('Find the capacity of "Saint Andrew\'s Hall" in Detroit');
    const [isRunning, setIsRunning] = useState(false);
    const [logs, setLogs] = useState<string[]>([]);
    const [screenshot, setScreenshot] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const { logAction } = useAgentStore();
    const logEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        logEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [logs]);

    const runAgent = async () => {
        setIsRunning(true);
        setLogs([]);
        setScreenshot(null);
        setError(null);

        try {
            // Update logs in real-time if the driver supported callbacks, 
            // but for now we'll just wait for the result or poll if we enhanced it.
            // Let's assume the driver returns the full logs at the end for this prototype.
            const result = await browserAgentDriver.drive(url, goal);

            setLogs(result.logs);

            if (result.success) {
                logAction({
                    type: AgentActionType.BROWSER_DRIVE,
                    description: `Successfully achieved goal: ${goal}`,
                    status: 'completed',
                    metadata: { url, goal, steps: result.logs.length }
                });
            } else {
                setError('Agent failed to complete the goal.');
                logAction({
                    type: AgentActionType.BROWSER_DRIVE,
                    description: `Failed goal: ${goal}`,
                    status: 'failed',
                    metadata: { url, goal, error: 'Incomplete' }
                });
            }
        } catch (err: unknown) {
            const errMessage = err instanceof Error ? err.message : 'An unexpected error occurred';
            setError(errMessage);
            setLogs(prev => [...prev, `[ERROR] ${errMessage}`]);
        } finally {
            setIsRunning(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-xl">
                <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                    <Terminal className="text-cyan-400" size={20} /> Autonomous Agent Lab
                </h2>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    <div className="space-y-4">
                        <div>
                            <label htmlFor="agent-url" className="block text-sm font-medium text-slate-400 mb-1">Target URL</label>
                            <div className="relative">
                                <ExternalLink className="absolute left-3 top-2.5 text-slate-600" size={16} />
                                <input
                                    id="agent-url"
                                    value={url}
                                    onChange={(e) => setUrl(e.target.value)}
                                    className="w-full bg-slate-950 border border-slate-800 rounded-lg pl-10 pr-4 py-2 text-white focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                                    placeholder="https://..."
                                />
                            </div>
                        </div>

                        <div>
                            <label htmlFor="agent-goal" className="block text-sm font-medium text-slate-400 mb-1">Instruction / Goal</label>
                            <textarea
                                id="agent-goal"
                                value={goal}
                                onChange={(e) => setGoal(e.target.value)}
                                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2 text-white h-32 resize-none focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                                placeholder="What should the agent do?"
                            />
                        </div>

                        <button
                            onClick={runAgent}
                            disabled={isRunning}
                            className="w-full bg-cyan-600 hover:bg-cyan-500 disabled:bg-slate-800 disabled:text-slate-500 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all transform active:scale-[0.98]"
                        >
                            {isRunning ? (
                                <>
                                    <Loader2 className="animate-spin" size={20} />
                                    Agent Driving...
                                </>
                            ) : (
                                <>
                                    <Play size={20} />
                                    Launch Agent
                                </>
                            )}
                        </button>

                        {error && (
                            <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-lg flex items-center gap-3">
                                <AlertCircle size={20} />
                                <span className="text-sm">{error}</span>
                            </div>
                        )}
                    </div>

                    <div className="flex flex-col h-[400px]">
                        <label className="block text-sm font-medium text-slate-400 mb-1 flex items-center gap-2">
                            <Terminal size={14} /> Execution Logs
                        </label>
                        <div className="flex-1 bg-black rounded-lg p-4 font-mono text-xs overflow-y-auto border border-slate-800 space-y-1 custom-scrollbar">
                            {logs.length === 0 && !isRunning && (
                                <div className="text-slate-700 italic">Logs will appear here once the agent starts...</div>
                            )}
                            {logs.map((log, i) => (
                                <div key={i} className={
                                    log.includes('[ERROR]') ? 'text-red-400' :
                                        log.includes('[Driver] AI Thought') ? 'text-blue-400' :
                                            log.includes('[Driver] AI Action') ? 'text-cyan-400 font-bold' :
                                                'text-slate-300'
                                }>
                                    {log}
                                </div>
                            ))}
                            {isRunning && (
                                <div className="text-cyan-400 animate-pulse flex items-center gap-2">
                                    <span className="w-1.5 h-1.5 bg-cyan-400 rounded-full"></span>
                                    Wait for AI reasoning...
                                </div>
                            )}
                            <div ref={logEndRef} />
                        </div>
                    </div>
                </div>
            </div>

            {/* Quick Tips */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-slate-900/50 border border-slate-800/50 p-4 rounded-xl flex items-start gap-3">
                    <div className="bg-cyan-500/10 p-2 rounded-lg text-cyan-400">
                        <ImageIcon size={18} />
                    </div>
