                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* All Characters Grid Modal */}
            {showAllGrid && (
                <div
                    className="fixed inset-0 z-[9999] bg-black/90 backdrop-blur-xl flex items-center justify-center p-8"
