                                    className="p-1.5 bg-gray-800/50 text-white rounded hover:bg-purple-600 transition-colors"
                                    title="Set as Last Frame"
                                    aria-label="Set as Last Frame"
                                >
                                    <ArrowRightToLine size={14} />
                                </button>
