import React, { useMemo, useState } from 'react';
import { useStore } from '@/core/store';
import { useShallow } from 'zustand/react/shallow';
import { formatSmartDate } from '@/lib/utils';
import { MessageSquare, Trash2, Clock, Search, Activity, FileText, Image as ImageIcon, Music, Video as VideoIcon, Bot } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import type { ConversationSession } from '@/core/store/slices/agent';
import { FilterItem } from './components/FilterItem';

export default function HistoryDashboard() {
    const {
        sessions,
        activeSessionId,
        setActiveSession,
        deleteSession,
        updateSessionTitle,
        fileNodes
    } = useStore(
        useShallow(state => ({
            sessions: state.sessions,
            activeSessionId: state.activeSessionId,
            setActiveSession: state.setActiveSession,
            deleteSession: state.deleteSession,
            updateSessionTitle: state.updateSessionTitle,
            fileNodes: state.fileNodes,
        }))
    );

    const [searchQuery, setSearchQuery] = useState('');
    const [filterType, setFilterType] = useState<'all' | 'agent' | 'file'>('all');

    // Combine sessions and files into a single unified timeline
    const timelineItems = useMemo(() => {
        interface TimelineItem {
            type: 'agent' | 'file';
            id: string;
            title: string;
            timestamp: number;
            fileType?: string;
            messageCount?: number;
        }
        const items: TimelineItem[] = [];

        if (filterType === 'all' || filterType === 'agent') {
            Object.values(sessions).forEach(session => {
                items.push({
                    type: 'agent',
                    id: session.id,
                    title: session.title || 'Temporal Stream',
                    timestamp: session.updatedAt,
                    messageCount: session.messages?.length || 0,
                });
            });
        }

        if (filterType === 'all' || filterType === 'file') {
            fileNodes.forEach((file: { id: string; name: string; createdAt?: number; _mockTimestamp?: number }) => {
                // Approximate timestamp if missing, ideally files have createdAt
                items.push({
                    type: 'file',
                    id: file.id,
                    title: file.name,
                    timestamp: file.createdAt || file._mockTimestamp || parseInt(file.id, 36) % 10000000000 + 1700000000000,
                    fileType: (file as { fileType?: string }).fileType,
                });
            });
        }

        // Sort descending
        return items
            .filter(item => item.title.toLowerCase().includes(searchQuery.toLowerCase()))
            .sort((a, b) => b.timestamp - a.timestamp);
    }, [sessions, fileNodes, filterType, searchQuery]);

    const getFileIcon = (fileType: string) => {
        switch (fileType) {
            case 'image': return <ImageIcon size={16} className="text-blue-400" />;
            case 'video': return <VideoIcon size={16} className="text-pink-400" />;
            case 'audio': return <Music size={16} className="text-green-400" />;
            default: return <FileText size={16} className="text-gray-400" />;
        }
    };

    return (
        <div className="flex h-full bg-background overflow-hidden relative text-white">
            {/* Ambient Background Effect */}
            <div className="absolute top-[-20%] left-[-10%] w-[800px] h-[800px] bg-purple-500/10 rounded-full blur-[150px] pointer-events-none" />

            {/* Left Sidebar (Filters) */}
            <div className="w-64 border-r border-white/5 bg-surface/30 backdrop-blur-xl flex flex-col z-10">
                <div className="p-6">
                    <h1 className="text-2xl font-black tracking-tight text-transparent bg-clip-text bg-linear-to-r from-purple-400 to-pink-600 flex items-center gap-2">
                        <Activity size={24} className="text-purple-500" />
                        HISTORY
                    </h1>
                    <p className="text-[10px] text-muted-foreground font-bold uppercase tracking-widest mt-1">Unified Activity Feed</p>
                </div>

                <nav className="flex-1 px-4 space-y-2 mt-4">
                    <FilterItem
                        icon={Clock}
                        label="All Activity"
                        active={filterType === 'all'}
                        onClick={() => setFilterType('all')}
                    />
                    <FilterItem
                        icon={Bot}
                        label="Agent Sessions"
                        active={filterType === 'agent'}
                        onClick={() => setFilterType('agent')}
                    />
                    <FilterItem
                        icon={FileText}
                        label="Asset Creation"
                        active={filterType === 'file'}
                        onClick={() => setFilterType('file')}
                    />
                </nav>
            </div>

            {/* Main Content (Timeline) */}
            <div className="flex-1 flex flex-col z-10 min-w-0">
                {/* Search Bar */}
                <div className="h-20 border-b border-white/5 flex items-center px-8 bg-surface/20 backdrop-blur-md">
                    <div className="relative w-full max-w-2xl">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
                        <input
                            type="text"
                            placeholder="Search history, agent sessions, or files..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full bg-black/40 border border-white/10 rounded-2xl pl-12 pr-4 py-3 text-sm text-gray-200 placeholder:text-gray-600 focus:outline-none focus:ring-2 focus:ring-purple-500/50 transition-all shadow-inner"
                        />
                    </div>
                </div>

                {/* Feed */}
                <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                    <div className="max-w-4xl mx-auto">
                        <div className="relative">
                            {/* Timeline Line */}
                            <div className="absolute left-[27px] top-4 bottom-0 w-px bg-white/10" />

                            {timelineItems.length === 0 ? (
                                <div className="text-center py-20 text-gray-500">
                                    <Clock size={48} className="mx-auto mb-4 opacity-20" />
                                    <p className="text-lg font-medium text-gray-400">No activity found</p>
                                    <p className="text-sm">Try adjusting your filters or search query.</p>
                                </div>
                            ) : (
                                <div className="space-y-6">
                                    <AnimatePresence>
                                        {timelineItems.map((item, i) => (
                                            <motion.div
                                                layout
                                                initial={{ opacity: 0, y: 10 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                exit={{ opacity: 0, scale: 0.95 }}
                                                transition={{ duration: 0.2, delay: i * 0.02 }}
                                                key={`${item.type}-${item.id}`}
                                                className="relative pl-16 group"
                                            >
                                                {/* Timeline Dot */}
                                                <div className="absolute left-5 top-1/2 -translate-y-1/2 w-4 h-4 rounded-full bg-background border-2 border-purple-500 shadow-[0_0_10px_rgba(168,85,247,0.5)] z-10 flex items-center justify-center">
                                                    <div className="w-1.5 h-1.5 rounded-full bg-purple-400" />
                                                </div>

                                                <div className="bg-surface/30 border border-white/5 rounded-xl p-4 hover:bg-surface/50 transition-colors flex items-center justify-between group-hover:border-white/10">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-10 h-10 rounded-lg bg-black/40 border border-white/5 flex items-center justify-center flex-shrink-0">
                                                            {item.type === 'agent' ? <Bot size={20} className="text-purple-400" /> : getFileIcon(item.fileType || 'file')}
                                                        </div>
                                                        <div>
                                                            <h3 className="font-bold text-gray-200">{item.title}</h3>
                                                            <div className="flex items-center gap-3 mt-1 text-xs text-gray-500 font-mono">
                                                                <span>{formatSmartDate(item.timestamp)}</span>
                                                                <span className="w-1 h-1 rounded-full bg-white/20" />
                                                                <span className="uppercase tracking-widest">{item.type}</span>
                                                                {item.type === 'agent' && (
                                                                    <>
                                                                        <span className="w-1 h-1 rounded-full bg-white/20" />
                                                                        <span className="flex items-center gap-1"><MessageSquare size={10} /> {item.messageCount || 0} msgs</span>
                                                                    </>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>

                                                    <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                        {item.type === 'agent' && (
                                                            <>
                                                                <button
                                                                    onClick={() => {
                                                                        setActiveSession(item.id);
                                                                    }}
                                                                    className="px-3 py-1.5 bg-purple-500/20 hover:bg-purple-500/40 text-purple-300 text-xs font-bold rounded transition-colors"
                                                                >
                                                                    Resume
                                                                </button>
                                                                <button
                                                                    onClick={() => deleteSession(item.id)}
                                                                    className="p-1.5 text-gray-500 hover:text-red-400 hover:bg-red-500/10 rounded transition-colors"
                                                                >
                                                                    <Trash2 size={14} />
                                                                </button>
                                                            </>
                                                        )}
                                                    </div>
                                                </div>
                                            </motion.div>
                                        ))}
                                    </AnimatePresence>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Search, Loader2, Book, Sparkles, X } from 'lucide-react';
import { EmptyState } from '@/components/shared/EmptyState';
import { useToast } from '@/core/context/ToastContext';
import { knowledgeBaseService, KnowledgeDoc } from './services/KnowledgeBaseService';
import { DocumentCard } from './components/DocumentCard';
import { KnowledgeChat } from './components/KnowledgeChat';
import { ModuleErrorBoundary } from '@/core/components/ModuleErrorBoundary';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

export default function KnowledgeBase() {
    const toast = useToast();
    const [documents, setDocuments] = useState<KnowledgeDoc[]>([]);
    const [isUploading, setIsUploading] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [isDragging, setIsDragging] = useState(false);

    // Chat & View State
    const [isChatOpen, setIsChatOpen] = useState(false);
    const [activeChatDoc, setActiveChatDoc] = useState<KnowledgeDoc | null>(null);
    const [viewingDoc, setViewingDoc] = useState<KnowledgeDoc | null>(null);

    const fileInputRef = useRef<HTMLInputElement>(null);

    const loadDocuments = useCallback(async () => {
        setIsLoading(true);
        try {
            const docs = await knowledgeBaseService.getDocuments();
            setDocuments(docs);
        } catch (_error: unknown) {
            toast.error("Failed to load Knowledge Base.");
        } finally {
            setIsLoading(false);
        }
    }, [toast]);

    useEffect(() => {
        loadDocuments();
    }, [loadDocuments]);

    const handleFileUpload = async (files: FileList | null) => {
        if (!files || files.length === 0) return;

        setIsUploading(true);
        toast.info(`Uploading ${files.length} file(s)...`);

        try {
            const count = await knowledgeBaseService.uploadFiles(files, undefined, (name: string) => {
                // Optional: Toast for each file, but might be too noisy
            });

            if (count > 0) {
                toast.success(`Successfully added ${count} document(s).`);
                await loadDocuments();
            } else {
                toast.error("Upload failed.");
            }
        } catch (_error: unknown) {
            toast.error("Upload encountered an error.");
        } finally {
            setIsUploading(false);
        }
    };

    const handleDelete = async (doc: KnowledgeDoc) => {
        if (!confirm(`Delete "${doc.title}"?`)) return;

        try {
            await knowledgeBaseService.deleteDocument(doc.rawName);
            toast.success("Document deleted.");
            await loadDocuments();
        } catch (_err: unknown) {
            toast.error("Failed to delete document.");
        }
    };

    const handleChat = (doc: KnowledgeDoc) => {
        setActiveChatDoc(doc);
        setIsChatOpen(true);
    };

    const toggleGlobalChat = () => {
        setActiveChatDoc(null);
        setIsChatOpen(!isChatOpen);
    };

    // Drag & Drop Handlers
    const handleDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
    const handleDragLeave = () => { setIsDragging(false); };
    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        handleFileUpload(e.dataTransfer.files);
    };

    const filteredDocs = documents.filter(doc =>
        doc.title.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <ModuleErrorBoundary moduleName="Knowledge Base">
            <div className="h-full flex flex-col bg-bg-dark text-white overflow-hidden relative">
                <div className="flex-1 overflow-y-auto p-8"
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                >
                    {/* Header Section */}
                    <div className="flex items-center justify-between mb-10">
                        <div className="animate-in fade-in slide-in-from-left duration-700">
                            <div className="flex items-center gap-3 mb-3">
                                <h1 className="text-4xl font-black flex items-center gap-3">
                                    <Book className="text-[#FFE135]" size={36} />
                                    <span className="bg-clip-text text-transparent bg-linear-to-r from-white to-gray-500">
                                        Knowledge Base
                                    </span>
                                </h1>
                                <span className="text-[10px] font-black bg-[#FFE135] text-black px-2 py-0.5 rounded-full uppercase tracking-tighter shadow-[0_0_15px_rgba(255,225,53,0.3)]">Beta</span>
                            </div>
                            <p className="text-gray-500 text-lg font-medium tracking-tight">Central Neural Repository & Document Intelligence</p>
                        </div>
                        <div className="flex gap-4 animate-in fade-in slide-in-from-right duration-700">
                            <button
                                onClick={toggleGlobalChat}
                                className={`px-6 py-3 rounded-2xl font-bold flex items-center gap-2 transition-all duration-500 transform active:scale-95 ${isChatOpen
                                    ? 'bg-[#FFE135] text-black shadow-[0_0_30px_rgba(255,225,53,0.4)] scale-105'
                                    : 'bg-[#161b22] text-gray-300 border border-gray-800 hover:border-[#FFE135]/40 hover:text-white'
                                    }`}
                            >
                                <Sparkles size={20} className={isChatOpen ? 'animate-spin-slow' : ''} />
                                {isChatOpen ? 'Neural Connection Active' : 'Initialize Neural Chat'}
                            </button>
                            <button
                                onClick={() => fileInputRef.current?.click()}
                                disabled={isUploading}
                                className="px-6 py-3 bg-[#FFE135]/10 border border-[#FFE135]/30 hover:bg-[#FFE135]/20 text-[#FFE135] disabled:opacity-50 disabled:cursor-not-allowed font-bold rounded-2xl transition-all transform active:scale-95 flex items-center gap-2"
                            >
                                {isUploading ? <Loader2 className="animate-spin" size={20} /> : <Upload size={20} />}
                                {isUploading ? 'Ingesting...' : 'Ingest Document'}
                            </button>
                        </div>
                        <input
                            type="file"
                            ref={fileInputRef}
                            className="hidden"
                            onChange={(e) => handleFileUpload(e.target.files)}
                            accept=".txt,.md,.json,.csv,.js,.ts,.tsx,.pdf"
                            multiple
                        />
                    </div>

                    {/* Search Bar */}
                    <div className="relative mb-12 max-w-3xl animate-in fade-in slide-in-from-bottom duration-1000">
                        <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none">
                            <Search className="text-gray-600 group-focus-within:text-[#FFE135] transition-colors" size={22} />
                        </div>
                        <input
                            type="text"
                            placeholder="Scan neural index for vectors..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full bg-[#161b22]/40 backdrop-blur-md border border-gray-800/80 focus:border-[#FFE135]/50 text-white rounded-2xl pl-14 pr-6 py-5 focus:ring-4 focus:ring-[#FFE135]/5 transition-all placeholder-gray-700 text-xl font-medium shadow-2xl"
                        />
                        {isDragging && (
                            <div className="absolute inset-0 bg-[#FFE135]/10 border-2 border-[#FFE135] border-dashed rounded-2xl flex items-center justify-center backdrop-blur-md z-10 animate-pulse">
                                <p className="text-[#FFE135] font-black text-2xl flex items-center gap-3 uppercase tracking-tighter">
                                    <Upload size={32} /> Release to Ingest
                                </p>
                            </div>
                        )}
                    </div>

                    {/* Content Grid */}
                    {isLoading ? (
                        <div className="flex flex-col items-center justify-center h-64 text-gray-500 gap-4">
                            <Loader2 className="animate-spin text-[#FFE135]" size={48} />
                            <p className="animate-pulse">Accessing Neural Archives...</p>
                        </div>
                    ) : filteredDocs.length === 0 ? (
                        <EmptyState
                            icon="document"
                            title="No documents found"
                            description="Upload files or drag & drop to populate the Knowledge Base."
                            className="h-64"
                        />
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 pb-20">
                            {filteredDocs.map(doc => (
                                <DocumentCard
                                    key={doc.id}
                                    doc={doc}
                                    onDelete={handleDelete}
                                    onChat={handleChat}
                                    onView={setViewingDoc}
                                />
                            ))}
                        </div>
                    )}
                </div>

                {/* Chat Sidebar Overlay */}
                <KnowledgeChat
                    isOpen={isChatOpen}
                    onClose={() => setIsChatOpen(false)}
                    activeDoc={activeChatDoc}
                />

                {/* Document Viewer Modal */}
                {viewingDoc && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 md:p-8 animate-in fade-in duration-300">
                        <div className="bg-[#161b22] border border-gray-800 rounded-3xl w-full max-w-4xl max-h-[90vh] flex flex-col shadow-2xl relative overflow-hidden transform scale-100 animate-in zoom-in-95 duration-300">
                            {/* Header */}
                            <div className="px-6 py-4 border-b border-gray-800 flex items-center justify-between bg-black/40">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 bg-[#FFE135]/10 rounded-xl border border-[#FFE135]/20">
                                        <Book className="text-[#FFE135]" size={20} />
                                    </div>
                                    <h2 className="text-white font-bold text-xl">{viewingDoc.title}</h2>
                                    <span className="bg-emerald-500/10 text-emerald-400 text-[10px] px-2 py-0.5 rounded-full font-mono uppercase tracking-widest border border-emerald-500/20">{viewingDoc.type}</span>
                                </div>
                                <button onClick={() => setViewingDoc(null)} className="p-2.5 text-gray-400 hover:text-white hover:bg-red-500/20 rounded-xl transition-all">
                                    <X size={20} />
                                </button>
                            </div>
                            {/* Content */}
                            <div className="p-6 md:p-8 overflow-y-auto flex-1 custom-scrollbar text-gray-300 prose prose-invert max-w-none prose-headings:text-white prose-a:text-[#FFE135] prose-pre:bg-black/50 prose-pre:border prose-pre:border-gray-800">
                                <ReactMarkdown remarkPlugins={[remarkGfm]}>
                                    {viewingDoc.content || '*No content available for this document.*'}
                                </ReactMarkdown>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </ModuleErrorBoundary>
    );
}

