                    className="absolute top-24 left-6 z-10 flex items-center gap-3 bg-teal-500/10 backdrop-blur-xl border border-teal-500/30 px-4 py-2 rounded-2xl shadow-[0_0_30px_rgba(20,184,166,0.1)]"
