                    <div className="flex items-center gap-3">
                        <button
                            onClick={onClose}
                            className="px-4 py-2 text-gray-400 hover:text-white transition-colors"
                            disabled={isGenerating}
                        >
                            Cancel
                        </button>
                        {!isGenerating && pendingCount > 0 && (
                            <button
                                onClick={handleStartGeneration}
                                className="px-6 py-2 bg-linear-to-r from-green-600 to-emerald-600 hover:from-green-500 hover:to-emerald-500 text-white font-bold rounded-lg transition-all flex items-center gap-2"
                            >
                                <Play size={16} />
                                Generate {pendingCount} Images
                            </button>
                        )}
                        {(completedCount > 0 || skippedCount > 0) && !isGenerating && (
                            <button
                                onClick={handleApply}
                                className="px-6 py-2 bg-white hover:bg-gray-200 text-black font-bold rounded-lg transition-colors flex items-center gap-2"
                            >
                                <Check size={16} />
                                Apply & Save
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

