import React, { useState, useCallback } from 'react';
import { Zap, Activity, Wifi, WifiOff, Sliders } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';

interface MIDIDevice {
    id: string;
    name: string;
    manufacturer: string;
    type: 'input' | 'output';
    state: 'connected' | 'disconnected';
}

interface MIDIEvent {
    channel: number;
    type: string;
    note?: number;
    velocity?: number;
    controller?: number;
    value?: number;
    timestamp: number;
}

function noteName(n: number): string {
    const notes = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    return `${notes[n % 12]}${Math.floor(n / 12) - 1}`;
}

function parseMIDI(data: Uint8Array): Omit<MIDIEvent, 'timestamp'> {
    const status = data[0]!;
    const channel = (status & 0x0F) + 1;
    const type = status & 0xF0;

    if (type === 0x90 && data[2]! > 0) {
        return { channel, type: 'Note On', note: data[1]!, velocity: data[2]! };
    }
    if (type === 0x80 || (type === 0x90 && data[2] === 0)) {
        return { channel, type: 'Note Off', note: data[1], velocity: data[2] };
    }
    if (type === 0xB0) {
        return { channel, type: 'CC', controller: data[1], value: data[2] };
    }
    if (type === 0xE0) {
        const pb = ((data[2]! << 7) | data[1]!) - 8192;
        return { channel, type: 'Pitch Bend', value: pb };
    }
    return { channel, type: `0x${type.toString(16).toUpperCase()}` };
}

export default function MIDIController() {
    const [supported] = useState(() => 'requestMIDIAccess' in navigator);
    const [devices, setDevices] = useState<MIDIDevice[]>([]);
    const [events, setEvents] = useState<MIDIEvent[]>([]);
    const [connected, setConnected] = useState(false);
    const [midiAccess, setMidiAccess] = useState<MIDIAccess | null>(null);

    const refreshDevices = useCallback((access: MIDIAccess) => {
        const list: MIDIDevice[] = [];
        access.inputs.forEach(input => {
            list.push({
                id: input.id,
                name: input.name || 'Unknown Input',
                manufacturer: input.manufacturer || '',
                type: 'input',
                state: input.state as 'connected' | 'disconnected',
            });
        });
        access.outputs.forEach(output => {
            list.push({
                id: output.id,
                name: output.name || 'Unknown Output',
                manufacturer: output.manufacturer || '',
                type: 'output',
                state: output.state as 'connected' | 'disconnected',
            });
        });
        setDevices(list);
    }, []);

    const handleConnect = useCallback(async () => {
        if (!navigator.requestMIDIAccess) return;
        try {
            const access = await navigator.requestMIDIAccess({ sysex: false });
            setMidiAccess(access);
            setConnected(true);
            refreshDevices(access);

            // Wire up message handlers
            access.inputs.forEach(input => {
                input.onmidimessage = (msg) => {
                    if (!msg.data) return;
                    const parsed = parseMIDI(msg.data as Uint8Array);
                    setEvents(prev => [{ ...parsed, timestamp: msg.timeStamp }, ...prev].slice(0, 50));
                };
            });

            // State change listener
            access.onstatechange = () => refreshDevices(access);
        } catch {
            // User denied MIDI access
        }
    }, [refreshDevices]);

    const connectedInputs = devices.filter(d => d.type === 'input' && d.state === 'connected');

    return (
        <div className="p-6 space-y-6 max-w-3xl mx-auto">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-black text-white tracking-tighter uppercase">
                        Hardware MIDI
                    </h2>
                    <p className="text-xs text-gray-500 mt-0.5">
                        WebMIDI API — connect physical gear to your workflows
                    </p>
                </div>
                {!supported && (
                    <span className="text-xs text-red-400 font-bold">WebMIDI not supported in this browser</span>
                )}
            </div>

            {/* Status card */}
            <div className={`rounded-xl border p-4 flex items-center gap-4 ${connected ? 'bg-green-500/5 border-green-500/20' : 'bg-white/[0.02] border-white/5'}`}>
                {connected ? (
                    <Wifi size={20} className="text-green-400" />
                ) : (
                    <WifiOff size={20} className="text-gray-500" />
                )}
                <div className="flex-1">
                    <p className="text-sm font-bold text-white">
                        {connected ? `${connectedInputs.length} input(s) active` : 'Not connected'}
                    </p>
                    <p className="text-[10px] text-gray-500">
                        {connected ? 'Listening for MIDI messages' : 'Click connect to request WebMIDI access'}
                    </p>
                </div>
                {!connected && supported && (
                    <button
                        onClick={handleConnect}
                        className="px-4 py-2 bg-purple-600 hover:bg-purple-500 text-white rounded-lg text-xs font-bold transition-colors"
                    >
                        Connect
                    </button>
                )}
            </div>

            {/* Devices */}
            {devices.length > 0 && (
                <div>
                    <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-3">
                        Devices ({devices.length})
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                        {devices.map(d => (
                            <div key={d.id} className="rounded-xl bg-white/[0.02] border border-white/5 p-3 flex items-center gap-3">
                                {d.type === 'input' ? (
                                    <Activity size={16} className="text-purple-400 flex-shrink-0" />
                                ) : (
                                    <Sliders size={16} className="text-blue-400 flex-shrink-0" />
                                )}
                                <div className="flex-1 min-w-0">
                                    <p className="text-xs font-bold text-white truncate">{d.name}</p>
                                    <p className="text-[10px] text-gray-500">{d.manufacturer || d.type}</p>
                                </div>
                                <div className={`w-2 h-2 rounded-full flex-shrink-0 ${d.state === 'connected' ? 'bg-green-500' : 'bg-gray-600'}`} />
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Event Monitor */}
            <div>
                <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <Zap size={10} />
                    Live Event Monitor
                    {events.length > 0 && (
                        <button onClick={() => setEvents([])} className="ml-auto text-gray-600 hover:text-gray-400 text-[10px] font-normal">
                            Clear
                        </button>
                    )}
                </h3>
                <div className="rounded-xl bg-black/30 border border-white/5 p-3 font-mono text-[11px] min-h-[120px] max-h-[280px] overflow-y-auto space-y-1 custom-scrollbar">
                    {events.length === 0 ? (
                        <p className="text-gray-600 text-center mt-8">
                            {connected ? 'Play a note or move a knob…' : 'Connect a MIDI device to see events'}
                        </p>
                    ) : (
                        <AnimatePresence initial={false}>
                            {events.map((e, i) => (
                                <motion.div
                                    key={`${e.timestamp}-${i}`}
                                    initial={{ opacity: 0, x: -4 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    className="flex items-center gap-3 text-[10px]"
                                >
                                    <span className="text-gray-600 w-20 flex-shrink-0">
                                        {e.timestamp.toFixed(0)}ms
                                    </span>
                                    <span className={`font-bold w-20 flex-shrink-0 ${
                                        e.type === 'Note On' ? 'text-green-400' :
                                        e.type === 'Note Off' ? 'text-red-400' :
                                        e.type === 'CC' ? 'text-yellow-400' : 'text-blue-400'
                                    }`}>
                                        {e.type}
                                    </span>
                                    <span className="text-gray-400">Ch {e.channel}</span>
                                    {e.note !== undefined && (
                                        <span className="text-purple-300">{noteName(e.note)} (vel {e.velocity})</span>
                                    )}
                                    {e.controller !== undefined && (
                                        <span className="text-purple-300">CC{e.controller} = {e.value}</span>
                                    )}
                                    {e.type === 'Pitch Bend' && (
                                        <span className="text-purple-300">{e.value}</span>
                                    )}
                                </motion.div>
                            ))}
                        </AnimatePresence>
                    )}
                </div>
            </div>

            {!supported && (
                <div className="rounded-xl bg-amber-500/5 border border-amber-500/20 p-4">
                    <p className="text-xs text-amber-400 font-bold">WebMIDI API Not Available</p>
                    <p className="text-[10px] text-amber-400/60 mt-1">
                        WebMIDI is supported in Chromium-based browsers. In the Electron desktop app, it's available by default.
                    </p>
                </div>
            )}
        </div>
    );
}

import React, { useState } from 'react';
import { Search, Plus, X, Tag as TagIcon } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';

interface TagMatrixProps {
    tags: string[];
    onAddTag: (tag: string) => void;
    onRemoveTag: (tag: string) => void;
    suggestions: Record<string, string[]>; // Category -> Tags
}

export const TagMatrix: React.FC<TagMatrixProps> = ({ tags, onAddTag, onRemoveTag, suggestions }) => {
    const [search, setSearch] = useState('');
    const [activeCategory, setActiveCategory] = useState<string>('All');
    const [isCustomInput] = useState(false);

    const categories = ['All', ...Object.keys(suggestions)];

    // Flatten suggestions for search
    const allSuggestions = Object.values(suggestions).flat();

    // Filter logic
    const filteredTags = activeCategory === 'All'
        ? allSuggestions
        : suggestions[activeCategory] || [];

    const shownSuggestions = search
        ? allSuggestions.filter(t => t.toLowerCase().includes(search.toLowerCase()))
        : filteredTags;

    const handleAdd = (tag: string) => {
        if (!tags.includes(tag)) {
            onAddTag(tag);
        }
        setSearch('');
    };

    const handleKeypress = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && search) {
            handleAdd(search);
        }
    };

    return (
        <div className="flex flex-col h-full bg-black/20 rounded-xl border border-white/5 overflow-hidden">
            {/* Header / Search */}
            <div className="p-4 border-b border-white/5 space-y-3">
                <div className="flex items-center gap-2 text-xs font-mono text-muted-foreground uppercase tracking-widest">
                    <TagIcon size={12} />
                    <span>Metadata Matrix</span>
                    <span className="bg-primary/20 text-primary px-1.5 rounded ml-auto">{tags.length} Active</span>
                </div>

                <div className="relative">
                    <Search className="absolute left-3 top-2.5 text-muted-foreground w-4 h-4" />
                    <input
                        type="text"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        onKeyDown={handleKeypress}
                        placeholder="Search or create tags..."
                        className="w-full bg-white/5 border border-white/10 rounded-lg pl-9 pr-4 py-2 text-sm text-white focus:outline-none focus:border-primary/50 transition-colors"
                    />
                </div>

                {/* Categories */}
                <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
                    {categories.map(cat => (
                        <button
                            key={cat}
                            onClick={() => setActiveCategory(cat)}
                            className={`text-[10px] px-3 py-1 rounded-full whitespace-nowrap transition-all border ${activeCategory === cat
                                    ? 'bg-primary/20 border-primary/50 text-white'
                                    : 'bg-white/5 border-transparent text-muted-foreground hover:bg-white/10'
                                }`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                {/* Active Tags Section */}
                {tags.length > 0 && (
                    <div className="mb-6">
                        <div className="text-[10px] text-muted-foreground font-bold mb-2">APPLIED TAGS</div>
                        <div className="flex flex-wrap gap-2">
                            <AnimatePresence>
                                {tags.map(tag => (
                                    <motion.div
                                        key={tag}
                                        initial={{ scale: 0.8, opacity: 0 }}
                                        animate={{ scale: 1, opacity: 1 }}
                                        exit={{ scale: 0.8, opacity: 0 }}
                                        className="group flex items-center gap-1.5 pl-3 pr-2 py-1.5 bg-primary/10 border border-primary/20 rounded-md text-xs text-primary-foreground hover:border-primary/50 transition-colors cursor-default"
                                    >
                                        <span>{tag}</span>
                                        <button
                                            onClick={() => onRemoveTag(tag)}
                                            className="p-0.5 hover:bg-black/20 rounded ml-1"
                                        >
                                            <X size={12} />
                                        </button>
                                    </motion.div>
                                ))}
                            </AnimatePresence>
                        </div>
                    </div>
                )}

                {/* Suggestions Grid */}
                <div>
                    <div className="text-[10px] text-muted-foreground font-bold mb-2">
                        {search ? 'SEARCH RESULTS' : `SUGGESTED: ${activeCategory.toUpperCase()}`}
                    </div>

                    <div className="grid grid-cols-2 lg:grid-cols-3 gap-2">
                        {shownSuggestions.map(tag => {
                            const isActive = tags.includes(tag);
                            return (
                                <button
                                    key={tag}
                                    onClick={() => !isActive && handleAdd(tag)}
                                    disabled={isActive}
                                    className={`text-left px-3 py-2 rounded-md text-xs transition-all flex items-center justify-between group ${isActive
                                            ? 'bg-white/5 text-muted-foreground opacity-50 cursor-default'
                                            : 'bg-secondary/30 hover:bg-secondary text-secondary-foreground hover:pl-4'
                                        }`}
                                >
                                    <span>{tag}</span>
                                    {!isActive && <Plus size={12} className="opacity-0 group-hover:opacity-100 transition-opacity" />}
                                </button>
                            );
                        })}
                        {shownSuggestions.length === 0 && (
                            <div className="col-span-full py-8 text-center text-muted-foreground text-xs italic">
                                No matching suggestions. Press Enter to create "{search}".
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';

import { motion, AnimatePresence } from 'motion/react';
import { useToast } from '@/core/context/ToastContext';
import { functions } from '@/services/firebase';
import { httpsCallable } from 'firebase/functions';
import { PlanningTab } from './components/PlanningTab';
import { OnTheRoadTab } from './components/OnTheRoadTab';
import { useTouring } from './hooks/useTouring';
import { Itinerary, NearbyPlace, FuelLogistics, LogisticsReport } from './types';

import { RoadMode } from './components/RoadMode';
import { useMobile } from '@/hooks/useMobile';
import { RoadManagerSidebar, TouringTab } from './components/RoadManagerSidebar';
import { RiderChecklist } from './components/RiderChecklist';
import { Phone, Fuel, Calendar, CheckSquare, AlertTriangle, Navigation } from 'lucide-react';
import { TourRouteOptimizer } from './components/TourRouteOptimizer';
import { TechnicalRiderGenerator } from './components/TechnicalRiderGenerator';
import { SetlistAnalytics } from './components/SetlistAnalytics';
import { VisaChecklist } from './components/VisaChecklist';
import { logger } from '@/utils/logger';
import { ModuleErrorBoundary } from '@/core/components/ModuleErrorBoundary';

const RoadManager: React.FC = () => {
    // Hooks must be called unconditionally before early returns
    const toast = useToast();
    const {
        currentItinerary: itinerary,
        setCurrentItinerary,
        saveItinerary,
        updateItineraryStop,
        vehicleStats,
        saveVehicleStats,
        loading: touringLoading
    } = useTouring();

    // Core State
    const [locations, setLocations] = useState<string[]>([]);
    const [newLocation, setNewLocation] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);

    // Feature Tabs
    const [activeTab, setActiveTab] = useState<TouringTab>('planning');

    // Logistics State
    const [isCheckingLogistics, setIsCheckingLogistics] = useState(false);
    const [logisticsReport, setLogisticsReport] = useState<LogisticsReport | null>(null);

    // On the Road State
    const [currentLocation, setCurrentLocation] = useState('');
    const [nearbyPlaces, setNearbyPlaces] = useState<NearbyPlace[]>([]);
    const [isFindingPlaces, setIsFindingPlaces] = useState(false);
    const [fuelLogistics, setFuelLogistics] = useState<FuelLogistics | null>(null);
    const [isCalculatingFuel, setIsCalculatingFuel] = useState(false);

    // Reactive mobile detection via centralized hook
    const { isAnyPhone: isMobile } = useMobile();

    if (isMobile) {
        return (
            <ModuleErrorBoundary moduleName="Road Manager">
                <RoadMode />
            </ModuleErrorBoundary>
        );
    }

    const handleAddLocation = () => {
        if (newLocation.trim()) {
            setLocations([...locations, newLocation.trim()]);
            setNewLocation('');
        }
    };

    const handleRemoveLocation = (index: number) => {
        setLocations(locations.filter((_, i) => i !== index));
    };

    const handleGenerateItinerary = async () => {
        if (locations.length === 0 || !startDate || !endDate) {
            toast.error("Please provide locations and dates.");
            return;
        }

        setIsGenerating(true);
        // setItinerary(null); // Managed by hook now
        setLogisticsReport(null);

        try {
            const generateItinerary = httpsCallable(functions, 'generateItinerary');
            const response = await generateItinerary({ locations, dates: { start: startDate, end: endDate } });
            const result = response.data as Itinerary;

            await saveItinerary({
                ...result,
                tourName: `Tour ${startDate} - ${locations[0]}`
            });

            toast.success("Itinerary generated and saved");
        } catch (_error: unknown) {
            // logger.error("Itinerary Generation Failed:", error);
            toast.error("Failed to generate itinerary");
        } finally {
            setIsGenerating(false);
        }
    };

    const handleCheckLogistics = async () => {
        if (!itinerary) return;

        setIsCheckingLogistics(true);
        try {
            const checkLogistics = httpsCallable(functions, 'checkLogistics');
            const response = await checkLogistics({ itinerary });
            const result = response.data as LogisticsReport;
            setLogisticsReport(result);
            toast.success("Logistics check complete");
        } catch (_error: unknown) {
            // logger.error("Logistics Check Failed:", error);
            toast.error("Failed to check logistics");
        } finally {
            setIsCheckingLogistics(false);
        }
    };

    const handleFindGasStations = async () => {
        if (!currentLocation) {
            toast.error("Please enter a location");
            return;
        }
        setIsFindingPlaces(true);
        try {
            const findPlaces = httpsCallable(functions, 'findPlaces');
            const response = await findPlaces({ location: currentLocation, type: 'gas_station' });
            const result = response.data as { places: NearbyPlace[] };
            setNearbyPlaces(result.places);
            toast.success("Found gas stations nearby");
        } catch (error: unknown) {
            logger.error("Find Places Failed:", error);
            toast.error("Failed to find gas stations");
        } finally {
            setIsFindingPlaces(false);
        }
    };

    const handleCalculateFuel = async () => {
        setIsCalculatingFuel(true);
        try {
            const calculateFuelLogistics = httpsCallable(functions, 'calculateFuelLogistics');
            const response = await calculateFuelLogistics(vehicleStats);
            const result = response.data as FuelLogistics;
            setFuelLogistics(result);
            toast.success("Fuel logistics calculated");
        } catch (error: unknown) {
            logger.error("Fuel Calc Failed:", error);
            toast.error("Failed to calculate fuel logistics");
        } finally {
            setIsCalculatingFuel(false);
        }
    };

    const handleUpdateStop = async (updatedStop: Itinerary['stops'][number]) => {
        if (!itinerary) return;

        // Optimistic UI Update
        const newStops = itinerary.stops.map(s => {
            if (s.date === updatedStop.date) {
                return updatedStop;
            }
            return s;
        });
        setCurrentItinerary({ ...itinerary, stops: newStops });

        try {
            // Find index of stop
            const index = itinerary.stops.findIndex(s => s.date === updatedStop.date);
            if (index !== -1) {
                await updateItineraryStop(index, updatedStop);
                toast.success("Day sheet updated");
            }
        } catch (err: unknown) {
            logger.error("Failed to update stop", err);
            toast.error("Failed to update stop");
        }
    };

    return (
        <ModuleErrorBoundary moduleName="Road Manager">
            <div className="absolute inset-0 flex text-white">
                {/* ── LEFT PANEL — Road Manager Sidebar ──────────────── */}
                <RoadManagerSidebar activeTab={activeTab} setActiveTab={setActiveTab} />

                {/* ── CENTER — Main Content ──────────────────────────── */}
                <div className="flex-1 flex flex-col min-w-0 overflow-y-auto selection:bg-yellow-500/30">
                    <main className="flex-1 p-6 md:p-8 w-full">
                        <AnimatePresence mode="wait">
                            <motion.div
                                key={activeTab}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                transition={{ duration: 0.2, ease: 'easeOut' }}
                                className="h-full"
                            >
                                {activeTab === 'planning' && (
                                    <PlanningTab
                                        startDate={startDate}
                                        setStartDate={setStartDate}
                                        endDate={endDate}
                                        setEndDate={setEndDate}
                                        locations={locations}
                                        newLocation={newLocation}
                                        setNewLocation={setNewLocation}
                                        handleAddLocation={handleAddLocation}
                                        handleRemoveLocation={handleRemoveLocation}
                                        handleGenerateItinerary={handleGenerateItinerary}
                                        isGenerating={isGenerating}
                                        itinerary={itinerary}
                                        handleCheckLogistics={handleCheckLogistics}
                                        isCheckingLogistics={isCheckingLogistics}
                                        logisticsReport={logisticsReport}
                                        onUpdateStop={handleUpdateStop}
                                    />
                                )}

                                {activeTab === 'on-the-road' && (
                                    <OnTheRoadTab
                                        currentLocation={currentLocation}
                                        setCurrentLocation={setCurrentLocation}
                                        handleFindGasStations={handleFindGasStations}
                                        isFindingPlaces={isFindingPlaces}
                                        nearbyPlaces={nearbyPlaces}
                                        fuelStats={vehicleStats || {
                                            milesDriven: 0,
                                            fuelLevelPercent: 50,
                                            tankSizeGallons: 15,
                                            mpg: 8,
                                            gasPricePerGallon: 3.50,
                                            userId: ''
                                        }}
                                        setFuelStats={saveVehicleStats}
                                        handleCalculateFuel={handleCalculateFuel}
                                        isCalculatingFuel={isCalculatingFuel}
                                        fuelLogistics={fuelLogistics}
                                        itinerary={itinerary}
                                    />
                                )}

                                {activeTab === 'rider' && (
                                    <div className="h-full">
                                        <RiderChecklist />
                                    </div>
                                )}

                                {activeTab === 'route-optimizer' && (
                                    <div className="h-full p-6 overflow-y-auto">
                                        <TourRouteOptimizer />
                                    </div>
                                )}

                                {activeTab === 'tech-rider' && (
                                    <div className="h-full p-6 overflow-y-auto">
                                        <TechnicalRiderGenerator />
                                    </div>
                                )}

                                {activeTab === 'setlist' && (
                                    <div className="h-full p-6 overflow-y-auto">
                                        <SetlistAnalytics />
                                    </div>
                                )}

                                {activeTab === 'visa' && (
                                    <div className="h-full p-6 overflow-y-auto">
                                        <VisaChecklist />
                                    </div>
                                )}
                            </motion.div>
                        </AnimatePresence>
                    </main>
                </div>

                {/* ── RIGHT PANEL — On The Road Info ─────────────────── */}
                <aside className="hidden lg:flex w-72 2xl:w-80 flex-col border-l border-white/5 overflow-y-auto p-3 gap-3 flex-shrink-0">
                    <ItinerarySummaryPanel itinerary={itinerary} />
                    <VehicleStatusPanel vehicleStats={vehicleStats} fuelLogistics={fuelLogistics} />
                    <RiderQuickPanel onNavigate={() => setActiveTab('rider')} />
                    <EmergencyContactsPanel />
                </aside>
            </div>
        </ModuleErrorBoundary>
    );
};

