export class BaseAgent implements SpecializedAgent {
    public id: string;
    public name: string;
    public description: string;
    public color: string;
    public category: 'manager' | 'department' | 'specialist';
    public systemPrompt: string;
    public tools: ToolDefinition[];
    protected functions: Record<string, AnyToolFunction> = {};
    /** Explicit allowlist of tool names. Populated from AgentConfig.authorizedTools.
     *  If undefined, all declared functionDeclarations are allowed. */
    protected authorizedTools?: string[];
    /** Fine-tuned model endpoint for this agent. When set and feature flag is enabled,
     *  this model is used instead of the default AI_MODELS.TEXT.AGENT. */
    protected modelId?: string;
    private toolSchemas: Map<string, ZodType> = new Map();

    // CRITICAL: Execution lock to prevent concurrent agent execution for same user/project
    // Prevents race conditions that cause agents to "dismantle" each other
    private static executionLocks: Map<string, Promise<AgentResponse>> = new Map();

    // Phase 2: Advanced loop detection to prevent stuck agents
    private loopDetector: LoopDetector = new LoopDetector();

    /**
     * Static WeakMaps for identity state — kept outside the instance
     * so that Object.freeze (from FreezeDiagnostic) doesn't block async minting
     * or identity card assignment.
     */
    private static identityMintPromises = new WeakMap<BaseAgent, Promise<AgentIdentityCard>>();
    private static identityCards = new WeakMap<BaseAgent, AgentIdentityCard>();

    /** Accessor for the cryptographic identity card (stored in static WeakMap to survive freeze) */
    protected get identityCard(): AgentIdentityCard | null {
        return BaseAgent.identityCards.get(this) ?? null;
    }
    protected set identityCard(card: AgentIdentityCard | null) {
        if (card) {
            BaseAgent.identityCards.set(this, card);
        } else {
            BaseAgent.identityCards.delete(this);
        }
    }

    constructor(config: AgentConfig) {
        this.id = config.id;
        this.name = config.name;
        this.description = config.description;
        this.color = config.color;
        this.category = config.category;
        this.systemPrompt = config.systemPrompt;

        // Phase 4: Use shallow clone for tools to preserve Zod schemas
        this.tools = config.tools ? [...config.tools] : [];

        // Store explicit tool allowlist from config (undefined = infer from declarations)
        this.authorizedTools = config.authorizedTools;

        // Store fine-tuned model ID if specified, otherwise check registry
        this.modelId = config.modelId || getFineTunedModel(config.id as ValidAgentId);

        // Accept pre-minted identity card if provided
        if (config.identityCard) {
            this.identityCard = config.identityCard;
        }

        // Populate tool schemas for validation
        this.tools.forEach(def => {
            def.functionDeclarations.forEach(fn => {
                if (fn.schema) {
                    this.toolSchemas.set(fn.name, fn.schema);
                }
            });
        });

        // Initialize functions
        this.functions = {
            // Phase 3.5: Migrated to use execution context for isolated state access
            get_project_details: async ({ projectId }, _context, toolContext?: ToolExecutionContext) => {
                // Use execution context if available, fallback to direct store access for backwards compatibility
                const projects = toolContext ? toolContext.get('projects') : (await import('@/core/store')).useStore.getState().projects;
                const project = (projects as Array<{ id: string }>)?.find(p => p.id === projectId);
                if (!project) return { success: false, error: 'Project not found' };
                return { success: true, data: project };
            },
            // Phase 3.5: Updated signature to accept toolContext (not used, but consistent)
            delegate_task: async ({ targetAgentId, task }: DelegateTaskArgs, context, _toolContext?: ToolExecutionContext) => {
                // Phase 2: Check for delegation loops
                const traceId = context?.traceId || 'unknown';
                const delegationCheck = DelegationLoopDetector.recordDelegation(traceId, targetAgentId);
                if (delegationCheck.isLoop) {
                    logger.warn(`[BaseAgent] Delegation loop detected: ${traceId} -> ${targetAgentId}. Pattern: ${delegationCheck.pattern}`);
                    return toolError(
                        `Cannot delegate: ${delegationCheck.reason}. Chain: ${delegationCheck.pattern}`,
                        'DELEGATION_LOOP'
                    );
                }

                // Swarm Seating Awareness: Enforce that only seated agents can be delegated to in Boardroom Mode
                const ctxRecord = context as Record<string, any>;
                if (ctxRecord?.isBoardroomMode && ctxRecord?.seatedAgents) {
                    const seatedAgents = ctxRecord.seatedAgents as string[];
                    if (!seatedAgents.includes(targetAgentId)) {
                        logger.warn(`[BaseAgent] Boardroom seating violation: Agent '${targetAgentId}' is not seated at the table.`);
                        return toolError(
                            `Cannot delegate to '${targetAgentId}'. This agent is not currently seated at the boardroom table. You must ask the user to invite them to the boardroom if you need their expertise.`,
                            'BOARDROOM_SEATING_VIOLATION'
                        );
                    }
                }

                // GEAP: Record delegation provenance for audit trail
                if (this.identityCard) {
                    agentIdentityService.recordDelegation(
                        this.identityCard,
                        'delegate_task',
                        targetAgentId,
                        traceId
                    );
                }

                try {
                    if (!context?.runAgent) {
                        return toolError('Agent system runner not available in context', 'INTERNAL_ERROR');
                    }

                    const result = await context.runAgent(targetAgentId, task, context, context?.traceId, context?.attachments);
                    return {
                        success: true,
                        data: result,
                        message: `Delegated task to ${targetAgentId}`
                    };
                } catch (err: unknown) {
                    const message = err instanceof Error ? err.message : String(err);
                    return toolError(`Delegation failed: ${message}`, 'EXECUTION_ERROR');
                }
            },
            // Phase 3.5: Updated signature to accept toolContext (not used, but consistent)
            consult_experts: async ({ consultations }: ConsultExpertsArgs, context, _toolContext?: ToolExecutionContext) => {
                if (!Array.isArray(consultations)) {
                    return toolError('Consultations must be an array', 'INVALID_ARGS');
                }

                // GEAP: Record consultation provenance for audit trail
                if (this.identityCard) {
                    const targetIds = consultations.map(c => c.targetAgentId).join(',');
                    agentIdentityService.recordDelegation(
                        this.identityCard,
                        'consult_experts',
                        targetIds,
                        context?.traceId
                    );
                }

                // Swarm Seating Awareness: Enforce that only seated agents can be consulted in Boardroom Mode
                const ctxRecord = context as Record<string, any>;
                if (ctxRecord?.isBoardroomMode && ctxRecord?.seatedAgents) {
                    const seatedAgents = ctxRecord.seatedAgents as string[];
                    const unseated = consultations.filter(c => !seatedAgents.includes(c.targetAgentId));
                    if (unseated.length > 0) {
                        const unseatedIds = unseated.map(u => u.targetAgentId).join(', ');
                        logger.warn(`[BaseAgent] Boardroom seating violation in consult_experts: Agents [${unseatedIds}] are not seated.`);
                        return toolError(
                            `Cannot consult [${unseatedIds}]. These agents are not currently seated at the boardroom table. You can only consult experts that have been invited by the user.`,
                            'BOARDROOM_SEATING_VIOLATION'
                        );
                    }
                }

                try {
                    const results = await Promise.all(
                        consultations.map(async (c: ExpertConsultation) => {
                            if (!VALID_AGENT_IDS.includes(c.targetAgentId)) {
                                return { agentId: c.targetAgentId, error: `Invalid agent ID: ${c.targetAgentId}` };
                            }

                            // Phase 4: Enforce hub-and-spoke architecture
                            const hubSpokeError = validateHubAndSpoke(this.id, c.targetAgentId);
                            if (hubSpokeError) {
                                logger.warn(`[BaseAgent] Hub-and-spoke violation in consult_experts: ${this.id} -> ${c.targetAgentId}`);
                                return { agentId: c.targetAgentId, error: hubSpokeError };
                            }

                            if (!context?.runAgent) {
                                return { agentId: c.targetAgentId, error: 'Agent system runner not available in context' };
                            }

                            const res = await context.runAgent(c.targetAgentId, c.task, context, context?.traceId, context?.attachments);
                            return { agentId: c.targetAgentId, response: res };
                        })
                    );

                    return {
                        success: true,
                        data: { results },
                        message: `Consulted ${consultations.length} experts`
                    };
                } catch (err: unknown) {
                    const message = err instanceof Error ? err.message : String(err);
                    return toolError(`Consultation failed: ${message}`, 'EXECUTION_ERROR');
                }
            },
            consult_specialist: async (args: Record<string, unknown>, context, toolContext?: ToolExecutionContext) => {
                const { targetAgentId, payload } = args as { targetAgentId: string; payload: Record<string, unknown> };

                // GEAP: Record consultation provenance for audit trail
                if (this.identityCard) {
                    agentIdentityService.recordDelegation(
                        this.identityCard,
                        'consult_specialist',
                        targetAgentId,
                        context?.traceId
                    );
                }

                try {
                    if (!VALID_AGENT_IDS.includes(targetAgentId as typeof VALID_AGENT_IDS[number])) {
                        return toolError(`Invalid agent ID: ${targetAgentId}`, 'INVALID_ARGS');
                    }

                    const hubSpokeError = validateHubAndSpoke(this.id, targetAgentId);
                    if (hubSpokeError) {
                        logger.warn(`[BaseAgent] Hub-and-spoke violation in consult_specialist: ${this.id} -> ${targetAgentId}`);
                        return toolError(hubSpokeError, 'HUB_SPOKE_VIOLATION');
                    }

                    // A2A Swarm Request
                    const { a2aClient } = await import('./a2a/A2AClient');
                    const directive = {
                        id: crypto.randomUUID(),
                        type: 'A2A_CONSULTATION',
                        title: `Consult ${targetAgentId}`,
                        status: 'in_progress',
                        steps: [],
                        createdAt: Date.now(),
                        updatedAt: Date.now()
                    };

                    const response = await a2aClient.invoke(targetAgentId, 'execute', payload, directive as any);
                    return {
                        success: true,
                        data: response,
                        message: `Consulted specialist ${targetAgentId}`
                    };
                } catch (err: unknown) {
                    const message = err instanceof Error ? err.message : String(err);
                    return toolError(`Specialist consultation failed: ${message}`, 'EXECUTION_ERROR');
                }
            },
            // Phase 3.5: Updated signature to accept toolContext (not used, but consistent)
            schedule_task: async (args: Record<string, unknown>, _context?: AgentContext, _toolContext?: ToolExecutionContext) => {
                const { targetAgentId, task, delayMinutes } = args as { targetAgentId: string; task: string; delayMinutes: number };
                const { proactiveService } = await import('./ProactiveService');
                const executeAt = Date.now() + (delayMinutes * 60000);
                const taskId = await proactiveService.scheduleTask(targetAgentId, task, executeAt);
                return {
                    success: true,
                    data: { taskId },
                    message: `Task scheduled for ${new Date(executeAt).toLocaleString()}`
                };
            },
            // Phase 3.5: Updated signature to accept toolContext (not used, but consistent)
            subscribe_to_event: async (args: Record<string, unknown>, _context?: AgentContext, _toolContext?: ToolExecutionContext) => {
                const { eventType, task } = args as { eventType: string; task: string };
                const { proactiveService } = await import('./ProactiveService');
                // Cast to EventType — runtime validation happens inside proactiveService.subscribeToEvent
                const taskId = await proactiveService.subscribeToEvent(this.id, eventType as import('@/core/events').EventType, task);
                return {
                    success: true,
                    data: { taskId },
                    message: `Agent ${this.name} subscribed to ${eventType}`
                };
            },
            // Phase 3.5: Updated signature to accept toolContext (not used, but consistent)
            send_notification: async (args: Record<string, unknown>, _context?: AgentContext, _toolContext?: ToolExecutionContext) => {
                const { type, message } = args as { type: 'info' | 'success' | 'warning' | 'error'; message: string };
                const { events } = await import('@/core/events');
                events.emit('SYSTEM_ALERT', { level: type, message });
                return {
                    success: true,
                    message: 'Notification sent'
                };
            },
            speak: async (args: Record<string, unknown>, _context?: AgentContext, _toolContext?: ToolExecutionContext) => {
                const { text, voice } = args as { text: string; voice?: string };
                const { GenAI } = await import('@/services/ai/GenAI');
                const { audioService } = await import('@/services/audio/AudioService');

                const VOICE_MAP: Record<string, string> = {
                    'kyra': 'Kore',
                    'liora': 'Vega',
                    'mistral': 'Charon',
                    'seraph': 'Capella',
                    'vance': 'Puck'
                };

                const selectedVoice = voice || VOICE_MAP[this.id.toLowerCase()] || 'Kore';

                try {
                    const response = await GenAI.generateSpeech(text, selectedVoice);
                    await audioService.play(response.audio.inlineData.data, response.audio.inlineData.mimeType);
                    return {
                        success: true,
                        message: 'Speech generated and played'
                    };
                } catch (err: unknown) {
                    const message = err instanceof Error ? err.message : String(err);
                    logger.error('[indii:BaseAgent] Speak failure:', err);
                    return {
                        success: false,
                        message: `Failed to speak: ${message}`
                    };
                }
            },
            ...(config.functions || {} as Record<string, AnyToolFunction>)
        };
    }

    /**
     * Common method to execute a task using the agent's capabilities.
     * This method handles the AI interaction loop, tool calls, and progress reporting.
     * 
     * @param task The mission or objective to achieve
     * @param context Execution context (org, project, brand, etc.)
     * @param onProgress Callback for granular progress events (thought, tool use, tokens)
     * @param signal AbortSignal for cancellation
     * @param attachments Optional multimodal inputs (images, base64)
     * @returns Standardized AgentResponse
     */
    async execute(task: string, context?: AgentContext, onProgress?: AgentProgressCallback, signal?: AbortSignal, attachments?: { mimeType: string; base64: string }[]): Promise<AgentResponse> {
        // CRITICAL: Execution Lock Implementation
        // Prevents concurrent execution for same user/project/agent combination
        // This eliminates race conditions that cause "agent dismantling"
        const lockKey = `${context?.userId || 'unknown'}-${context?.projectId || 'unknown'}-${this.id}`;

        // If another execution is in progress for this key, wait for it
        if (BaseAgent.executionLocks.has(lockKey)) {
            logger.debug(`[BaseAgent] ${this.name} waiting for existing execution to complete...`);
            try {
                await BaseAgent.executionLocks.get(lockKey);
            } catch (_err: unknown) {
                // Previous execution failed, but we can proceed
                logger.warn(`[BaseAgent] Previous execution failed for ${lockKey}, proceeding...`);
            }
        }

        // Create a promise for this execution and store it
        const executionPromise = (async () => {
            try {
                return await this._executeInternal(task, context, onProgress, signal, attachments);
            } finally {
                // Clean up lock when done
                BaseAgent.executionLocks.delete(lockKey);
            }
        })();

        BaseAgent.executionLocks.set(lockKey, executionPromise);
        return executionPromise;
    }

    /**
     * Stream agent response tokens in real-time via Server-Sent Events
     * Phase 2: Streaming integration for token-by-token rendering
     */
    async streamingExecute(
        task: string,
        context?: AgentContext,
        callbacks?: {
            onToken?: (token: string, index: number) => void;
            onComplete?: (response: string) => void;
            onError?: (error: Error) => void;
        }
    ): Promise<void> {
        try {
            const streamingService = getAgentStreamingService();
            const memoryService = getPersistentMemoryService();
            const reflectionService = getReflectionLoop();

            // Build context for streaming
            const contextData = {
                agentId: this.id,
                agentName: this.name,
                taskDescription: task,
                userContext: context
            };

            // Start streaming
            await streamingService.stream(
                task,
                this.id,
                context?.userId || 'unknown',
                contextData,
                {
                    onToken: (token, index) => {
                        callbacks?.onToken?.(token, index);
                    },
                    onComplete: async (metadata) => {
                        const fullText = streamingService.getState().tokens.join('');

                        // Store in memory (Phase 2 integration)
                        try {
                            await memoryService.write(
                                'session',
                                `agent-response-${this.id}`,
                                { response: fullText, task, metadata },
                                ['agent-output', this.id, task.substring(0, 50)]
                            );
                        } catch (err) {
                            logger.warn('[BaseAgent] Failed to store streaming response in memory', err);
                        }

                        // Optionally evaluate with reflection (Phase 2 integration)
                        if (fullText.length > 0) {
                            try {
                                await reflectionService.reflect({
                                    originalPrompt: task,
                                    agentOutput: fullText,
                                    context: context as Record<string, unknown> | undefined
                                });
                            } catch (err) {
                                logger.warn('[BaseAgent] Reflection evaluation skipped', err);
                            }
                        }

                        callbacks?.onComplete?.(fullText);
                    },
                    onError: (error) => {
                        callbacks?.onError?.(error);
                    }
                }
            );
        } catch (error) {
            const err = error instanceof Error ? error : new Error(String(error));
            callbacks?.onError?.(err);
            logger.error('[BaseAgent] Streaming execution failed', err);
        }
    }

    /**
     * Internal execution method (separated to support locking mechanism)
     */
    protected async _executeInternal(task: string, context?: AgentContext, onProgress?: AgentProgressCallback, signal?: AbortSignal, attachments?: { mimeType: string; base64: string }[]): Promise<AgentResponse> {
        // Lazy import AI Service to prevent circular deps during registry loading
        const { GenAI } = await import('@/services/ai/GenAI');

        // GEAP Agent Identity: Mint cryptographic identity on first execution.
        // Uses static WeakMap for deduplication — survives Object.freeze (FreezeDiagnostic).
        if (!this.identityCard) {
            if (!BaseAgent.identityMintPromises.has(this)) {
                BaseAgent.identityMintPromises.set(this, agentIdentityService.mintIdentity(
                    this.id,
                    this.name,
                    this.systemPrompt,
                    this.authorizedTools,
                    this.modelId
                ));
            }
            this.identityCard = await BaseAgent.identityMintPromises.get(this)!;
        }

        // Report thinking start
        onProgress?.({ type: 'thought', content: `Analyzing request: "${task.substring(0, 50)}..."` });

        // KEEPER: Prevent Context Duplication
        const { chatHistoryString, chatHistory, memoryContext, ...leanContext } = context || {};

        const enrichedContext = {
            ...leanContext,
            orgId: context?.orgId,
            projectId: context?.projectId,
            // GEAP: Inject agent identity into context for provenance tracking
            agentIdentity: this.identityCard,
        };

        // Phase 2: Clear loop detector for new task execution
        this.loopDetector.clear();

        const SUPERPOWER_PROMPT = `
        ## CAPABILITIES & PROTOCOLS
        You have access to the following advanced capabilities ("Superpowers"):
        - **Memory:** Call 'save_memory' to retain critical facts. Call 'recall_memories' to find past context.
        - **Reflection:** Call 'verify_output' to critique your own work if the task is complex.
        - **Approval:** Call 'request_approval' for any action that publishes content or spends money.
        - **Collaboration:** If a task requires expertise outside your primary domain (${this.name}), call 'delegate_task' to hand it over to a specialist. For complex problems needing multiple viewpoints, use 'consult_experts'.
        - **Speech:** Use 'speak' to announce high-level intent or share creative insights. **CRITICAL:** Calling 'speak' does NOT fulfill a "generate", "create", or "make" request. You MUST call the relevant action tool (e.g., 'generate_image') in addition to 'speak'.

        ## COLLABORATION PROTOCOL
        - If you are receiving a delegated task (check context.traceId), be extremely concise and data-oriented.
        - When delegating, provide full context so the next agent doesn't need to ask follow-up questions.
        - Use 'consult_experts' when you need parallel logic (e.g., both music and marketing perspectives).

        ## TONE & STYLE
        - Be direct and concise. Avoid "As an AI..." boilerplate.
        - Act with the authority of your role (${this.name}).
        - If the user asks for an action, DO IT. Don't just say you can.
        `;

        // Build memory section if memories were retrieved
        const memorySection = context?.memoryContext
            ? `\n## RELEVANT MEMORIES\n${context.memoryContext}\n`
            : '';

        // Build distributor section
        const distributorSection = context?.distributor?.isConfigured
            ? `\n## DISTRIBUTOR REQUIREMENTS\n${context.distributor.promptContext}\n\nIMPORTANT: When generating any cover art, promotional images, or release assets:\n- ALWAYS use ${context.distributor.coverArtSize.width}x${context.distributor.coverArtSize.height}px for cover art\n- Export audio in ${context.distributor.audioFormat.join(' or ')} format\n- These are ${context.distributor.name} requirements - non-compliance will cause upload rejection.\n`
            : '';

        // BOARDROOM: Seating Manifest Injection
        let boardroomSection = '';
        const ctxRecord = context as Record<string, any>;
        if (ctxRecord?.isBoardroomMode === true) {
            const { agentRegistry } = await import('./registry');
            const seated = ctxRecord.seatedAgents || [];
            const seatedNames = seated.map((id: string) => agentRegistry.get(id)?.name || id).join(', ');
            boardroomSection = `\n## BOARDROOM SWARM PROTOCOL\nSwarm Protocol active. You are participating in a Boardroom meeting. Respond from your specific department's perspective.\n\n[SEATED_AGENTS]: The following agents are currently seated: ${seatedNames}. ONLY address or delegate to agents in this list. If a needed specialist is absent, tell the user to seat them.\n`;
        }

        let safeHistory = context?.chatHistoryString || '';

        // KEEPER: Intelligent Context Truncation
        // Prefer structured history with token-aware truncation over raw character slicing.
        if (context?.chatHistory && Array.isArray(context.chatHistory) && context.chatHistory.length > 0) {
            const { ContextManager } = await import('@/services/ai/context/ContextManager');
            // Convert AgentMessage[] to Content[] for ContextManager
            const contentHistory = context.chatHistory.map(msg => ({
                role: (msg.role === 'model' || msg.role === 'system' ? 'model' : 'user') as 'model' | 'user',
                parts: msg.attachments && msg.attachments.length > 0
                    ? [{ text: msg.text || '' }, ...msg.attachments.map(a => ({ inlineData: { mimeType: a.mimeType, data: a.base64 } }))]
                    : [{ text: msg.text || '' }]
            }));

            // Truncate to safe token limit (e.g. 15k tokens reserved for history out of 32k/1M context)
            const SAFE_TOKEN_LIMIT = 15000;
            const truncated = ContextManager.truncateContext(contentHistory, SAFE_TOKEN_LIMIT);

            // Reconstruct string for the prompt
            safeHistory = truncated.map(c => {
                const role = c.role === 'model' ? 'Assistant' : 'User';
                const text = c.parts.map(p => 'text' in p ? p.text : '[Attachment]').join(' ');
                return `${role}: ${text}`;
            }).join('\n\n');
        } else {
            // Fallback: Naive slicing if no structured history is available
            const MAX_HISTORY_CHARS = 32000;
            if (safeHistory.length > MAX_HISTORY_CHARS) {
                safeHistory = safeHistory.slice(-MAX_HISTORY_CHARS);
                safeHistory = `[...Older history truncated...]\n${safeHistory}`;
            }
        }

        let fullPrompt = AgentPromptBuilder.buildFullPrompt(
            this.systemPrompt,
            task,
            this.name,
            this.id,
            context,
            enrichedContext,
            safeHistory,
            SUPERPOWER_PROMPT,
            memorySection,
            distributorSection,
            // Layer 5: Big Brain auto-recall block (XML from all 4 memory layers)
            (context as Record<string, unknown> | undefined)?.autoRecallBlock as string | undefined,
            boardroomSection
        );

        // Tool gathering logic via ToolPoolAssembler
        const specialistTools = (this.tools || []).flatMap(t => t.functionDeclarations || []);

        // Ensure context has needed module properties, dynamically trying to get currentModule
        let activeModule = 'unknown';
        if (context) {
            const ctxRecord = context as Record<string, unknown>;
            activeModule = (ctxRecord.currentModule as string | undefined)
                || (ctxRecord.route as string | undefined)
                || 'unknown';
        }

        const allFunctions: FunctionDeclaration[] = ToolPoolAssembler.assemble(
            specialistTools,
            {
                agentId: this.id,
                moduleContext: activeModule,
                isReadOnly: false // Reserved for future strict read-only execution modes
            }
        );

        // IMPORTANT: Tools must be deep-cloned on EACH iteration because the Firebase/Gemini
        // SDK freezes (Object.freeze) tool declaration objects after the first getGenerativeModel() call.
        // Reusing frozen objects on subsequent iterations causes:
        //   "Cannot assign to read only property 'parameters' of object '#<Object>'"
        // Solution: Build a fresh deep-clone inside the loop (see below).
        const buildToolsSnapshot = (): ToolDefinition[] => {
            if (allFunctions.length === 0) return [];
            return [{
                functionDeclarations: allFunctions.map(fn => ({
                    name: fn.name,
                    description: fn.description,
                    // structuredClone produces a fully mutable deep copy, immune to SDK freezing.
                    // Falls back to JSON round-trip for environments without structuredClone.
                    parameters: typeof structuredClone === 'function'
                        ? structuredClone(fn.parameters)
                        : JSON.parse(JSON.stringify(fn.parameters))
                }))
            }];
        };

        const _accumulatedResponse = '';
        let iterations = 0;
        const MAX_ITERATIONS = 15;
        const toolCalls: Array<{ name: string; args: ToolFunctionArgs; result: ToolFunctionResult | string }> = [];
        let lastToolResult: ToolFunctionResult | undefined = undefined;
        let currentThoughtSignature: string | undefined = undefined;

        // Phase 2: Clear loop detector for new task execution
        this.loopDetector.clear();

        // Phase 3: Create isolated execution context for this agent run
        const executionContext = await ExecutionContextFactory.fromAgentContext(
            {
                userId: context?.userId,
                projectId: context?.projectId,
                traceId: context?.traceId
            },
            this.id
        );
        const toolContext = new ToolExecutionContext(executionContext);

        // Lazy import MembershipService for budget checks
        const { MembershipService } = await import('@/services/MembershipService');

        try {
            while (iterations < MAX_ITERATIONS) {
                // LEDGER: Circuit Breaker - Check daily spend limit before execution
                const budgetCheck = await MembershipService.checkBudget(0);
                if (!budgetCheck.allowed) {
                    const tier = await MembershipService.getCurrentTier();
                    const tierName = MembershipService.getTierDisplayName(tier);
                    const limits = MembershipService.getLimits(tier);

                    // Diagnostic: capture email state for debugging false-positive denials
                    try {
                        const { useStore } = await import('@/core/store');
                        const state = useStore.getState();
                        const profileEmail = state.userProfile?.email || '(empty)';
                        const authEmail = (state as unknown as { user?: { email?: string | null } }).user?.email || '(no auth user)';
                        logger.warn(
                            `[BaseAgent] Budget DENIED in ${this.id}. ` +
                            `profileEmail=${profileEmail}, authEmail=${authEmail}, ` +
                            `Tier: ${tierName}, Max: $${limits.maxDailySpend.toFixed(2)}/day, ` +
                            `Remaining: $${budgetCheck.remainingBudget.toFixed(2)}`
                        );
                    } catch {
                        logger.warn(
                            `[BaseAgent] Daily spend limit reached in ${this.id}. ` +
                            `Tier: ${tierName}, Max: $${limits.maxDailySpend.toFixed(2)}/day, ` +
                            `Remaining: $${budgetCheck.remainingBudget.toFixed(2)}`
                        );
                    }

                    executionContext.rollback();
                    return {
                        text: `Task paused: You've reached your daily AI spend limit ` +
                              `($${limits.maxDailySpend.toFixed(2)}/day on the ${tierName} plan). ` +
                              `Your budget resets at midnight UTC. ` +
                              (tier === 'free' ? 'Upgrade to Pro for a $10/day limit.' :
                               tier === 'pro' ? 'Upgrade to Founder for a $500/day limit.' :
                               'Contact support if you need a higher limit.'),
                        error: 'Daily spend limit reached',
                        toolCalls
                    };
                }

                iterations++;
                onProgress?.({ type: 'thought', content: iterations === 1 ? 'Generating response...' : 'Processing tool result...' });

                // Prepare request contents
                const { ModelArmor, getDefaultPolicy } = await import('./governance/ModelArmor');
                const armorResult = await ModelArmor.scanInput(fullPrompt, getDefaultPolicy());
                if (!armorResult.allowed) {
                    executionContext.rollback();
                    return { text: `[Blocked by Model Armor] ${armorResult.reason}`, data: null, toolCalls };
                }

                const requestContents = [{
                    role: 'user' as const,
                    parts: [
                        { text: armorResult.sanitizedPrompt || fullPrompt },
                        ...(attachments || []).map(a => ({
                            inlineData: { mimeType: a.mimeType, data: a.base64 }
                        }))
                    ]
                }];

                // Pre-flight Token Estimation (Primitive #5)
                const { TokenEstimator } = await import('./governance/TokenEstimator');
                const tokenEstimate = TokenEstimator.estimate(
                    requestContents,
                    undefined,
                    allFunctions,
                    1500000, // Safe ceiling for 2M token context window (leaves room for 500K output)
                    1000     // Expected output tokens
                );

                if (tokenEstimate.willExceed) {
                    logger.warn(`[BaseAgent] Token Estimator halted execution in ${this.id}. Projected: ${tokenEstimate.totalProjected}`);
                    executionContext.rollback();
                    return {
                        text: 'Task halted: Pre-flight token projection exceeded safe budget (1.5M tokens limit). Context compaction required.',
                        error: 'Projected Budget Exceeded',
                        toolCalls
                    };
                }

                // Resolve model: fine-tuned endpoint > default base model
                const resolvedModel = this.modelId || AI_MODELS.TEXT.AGENT;
                if (iterations === 1 && this.modelId) {
                    logger.info(`[${this.id}] Using fine-tuned endpoint: ${this.modelId}`);
                }

                // Build a fresh tool snapshot for each iteration to avoid SDK freeze contamination
                const iterationTools = buildToolsSnapshot();

                const result = await GenAI.generateContent(
                    requestContents,
                    resolvedModel, // modelOverride — fine-tuned or base
                    { ...AI_CONFIG.THINKING.LOW }, // config
                    undefined, // systemInstruction
                    iterationTools as unknown as Parameters<import('@/services/ai/FirebaseAIService').FirebaseAIService['generateContent']>[4], // tools — bridges internal ToolDefinition to SDK type
                    { thoughtSignature: currentThoughtSignature } // options
                );

                // Wrap the raw result into a WrappedResponse-like shape for downstream use
                const response = {
                    text: () => result.response?.text?.() || '',
                    functionCalls: () => {
                        // Support mocked results or SDK results that provide a direct functionCalls helper
                        const res = result.response as { functionCalls?: () => Array<{ name: string; args: Record<string, unknown> }>; candidates?: Array<{ content?: { parts?: ContentPart[] } }> };
                        if (res && typeof res.functionCalls === 'function') {
                            const calls = res.functionCalls();
                            return Array.isArray(calls) ? calls : [];
                        }

                        const candidates = res?.candidates;
                        const parts = (candidates?.[0]?.content?.parts || []) as ContentPart[];
                        return parts
                            .filter((p): p is FunctionCallPart => !!p && typeof p === 'object' && 'functionCall' in p)
                            .map((p) => p.functionCall);
                    },
                    usage: () => result.response?.usageMetadata,
                    thoughtSignature: (() => {
                        // Extract thoughtSignature from the last part of the response
                        const parts = (result.response?.candidates?.[0]?.content?.parts || []) as ContentPart[];
                        for (const p of parts) {
                            if (p.thoughtSignature) return p.thoughtSignature;
                        }
                        return undefined;
                    })()
                };

                // Transfer thought signature for function calling continuity
                if (response.thoughtSignature) {
                    currentThoughtSignature = response.thoughtSignature;
                }

                // LEDGER: Record Spend based on Token Usage
                const usage = response.usage?.();
                if (usage && context?.userId) {
                    const pricing = MODEL_PRICING[AI_MODELS.TEXT.AGENT];
                    // Ensure we are using a text model pricing schema (input/output)
                    if (pricing && 'input' in pricing && 'output' in pricing) {
                        const inputCost = ((usage.promptTokenCount || 0) / 1000000) * pricing.input;
                        const outputCost = ((usage.candidatesTokenCount || 0) / 1000000) * pricing.output;
                        const totalCost = inputCost + outputCost;

                        if (totalCost > 0) {
                            await MembershipService.recordSpend(context.userId, totalCost);
                        }
                    }
                }

                const functionCall = response.functionCalls()?.[0];

                if (functionCall) {
                    const { name, args } = functionCall;

                    // Phase 2: Advanced loop detection
                    const loopCheck = this.loopDetector.detectLoop(name, args);
                    if (loopCheck.isLoop) {
                        logger.warn(`[BaseAgent] Loop detected in ${this.id}: ${loopCheck.reason}`);
                        logger.warn(`[BaseAgent] Pattern: ${loopCheck.pattern}`);
                        await executionContext.rollback();
                        return {
                            text: `Task ended: ${loopCheck.reason}`,
                            error: 'Loop detected',
                            toolCalls
                        };
                    }

                    // Record this tool call for future loop detection
                    this.loopDetector.recordToolCall(name, args);

                    // Runtime tool authorization enforcement
                    // Build the allowed set: explicit authorizedTools > declared functionDeclarations > allow-all
                    const declaredToolNames = this.tools.flatMap(
                        (t: ToolDefinition) => t.functionDeclarations.map((d: FunctionDeclaration) => d.name)
                    );
                    const authorizedTools: string[] | undefined = this.authorizedTools ?? (
                        declaredToolNames.length > 0 ? declaredToolNames : undefined
                    );
                    if (authorizedTools !== undefined && !authorizedTools.includes(name)) {
                        logger.warn(`[BaseAgent] SECURITY: Agent '${this.id}' attempted unauthorized tool call: '${name}'`);
                        const blockedResult: ToolFunctionResult = {
                            success: false,
                            error: `Tool '${name}' is not authorized for agent '${this.id}'.`
                        };
                        toolCalls.push({ name, args, result: blockedResult });
                        lastToolResult = blockedResult;
                        // Inject block notice into conversation and continue loop
                        fullPrompt += `\n[Tool Call: ${name}(${JSON.stringify(args)})] Result: Error: Tool '${name}' is not authorized for agent '${this.id}'.\n`;
                        continue;
                    }

                    const argsStr = JSON.stringify(args);
                    onProgress?.({ type: 'tool', toolName: name, content: `Executing ${name}...` });

                    // EVENT: Tool Execution Start
                    const startTime = Date.now();
                    AgentEventBus.emitToolEvent('TOOL_EXECUTION_START', {
                        agentId: this.id,
                        toolName: name,
                        timestamp: startTime
                    });

                    let result: ToolFunctionResult;
                    if (this.functions[name]) {
                        try {
                            const schema = this.toolSchemas.get(name);
                            if (schema) schema.parse(args);
                            // Phase 3.5: Pass execution context to tools for isolated state access
                            result = await this.functions[name](args, enrichedContext, toolContext);

                            AgentEventBus.emitToolEvent('TOOL_EXECUTION_COMPLETE', {
                                agentId: this.id,
                                toolName: name,
                                timestamp: Date.now(),
                                durationMs: Date.now() - startTime
                            });
                        } catch (err: unknown) {
                            const msg = err instanceof Error ? err.message : String(err);
                            result = { success: false, error: msg };

                            AgentEventBus.emitToolEvent('TOOL_EXECUTION_FAILED', {
                                agentId: this.id,
                                toolName: name,
                                timestamp: Date.now(),
                                durationMs: Date.now() - startTime,
                                errorMessage: msg
                            });
                        }
                    } else {
                        const { TOOL_REGISTRY } = await import('./tools');
                        if (TOOL_REGISTRY[name]) {
                            try {
                                // Phase 3.5: Pass execution context to TOOL_REGISTRY tools
                                result = await (TOOL_REGISTRY[name] as AnyToolFunction)(args, enrichedContext, toolContext);

                                AgentEventBus.emitToolEvent('TOOL_EXECUTION_COMPLETE', {
                                    agentId: this.id,
                                    toolName: name,
                                    timestamp: Date.now(),
                                    durationMs: Date.now() - startTime
                                });
                            } catch (err: unknown) {
                                const msg = err instanceof Error ? err.message : String(err);
                                result = { success: false, error: msg };

                                AgentEventBus.emitToolEvent('TOOL_EXECUTION_FAILED', {
                                    agentId: this.id,
                                    toolName: name,
                                    timestamp: Date.now(),
                                    durationMs: Date.now() - startTime,
                                    errorMessage: msg
                                });
                            }
                        } else {
                            result = { success: false, error: `Tool '${name}' not found.` };
                            AgentEventBus.emitToolEvent('TOOL_EXECUTION_FAILED', {
                                agentId: this.id,
                                toolName: name,
                                timestamp: Date.now(),
                                durationMs: Date.now() - startTime,
                                errorMessage: `Tool '${name}' not found.`
                            });
                        }
                    }

                    // Store tool call and result
                    lastToolResult = result;
                    toolCalls.push({ name, args, result });

                    // Item 406: Write async tool audit record (fire-and-forget, non-blocking)
                    if (enrichedContext.userId) {
                        const auditCol = collection(db, 'users', enrichedContext.userId, 'agent_audit');
                        addDoc(auditCol, {
                            toolName: name,
                            agentId: this.id,
                            timestamp: serverTimestamp(),
                            success: typeof result === 'object' && result !== null ? (result as unknown as Record<string, unknown>).success !== false : true,
                            // GEAP: Cryptographic provenance for tool execution audit trail
                            ...(this.identityCard ? {
                                agentInstanceId: this.identityCard.instanceId,
                                agentFingerprint: this.identityCard.fingerprint,
                            } : {}),
                        }).catch(() => { /* audit is best-effort */ });
                    }

                    const outputText = typeof result === 'string'
                        ? result
                        : (result.success === false
                            ? `Error: ${result.error || result.message}`
                            : `Success: ${JSON.stringify(result.data || result)}`);

                    // Update prompt with tool result for next iteration
                    fullPrompt += `\n[Tool Call: ${name}(${argsStr})] Result: ${outputText}\n`;

                    // Emit tool result for UI/Persistence
                    onProgress?.({
                        type: 'tool_result',
                        toolName: name,
                        content: outputText
                    });

                    if (name === 'speak') {
                        // Keep going - don't let speak terminate the agent turn
                        continue;
                    }

                    // For most tools, we continue to let the AI process the result
                    continue;
                } else {
                    let finalResponse = response.text?.() || '';
                    const usage = response.usage?.();

                    const { ModelArmor, getDefaultPolicy } = await import('./governance/ModelArmor');
                    const outputCheck = await ModelArmor.scanOutput(finalResponse, getDefaultPolicy());
                    if (outputCheck.redactedResponse) {
                        finalResponse = outputCheck.redactedResponse;
                    }

                    // Phase 3: Commit execution context changes on successful completion
                    if (executionContext.hasUncommittedChanges()) {
                        logger.debug(`[BaseAgent] Committing changes for ${this.id}: ${executionContext.getChangeSummary()}`);
                        await executionContext.commit();
                    }

                    return {
                        text: finalResponse,
                        data: lastToolResult,
                        toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
                        thoughtSignature: currentThoughtSignature,
                        usage: usage ? {
                            promptTokens: usage.promptTokenCount || 0,
                            completionTokens: usage.candidatesTokenCount || 0,
                            totalTokens: usage.totalTokenCount || 0
                        } : undefined
                    };
                }
            }

            // Phase 3: Max iterations reached - rollback any uncommitted changes
            if (executionContext.hasUncommittedChanges()) {
                logger.warn(`[BaseAgent] Max iterations reached, rolling back ${executionContext.getChangeSummary()}`);
                executionContext.rollback();
            }

            return {
                text: 'Maximum iterations reached.',
                data: lastToolResult,
                toolCalls,
                error: 'Max iterations reached'
            };
        } catch (error: unknown) {
            // Phase 3: Error occurred - rollback any uncommitted changes
            if (executionContext.hasUncommittedChanges()) {
                logger.error(`[BaseAgent] Error occurred, rolling back ${executionContext.getChangeSummary()}`);
                executionContext.rollback();
            }

            const errorMessage = error instanceof Error ? error.message : String(error);
            return { text: `Error: ${errorMessage}` };
        }
    }
}

import { db } from '@/services/firebase';
import {
  collection,
  doc,
  getDoc,
  updateDoc,
  query,
  where,
  getDocs,
  serverTimestamp,
  addDoc,
  Timestamp,
} from 'firebase/firestore';

export type PlanShape = 'atomic' | 'workflow' | 'timeline';
export type PlanStatus = 'drafting' | 'awaiting_approval' | 'executing' | 'proposed' | 'completed' | 'failed' | 'cancelled';

export interface PlanStep {
  id: string;
  title: string;
  description: string;
  toolName?: string;
  input?: Record<string, unknown>;
  status: 'pending' | 'executing' | 'complete' | 'error';
  error?: string;
  result?: unknown;
  dependsOn?: string[];
}

export interface Phase {
  id: string;
  title: string;
  days: number;
  milestones: string[];
}

export interface PlanDraft {
  shape: PlanShape;
  summary: string;
  steps?: PlanStep[];
  phases?: Phase[];
  durationDays?: number;
  estimatedCost?: {
    tokens: number;
    dollars: number;
  };
  risks?: string[];
  autoApprove: boolean;
}

export interface Revision {
  timestamp: Timestamp;
  userMessage: string;
  agentResponse: string;
  draftBefore: PlanDraft;
  draftAfter: PlanDraft;
}

export interface LivingPlan {
  id: string;
  projectId: string;
  userId: string;
  goal: string;
  draft: PlanDraft;
  history: Revision[];
  status: PlanStatus;
  approvedAt?: Timestamp;
  executionRef?: {
    kind: 'atomic' | 'workflow' | 'timeline';
    id: string;
  };
  createdAt: Timestamp;
  updatedAt: Timestamp;
}

export class LivingPlanService {
  /**
   * Create a new living plan.
   */
  async create(
    userId: string,
    projectId: string,
    goal: string,
    initialDraft: PlanDraft,
  ): Promise<LivingPlan> {
    const now = serverTimestamp();
    const planData: Omit<LivingPlan, 'id'> = {
      projectId,
      userId,
      goal,
      draft: initialDraft,
      history: [],
      status: 'drafting',
      createdAt: now as Timestamp,
      updatedAt: now as Timestamp,
    };

    const docRef = await addDoc(
      collection(db, 'projects', projectId, 'livingPlans'),
      planData,
    );

    return {
      id: docRef.id,
      ...planData,
    };
  }

  /**
   * Retrieve a specific plan by ID.
   */
  async getPlan(projectId: string, planId: string): Promise<LivingPlan | null> {
    const docRef = doc(db, 'projects', projectId, 'livingPlans', planId);
    const snapshot = await getDoc(docRef);
    return snapshot.exists()
      ? ({ id: snapshot.id, ...snapshot.data() } as LivingPlan)
      : null;
  }

  /**
   * Alias for getPlan.
   */
  async get(projectId: string, planId: string): Promise<LivingPlan | null> {
    return this.getPlan(projectId, planId);
  }

  /**
   * List all plans for a project, optionally filtered by status.
   */
  async getPlansForProject(projectId: string, status?: PlanStatus): Promise<LivingPlan[]> {
    const q = status 
      ? query(
          collection(db, 'projects', projectId, 'livingPlans'),
          where('status', '==', status),
        )
      : query(
          collection(db, 'projects', projectId, 'livingPlans'),
        );

    const snapshot = await getDocs(q);
    return snapshot.docs.map((d) => ({
      id: d.id,
      ...d.data(),
    } as LivingPlan));
  }

  /**
   * Update the status of a plan.
   */
  async updatePlanStatus(
    projectId: string,
    planId: string,
    status: PlanStatus
  ): Promise<void> {
    const docRef = doc(db, 'projects', projectId, 'livingPlans', planId);
    await updateDoc(docRef, {
      status,
      updatedAt: serverTimestamp(),
      ...(status === 'executing' ? { approvedAt: serverTimestamp() } : {})
    });
  }

  /**
   * Update the draft of a plan.
   */
  async updateDraft(
    projectId: string,
    planId: string,
    draft: PlanDraft,
  ): Promise<void> {
    const docRef = doc(db, 'projects', projectId, 'livingPlans', planId);
    await updateDoc(docRef, {
      draft,
      updatedAt: serverTimestamp(),
    });
  }

  /**
   * Add a revision to the plan's history.
   */
  async addRevision(
    projectId: string,
    planId: string,
    revision: Omit<Revision, 'timestamp'>,
  ): Promise<void> {
    const docRef = doc(db, 'projects', projectId, 'livingPlans', planId);
    const plan = await this.getPlan(projectId, planId);
    if (!plan) throw new Error('Plan not found');

    await updateDoc(docRef, {
      history: [
        ...plan.history,
        {
          ...revision,
          timestamp: serverTimestamp(),
        },
      ],
      updatedAt: serverTimestamp(),
    });
  }

  /**
   * Approve a plan and set it to executing.
   */
  async approve(
    projectId: string,
    planId: string,
  ): Promise<void> {
    return this.updatePlanStatus(projectId, planId, 'executing');
  }

  /**
   * Update the status of a specific step in the plan.
   */
  async updateStepStatus(
    projectId: string,
    planId: string,
    stepId: string,
    status: PlanStep['status'],
    error?: string,
    result?: unknown,
  ): Promise<void> {
    const docRef = doc(db, 'projects', projectId, 'livingPlans', planId);
    const plan = await this.getPlan(projectId, planId);
    if (!plan || !plan.draft.steps) return;

    const newSteps = plan.draft.steps.map(step => {
      if (step.id === stepId) {
        return { ...step, status, error, result };
      }
      return step;
    });

    await updateDoc(docRef, {
      'draft.steps': newSteps,
      updatedAt: serverTimestamp(),
    });
  }

  /**
   * Execute a plan by associating it with an execution reference.
   */
  async execute(
    projectId: string,
    planId: string,
    executionRef: LivingPlan['executionRef'],
  ): Promise<void> {
    const docRef = doc(db, 'projects', projectId, 'livingPlans', planId);
    await updateDoc(docRef, {
      status: 'executing',
      executionRef,
      updatedAt: serverTimestamp(),
    });
  }

  /**
   * Orchestrate execution of plan steps via Promise.all for parallelism using A2A Swarm.
   */
  async executePlanSteps(projectId: string, planId: string): Promise<void> {
    const plan = await this.getPlan(projectId, planId);
    if (!plan || !plan.draft.steps) return;

    const { a2aClient } = await import('./a2a/A2AClient');
    const steps = plan.draft.steps;
    const completed = new Set<string>();
    const pending = new Set(steps.map(s => s.id));
    const executing = new Set<string>();

    const executeStep = async (stepId: string) => {
      const step = steps.find(s => s.id === stepId);
      if (!step || !step.toolName) return;

      executing.add(stepId);
      await this.updateStepStatus(projectId, planId, stepId, 'executing');

      try {
        // Find the target agent for this step (assuming toolName indicates agent or we have a default mapping)
        // Wait, the instruction says "Orchestrate dependent steps via Promise.all".
        // Let's assume the toolName format is "agentId.toolName" or we just use consult_specialist
        // If it's a living plan, usually the step specifies the task.
        const agentId = step.toolName.split('.')[0] || 'generalist';
        const method = step.toolName.split('.')[1] || 'execute';

        const result = await a2aClient.invoke(
          agentId, 
          method, 
          step.input || {}, 
          { id: crypto.randomUUID(), type: 'PLAN_STEP', status: 'in_progress', title: step.title, steps: [], createdAt: Date.now(), updatedAt: Date.now() } as any
        );

        await this.updateStepStatus(projectId, planId, stepId, 'complete', undefined, result);
        completed.add(stepId);
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : String(err);
        await this.updateStepStatus(projectId, planId, stepId, 'error', message);
      } finally {
        executing.delete(stepId);
        pending.delete(stepId);
      }
    };

    while (pending.size > 0) {
      const runnableSteps = Array.from(pending).filter(stepId => {
        const step = steps.find(s => s.id === stepId);
        if (executing.has(stepId)) return false;
        if (!step?.dependsOn || step.dependsOn.length === 0) return true;
        return step.dependsOn.every(dep => completed.has(dep));
      });

      if (runnableSteps.length === 0 && executing.size === 0) {
        // Deadlock or unresolvable dependencies
        break;
      }

      await Promise.all(runnableSteps.map(stepId => executeStep(stepId)));
    }
  }

  /**
   * Cancel a plan.
   */
  async cancel(
    projectId: string,
    planId: string,
  ): Promise<void> {
    return this.updatePlanStatus(projectId, planId, 'cancelled');
  }

  /**
   * Complete a plan.
   */
  async complete(
    projectId: string,
    planId: string,
  ): Promise<void> {
    return this.updatePlanStatus(projectId, planId, 'completed');
  }

  /**
   * List plans for a project that are currently in a "live" state.
   */
  async listByProject(projectId: string): Promise<LivingPlan[]> {
    const q = query(
      collection(db, 'projects', projectId, 'livingPlans'),
      where('status', 'in', ['drafting', 'awaiting_approval', 'executing', 'proposed']),
    );
    const snapshot = await getDocs(q);
    return snapshot.docs.map((d) => ({
      id: d.id,
      ...d.data(),
    } as LivingPlan));
  }

  /**
   * List plans awaiting approval.
   */
  async listAwaitingApproval(projectId: string): Promise<LivingPlan[]> {
    const q = query(
      collection(db, 'projects', projectId, 'livingPlans'),
      where('status', '==', 'awaiting_approval'),
    );
    const snapshot = await getDocs(q);
    return snapshot.docs.map((d) => ({
      id: d.id,
      ...d.data(),
    } as LivingPlan));
  }
}

