import { logger } from '@/utils/logger';
import { db } from '../../firebase';
import {
    collection,
    getDocs,
    query,
    where,
    orderBy,
    limit,
    deleteDoc,
    writeBatch,
    doc as firestoreDoc,
    getCountFromServer,
} from 'firebase/firestore';
import { FirebaseAIService as AIService } from '../../ai/FirebaseAIService';
import type { GenerationConfig } from '@/shared/types/ai.dto';
import { MemoryConsolidator } from './MemoryConsolidator';
import { MemoryIngestionPipeline, memoryIngestionPipeline } from './MemoryIngestionPipeline';
import { AgentEventBus } from '../governance/AgentEventBus';
import type {
    AlwaysOnMemory,
    AlwaysOnMemoryConfig,
    AlwaysOnEngineStatus,
    ConsolidationInsight,
    MemoryTier,
    AlwaysOnMemoryCategory,
} from '@/types/AlwaysOnMemory';
import {
    DEFAULT_ENGINE_CONFIG,
    DEFAULT_CONSOLIDATION_CONFIG,
} from '@/types/AlwaysOnMemory';

// ============================================================================
// ENGINE
// ============================================================================

/**
 * AlwaysOnMemoryEngine — The central orchestrator for the Always-On Memory Agent.
 *
 * Mirrors Google's hub-and-spoke ADK pattern in TypeScript:
 * - IngestAgent → MemoryIngestionPipeline (text, files, sessions)
 * - ConsolidateAgent → MemoryConsolidator (timer-based background consolidation)
 * - QueryAgent → Built-in query synthesis with citation references
 *
 * Key improvements over Google's reference:
 * 1. Tiered memory (working → shortTerm → longTerm → archived)
 * 2. Importance decay and reinforcement
 * 3. Entity graph for cross-memory connections
 * 4. Domain-aware categories for creative workflows
 * 5. Firestore persistence with cloud sync
 * 6. Integrated with indii agent architecture
 *
 * @example
 * ```typescript
 * const engine = AlwaysOnMemoryEngine.getInstance();
 * await engine.start('user-123');
 *
 * // Ingest text
 * await engine.ingest('User prefers dark blue album art with minimal typography');
 *
 * // Query
 * const answer = await engine.query('What are the visual preferences?');
 *
 * // Manual consolidation
 * await engine.consolidateNow();
 *
 * // Stop
 * engine.stop();
 * ```
 */
export class AlwaysOnMemoryEngine {
    private static instance: AlwaysOnMemoryEngine | null = null;

    private userId: string = '';
    private config: AlwaysOnMemoryConfig | null = null;
    private consolidationTimer: ReturnType<typeof setInterval> | null = null;
    private isRunning = false;
    private isConsolidating = false;
    private isIngesting = false;
    private startedAt: Date | null = null;
    private lastConsolidatedAt: Date | null = null;
    private lastIngestedAt: Date | null = null;
    private pipeline: MemoryIngestionPipeline;

    private constructor() {
        this.pipeline = memoryIngestionPipeline;
    }

    /**
     * Get the singleton instance of the engine.
     */
    public static getInstance(): AlwaysOnMemoryEngine {
        if (!AlwaysOnMemoryEngine.instance) {
            AlwaysOnMemoryEngine.instance = new AlwaysOnMemoryEngine();
        }
        return AlwaysOnMemoryEngine.instance;
    }

    // ========================================================================
    // LIFECYCLE
    // ========================================================================

    /**
     * Start the Always-On Memory Engine for a specific user.
     * Begins the background consolidation timer.
     *
     * @param userId - The user to operate for
     * @param config - Optional configuration overrides
     */
    public async start(
        userId: string,
        config?: Partial<Omit<AlwaysOnMemoryConfig, 'userId'>>
    ): Promise<void> {
        if (this.isRunning && this.userId === userId) {
            logger.info('[AlwaysOnMemoryEngine] Already running for this user');
            return;
        }

        // Stop any existing engine
        if (this.isRunning) {
            this.stop();
        }

        this.userId = userId;
        this.config = {
            userId,
            ...DEFAULT_ENGINE_CONFIG,
            ...config,
        };
        this.isRunning = true;
        this.startedAt = new Date();

        // Start the consolidation timer
        const intervalMs = this.config.consolidation.intervalMs;
        this.consolidationTimer = setInterval(async () => {
            await this.runConsolidationCycle();
        }, intervalMs);

        logger.info(
            `[AlwaysOnMemoryEngine] 🧠 Started for user ${userId}\n` +
            `   Consolidation: every ${intervalMs / 60000}m\n` +
            `   Inbox watcher: ${this.config.inboxWatcherEnabled ? 'enabled' : 'disabled'}`
        );
    }

    /**
     * Stop the engine and clear all timers.
     */
    public stop(): void {
        if (this.consolidationTimer) {
            clearInterval(this.consolidationTimer);
            this.consolidationTimer = null;
        }
        this.isRunning = false;
        logger.info('[AlwaysOnMemoryEngine] 🧠 Engine stopped');
    }

    /**
     * Check if the engine is currently running.
     */
    public get running(): boolean {
        return this.isRunning;
    }

    // ========================================================================
    // INGEST (IngestAgent equivalent)
    // ========================================================================

    /**
     * Ingest text into the memory system.
     *
     * @param text - The text to remember
     * @param source - Where this came from (default: 'user_input')
     * @param category - Optional category override
     * @returns Summary of what was stored
     */
    public async ingest(
        text: string,
        source: string = 'user_input',
        category?: AlwaysOnMemoryCategory
    ): Promise<string> {
        if (!this.userId) throw new Error('Engine not started. Call start() first.');

        this.isIngesting = true;
        try {
            const result = await this.pipeline.ingestText(this.userId, { text, source, category });
            this.lastIngestedAt = new Date();

            if (result.skipped) {
                return `Skipped: ${result.skipReason}`;
            }
            return result.success
                ? `📥 Stored: ${result.summary}`
                : `❌ Failed: ${result.error}`;
        } finally {
            this.isIngesting = false;
        }
    }

    /**
     * Ingest a file into the memory system.
     *
     * @param fileBytes - Raw file content
     * @param fileName - Original filename
     * @param mimeType - MIME type of the file
     * @returns Summary of what was stored
     */
    public async ingestFile(
        fileBytes: Uint8Array,
        fileName: string,
        mimeType: string
    ): Promise<string> {
        if (!this.userId) throw new Error('Engine not started. Call start() first.');

        this.isIngesting = true;
        try {
            const result = await this.pipeline.ingestFile(this.userId, {
                fileBytes,
                fileName,
                mimeType,
                sizeBytes: fileBytes.length,
            });
            this.lastIngestedAt = new Date();

            return result.success
                ? `🔮 Ingested ${fileName}: ${result.summary}`
                : `❌ Failed: ${result.error}`;
        } finally {
            this.isIngesting = false;
        }
    }

    /**
     * Ingest key memories from an agent conversation session.
     *
     * @param messages - Conversation messages
     * @param sessionId - Session ID for tracking
     * @returns Number of memories extracted
     */
    public async ingestFromSession(
        messages: Array<{ role: string; text: string }>,
        sessionId: string
    ): Promise<number> {
        if (!this.userId) throw new Error('Engine not started. Call start() first.');

        this.isIngesting = true;
        try {
            const results = await this.pipeline.ingestFromSession(this.userId, messages, sessionId);
            this.lastIngestedAt = new Date();
            return results.filter(r => r.success && !r.skipped).length;
        } finally {
            this.isIngesting = false;
        }
    }

    // ========================================================================
    // CONSOLIDATE (ConsolidateAgent equivalent)
    // ========================================================================

    /**
     * Trigger an immediate consolidation cycle.
     * Normally runs on a timer, but can be called manually.
     */
    public async consolidateNow(): Promise<string> {
        return this.runConsolidationCycle();
    }

    /**
     * Internal consolidation cycle runner.
     */
    private async runConsolidationCycle(): Promise<string> {
        if (!this.userId) return 'Engine not started';
        if (this.isConsolidating) return 'Consolidation already in progress';

        this.isConsolidating = true;
        try {
            const config = this.config?.consolidation || DEFAULT_CONSOLIDATION_CONFIG;
            const result = await MemoryConsolidator.runConsolidationCycle(this.userId, config);
            this.lastConsolidatedAt = new Date();

            return (
                `🔄 Consolidation complete: ` +
                `${result.memoriesProcessed} processed, ` +
                `${result.insightsGenerated} insights, ` +
                `${result.connectionsFound} connections`
            );
        } catch (error: unknown) {
            logger.error('[AlwaysOnMemoryEngine] Consolidation failed:', error);
            return `❌ Consolidation failed: ${error instanceof Error ? error.message : String(error)}`;
        } finally {
            this.isConsolidating = false;
        }
    }

    // ========================================================================
    // QUERY (QueryAgent equivalent)
    // ========================================================================

    /**
     * Query the memory system with a natural language question.
     * Reads all memories and consolidation insights, then synthesizes an answer
     * with source citations.
     *
     * @param question - The question to answer
     * @returns Synthesized answer with [Memory X] citations
     */
    public async query(question: string): Promise<string> {
        if (!this.userId) throw new Error('Engine not started. Call start() first.');

        try {
            // Step 1: Fetch all memories (most recent first)
            const memories = await this.getAllMemories(50);

            // Step 2: Fetch consolidation insights
            const insights = await this.getInsights(10);

            // Step 3: If no memories exist, say so honestly
            if (memories.length === 0) {
                return 'I don\'t have any memories stored yet. Try ingesting some information first.';
            }

            // Step 4: Build a context block for the LLM
            const memoryBlock = memories.map((m, i) =>
                `[Memory ${m.id}] (${m.category}, importance: ${m.importance.toFixed(2)}, ` +
                `tier: ${m.tier}):\n  ${m.summary || m.content}`
            ).join('\n\n');

            const insightBlock = insights.length > 0
                ? '\n\nCONSOLIDATION INSIGHTS:\n' + insights.map((ins, i) =>
                    `[Insight ${i + 1}]: ${ins.insight} (from memories: ${ins.sourceMemoryIds.join(', ')})`
                ).join('\n')
                : '';

            // Step 5: Synthesize answer using Gemini Pro for deep reasoning
            const prompt = `You are a Memory Query Agent for a creative music/visual production platform called indii.
Answer the following question based ONLY on the stored memories and insights below.
Reference memory IDs in your answer like [Memory abc123].
If no relevant memories exist for the question, say so honestly.
Be thorough but concise. Always cite your sources.

MEMORIES:
${memoryBlock}
${insightBlock}

QUESTION: ${question}

ANSWER:`;

            const answer = await AIService.getInstance().generateText(
                prompt,
                0,
                { temperature: 0.3 } as Record<string, unknown>
            );

            // Step 6: Reinforce accessed memories (boost importance of relevant ones)
            this.reinforceAccessedMemories(memories, answer).catch(err => {
                logger.error('[AlwaysOnMemoryEngine] Reinforcement failed:', err);
            });

            return answer;
        } catch (error: unknown) {
            logger.error('[AlwaysOnMemoryEngine] Query failed:', error);
            return `❌ Query failed: ${error instanceof Error ? error.message : String(error)}`;
        }
    }

    // ========================================================================
    // STATUS & MANAGEMENT
    // ========================================================================

    /**
     * INDII GROWTH PROTOCOL
     * Monitor Meta Pixel event history. Once 2,000+ conversion events are logged,
     * instruct the Marketing Agent to transition to Saver Lookalike Audiences.
     */
    public async evaluateMarketingLookalikeThreshold(totalPixelEvents: number): Promise<void> {
        if (!this.userId) return;

        if (totalPixelEvents >= 2000) {
            logger.info(`[AlwaysOnMemoryEngine] 2,000+ conversion events detected (${totalPixelEvents}). Triggering Saver Lookalike transition.`);

            // Inject a high-priority system memory insight
            await this.ingest(
                '2,000+ conversion events logged. Shift all target audiences from interest-based targeting to Saver Lookalike Audiences.',
                'system_trigger',
                'marketing' as AlwaysOnMemoryCategory
            );

            // Trigger the Marketing Agent via Event Bus
            AgentEventBus.emitSystemEvent('MARKETING_AUTOMATION_TRIGGERED', 'Lookalike Audiences threshold reached. Shifting from interest-based to Saver Lookalike Audiences.');
        }
    }

    /**
     * Get the current status of the engine.
     */
    public async getStatus(): Promise<AlwaysOnEngineStatus> {
        const status: AlwaysOnEngineStatus = {
            isRunning: this.isRunning,
            isConsolidating: this.isConsolidating,
            isIngesting: this.isIngesting,
            totalMemories: 0,
            unconsolidatedCount: 0,
            totalInsights: 0,
            memoriesByTier: { working: 0, shortTerm: 0, longTerm: 0, archived: 0 },
            memoriesByCategory: {},
            startedAt: this.startedAt || undefined,
            lastConsolidatedAt: this.lastConsolidatedAt || undefined,
            lastIngestedAt: this.lastIngestedAt || undefined,
        };

        if (!this.userId) return status;

        try {
            // Get total count
            const memoryRef = collection(db, 'users', this.userId, 'alwaysOnMemories');
            const totalSnap = await getCountFromServer(query(memoryRef, where('isActive', '==', true)));
            status.totalMemories = totalSnap.data().count;

            // Get unconsolidated count
            const unconsolidatedSnap = await getCountFromServer(
                query(memoryRef, where('consolidated', '==', false), where('isActive', '==', true))
            );
            status.unconsolidatedCount = unconsolidatedSnap.data().count;

            // Get insights count
            const insightRef = collection(db, 'users', this.userId, 'consolidationInsights');
            const insightSnap = await getCountFromServer(query(insightRef));
            status.totalInsights = insightSnap.data().count;

            // Get tier breakdown (fetch a sample to estimate)
            const tierSample = await getDocs(
                query(memoryRef, where('isActive', '==', true), limit(200))
            );
            for (const doc of tierSample.docs) {
                const data = doc.data();
                const tier = (data.tier || 'working') as MemoryTier;
                status.memoriesByTier[tier] = (status.memoriesByTier[tier] || 0) + 1;

                const category = data.category as AlwaysOnMemoryCategory;
                if (category) {
                    status.memoriesByCategory[category] = (status.memoriesByCategory[category] || 0) + 1;
                }
            }
        } catch (error: unknown) {
            logger.error('[AlwaysOnMemoryEngine] Status fetch failed:', error);
        }

        return status;
    }

    /**
     * Get all memories for the current user.
     */
    public async getAllMemories(maxCount: number = 50): Promise<AlwaysOnMemory[]> {
        if (!this.userId) return [];

        const memoryRef = collection(db, 'users', this.userId, 'alwaysOnMemories');
        const q = query(
            memoryRef,
            where('isActive', '==', true),
            orderBy('createdAt', 'desc'),
            limit(maxCount)
        );

        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data(),
        })) as AlwaysOnMemory[];
    }

    /**
     * Get consolidation insights for the current user.
     */
    public async getInsights(maxCount: number = 10): Promise<ConsolidationInsight[]> {
        if (!this.userId) return [];

        const insightRef = collection(db, 'users', this.userId, 'consolidationInsights');
        const q = query(
            insightRef,
            orderBy('createdAt', 'desc'),
            limit(maxCount)
        );

        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data(),
        })) as ConsolidationInsight[];
    }

    /**
     * Delete a specific memory.
     */
    public async deleteMemory(memoryId: string): Promise<void> {
        if (!this.userId) throw new Error('Engine not started');

        const ref = firestoreDoc(db, 'users', this.userId, 'alwaysOnMemories', memoryId);
        await deleteDoc(ref);
        logger.info(`[AlwaysOnMemoryEngine] 🗑️ Deleted memory ${memoryId}`);
    }

    /**
     * Clear all memories and insights for the current user. Full reset.
     */
    public async clearAll(): Promise<{ memoriesDeleted: number; insightsDeleted: number }> {
        if (!this.userId) throw new Error('Engine not started');

        let memoriesDeleted = 0;
        let insightsDeleted = 0;

        // Delete all memories
        const memoryRef = collection(db, 'users', this.userId, 'alwaysOnMemories');
        const memorySnapshot = await getDocs(query(memoryRef, limit(500)));
        const memBatch = writeBatch(db);
        for (const doc of memorySnapshot.docs) {
            memBatch.delete(doc.ref);
            memoriesDeleted++;
        }
        if (memoriesDeleted > 0) await memBatch.commit();

        // Delete all insights
        const insightRef = collection(db, 'users', this.userId, 'consolidationInsights');
        const insightSnapshot = await getDocs(query(insightRef, limit(500)));
        const insBatch = writeBatch(db);
        for (const doc of insightSnapshot.docs) {
            insBatch.delete(doc.ref);
            insightsDeleted++;
        }
        if (insightsDeleted > 0) await insBatch.commit();

        // Delete all ingestion events
        const eventRef = collection(db, 'users', this.userId, 'ingestionEvents');
        const eventSnapshot = await getDocs(query(eventRef, limit(500)));
        const evtBatch = writeBatch(db);
        for (const doc of eventSnapshot.docs) {
            evtBatch.delete(doc.ref);
        }
        if (!eventSnapshot.empty) await evtBatch.commit();

        logger.info(
            `[AlwaysOnMemoryEngine] 🗑️ Full reset: ${memoriesDeleted} memories, ${insightsDeleted} insights deleted`
        );

        return { memoriesDeleted, insightsDeleted };
    }

    // ========================================================================
    // PRIVATE - UTILITY
    // ========================================================================

    /**
     * Reinforce memories that were referenced in a query answer.
     * Memories that prove useful get an importance boost.
     */
    private async reinforceAccessedMemories(
        memories: AlwaysOnMemory[],
        answer: string
    ): Promise<void> {
        // Find memory IDs referenced in the answer
        for (const memory of memories) {
            if (answer.includes(memory.id) || answer.includes(`Memory ${memory.id}`)) {
                await MemoryConsolidator.reinforceMemory(this.userId, memory.id, 0.03);
            }
        }
    }
}

// Export singleton accessor
export const alwaysOnMemoryEngine = AlwaysOnMemoryEngine.getInstance();

import { logger } from '@/utils/logger';
import { db } from '../../firebase';
import {
    collection,
    addDoc,
    getDocs,
    query,
    where,
    orderBy,
    limit,
    updateDoc,
    doc as firestoreDoc,
    writeBatch,
    Timestamp,
} from 'firebase/firestore';
import { MemorySummarizer } from './MemorySummarizer';
import type {
    AlwaysOnMemory,
    ConsolidationInsight,
    ConsolidationConfig,
    MemoryConnection,
    MemoryTier,
    MemoryTierConfig,
} from '@/types/AlwaysOnMemory';
import {
    DEFAULT_CONSOLIDATION_CONFIG,
    DEFAULT_TIER_CONFIG,
} from '@/types/AlwaysOnMemory';

// ============================================================================
// HELPERS
// ============================================================================

/**
 * Simple cosine similarity between two vectors.
 */
function cosineSimilarity(a: number[], b: number[]): number {
    if (a.length !== b.length || a.length === 0) return 0;
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;
    for (let i = 0; i < a.length; i++) {
        dotProduct += a[i]! * b[i]!;
        normA += a[i]! * a[i]!;
        normB += b[i]! * b[i]!;
    }
    const denominator = Math.sqrt(normA) * Math.sqrt(normB);
    return denominator === 0 ? 0 : dotProduct / denominator;
}

// ============================================================================
// CONSOLIDATION ENGINE
// ============================================================================

/**
 * MemoryConsolidator — Upgraded consolidation engine for the Always-On Memory Agent.
 *
 * Like the human brain during sleep, this engine:
 * 1. Reviews unconsolidated memories
 * 2. Finds connections and patterns across them
 * 3. Generates cross-cutting insights
 * 4. Promotes high-value memories through tiers
 * 5. Applies importance decay to aging memories
 * 6. Archives low-value, stale memories
 *
 * Backward compatible with the original `consolidate()` method signature
 * from the legacy MemoryConsolidator.
 */
export class MemoryConsolidator {
    // ========================================================================
    // LEGACY API (backward compatible)
    // ========================================================================

    /**
     * Merges multiple related memories into a single consolidated entry.
     * This is the original API, preserved for backward compatibility.
     *
     * @deprecated Use `runConsolidationCycle()` for the full Always-On pipeline.
     */
    public static async consolidate(
        userId: string,
        memories: Array<{ id: string; content: string; type?: string }>,
        targetType: 'fact' | 'rule' | 'summary' = 'summary'
    ): Promise<string | null> {
        if (memories.length < 2) return null;

        try {
            const summaryContent = await MemorySummarizer.summarizeMemories(memories);

            // Create the new consolidated memory
            const memoryRef = collection(db, 'users', userId, 'alwaysOnMemories');
            const newDoc = await addDoc(memoryRef, {
                content: summaryContent,
                rawText: memories.map(m => m.content).join('\n\n'),
                summary: summaryContent,
                category: targetType === 'rule' ? 'fact' : 'context',
                tier: 'longTerm',
                entities: [],
                topics: [],
                importance: 0.7,
                source: 'consolidation',
                createdAt: Timestamp.now(),
                updatedAt: Timestamp.now(),
                lastAccessedAt: Timestamp.now(),
                accessCount: 0,
                isActive: true,
                consolidated: true,
                connections: [],
                relatedMemoryIds: memories.map(m => m.id),
                tags: [],
            });

            // Mark the old memories as consolidated
            const batch = writeBatch(db);
            const nowTimestamp = Timestamp.now();
            for (const m of memories) {
                const ref = firestoreDoc(db, 'users', userId, 'alwaysOnMemories', m.id);
                batch.update(ref, { consolidated: true, updatedAt: nowTimestamp });
            }
            await batch.commit();

            return newDoc.id;
        } catch (error: unknown) {
            logger.error('[MemoryConsolidator] Consolidation failed:', error);
            return null;
        }
    }

    // ========================================================================
    // ALWAYS-ON CONSOLIDATION CYCLE
    // ========================================================================

    /**
     * Run a full consolidation cycle. This is called periodically by the engine.
     *
     * Steps:
     * 1. Fetch unconsolidated memories
     * 2. Group related memories using embedding similarity
     * 3. Generate insights for each group
     * 4. Store connections and cross-references
     * 5. Mark processed memories as consolidated
     * 6. Apply importance decay
     * 7. Promote/demote memories through tiers
     *
     * @param userId - The user whose memories to consolidate
     * @param config - Consolidation configuration
     * @returns Summary of what was done
     */
    public static async runConsolidationCycle(
        userId: string,
        config: ConsolidationConfig = DEFAULT_CONSOLIDATION_CONFIG
    ): Promise<{
        memoriesProcessed: number;
        insightsGenerated: number;
        connectionsFound: number;
        tiersUpdated: number;
        memoriesDecayed: number;
    }> {
        const result = {
            memoriesProcessed: 0,
            insightsGenerated: 0,
            connectionsFound: 0,
            tiersUpdated: 0,
            memoriesDecayed: 0,
        };

        try {
            // Step 1: Fetch unconsolidated memories
            const unconsolidated = await this.getUnconsolidatedMemories(userId, config.batchSize);

            if (unconsolidated.length < config.minMemoriesForConsolidation) {
                logger.info(
                    `[MemoryConsolidator] 🔄 Skipping consolidation ` +
                    `(${unconsolidated.length} unconsolidated, need ${config.minMemoriesForConsolidation})`
                );
            } else {
                // Step 2: Group related memories
                const groups = this.groupByEmbeddingSimilarity(unconsolidated, config.similarityThreshold);

                // Step 3: Generate insights for each group
                for (const group of groups) {
                    if (group.length < 2) continue;

                    const insight = await MemorySummarizer.generateInsight(userId, group);
                    if (insight) {
                        // Store the insight
                        await this.storeInsight(userId, insight);
                        result.insightsGenerated++;
                        result.connectionsFound += insight.connections.length;

                        // Step 4: Store connections on the memories themselves
                        await this.storeConnections(userId, insight.connections);
                    }

                    // Step 5: Mark memories as consolidated
                    await this.markAsConsolidated(userId, group.map(m => m.id));
                    result.memoriesProcessed += group.length;
                }

                // Handle any remaining ungrouped memories (mark as consolidated to avoid re-processing)
                const processedIds = new Set(groups.flat().map(m => m.id));
                const unprocessed = unconsolidated.filter(m => !processedIds.has(m.id));
                if (unprocessed.length > 0) {
                    await this.markAsConsolidated(userId, unprocessed.map(m => m.id));
                    result.memoriesProcessed += unprocessed.length;
                }
            }

            // Step 6: Apply importance decay to all active memories
            result.memoriesDecayed = await this.applyImportanceDecay(userId, config.importanceDecayPerDay);

            // Step 7: Update memory tiers
            result.tiersUpdated = await this.updateTiers(userId, DEFAULT_TIER_CONFIG);

            logger.info(
                `[MemoryConsolidator] 🔄 Consolidation complete: ` +
                `${result.memoriesProcessed} processed, ` +
                `${result.insightsGenerated} insights, ` +
                `${result.connectionsFound} connections, ` +
                `${result.tiersUpdated} tier changes, ` +
                `${result.memoriesDecayed} decayed`
            );

            return result;
        } catch (error: unknown) {
            logger.error('[MemoryConsolidator] Consolidation cycle failed:', error);
            return result;
        }
    }

    // ========================================================================
    // PRIVATE - FETCHING
    // ========================================================================

    /**
     * Fetch unconsolidated memories for a user.
     */
    private static async getUnconsolidatedMemories(
        userId: string,
        batchSize: number
    ): Promise<AlwaysOnMemory[]> {
        const memoryRef = collection(db, 'users', userId, 'alwaysOnMemories');
        const q = query(
            memoryRef,
            where('consolidated', '==', false),
            where('isActive', '==', true),
            orderBy('createdAt', 'desc'),
            limit(batchSize)
        );

        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data(),
        })) as AlwaysOnMemory[];
    }

    // ========================================================================
    // PRIVATE - GROUPING
    // ========================================================================

    /**
     * Group memories by embedding similarity using a greedy clustering approach.
     * Memories with similarity >= threshold are placed in the same group.
     */
    private static groupByEmbeddingSimilarity(
        memories: AlwaysOnMemory[],
        threshold: number
    ): AlwaysOnMemory[][] {
        const groups: AlwaysOnMemory[][] = [];
        const assigned = new Set<string>();

        for (const memory of memories) {
            if (assigned.has(memory.id)) continue;

            const group: AlwaysOnMemory[] = [memory];
            assigned.add(memory.id);

            // Find all memories similar to this one
            for (const other of memories) {
                if (assigned.has(other.id)) continue;

                // Use embedding similarity if available
                if (memory.embedding?.length && other.embedding?.length) {
                    const similarity = cosineSimilarity(memory.embedding, other.embedding);
                    if (similarity >= threshold) {
                        group.push(other);
                        assigned.add(other.id);
                    }
                } else {
                    // Fallback: topic/entity overlap
                    const topicOverlap = this.calculateSetOverlap(
                        new Set(memory.topics || []),
                        new Set(other.topics || [])
                    );
                    const entityOverlap = this.calculateSetOverlap(
                        new Set((memory.entities || []).map(e => e.name.toLowerCase())),
                        new Set((other.entities || []).map(e => e.name.toLowerCase()))
                    );
                    if (topicOverlap > 0.5 || entityOverlap > 0.3) {
                        group.push(other);
                        assigned.add(other.id);
                    }
                }
            }

            groups.push(group);
        }

        return groups;
    }

    /**
     * Calculate Jaccard overlap between two sets.
     */
    private static calculateSetOverlap(a: Set<string>, b: Set<string>): number {
        if (a.size === 0 || b.size === 0) return 0;
        const intersection = [...a].filter(x => b.has(x));
        const union = new Set([...a, ...b]);
        return intersection.length / union.size;
    }

    // ========================================================================
    // PRIVATE - STORAGE
    // ========================================================================

    /**
     * Store a consolidation insight.
     */
    private static async storeInsight(
        userId: string,
        insight: Omit<ConsolidationInsight, 'id'>
    ): Promise<string> {
        const insightRef = collection(db, 'users', userId, 'consolidationInsights');
        const docRef = await addDoc(insightRef, {
            ...insight,
            connections: insight.connections.map(c => ({
                fromMemoryId: c.fromMemoryId,
                toMemoryId: c.toMemoryId,
                relationship: c.relationship,
                confidence: c.confidence,
                discoveredAt: c.discoveredAt,
            })),
        });
        logger.info(`[MemoryConsolidator] 💡 New insight: ${insight.insight.slice(0, 80)}...`);
        return docRef.id;
    }

    /**
     * Store connections on the memories themselves (bidirectional).
     */
    private static async storeConnections(
        userId: string,
        connections: MemoryConnection[]
    ): Promise<void> {
        const batch = writeBatch(db);

        for (const conn of connections) {
            // We need to read the current connections, add the new one, and write back.
            // Since writeBatch doesn't support reads, we'll use individual updates.
            try {
                // Update the "from" memory
                const _fromRef = firestoreDoc(db, 'users', userId, 'alwaysOnMemories', conn.fromMemoryId);
                // Note: In production, you'd read the current connections first.
                // For simplicity, we use arrayUnion-like behavior.
                // Firestore arrayUnion requires exact match, so we store as a subcollection instead.
                // For now, log and skip complex cross-referencing.
                logger.debug(
                    `[MemoryConsolidator] 🔗 Connection: ${conn.fromMemoryId} → ${conn.toMemoryId}: ${conn.relationship}`
                );
            } catch (error: unknown) {
                logger.error('[MemoryConsolidator] Failed to store connection:', error);
            }
        }
    }

    /**
     * Mark memories as consolidated.
     */
    private static async markAsConsolidated(
        userId: string,
        memoryIds: string[]
    ): Promise<void> {
        const batch = writeBatch(db);
        const now = Timestamp.now();

        for (const id of memoryIds) {
            const ref = firestoreDoc(db, 'users', userId, 'alwaysOnMemories', id);
            batch.update(ref, { consolidated: true, updatedAt: now });
        }

        await batch.commit();
    }

    // ========================================================================
    // PRIVATE - IMPORTANCE DECAY
    // ========================================================================

    /**
     * Apply importance decay to all active memories.
     * Memories that haven't been accessed recently lose a small amount of importance.
     * Frequently accessed memories are reinforced instead.
     *
     * @returns Number of memories that had their importance changed
     */
    private static async applyImportanceDecay(
        userId: string,
        decayPerDay: number
    ): Promise<number> {
        try {
            const memoryRef = collection(db, 'users', userId, 'alwaysOnMemories');
            const q = query(
                memoryRef,
                where('isActive', '==', true),
                limit(100)
            );

            const snapshot = await getDocs(q);
            if (snapshot.empty) return 0;

            const batch = writeBatch(db);
            const now = Date.now();
            const nowTimestamp = Timestamp.now();
            let decayedCount = 0;

            for (const docSnap of snapshot.docs) {
                const memory = docSnap.data() as AlwaysOnMemory;
                const lastAccessed = memory.lastAccessedAt?.toMillis?.() || now;
                const daysSinceAccess = (now - lastAccessed) / (1000 * 60 * 60 * 24);

                if (daysSinceAccess < 1) continue; // Skip recently accessed memories

                // Calculate decay: importance decreases exponentially with days since access
                const decayFactor = Math.pow(1 - decayPerDay, daysSinceAccess);
                const newImportance = Math.max(0.01, memory.importance * decayFactor);

                // Only update if importance changed meaningfully
                if (Math.abs(newImportance - memory.importance) > 0.005) {
                    const ref = firestoreDoc(db, 'users', userId, 'alwaysOnMemories', docSnap.id);
                    batch.update(ref, {
                        importance: parseFloat(newImportance.toFixed(4)),
                        updatedAt: nowTimestamp,
                    });
                    decayedCount++;
                }
            }

            if (decayedCount > 0) {
                await batch.commit();
            }

            return decayedCount;
        } catch (error: unknown) {
            logger.error('[MemoryConsolidator] Importance decay failed:', error);
            return 0;
        }
    }

    // ========================================================================
    // PRIVATE - TIER MANAGEMENT
    // ========================================================================

    /**
     * Update memory tiers based on age, access frequency, and importance.
     *
     * Promotion path: working → shortTerm → longTerm
     * Demotion path: longTerm → archived (if importance drops too low)
     *
     * @returns Number of memories that changed tiers
     */
    private static async updateTiers(
        userId: string,
        tierConfig: MemoryTierConfig
    ): Promise<number> {
        try {
            const memoryRef = collection(db, 'users', userId, 'alwaysOnMemories');
            const q = query(
                memoryRef,
                where('isActive', '==', true),
                limit(200)
            );

            const snapshot = await getDocs(q);
            if (snapshot.empty) return 0;

            const batch = writeBatch(db);
            const now = Date.now();
            const nowTimestamp = Timestamp.now();
            let tiersChanged = 0;

            for (const docSnap of snapshot.docs) {
                const memory = docSnap.data() as AlwaysOnMemory;
                const createdAt = memory.createdAt?.toMillis?.() || now;
                const ageMs = now - createdAt;
                const currentTier = memory.tier || 'working';
                let newTier: MemoryTier = currentTier;

                // Promotion logic
                if (currentTier === 'working' && ageMs > tierConfig.workingToShortTermMs) {
                    newTier = 'shortTerm';
                } else if (currentTier === 'shortTerm' && ageMs > tierConfig.shortTermToLongTermMs) {
                    // Only promote to longTerm if the memory has been accessed at least once
                    // or has high importance
                    if (memory.accessCount >= tierConfig.minAccessCountForRetention || memory.importance >= 0.6) {
                        newTier = 'longTerm';
                    }
                }

                // Archival logic — long-term memories with very low importance get archived
                if (currentTier === 'longTerm' && ageMs > tierConfig.longTermToArchivedMs) {
                    if (memory.accessCount < tierConfig.minAccessCountForRetention && memory.importance < 0.15) {
                        newTier = 'archived';
                    }
                }

                if (newTier !== currentTier) {
                    const ref = firestoreDoc(db, 'users', userId, 'alwaysOnMemories', docSnap.id);
                    batch.update(ref, {
                        tier: newTier,
                        updatedAt: nowTimestamp,
                    });
                    tiersChanged++;
                }
            }

            if (tiersChanged > 0) {
                await batch.commit();
            }

            return tiersChanged;
        } catch (error: unknown) {
            logger.error('[MemoryConsolidator] Tier update failed:', error);
            return 0;
        }
    }

    // ========================================================================
    // PUBLIC - REINFORCEMENT
    // ========================================================================

    /**
     * Reinforce a memory — boost its importance because it was accessed or referenced.
     * This is the opposite of decay: memories that prove useful get stronger.
     *
     * @param userId - User ID
     * @param memoryId - Memory to reinforce
     * @param boostAmount - How much to boost importance (default: 0.05)
     */
    public static async reinforceMemory(
        userId: string,
        memoryId: string,
        boostAmount: number = 0.05
    ): Promise<void> {
        try {
            const ref = firestoreDoc(db, 'users', userId, 'alwaysOnMemories', memoryId);
            const { getDoc } = await import('firebase/firestore');
            const docSnap = await getDoc(ref);

            if (!docSnap.exists()) return;

            const memory = docSnap.data() as AlwaysOnMemory;
            const newImportance = Math.min(1.0, memory.importance + boostAmount);

            await updateDoc(ref, {
                importance: parseFloat(newImportance.toFixed(4)),
                accessCount: (memory.accessCount || 0) + 1,
                lastAccessedAt: Timestamp.now(),
                updatedAt: Timestamp.now(),
            });
        } catch (error: unknown) {
            logger.error('[MemoryConsolidator] Reinforcement failed:', error);
        }
    }
}

/* eslint-disable @typescript-eslint/no-explicit-any -- Service layer uses dynamic types for external API responses */
import { FirebaseAIService as AIService } from '../../ai/FirebaseAIService';
import { logger } from '@/utils/logger';
import type { GenerationConfig } from '@/shared/types/ai.dto';
import type { AlwaysOnMemory, MemoryEntity, ConsolidationInsight, MemoryConnection } from '@/types/AlwaysOnMemory';
