/**
 * Hive Tools — Agent-facing tools for Layer 2 (Deep Hive)
 *
 * Provides semantic search over the episodic memory graph.
 * The Deep Hive stores cross-session insights, consolidated patterns,
 * and semantically-indexed memories for intent-based retrieval.
 */

import { memoryService } from '../MemoryService';
import { wrapTool, toolError } from '../utils/ToolUtils';
import type { AnyToolFunction, AgentContext } from '../types';
import type { ToolExecutionContext } from '../ToolExecutionContext';

export const HiveTools = {
    /**
     * Semantically search the Deep Hive for relevant cross-session memories.
     * Uses vector similarity to find memories matching the user's intent.
     */
    hive_search: wrapTool(
        'hive_search',
        async (
            args: { query: string; limit?: number },
            _context?: AgentContext,
            toolContext?: ToolExecutionContext
        ) => {
            const { useStore } = await import('@/core/store');
            const state = useStore.getState();
            const projectId = state.currentProjectId;

            if (!projectId) {
                return toolError('No active project. Open a project first.', 'NO_PROJECT');
            }

            if (!args.query || args.query.trim().length < 2) {
                return toolError('Query must be at least 2 characters.', 'INVALID_INPUT');
            }

            try {
                const memories = await memoryService.retrieveRelevantMemories(
                    projectId,
                    args.query.trim(),
                    args.limit || 10
                );

                return {
                    query: args.query.trim(),
                    memories,
                    memoryCount: memories.length,
                    message: memories.length > 0
                        ? `Found ${memories.length} relevant memories for "${args.query}".`
                        : `No relevant memories found for "${args.query}".`,
                };
            } catch (error: unknown) {
                return toolError(`Hive search failed: ${error}`, 'SEARCH_FAILED');
            }
        }
    ),
} satisfies Record<string, AnyToolFunction>;

import { logger } from '@/utils/logger';
import { livingPlanService, PlanDraft, LivingPlan } from '../LivingPlanService';
import { useStore } from '@/core/store';
import { AgentContext, ToolFunctionResult } from '../types';
import { z } from 'zod';

/**
 * Tools for interacting with Living Plans.
 * These are registered with agents to allow them to propose and manage plans.
 */
export const LivingPlanTools = {
    /**
     * Propose a new structured plan to the user.
     * This creates a 'Draft' plan in Firestore and returns the ID.
     */
    propose_plan: async (args: PlanDraft, context?: AgentContext, toolContext?: any): Promise<ToolFunctionResult> => {
        const { useStore } = await import('@/core/store');
        const state = useStore.getState();
        const projectId = toolContext?.get('currentProjectId') || context?.projectId || state.currentProjectId;
        const userId = context?.userId || state.user?.uid;

        if (!projectId) {
            return { success: true, error: 'No active project found. Cannot propose a plan.' };
        }
        if (!userId) {
            return { success: true, error: 'User not authenticated. Cannot propose a plan.' };
        }

        logger.debug('[LivingPlanTools] Proposing plan:', args.summary);

        try {
            const plan = await livingPlanService.create(userId, projectId, args.summary, args);
            return {
                success: true,
                data: {
                    planId: plan.id,
                    status: 'proposed'
                }
            };
        } catch (error: any) {
            logger.error('[LivingPlanTools] Error proposing plan:', error);
            return { success: false, error: error.message };
        }
    },

    /**
     * Refine an existing plan draft before it is approved.
     */
    refine_plan: async (args: { planId: string; updates: Partial<PlanDraft> }, context?: AgentContext, toolContext?: any): Promise<ToolFunctionResult> => {
        const { useStore } = await import('@/core/store');
        const state = useStore.getState();
        const projectId = toolContext?.get('currentProjectId') || context?.projectId || state.currentProjectId;

        if (!projectId) {
            return { success: true, error: 'No active project found.' };
        }

        try {
            const plan = await livingPlanService.get(projectId, args.planId);
            if (!plan) {
                return { success: false, error: 'Plan not found.' };
            }

            const newDraft = { ...plan.draft, ...args.updates };
            await livingPlanService.updateDraft(projectId, args.planId, newDraft);
            return { success: true };
        } catch (error: any) {
            logger.error('[LivingPlanTools] Error refining plan:', error);
            return { success: false, error: error.message };
        }
    },

    /**
     * Get the details of a specific plan.
     */
    get_plan: async (args: { planId: string }, context?: AgentContext, toolContext?: any): Promise<ToolFunctionResult> => {
        const { useStore } = await import('@/core/store');
        const state = useStore.getState();
        const projectId = toolContext?.get('currentProjectId') || context?.projectId || state.currentProjectId;

        if (!projectId) {
            return { success: true, error: 'No active project found.' };
        }

        try {
            const plan = await livingPlanService.get(projectId, args.planId);
            if (!plan) {
                return { success: false, error: 'Plan not found.' };
            }
            return { success: true, data: plan };
        } catch (error: any) {
            logger.error('[LivingPlanTools] Error getting plan:', error);
            return { success: false, error: error.message };
        }
    },

    /**
     * Cancel a plan in progress.
     */
    cancel_plan: async (args: { planId: string }, context?: AgentContext, toolContext?: any): Promise<ToolFunctionResult> => {
        const { useStore } = await import('@/core/store');
        const state = useStore.getState();
        const projectId = toolContext?.get('currentProjectId') || context?.projectId || state.currentProjectId;

        if (!projectId) {
            return { success: true, error: 'No active project found.' };
        }

        try {
            await livingPlanService.cancel(projectId, args.planId);
            return { success: true };
        } catch (error: any) {
            logger.error('[LivingPlanTools] Error cancelling plan:', error);
            return { success: false, error: error.message };
        }
    },

    /**
     * Mark a plan step as complete.
     */
    complete_step: async (args: { planId: string; stepId: string; result?: any }, context?: AgentContext, toolContext?: any): Promise<ToolFunctionResult> => {
        const { useStore } = await import('@/core/store');
        const state = useStore.getState();
        const projectId = toolContext?.get('currentProjectId') || context?.projectId || state.currentProjectId;

        if (!projectId) {
            return { success: true, error: 'No active project found.' };
        }

        try {
            await livingPlanService.updateStepStatus(projectId, args.planId, args.stepId, 'complete', undefined, args.result);
            return { success: true };
        } catch (error: any) {
            logger.error('[LivingPlanTools] Error completing step:', error);
            return { success: false, error: error.message };
        }
    },

    /**
     * Mark the plan as completed successfully.
     */
    complete_plan: async (args: { planId: string }, context?: AgentContext, toolContext?: any): Promise<ToolFunctionResult> => {
        const { useStore } = await import('@/core/store');
        const state = useStore.getState();
        const projectId = toolContext?.get('currentProjectId') || context?.projectId || state.currentProjectId;

        if (!projectId) {
            return { success: true, error: 'No active project found.' };
        }

        try {
            await livingPlanService.complete(projectId, args.planId);
            return { success: true };
        } catch (error: any) {
            logger.error('[LivingPlanTools] Error completing plan:', error);
            return { success: false, error: error.message };
        }
    }
};

import { Editing } from '@/services/image/EditingService';
import { PLATFORM_DIMENSIONS } from '@/services/image/CanvasBatchService';
import { wrapTool, toolSuccess, toolError } from '../utils/ToolUtils';
import type { AnyToolFunction } from '../types';
import { logger } from '@/utils/logger';

// ============================================================================
// MediaTools Implementation
// ============================================================================

export const MediaTools = {
    /**
     * Resizes and adapts an image for various social media platforms using AI outpainting.
     */
    resize_image_for_socials: wrapTool('resize_image_for_socials', async (args: { imageUrl: string, platforms?: string[], promptOverride?: string }) => {
        const { useStore } = await import('@/core/store');
        const store = useStore.getState();
        const { addToHistory, currentProjectId } = store;

        const imgMatch = args.imageUrl.match(/^data:(image\/.+);base64,(.+)$/);
        if (!imgMatch) {
            return toolError("Invalid imageUrl data. Must be a base64 image data URI.", 'INVALID_INPUT');
        }

        const image = { mimeType: imgMatch[1]!, data: imgMatch[2]! };
        const targets = args.platforms 
            ? PLATFORM_DIMENSIONS.filter(d => args.platforms?.includes(d.platform || d.id))
            : PLATFORM_DIMENSIONS;

        if (targets.length === 0) {
            return toolError("No valid platforms selected. Available: " + PLATFORM_DIMENSIONS.map(d => d.platform || d.id).join(', '), 'INVALID_INPUT');
        }

        const results: Array<{ id: string, url: string, platform: string, label: string }> = [];
        const jobId = `resize_${Date.now()}`;

        store.addJob({
            id: jobId,
            title: `Resizing image for ${targets.length} socials...`,
            progress: 0,
            status: 'running',
            type: 'ai_generation'
        });

        try {
            for (let i = 0; i < targets.length; i++) {
                const target = targets[i]!;
                const aspect = target.width / target.height;
                const aspectLabel = aspect > 1 ? 'landscape' : aspect < 1 ? 'vertical' : 'square';

                const prompt = args.promptOverride || 
                    `Rescale and outpaint this image to fit a ${target.label} (${target.width}x${target.height}) aspect ratio. 
                    Preserve the main subject in the center. Fill the background naturally to match the existing style, lighting, and textures. 
                    Do not stretch or distort the subject.`;

                logger.info(`[MediaTools] Resizing for ${target.label}...`);

                const result = await Editing.editImage({
                    image,
                    prompt,
                    model: 'pro', // Use Pro for higher quality social assets
                    forceHighFidelity: true
                });

                if (result) {
                    addToHistory({
                        id: result.id,
                        url: result.url,
                        prompt: `Resized for ${target.label}`,
                        type: 'image',
                        timestamp: Date.now(),
                        projectId: currentProjectId
                    });

                    results.push({
                        id: result.id,
                        url: result.url,
                        platform: target.platform || target.id,
                        label: target.label
                    });
                }

                store.updateJobProgress(jobId, ((i + 1) / targets.length) * 100);
            }

            store.updateJobStatus(jobId, 'success');

            return toolSuccess({
                count: results.length,
                variants: results
            }, `Successfully generated ${results.length} social media variants using AI outpainting.`);

        } catch (error: unknown) {
            const err = error as Error;
            logger.error('[MediaTools] Resize failed:', err);
            store.updateJobStatus(jobId, 'error', err.message);
            return toolError(`Failed to resize image: ${err.message}`);
        }
    }),

    /**
     * Extracts Audio DNA from a track - BPM, Key, Mood, Genre, and Energy.
     */
    analyze_audio_dna: wrapTool('analyze_audio_dna', async (args: { audioUrl: string }) => {
        try {
            const { audioIntelligence } = await import('@/services/audio/AudioIntelligenceService');

            // AudioIntelligenceService.analyze requires a File/Blob.
            // Since we have a URL, we must fetch it.
            logger.info(`[MediaTools] Fetching audio for DNA extraction: ${args.audioUrl}`);
            const response = await fetch(args.audioUrl);
            if (!response.ok) throw new Error(`Failed to fetch audio from ${args.audioUrl}`);
            const blob = await response.blob();

            // Try to get filename from URL or default
            const fileName = args.audioUrl.split('/').pop() || 'analyzing_track.mp3';
            const file = new File([blob], fileName, { type: blob.type || 'audio/mpeg' });

            // Start analysis
            const profile = await audioIntelligence.analyze(file);

            const { useStore } = await import('@/core/store');
            const { currentProjectId, updateProjectMetadata } = useStore.getState();

            // Structure 'dna' for UI consumption based on legacy expectations
            const dna = {
                bpm: profile.technical.bpm,
                key: profile.technical.key,
                mood: profile.semantic.mood.join(', '),
                energy: profile.technical.energy,
                genre: profile.semantic.genre.join(', ')
            };

            if (currentProjectId && profile) {
                // Update project metadata with the DNA info
                updateProjectMetadata(currentProjectId, {
                    audioDna: profile
                });
            }

            return toolSuccess({
                dna,
                profile // Return full profile for advanced tools
            }, `Audio DNA extracted successfully:\nBPM: ${dna.bpm}\nKey: ${dna.key}\nMood: ${dna.mood}\nEnergy: ${dna.energy}\nGenre: ${dna.genre}`);

        } catch (e: unknown) {
            const error = e as Error;
            logger.error('[MediaTools] Audio analysis failed:', error);
            return toolError(`Failed to analyze audio: ${error.message}`);
        }
    }),

    /**
     * Crops an image to a specific aspect ratio or focus point using AI reframing.
     */
    crop_image: wrapTool('crop_image', async (args: { imageUrl: string, aspect: string, focusPoint?: string }) => {
        const { useStore } = await import('@/core/store');
        const store = useStore.getState();
        const { addToHistory, currentProjectId } = store;

        const imgMatch = args.imageUrl.match(/^data:(image\/.+);base64,(.+)$/);
        if (!imgMatch) return toolError("Invalid imageUrl data. Must be a base64 image data URI.", 'INVALID_INPUT');
        const image = { mimeType: imgMatch[1]!, data: imgMatch[2]! };

        const jobId = `crop_${Date.now()}`;
        store.addJob({ id: jobId, title: `Cropping image to ${args.aspect}...`, progress: 0, status: 'running', type: 'ai_generation' });

        try {
            const prompt = `Crop and reframe this image to a ${args.aspect} aspect ratio. Ensure the main subject ${args.focusPoint ? `(focusing on ${args.focusPoint})` : ''} remains perfectly framed. Do not distort the image.`;

            const result = await Editing.editImage({
                image,
                prompt,
                model: 'pro',
                forceHighFidelity: true
            });

            if (result) {
                addToHistory({ id: result.id, url: result.url, prompt: `Cropped to ${args.aspect}`, type: 'image', timestamp: Date.now(), projectId: currentProjectId });
                store.updateJobStatus(jobId, 'success');
                return toolSuccess({ id: result.id, url: result.url, aspect: args.aspect }, `Successfully cropped image to ${args.aspect}.`);
            }
            store.updateJobStatus(jobId, 'error', 'Failed to crop image');
            return toolError("Failed to generate cropped image.");
        } catch (error: unknown) {
            const err = error as Error;
            store.updateJobStatus(jobId, 'error', err.message);
            return toolError(`Failed to crop image: ${err.message}`);
        }
    }),

    /**
     * Generates a thumbnail from a video reference.
     */
    generate_thumbnail: wrapTool('generate_thumbnail', async (args: { videoUrl: string, timestamp?: string }) => {
        return toolError("generate_thumbnail is pending FFmpeg server-side integration.", 'NOT_IMPLEMENTED');
    })
};

