    public async ensureInitialized() {
        if (!this.isInitialized) {
            await this.bootstrap();
        }
        if (!this.model && !this.fallbackClient) {
            throw new AppException(AppErrorCode.INTERNAL_ERROR, 'AI Service not properly initialized');
        }
    }

    public handleError(error: unknown): AppException {
        if (error instanceof AppException) return error;
        const msg = error instanceof Error ? error.message : String(error);

        // Handle abort signals explicitly (these are retryable)
        if (msg.includes('aborted') || msg.includes('signal is aborted') || msg.includes('AbortError')) {
            return new AppException(
                AppErrorCode.CANCELLED,
                'AI Request was cancelled or timed out. Please try again.',
                { retryable: true }
            );
        }

        // Handle Firebase Installations API specific errors (missing API config)
        if (msg.includes('Installations') || msg.includes('installations')) {
            return new AppException(
                AppErrorCode.INTERNAL_ERROR,
                'Firebase Installations API is disabled or restricted. Please enable it in Google Cloud Console.',
                { originalError: msg }
            );
        }

        const lowerMsg = msg.toLowerCase();
        if (
            lowerMsg.includes('permission-denied') ||
            lowerMsg.includes('permission_denied') ||
            lowerMsg.includes('app-check-token') ||
            lowerMsg.includes('unauthorized')
        ) {
            if (this.useFallbackMode) {
                return new AppException(
                    AppErrorCode.UNAUTHORIZED,
                    'AI Verification Failed (Fallback API Key Invalid/Restricted). Check VITE_API_KEY permissions.',
                    { retryable: false }
                );
            }
            return new AppException(AppErrorCode.UNAUTHORIZED, 'AI Verification Failed (App Check/Auth)', { retryable: false });
        }
        if (msg.includes('Recaptcha')) {
            return new AppException(AppErrorCode.UNAUTHORIZED, 'Client Verification Failed (ReCaptcha)');
        }

        // Detailed Quota & Rate Limit Mapping
        if (msg.includes('quota') || msg.includes('resource-exhausted')) {
            return new AppException(AppErrorCode.QUOTA_EXCEEDED, 'AI Quota Exceeded');
        }
        if (msg.includes('429') || lowerMsg.includes('rate limit')) {
            return new AppException(AppErrorCode.RATE_LIMITED, 'AI Rate Limit Exceeded', { retryable: true });
        }

        // Service Availability
        if (msg.includes('503') || msg.includes('500') || lowerMsg.includes('service unavailable') || lowerMsg.includes('overloaded') || lowerMsg.includes('internal error')) {
            return new AppException(AppErrorCode.NETWORK_ERROR, 'AI Service Temporarily Unavailable or Internal Error', { retryable: true });
        }

        // @google/genai ApiError — check HTTP status code directly
        const httpStatus = (error as { status?: number })?.status;
        if (httpStatus === 404) {
            return new AppException(
                AppErrorCode.INTERNAL_ERROR,
                'AI Model Not Found — the requested model is not available on this API endpoint. Check model configuration.',
                { retryable: false, originalError: msg }
            );
        }
        if (httpStatus === 400) {
            return new AppException(
                AppErrorCode.INTERNAL_ERROR,
                `AI Bad Request — invalid model or request configuration. ${msg}`,
                { retryable: false, originalError: msg }
            );
        }
        if (httpStatus === 429) {
            return new AppException(AppErrorCode.RATE_LIMITED, 'AI Rate Limit Exceeded', { retryable: true });
        }
        if (httpStatus === 503 || httpStatus === 500) {
            return new AppException(AppErrorCode.NETWORK_ERROR, 'AI Service Temporarily Unavailable', { retryable: true });
        }

        return new AppException(AppErrorCode.INTERNAL_ERROR, `AI Service Failure: ${msg}`, { retryable: false });
    }

    public async withRetry<T>(
        operation: () => Promise<T>,
        retries = 3,
        initialDelay = 1000,
        signal?: AbortSignal
    ): Promise<T> {
        let lastError: unknown;

        for (let attempt = 0; attempt <= retries; attempt++) {
            try {
                if (signal?.aborted) {
                    const reason = signal.reason === 'TIMEOUT' ? 'AI Request timed out' : (signal.reason || 'Operation cancelled by user');
                    throw typeof reason === 'string' ? new Error(reason) : reason;
                }
                return await operation();
            } catch (error: unknown) {
                lastError = error;

                if (signal?.aborted) {
                    throw error;
                }

                const appException = this.handleError(error);
                const isRetryable = appException.details?.retryable;

                if (attempt < retries && isRetryable) {
                    // Exponential backoff with jitter
                    const backoff = (initialDelay * Math.pow(2, attempt)) + secureRandomInt(0, 200);
                    const waitTime = Math.min(backoff, 15000); // Absolute cap at 15s

                    logger.warn(`[FirebaseAIService] Transient error, retrying in ${Math.round(waitTime)}ms... (Attempt ${attempt + 1}/${retries})`);

                    await new Promise((resolve, reject) => {
                        const timer = setTimeout(resolve, waitTime);
                        if (signal) {
                            signal.addEventListener('abort', () => {
                                clearTimeout(timer);
                                reject(new Error('Operation cancelled by user during retry backoff'));
                            }, { once: true });
                        }
                    });

                    continue;
                }
                throw appException;
            }
        }
        throw this.handleError(lastError);
    }

    public sanitizePrompt(prompt: string | Content[]): string | Content[] {
        if (typeof prompt === 'string') {
            return InputSanitizer.sanitize(prompt);
        }

        if (Array.isArray(prompt)) {
            return prompt.map(content => ({
                role: content.role || 'user',
                parts: content.parts.map((part) => {
                    if ('text' in part && typeof part.text === 'string') {
                        return { ...part, text: InputSanitizer.sanitize(part.text) };
                    }
                    return part;
                })
            })) as Content[];
        }

        return prompt;
    }

    /**
     * Get circuit state for monitoring (internal/admin use)
     */
    public getCircuitStates(): Record<string, string> {
        return {
            content: this.contentBreaker.getState(),
            media: this.mediaBreaker.getState(),
            aux: this.auxBreaker.getState()
        };
    }

    private static instance: FirebaseAIService;
    public static getInstance(): FirebaseAIService {
        if (!FirebaseAIService.instance) {
            FirebaseAIService.instance = new FirebaseAIService();
        }
        return FirebaseAIService.instance;
    }
}

export const firebaseAI = FirebaseAIService.getInstance();

/**
 * NeuralCortexService — Semantic Visual Memory Core
 *
 * Implements the NEURAL_CORTEX.md specification:
 * - Stores and retrieves semantic entity profiles keyed by content fingerprint.
 * - Encodes audio DNA targetPrompts as multimodal embeddings for cross-modal retrieval.
 * - Provides drift detection by comparing new embeddings against stored anchors.
 * - Fail-closed on missing provenance, residency violations, or contract mismatches.
 *
 * Data Flow:
 *   AudioIntelligenceProfile.semantic.targetPrompts
 *     → embedContent() → Firestore vector index
 *     → retrieveSimilar() → buildRenderDirectives()
 *
 * @see docs/NEURAL_CORTEX.md
 */

import {
    doc, setDoc, getDoc, collection,
    where, getDocs, Timestamp, serverTimestamp,
} from 'firebase/firestore';
import { db, auth } from '@/services/firebase';
import { GenAI } from '@/services/ai/GenAI';
import { APPROVED_MODELS } from '@/core/config/ai-models';
import type { AudioIntelligenceProfile, AudioSemanticData } from '@/services/audio/types';
import { logger } from '@/utils/logger';

// ─────────────────────────────────────────────
// Data Contracts
// ─────────────────────────────────────────────

/** Canonical stored record for a semantic entity in the Cortex. */
export interface CortexEntityProfile {
    /** Content hash / fingerprint (from AudioIntelligenceService) */
    id: string;
    /** Firebase Auth UID of the owning user */
    userId: string;
    /** Human-readable label (filename or track title) */
    label: string;
    /** The full Audio DNA semantic payload */
    semantic: AudioSemanticData;
    /** Embedding vectors for image and veo prompts */
    embeddings: {
        image: number[];
        veo: number[];
    };
    /** ISO timestamp of creation */
    createdAt: Timestamp | ReturnType<typeof serverTimestamp>;
    /** Model version that generated the embeddings */
    embeddingModelVersion: string;
    /** Drift score vs. the prior stored entity (0.0 = identical, 1.0 = completely different) */
    driftScore?: number;
}

/** Render directives produced from a retrieved entity profile. */
export interface RenderDirectives {
    /** Composite prompt for gemini-3-pro-image-preview */
    imagePrompt: string;
    /** Composite prompt for veo-3.1-generate-preview */
    veoPrompt: string;
    /** Summary of mood/genre for labeling */
    styleSummary: string;
    /** Marketing copy suitable for DSP pitch */
    marketingComment: string;
    /** Drift warning if the retrieved entity deviated from prior anchors */
    driftWarning?: string;
}

/** Result of a similarity search against the Cortex index. */
export interface CortexRetrievalResult {
    entity: CortexEntityProfile;
    /** Cosine similarity: 1.0 = identical, 0.0 = orthogonal */
    similarity: number;
}

// ─────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────

const CORTEX_COLLECTION = 'neural_cortex';
const DRIFT_ALERT_THRESHOLD = 0.35; // Flag drift when similarity falls below this
const EMBEDDING_MODEL = APPROVED_MODELS.EMBEDDING_DEFAULT;

// ─────────────────────────────────────────────
// Utility
// ─────────────────────────────────────────────

/** Cosine similarity between two float vectors. Returns NaN if either is empty. */
function cosineSimilarity(a: number[], b: number[]): number {
    if (a.length === 0 || b.length === 0 || a.length !== b.length) return NaN;
    let dot = 0, magA = 0, magB = 0;
    for (let i = 0; i < a.length; i++) {
        dot += a[i]! * b[i]!;
        magA += a[i]! * a[i]!;
        magB += b[i]! * b[i]!;
    }
    return dot / (Math.sqrt(magA) * Math.sqrt(magB));
}

/** Embed a single text string using the approved embedding model. */
async function embedText(text: string): Promise<number[]> {
    const result = await GenAI.embedContent({
        model: EMBEDDING_MODEL,
        content: {
            role: 'user',
            parts: [{ text }]
        }
    });
    return result.values;
}

// ─────────────────────────────────────────────
// Service
// ─────────────────────────────────────────────

export class NeuralCortexService {

    private get userId(): string {
        const uid = auth.currentUser?.uid;
        if (!uid) throw new Error('[NeuralCortex] User not authenticated. Fail-closed.');
        return uid;
    }

    /**
     * Ingests an AudioIntelligenceProfile into the Cortex.
     *
     * - Generates embeddings for image + veo prompts.
     * - Calculates drift score vs. the prior stored entity (if any).
     * - Fails closed if required provenance (id, userId, semantic) is missing.
     */
    async ingest(profile: AudioIntelligenceProfile, label: string): Promise<CortexEntityProfile> {
        const uid = this.userId;

        // Contract validation: fail closed on missing fields
        if (!profile.id || !profile.semantic) {
            throw new Error('[NeuralCortex] Contract violation: profile.id and profile.semantic are required for ingest.');
        }

        logger.info(`[NeuralCortex] Ingesting entity for "${label}" (${profile.id})`);

        // 1. Check for prior entity (drift detection)
        const priorEntity = await this.getEntity(profile.id);

        // 2. Generate embeddings
        const [imageEmbedding, veoEmbedding] = await Promise.all([
            embedText(profile.semantic.targetPrompts.image),
            embedText(profile.semantic.targetPrompts.veo)
        ]);

        // 3. Calculate drift vs. prior
        let driftScore: number | undefined;
        if (priorEntity?.embeddings?.image && priorEntity.embeddings.image.length > 0) {
            const imageSim = cosineSimilarity(imageEmbedding, priorEntity.embeddings.image);
            driftScore = isNaN(imageSim) ? undefined : 1 - imageSim;

            if (driftScore !== undefined && driftScore > DRIFT_ALERT_THRESHOLD) {
                logger.warn(`[NeuralCortex] HIGH DRIFT detected for "${label}": score=${driftScore.toFixed(3)} (threshold=${DRIFT_ALERT_THRESHOLD})`);
            }
        }

        // 4. Build entity record
        const entity: CortexEntityProfile = {
            id: profile.id,
            userId: uid,
            label,
            semantic: profile.semantic,
            embeddings: {
                image: imageEmbedding,
                veo: veoEmbedding
            },
            createdAt: serverTimestamp() as ReturnType<typeof serverTimestamp>,
            embeddingModelVersion: EMBEDDING_MODEL,
            ...(driftScore !== undefined && { driftScore })
        };

        // 5. Persist to Firestore (users/{uid}/neural_cortex/{id})
        const ref = doc(db, 'users', uid, CORTEX_COLLECTION, profile.id);
        await setDoc(ref, entity, { merge: false });

        logger.info(`[NeuralCortex] Ingested entity "${label}" (drift=${driftScore?.toFixed(3) ?? 'n/a'})`);

        return entity;
    }

    /**
     * Retrieves a single entity profile by content ID.
     * Returns null if not found (non-blocking).
     */
    async getEntity(id: string): Promise<CortexEntityProfile | null> {
        try {
            const uid = this.userId;
            const ref = doc(db, 'users', uid, CORTEX_COLLECTION, id);
            const snap = await getDoc(ref);
            if (!snap.exists()) return null;
            return snap.data() as CortexEntityProfile;
        } catch (err: unknown) {
            logger.warn(`[NeuralCortex] Failed to retrieve entity ${id}:`, err);
            return null;
        }
    }

    /**
     * Retrieves all entity profiles for the current user.
     * Used to build a local index for similarity search.
     */
    async listEntities(): Promise<CortexEntityProfile[]> {
        try {
            const uid = this.userId;
            const ref = collection(db, 'users', uid, CORTEX_COLLECTION);
            const snap = await getDocs(ref);
            return snap.docs.map(d => d.data() as CortexEntityProfile);
        } catch (err: unknown) {
            logger.error('[NeuralCortex] Failed to list entities:', err);
            return [];
        }
    }

    /**
     * Finds the most semantically similar entities in the Cortex for a given query prompt.
     *
     * Uses cosine similarity on the stored image embeddings.
     * Results are sorted by descending similarity.
     *
     * @param queryPrompt  The image or veo prompt to search by.
     * @param topK         Maximum results to return (default: 5).
     */
    async retrieveSimilar(queryPrompt: string, topK = 5): Promise<CortexRetrievalResult[]> {
        logger.info(`[NeuralCortex] Searching for similar entities (topK=${topK})`);

        // 1. Embed the query
        const queryEmbedding = await embedText(queryPrompt);

        // 2. Load all entities (client-side ANN — replace with server-side vector search when available)
        const entities = await this.listEntities();

        if (entities.length === 0) {
            logger.info('[NeuralCortex] No entities in Cortex yet.');
            return [];
        }

        // 3. Score by cosine similarity
        const scored: CortexRetrievalResult[] = entities
            .map(entity => ({
                entity,
                similarity: cosineSimilarity(queryEmbedding, entity.embeddings.image)
            }))
            .filter(r => !isNaN(r.similarity))
            .sort((a, b) => b.similarity - a.similarity)
            .slice(0, topK);

        logger.info(`[NeuralCortex] Retrieved ${scored.length} entities (top sim=${scored[0]?.similarity.toFixed(3) ?? 'n/a'})`);

        return scored;
    }

    /**
     * Builds structured render directives from a retrieved entity profile.
     *
     * Synthesizes a composite prompt by enriching the raw targetPrompts with
     * mood, timbre, and lighting context from the Audio DNA.
     */
    buildRenderDirectives(entity: CortexEntityProfile): RenderDirectives {
        const { semantic } = entity;
        const moodStr = semantic.mood.join(', ');
        const genreStr = semantic.genre.join(' / ');

        // Enrich image prompt with lighting and timbre
        const imagePrompt = [
            semantic.targetPrompts.image,
            `Lighting: ${semantic.visualImagery.lighting}.`,
            `Texture: ${semantic.timbre.texture}, ${semantic.timbre.brightness}.`,
            `Era: ${semantic.productionValue.era}.`
        ].join(' ');

        // Enrich veo prompt with mood and atmospheric context
        const veoPrompt = [
            semantic.targetPrompts.veo,
            `Mood: ${moodStr}.`,
            `Narrative: ${semantic.visualImagery.narrative}`
        ].join(' ');

        const styleSummary = `${genreStr} · ${moodStr} · ${semantic.timbre.texture}`;

        const driftWarning = entity.driftScore !== undefined && entity.driftScore > DRIFT_ALERT_THRESHOLD
            ? `⚠️ Visual drift detected (score: ${entity.driftScore.toFixed(2)}). Manual continuity review recommended.`
            : undefined;

        return {
            imagePrompt,
            veoPrompt,
            styleSummary,
            marketingComment: semantic.marketingComment,
            ...(driftWarning && { driftWarning })
        };
    }

    /**
     * Convenience method: ingest + immediately retrieve render directives.
     * The canonical "one-shot" path for the Creative Director agent.
     */
    async processAndDirect(
        profile: AudioIntelligenceProfile,
        label: string
    ): Promise<RenderDirectives> {
        const entity = await this.ingest(profile, label);
        return this.buildRenderDirectives(entity);
    }
}

export const neuralCortex = new NeuralCortexService();

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { CircuitBreaker, CircuitState } from '../utils/CircuitBreaker';
import { RateLimiter } from '../RateLimiter';

describe('QA Stress Tests: Reliability & Stability', () => {

    describe('RateLimiter Stress Test', () => {
        beforeEach(() => {
            vi.useFakeTimers();
        });

        afterEach(() => {
            vi.useRealTimers();
        });

        it('should throttle bursts of requests correctly', async () => {
            // Configure: 60 requests per minute (1 per second), burst of 1
            const limiter = new RateLimiter(60, 1);

            const start = Date.now();
            const acquisitions: number[] = [];

            // Fire 5 requests immediately
            const _p1 = limiter.acquire().then(() => acquisitions.push(Date.now()));
            const _p2 = limiter.acquire().then(() => acquisitions.push(Date.now()));
            const _p3 = limiter.acquire().then(() => acquisitions.push(Date.now()));

            // First should happen immediately (burst)
            await vi.advanceTimersByTimeAsync(1); // minimal tick
            expect(acquisitions.length).toBe(1);

            // Second should wait ~1000ms
            await vi.advanceTimersByTimeAsync(1000);
            expect(acquisitions.length).toBe(2);

            // Third should wait another ~1000ms
            await vi.advanceTimersByTimeAsync(1000);
            expect(acquisitions.length).toBe(3);
        });

        it('should timeout if rate limit prevents acquisition for too long', async () => {
            // Very slow limiter: 1 request per minute
            const limiter = new RateLimiter(1, 1);

            // Acquire the burst token
            await limiter.acquire();

            // Try to acquire next one with short timeout (e.g. 100ms)
            // Try to acquire next one with short timeout (e.g. 100ms)
            // It should fail because next token is 60s away.
            // We must start the promise and attach the handler BEFORE advancing timers to avoid "Unhandled Rejection"
            const acquirePromise = limiter.acquire(100);
            const expectation = expect(acquirePromise).rejects.toThrow('Rate limit acquisition timed out');

            // Advance time past the timeout AND past the internal sleep logic (1000ms)
            // We need to wake up the loop.
            await vi.advanceTimersByTimeAsync(2000);

            await expectation;
        });
    });

    describe('CircuitBreaker Recovery Under Load', () => {
        let breaker: CircuitBreaker;
        const failureThreshold = 3;
        const resetTimeoutMs = 5000;

        beforeEach(() => {
            vi.useFakeTimers();
            breaker = new CircuitBreaker({
                failureThreshold,
                resetTimeoutMs
            });
        });

        afterEach(() => {
            vi.useRealTimers();
        });

        it('should open circuit after threshold failures and block immediately', async () => {
            const failingAction = vi.fn().mockRejectedValue(new Error('Service Down'));

            // 1. Fail up to threshold
            for (let i = 0; i < failureThreshold; i++) {
                await expect(breaker.execute(failingAction)).rejects.toThrow('Service Down');
            }

            // 2. Next failure should be immediate (Circuit Open) and NOT call the action
            const start = Date.now();
            await expect(breaker.execute(failingAction)).rejects.toThrow(/Circuit.OPEN/);

            // Verify action wasn't called again
            expect(failingAction).toHaveBeenCalledTimes(failureThreshold);
        });

        it('should attempt recovery (HALF_OPEN) after timeout', async () => {
            const action = vi.fn()
                .mockRejectedValueOnce(new Error('Fail 1'))
                .mockRejectedValueOnce(new Error('Fail 2'))
                .mockRejectedValueOnce(new Error('Fail 3')) // Opens here
                .mockResolvedValue('Success'); // Next one succeeds if called

            // Trip the breaker
            for (let i = 0; i < failureThreshold; i++) {
                try { await breaker.execute(action); } catch { /* expected */ }
            }
            expect(breaker.getState()).toBe(CircuitState.OPEN);

            // Advance time past reset timeout
            vi.setSystemTime(Date.now() + resetTimeoutMs + 100);

            // Next call should execute (HALF_OPEN probe)
            const result = await breaker.execute(action);
            expect(result).toBe('Success');
            expect(breaker.getState()).toBe(CircuitState.CLOSED);
        });

        it('should re-open circuit if probe fails in HALF_OPEN state', async () => {
            const action = vi.fn().mockRejectedValue(new Error('Persistent Failure'));

            // Trip the breaker
            for (let i = 0; i < failureThreshold; i++) {
                try { await breaker.execute(action); } catch { /* expected */ }
            }

            // Advance time
            vi.setSystemTime(Date.now() + resetTimeoutMs + 100);

            // Probe fails
            await expect(breaker.execute(action)).rejects.toThrow('Persistent Failure');

            // Should be OPEN again
            expect(breaker.getState()).toBe(CircuitState.OPEN);
        });
    });
});

