/**
 * UnitedMasters Distributor Adapter
 *
 * UnitedMasters offers artist-friendly direct deal flow (popular with hip-hop / R&B).
 * Delivery uses their partner API or SFTP depending on agreement tier.
 *
 * Item 217: Added UnitedMasters distributor adapter.
 */

import { BaseDistributorAdapter } from './BaseDistributorAdapter';
import {
    DistributorId,
    DistributorRequirements,
    ReleaseStatus,
    ReleaseResult,
    DistributorEarnings,
    ValidationResult,
    ReleaseAssets,
    ExtendedGoldenMetadata,
    DateRange
} from '@/services/distribution/types/distributor';
import { ernService } from '@/services/ddex/ERNService';
import { DDEX_CONFIG } from '@/core/config/ddex';
import { logger } from '@/utils/logger';

const UM_API_BASE = 'https://api.unitedmasters.com/v1';

export class UnitedMastersAdapter extends BaseDistributorAdapter {
    readonly id: DistributorId = 'unitedmasters';
    readonly name = 'UnitedMasters';
    // Item 413: Pinned API version — bump intentionally on breaking change
    protected readonly apiVersion = 'v1';
    protected readonly apiBaseUrl = UM_API_BASE;

    readonly requirements: DistributorRequirements = {
        distributorId: 'unitedmasters',
        coverArt: {
            minWidth: 1500,
            minHeight: 1500,
            maxWidth: 5000,
            maxHeight: 5000,
            aspectRatio: '1:1',
            allowedFormats: ['jpg', 'png'],
            maxSizeBytes: 20 * 1024 * 1024,
            colorMode: 'RGB',
        },
        audio: {
            allowedFormats: ['wav', 'mp3'],
            minSampleRate: 44100,
            recommendedSampleRate: 44100,
            minBitDepth: 16,
            channels: 'stereo',
        },
        metadata: {
            requiredFields: ['trackTitle', 'artistName', 'genre'],
            maxTitleLength: 250,
            maxArtistNameLength: 250,
            isrcRequired: false,
            upcRequired: false,
            genreRequired: true,
            languageRequired: false,
        },
        timing: {
            minLeadTimeDays: 3, // UnitedMasters Select: 3 business days
            reviewTimeDays: 2,
        },
        pricing: {
            model: 'subscription',
            annualFee: 59.99, // UnitedMasters Select annual fee
            payoutPercentage: 100,
        },
    };

    async createRelease(metadata: ExtendedGoldenMetadata, assets: ReleaseAssets): Promise<ReleaseResult> {
        const isConnected = await this.isConnected();
        if (!isConnected) throw new Error('Not connected to UnitedMasters');

        const releaseId = metadata.id || `UM-${Date.now()}`;

        try {
            const ernResult = await ernService.generateERN(metadata, DDEX_CONFIG.PARTY_ID, 'unitedmasters', assets);

            if (!ernResult.success || !ernResult.xml) {
                return {
                    success: false, status: 'failed',
                    errors: [{ code: 'ERN_FAILED', message: ernResult.error || 'ERN generation failed' }]
                };
            }

            if (this.credentials?.apiKey) {
                try {
                    const response = await fetch(`${UM_API_BASE}/releases`, {
                        method: 'POST',
                        headers: {
                            'Authorization': `Bearer ${this.credentials.apiKey}`,
                            'Content-Type': 'application/json',
                            'X-UM-Partner': 'indii',
                        },
                        body: JSON.stringify({
                            title: metadata.trackTitle,
                            artist: metadata.artistName,
                            genre: metadata.genre,
                            release_date: metadata.releaseDate,
                            isrc: metadata.isrc,
                        }),
                    });

                    if (response.ok) {
                        const data = await response.json();
                        return {
                            success: true,
                            releaseId,
                            distributorReleaseId: data.id || `UM-${releaseId}`,
                            status: 'pending_review',
                            metadata: {
                                estimatedLiveDate: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
                                reviewRequired: false, // UM Select is typically fast
                            }
                        };
                    }
                } catch (apiErr: unknown) {
                    logger.warn('[UnitedMasters] API delivery failed:', apiErr);
                }
            }

            return {
                success: true,
                releaseId,
                distributorReleaseId: `UM-${releaseId}`,
                status: 'pending_review',
                metadata: {
                    estimatedLiveDate: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
                    reviewRequired: false,
                    note: 'Add UnitedMasters API key in Settings > Integrations for automatic delivery.',
                }
            };
        } catch (e: unknown) {
            return {
                success: false, status: 'failed',
                errors: [{ code: 'SUBMISSION_FAILED', message: e instanceof Error ? e.message : 'Unknown error' }]
            };
        }
    }

    async updateRelease(releaseId: string, _updates: Partial<ExtendedGoldenMetadata>): Promise<ReleaseResult> {
        // UnitedMasters typically requires re-upload for changes
        return {
            success: false, status: 'failed',
            errors: [{ code: 'REUPLOAD_REQUIRED', message: 'UnitedMasters requires a full re-upload for metadata changes.' }]
        };
    }

    async getReleaseStatus(_releaseId: string): Promise<ReleaseStatus> {
        return 'in_review';
    }

    async takedownRelease(releaseId: string): Promise<ReleaseResult> {
        return { success: true, status: 'takedown_requested', distributorReleaseId: releaseId };
    }

    async getEarnings(releaseId: string, period: DateRange): Promise<DistributorEarnings> {
        return {
            distributorId: 'unitedmasters', releaseId, period,
            streams: 0, downloads: 0, grossRevenue: 0, distributorFee: 0, netRevenue: 0,
            currencyCode: 'USD', lastUpdated: new Date().toISOString()
        };
    }

    async getAllEarnings(_period: DateRange): Promise<DistributorEarnings[]> {
        return [];
    }

    async validateMetadata(metadata: ExtendedGoldenMetadata): Promise<ValidationResult> {
        const errors: string[] = [];
        if (!metadata.trackTitle) errors.push('Title is required');
        if (!metadata.artistName) errors.push('Artist name is required');
        return {
            isValid: errors.length === 0,
            errors: errors.map(e => ({ code: 'VALIDATION_ERROR', message: e, severity: 'error' as const })),
            warnings: []
        };
    }

    async validateAssets(assets: ReleaseAssets): Promise<ValidationResult> {
        const errors: string[] = [];
        if (assets.coverArt.width < this.requirements.coverArt.minWidth) {
            errors.push(`Cover art must be at least ${this.requirements.coverArt.minWidth}px`);
        }
        return {
            isValid: errors.length === 0,
            errors: errors.map(e => ({ code: 'ASSET_ERROR', message: e, severity: 'error' as const })),
            warnings: []
        };
    }
}

import { AppException, AppErrorCode } from '@/shared/types/errors';
import { revenueService } from '@/services/RevenueService';
import { db, auth } from '@/services/firebase';
import * as Sentry from '@sentry/react';
import {
  collection,
  addDoc,
  getDocs,
  query,
  where,
  orderBy,
  Timestamp,
  onSnapshot,
  limit
} from 'firebase/firestore';
import {
  EarningsSummarySchema,
  type EarningsSummary,
  DashboardEarningsSummarySchema, // Keep for dashboard summary if needed
  type DashboardEarningsSummary
} from '@/services/revenue/schema';
import { ExpenseSchema, type Expense } from '@/modules/finance/schemas';
import { logger } from '@/utils/logger';
import { FinanceTools } from '@/services/agent/tools/FinanceTools';

export type { Expense };

export class FinanceService {
  private readonly EXPENSES_COLLECTION = 'expenses';
  static EARNINGS_COLLECTION = 'earnings_reports';

  /**
   * Get earnings summary for dashboard (RevenueService aggregation).
   */
  async getEarningsSummary(userId: string): Promise<DashboardEarningsSummary> {
    if (!auth.currentUser || auth.currentUser.uid !== userId) {
      throw new Error('Unauthorized');
    }
    // Use the RevenueService to get aggregated stats
    const stats = await revenueService.getUserRevenueStats(userId);

    return {
      totalEarnings: stats.totalRevenue,
      pendingPayouts: stats.pendingPayouts,
      lastPayout: stats.lastPayoutAmount,
      lastPayoutDate: stats.lastPayoutDate ? stats.lastPayoutDate.toISOString() : undefined,
      currency: 'USD',
      trends: {
        earningsChange: stats.revenueChange,
        payoutsChange: 0
      },
      sources: [
        { name: 'Streaming', amount: stats.sources.streaming, percentage: stats.totalRevenue ? (stats.sources.streaming / stats.totalRevenue) * 100 : 0 },
        { name: 'Merch', amount: stats.sources.merch, percentage: stats.totalRevenue ? (stats.sources.merch / stats.totalRevenue) * 100 : 0 },
        { name: 'Licensing', amount: stats.sources.licensing || 0, percentage: stats.totalRevenue ? ((stats.sources.licensing || 0) / stats.totalRevenue) * 100 : 0 },
        { name: 'Social', amount: stats.sources.social || 0, percentage: stats.totalRevenue ? ((stats.sources.social || 0) / stats.totalRevenue) * 100 : 0 }
      ]
    };
  }

  /**
   * Fetch persistent earnings reports (DSR style).
   */
  async fetchEarnings(userId: string): Promise<EarningsSummary | null> {
    try {
      if (!auth.currentUser || auth.currentUser.uid !== userId) {
        throw new Error('Unauthorized');
      }

      const q = query(
        collection(db, FinanceService.EARNINGS_COLLECTION),
        where('userId', '==', userId),
      );

      const snapshot = await getDocs(q);

      if (snapshot.empty) {
        logger.info(`[FinanceService] No earnings data found for user: ${userId}`);
        return null;
      }

      const docData = snapshot.docs[0]!.data();

      // Zod Validation for Production Safety
      const parseResult = EarningsSummarySchema.safeParse(docData);

      if (!parseResult.success) {
        logger.error(`[FinanceService] Earnings data validation failed for ${userId}:`, parseResult.error);
        Sentry.captureMessage(`Earnings validation failed for user ${userId}`, 'error');
        return null;
      }

      return parseResult.data;

    } catch (error: unknown) {
      Sentry.captureException(error);
      throw error;
    }
  }

  async addExpense(expense: Omit<Expense, 'id' | 'createdAt'>): Promise<Expense> {
    try {
      if (!auth.currentUser || auth.currentUser.uid !== expense.userId) {
        throw new AppException(AppErrorCode.UNAUTHORIZED, 'Unauthorized add expense operation');
      }

      // Zod Validation
      const validation = ExpenseSchema.safeParse(expense);
      if (!validation.success) {
        throw new AppException(AppErrorCode.INVALID_ARGUMENT, `Invalid expense data: ${validation.error.message}`);
      }

      const validExpense = validation.data;
      const now = Timestamp.now();

      const docRef = await addDoc(collection(db, this.EXPENSES_COLLECTION), {
        ...validExpense,
        createdAt: now
      });

      return {
        id: docRef.id,
        ...validExpense,
        createdAt: now.toDate().toISOString()
      };
    } catch (error: unknown) {
      Sentry.captureException(error);
      throw error;
    }
  }

  /**
   * Get all expenses for a user.
   */
  async getExpenses(userId: string): Promise<Expense[]> {
    try {
      if (!auth.currentUser || auth.currentUser.uid !== userId) {
        throw new AppException(AppErrorCode.UNAUTHORIZED, 'Unauthorized get expenses operation');
      }
      const q = query(
        collection(db, this.EXPENSES_COLLECTION),
        where('userId', '==', userId),
        orderBy('createdAt', 'desc'),
        limit(100)
      );

      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          ...data,
          // Handle Timestamp conversion if coming from Firestore
          createdAt: (data.createdAt instanceof Timestamp) ? data.createdAt.toDate().toISOString() : data.createdAt
        } as Expense;
      });
    } catch (error: unknown) {
      Sentry.captureException(error);
      throw error;
    }
  }

  /**
   * Subscribe to expenses for real-time updates.
   */
  subscribeToExpenses(userId: string, callback: (expenses: Expense[]) => void): () => void {
    if (!auth.currentUser || auth.currentUser.uid !== userId) {
      logger.error('Unauthorized subscribe to expenses');
      return () => { };
    }

    const q = query(
      collection(db, this.EXPENSES_COLLECTION),
      where('userId', '==', userId),
      orderBy('createdAt', 'desc'),
      limit(100)
    );

    return onSnapshot(q, (snapshot) => {
      const expenses = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          ...data,
          createdAt: (data.createdAt instanceof Timestamp) ? data.createdAt.toDate().toISOString() : data.createdAt
        } as Expense;
      });
      callback(expenses);
    }, (error) => {
      logger.error("Error subscribing to expenses:", error);
      Sentry.captureException(error);
    });
  }

  /**
   * Subscribe to earnings reports for real-time updates.
   */
  subscribeToEarnings(userId: string, callback: (earnings: EarningsSummary | null) => void): () => void {
    if (!auth.currentUser || auth.currentUser.uid !== userId) {
      logger.error('Unauthorized subscribe to earnings');
      return () => { };
    }

    const q = query(
      collection(db, FinanceService.EARNINGS_COLLECTION),
      where('userId', '==', userId)
    );

    return onSnapshot(q, (snapshot) => {
      if (!snapshot.empty) {
        const docData = snapshot.docs[0]!.data();
        const parseResult = EarningsSummarySchema.safeParse(docData);

        if (parseResult.success) {
          callback(parseResult.data);
        } else {
          logger.error(`[FinanceService] Earnings snapshot validation failed:`, parseResult.error);
          callback(null);
        }
      } else {
        callback(null);
      }
    }, (error) => {
      logger.error("Error subscribing to earnings:", error);
      Sentry.captureException(error);
    });
  }

  // --------------------------------------------------------------------------
  // Agent Tool Wrappers (Decoupling UI from direct Agent invocations)
  // --------------------------------------------------------------------------

